import{a as e,i as t,n,r,t as i}from"./student-vHKn45kh.js";var a={atomic:JSON.parse(`{"objectives":["Describe the behaviour of sub-atomic particles in an electric field","Define and use the four quantum numbers n, l, mₗ, mₛ for n = 1, 2, 3","Describe the shapes of s and p orbitals","Apply Aufbau, Pauli, and Hund principles to write electron configurations","Write electron configurations of atoms and ions, including transition-metal ions","Define ionisation energy and explain factors that affect it (nuclear charge, distance, shielding, penetration)","Explain trends in IE across a period and down a group, including Al and S anomalies","Deduce electronic configuration / group number from successive IE data"],"chapters":[{"id":"ch1","title":"Subatomic Particles","blocks":[{"type":"p","text":"Every atom is built from three subatomic particles: protons, neutrons, and electrons. Their relative masses and charges dictate almost everything that follows — bonding, spectra, ionisation, even the colour of transition-metal complexes."},{"type":"d","caption":"The three subatomic particles"},{"type":"h","text":"Inside the atom"},{"type":"p","text":"Protons and neutrons sit together in a tiny, dense core called the nucleus. Electrons occupy the space around the nucleus in regions called shells. The atom is mostly empty space: if the nucleus were a pea in the centre of a football stadium, the electrons would be found near the outer seats."},{"type":"d","caption":"The nuclear model"},{"type":"callout","title":"Atomic number (Z)","body":"Number of protons. Defines the element. Identical to the number of electrons in a NEUTRAL atom."},{"type":"callout","title":"Mass number (A)","body":"Total number of protons + neutrons. Number of neutrons = A − Z."},{"type":"callout","title":"Isotopes","body":"Same Z, different A — same element, different number of neutrons. Examples: ¹²C and ¹³C, ³⁵Cl and ³⁷Cl. Isotopes have identical chemistry (electrons unchanged) but different mass."},{"type":"h","text":"Notation"},{"type":"ul","items":["An element X with mass number A and atomic number Z is written ᴬ_Z X (e.g. ²³_₁₁Na).","The mass number sits top-left; the atomic number bottom-left.","Charge (if any) goes top-right: Mg²⁺, O²⁻."]},{"type":"takeaway","items":["Protons + neutrons in the nucleus; electrons in shells around it.","Z identifies the element; A − Z = number of neutrons.","Isotopes share Z but differ in neutron count and so in mass.","A neutral atom has equal numbers of protons and electrons."]}]},{"id":"ch2","title":"Behaviour in Electric Fields","blocks":[{"type":"p","text":"When a beam of charged particles passes between oppositely-charged plates, each particle is deflected according to its charge-to-mass ratio. This is the principle behind mass spectrometry and cathode-ray tubes, and it is a favourite exam question."},{"type":"d","caption":"Relative deflection in a uniform electric field"},{"type":"h","text":"The three rules"},{"type":"ul","items":["Electrons (e⁻, charge −1) deflect TOWARDS the positive plate, and strongly — their mass is tiny.","Protons (p⁺, charge +1) deflect TOWARDS the negative plate, but less than electrons of the same speed.","Neutrons (n⁰, charge 0) are NOT deflected at all."]},{"type":"callout","title":"Deflection ∝ charge/mass","body":"For the same accelerating voltage and field, a particle with larger q/m is deflected more. Electrons win by a factor of ~1836 over protons (same charge magnitude, much smaller mass)."},{"type":"h","text":"Why the direction matters"},{"type":"p","text":"The DIRECTION of deflection tells you the SIGN of the charge: opposite charges attract. The MAGNITUDE of deflection tells you q/m, and so distinguishes particles of different mass with the same charge — exactly how a mass spectrometer separates isotopes."},{"type":"takeaway","items":["Direction → sign of charge.","Magnitude → q/m ratio.","Neutrons ignore electric fields entirely."]}]},{"id":"ch3","title":"Quantum Numbers (n, l, mₗ, mₛ)","blocks":[{"type":"p","text":"Electrons aren't little planets orbiting a nucleus. They occupy three-dimensional regions called orbitals, each described by a unique set of FOUR quantum numbers. At A-level only n = 1, 2, 3 need be examined in detail, but the framework underpins everything in this topic."},{"type":"d","caption":"The four quantum numbers"},{"type":"h","text":"The four quantum numbers"},{"type":"ul","items":["PRINCIPAL n — the shell. n = 1, 2, 3, … Higher n means a larger, higher-energy shell.","AZIMUTHAL l — the subshell within a shell. l = 0, 1, 2, … (n−1). Letter labels: 0 = s, 1 = p, 2 = d, 3 = f.","MAGNETIC mₗ — the orientation of the orbital in space. mₗ = −l, … 0, … +l (so 2l + 1 orbitals per subshell).","SPIN mₛ — the electron's spin. mₛ = +½ or −½. Each orbital holds at most 2 electrons, with opposite spins."]},{"type":"h","text":"How shells, subshells, and orbitals nest"},{"type":"ul","items":["n = 1 — one subshell (1s) → one orbital → max 2 electrons.","n = 2 — two subshells (2s, 2p). 2s has 1 orbital (2 e⁻); 2p has 3 orbitals (6 e⁻). Total 8 electrons.","n = 3 — three subshells (3s, 3p, 3d). 3s 1 orbital (2 e⁻), 3p 3 orbitals (6 e⁻), 3d 5 orbitals (10 e⁻). Total 18 electrons.","In general, shell n holds up to 2n² electrons."]},{"type":"callout","title":"Energies WITHIN a shell are NOT equal","body":"For a given n, the order is s < p < d < f. The s subshell is lowest in energy because s electrons penetrate closer to the nucleus (see Chapter 5)."},{"type":"h","text":"Number of orbitals and electrons — quick formulas"},{"type":"ul","items":["Subshell s → 1 orbital → max 2 electrons.","Subshell p → 3 orbitals → max 6 electrons.","Subshell d → 5 orbitals → max 10 electrons.","Subshell f → 7 orbitals → max 14 electrons."]},{"type":"takeaway","items":["Four quantum numbers uniquely identify any electron.","n = shell, l = subshell, mₗ = orbital orientation, mₛ = spin.","l ranges 0 to n−1; mₗ ranges −l to +l.","Shell n holds 2n² electrons in total."]}]},{"id":"ch4","title":"Shapes of s and p Orbitals","blocks":[{"type":"p","text":"An orbital is a 3-D region in which there is over 90 % probability of finding an electron. The shape matters because it controls how orbitals overlap when atoms bond."},{"type":"d","caption":"s and p orbital shapes"},{"type":"h","text":"s orbitals"},{"type":"ul","items":["Spherical, centred on the nucleus.","There is exactly ONE s orbital per shell (n = 1, 2, 3, …).","Higher s orbitals (2s, 3s, …) are larger and have nodal regions where the electron density drops to zero."]},{"type":"h","text":"p orbitals"},{"type":"ul","items":["Dumbbell-shaped — two lobes either side of the nucleus.","There are THREE p orbitals per shell (from n = 2 onwards), oriented along the x, y and z axes — labelled pₓ, pᵧ, p_z.","They are mutually perpendicular.","In an isolated atom the three p orbitals are degenerate (same energy)."]},{"type":"h","text":"d orbitals (background only)"},{"type":"p","text":"There are five d orbitals per shell from n = 3 onwards. Their shapes are more complex (cloverleaf, plus a doughnut/lobe variant). The syllabus does not require you to draw them — only s and p shapes are examined. The d orbitals matter when we get to transition-metal complexes (AC-21)."},{"type":"callout","title":"Why three p orbitals?","body":"Because mₗ for p (l = 1) takes three values: −1, 0, +1. Each value corresponds to a different spatial orientation. Hund's rule fills each one singly first, giving atoms like nitrogen (2p³) a half-filled, unusually stable arrangement."},{"type":"takeaway","items":["s: spherical, 1 per shell.","p: dumbbell, 3 per shell (n ≥ 2), perpendicular orientations.","d: more complex, 5 per shell (n ≥ 3); shapes not examinable."]}]},{"id":"ch5","title":"Filling Orbitals — Aufbau, Pauli, Hund","blocks":[{"type":"p","text":"When you assign electrons to orbitals to write a configuration, three rules govern the order. They are deceptively simple and often confused — get them straight and most configuration questions follow automatically."},{"type":"d","caption":"Subshell filling order with the three rules"},{"type":"h","text":"Aufbau (\\"building up\\")"},{"type":"p","text":"Electrons enter the lowest-energy subshell available first. The order is: 1s → 2s → 2p → 3s → 3p → 4s → 3d → 4p → 5s → 4d → 5p → 6s → 4f → 5d → 6p → 7s …"},{"type":"callout","title":"The 4s/3d crossover","body":"4s fills BEFORE 3d in the neutral atom because 4s is slightly lower in energy. But once 3d has electrons, the 3d level drops below 4s. Consequence: when forming a positive ion, 4s ELECTRONS LEAVE FIRST. Hence Fe is [Ar] 3d⁶ 4s² but Fe²⁺ is [Ar] 3d⁶ (not [Ar] 3d⁴ 4s²)."},{"type":"h","text":"Pauli (exclusion principle)"},{"type":"p","text":"No two electrons in the same atom can have all four quantum numbers identical. In practice this means each orbital can hold AT MOST 2 electrons — and those two must have OPPOSITE spins."},{"type":"h","text":"Hund's rule"},{"type":"p","text":"When filling a degenerate set of orbitals (e.g. the three 2p orbitals), put one electron in EACH orbital first — all with parallel spins — before pairing any of them up. Pairing electrons in the same orbital costs energy because of electron-electron repulsion, so single occupation is preferred whenever possible."},{"type":"h","text":"Building configurations — examples"},{"type":"ul","items":["Na (Z = 11):  1s² 2s² 2p⁶ 3s¹  =  [Ne] 3s¹","Cl (Z = 17):  1s² 2s² 2p⁶ 3s² 3p⁵  =  [Ne] 3s² 3p⁵","Ar (Z = 18):  [Ne] 3s² 3p⁶  (full Period-3 octet)","K  (Z = 19):  [Ar] 4s¹  (4s before 3d)","Ti (Z = 22):  [Ar] 3d² 4s²","Fe (Z = 26):  [Ar] 3d⁶ 4s²"]},{"type":"h","text":"The two famous anomalies"},{"type":"callout","title":"Cr and Cu break the pattern","body":"Cr is [Ar] 3d⁵ 4s¹ (NOT 3d⁴ 4s²) — half-filled d subshell is extra stable. Cu is [Ar] 3d¹⁰ 4s¹ (NOT 3d⁹ 4s²) — fully-filled d subshell is extra stable. Memorise these two; the rest follow Aufbau cleanly."},{"type":"h","text":"Configurations of common ions"},{"type":"ul","items":["Na⁺: [Ne] (lost 3s¹). Mg²⁺: [Ne] (lost 3s²). Al³⁺: [Ne] (lost 3s² 3p¹).","Cl⁻: [Ar] (gained one to fill 3p). O²⁻: [Ne] (gained two to fill 2p).","Fe²⁺: [Ar] 3d⁶ (lost both 4s electrons).","Fe³⁺: [Ar] 3d⁵ (lost both 4s and one 3d).","Cu²⁺: [Ar] 3d⁹ (lost 4s¹ and one 3d)."]},{"type":"callout","title":"Test yourself","body":"Write out the configurations of Mn, Mn²⁺, V³⁺, Co³⁺, Zn²⁺. Mn: [Ar] 3d⁵ 4s²; Mn²⁺: [Ar] 3d⁵ (lost 4s²); V³⁺: [Ar] 3d² (lost 4s² and one 3d); Co³⁺: [Ar] 3d⁶; Zn²⁺: [Ar] 3d¹⁰."},{"type":"takeaway","items":["Aufbau: fill lowest-energy subshell first.","Pauli: max 2 electrons per orbital, opposite spins.","Hund: singly occupy degenerate orbitals before pairing.","4s fills first but empties first when ionising.","Cr (3d⁵ 4s¹) and Cu (3d¹⁰ 4s¹) are anomalies."]}]},{"id":"ch6","title":"Ionisation Energy — Foundations","blocks":[{"type":"p","text":"Ionisation energy (IE) is the energy needed to remove one mole of electrons from one mole of gaseous atoms (or ions). It is always endothermic — work is being done against the attraction between the negative electron and the positive nucleus. The size of an IE depends on three competing factors: nuclear charge, distance from nucleus, and shielding by inner electrons."},{"type":"callout","title":"First ionisation energy (IE₁)","body":"X(g)  →  X⁺(g) + e⁻         ΔH = IE₁  (always positive)"},{"type":"callout","title":"Second ionisation energy (IE₂)","body":"X⁺(g)  →  X²⁺(g) + e⁻        ΔH = IE₂. ALWAYS larger than IE₁ — removing from a positive ion is harder."},{"type":"h","text":"The three factors that control IE"},{"type":"ul","items":["Nuclear charge — more protons mean a stronger pull on electrons → HIGHER IE.","Distance from nucleus (atomic radius) — outer electrons further from the nucleus are easier to remove → LOWER IE.","Shielding (screening) — inner-shell electrons reduce the effective nuclear charge felt by outer electrons → LOWER IE for the outer ones."]},{"type":"h","text":"Penetration explains why s < p < d in energy within a shell"},{"type":"d","caption":"Why 3s < 3p < 3d in energy"},{"type":"p","text":"Within the same shell (same n), an s orbital \\"penetrates\\" closer to the nucleus than a p orbital, which in turn penetrates closer than a d orbital. Closer penetration means the electron experiences less shielding from inner electrons and more of the actual nuclear charge — so the s electron is held more tightly (lower in energy). This is why 3s < 3p < 3d, and is also why 4s actually drops below 3d for early TMs."},{"type":"h","text":"Effective nuclear charge (Z_eff)"},{"type":"p","text":"A useful concept: Z_eff = Z − S, where S is the total shielding from inner electrons. For example, in Na the outermost 3s electron sees Z = 11, but the 10 inner electrons (1s² 2s² 2p⁶) shield it almost completely, so Z_eff ≈ 11 − 10 = 1. That is why Na's first IE is small. Compare to Mg: Z = 12, but its outer 3s² electron is shielded by 10 inner electrons, giving Z_eff ≈ 2. Higher Z_eff → harder to remove → higher IE."},{"type":"callout","title":"Putting it together","body":"IE rises when (a) nuclear charge rises faster than shielding, or (b) the electron being removed is in a smaller, lower-energy orbital. IE falls when (a) shielding outpaces nuclear charge, or (b) the electron is far from the nucleus or in a higher-energy subshell."},{"type":"takeaway","items":["IE is always endothermic — energy in.","Three factors: nuclear charge ↑, distance ↑, shielding ↑ — all matter.","Within a shell: s < p < d in energy (penetration argument).","Effective nuclear charge Z_eff = Z − S."]}]},{"id":"ch7","title":"IE Trends & Successive IE","blocks":[{"type":"h","text":"Across a period (Na → Ar)"},{"type":"p","text":"First ionisation energy GENERALLY rises across a period: nuclear charge increases by 1 per element, but each new electron goes into the same outer shell, so shielding stays roughly constant. Net effect: Z_eff rises, electrons held more tightly, IE rises."},{"type":"d","caption":"First IE across Period 3"},{"type":"callout","title":"Two famous dips: Al and S","body":"The trend is NOT monotonic. There is a small drop at Al (relative to Mg) and another at S (relative to P)."},{"type":"h","text":"Why Al dips below Mg"},{"type":"p","text":"Mg: outer 3s². Al: outer 3s² 3p¹. The fourth outer electron in Al is in 3p, which is HIGHER in energy than 3s (penetration argument). So the 3p¹ electron is easier to remove than a 3s electron from Mg, even though Al has more protons. The drop is small because the difference between 3s and 3p is small."},{"type":"h","text":"Why S dips below P"},{"type":"p","text":"P: outer 3s² 3p³. The three 3p orbitals each hold one electron (Hund's rule). S: outer 3s² 3p⁴. The fourth 3p electron must PAIR up with one of the existing 3p electrons. Pairing brings extra electron-electron repulsion in the same orbital, which destabilises that paired electron and makes it easier to remove. So S has a slightly LOWER IE₁ than P, despite more protons."},{"type":"h","text":"Down a group"},{"type":"p","text":"IE FALLS down a group. Atomic radius grows (more shells), and shielding by inner electrons grows roughly in step with nuclear charge — so Z_eff stays similar, but the outer electron is much further from the nucleus and so easier to remove."},{"type":"h","text":"Successive ionisation energies"},{"type":"p","text":"Each ionisation gets harder than the last. Big jumps appear when you break into a NEW (inner) shell, because the next electron is in a much smaller orbital with much less shielding. This is how we use IE data to deduce GROUP NUMBER."},{"type":"d","caption":"Successive IE of Na (log) — jumps reveal shell structure"},{"type":"h","text":"Reading successive-IE data"},{"type":"ul","items":["A big jump after the 1st electron → Group I (only 1 valence electron).","After the 2nd → Group II.","After the 3rd → Group III.","After the 4th → Group IV.","In general, the position of the FIRST big jump tells you the group number."]},{"type":"callout","title":"Spotting the jump","body":"Look at the RATIO between successive IE values. Within the same shell, the ratio is typically 1.5–2×. Jumping into the next shell, the ratio is 4× or more. The first big multiplicative jump = the boundary between valence and core."},{"type":"h","text":"IE definition for higher ionisations"},{"type":"ul","items":["IE₁: X(g) → X⁺(g) + e⁻","IE₂: X⁺(g) → X²⁺(g) + e⁻","IE₃: X²⁺(g) → X³⁺(g) + e⁻","and so on."]},{"type":"takeaway","items":["IE rises across a period (Z_eff up).","IE falls down a group (radius and shielding up).","Period 3 dips: Al (3p > 3s) and S (3p pair repulsion).","Successive IEs: big jump = new shell = group number."]}]}]}`),hydrocarbons:JSON.parse(`{"objectives":["Use IUPAC nomenclature and displayed formulae for hydrocarbons C1–C10","Describe the forms of isomerism found in hydrocarbons","Explain the use of crude oil and natural gas as sources of hydrocarbons","Describe the reactions of ethane (combustion, free-radical chlorination)","Describe the reactions of ethene (all six: halogens, HX, H₂, H₂O, KMnO₄ cold, KMnO₄ hot, polymerisation)","Describe the mechanism of free radical substitution","Describe the mechanism of electrophilic addition (including bromonium ion for Br₂)","Describe the reactions and mechanism for benzene electrophilic substitution","Describe the reactions of methylbenzene: ortho/para direction and activation of ring","Predict whether halogenation occurs on the ring or the side chain","Describe the oxidation of arene side chains with KMnO₄","Explain industrial uses and environmental impact of hydrocarbons"],"chapters":[{"id":"h1","title":"Nomenclature (C1–C10)","blocks":[{"type":"p","text":"Every organic compound has a systematic IUPAC name that tells you its structure exactly. Master nomenclature and you unlock half of organic chemistry — every mechanism, test, and synthesis depends on knowing what you're looking at."},{"type":"h","text":"The three hydrocarbon families"},{"type":"ul","items":["Alkanes — saturated (only single C-C bonds). General formula CₙH₂ₙ₊₂. Suffix -ane.","Alkenes — one or more C=C double bonds. General formula CₙH₂ₙ (for one C=C). Suffix -ene.","Arenes — contain a benzene ring. Based on C₆H₆."]},{"type":"d","caption":"The alkane homologous series"},{"type":"h","text":"IUPAC rules — three steps"},{"type":"ul","items":["Find the longest carbon chain containing the functional group. That is the parent name.","Number the chain to give the functional group the LOWEST possible locant. C=C wins over branches.","Name and locate each substituent alphabetically as a prefix (methyl, ethyl, chloro, bromo…)."]},{"type":"callout","title":"Stem names C1–C10","body":"meth- eth- prop- but- pent- hex- hept- oct- non- dec-. Learn these cold."},{"type":"h","text":"Worked examples"},{"type":"ul","items":["CH₃CH(CH₃)CH₂CH₃   →   2-methylbutane","CH₃CH=CHCH₂CH₃    →   pent-2-ene","C₆H₅CH₃             →   methylbenzene (traditional: toluene)"]},{"type":"takeaway","items":["Longest chain = parent. Lowest locant = priority. Alphabetical prefix = substituent.","Suffix changes with family: -ane, -ene, -yne.","For C=C in C4+, always specify the position (but-1-ene vs but-2-ene)."]}]},{"id":"h2","title":"Isomerism","blocks":[{"type":"p","text":"Isomers are compounds with the same molecular formula but different structures. Even a small molecule like C₄H₁₀ has two isomers; C₅H₁₂ has three; C₁₀H₂₂ has 75."},{"type":"h","text":"Structural isomerism"},{"type":"ul","items":["Chain — different skeleton. butane vs 2-methylpropane (both C₄H₁₀).","Positional — same skeleton, functional group in a different position. but-1-ene vs but-2-ene.","Functional group — same formula, different class. C₂H₆O can be ethanol or methoxymethane."]},{"type":"h","text":"Stereoisomerism — cis/trans"},{"type":"p","text":"Alkenes cannot rotate around their C=C double bond — it's held rigid by the π overlap. That locks substituents on either side of the bond into one of two fixed positions."},{"type":"d","caption":"cis vs trans but-2-ene"},{"type":"callout","title":"Requirement for cis/trans isomerism","body":"The C=C must have TWO different groups on each carbon. CH₂=CHCl has only one isomer — one carbon has two Hs. CH₃CH=CHCH₃ has cis and trans."},{"type":"callout","title":"Physical differences","body":"cis and trans isomers have slightly different boiling points, melting points, and (for polar molecules) different dipole moments. cis generally has a net dipole; trans often cancels to zero."},{"type":"takeaway","items":["Same molecular formula ≠ same molecule.","Structural (chain/positional/functional-group) vs stereo (cis/trans).","cis/trans needs restricted rotation AND two different groups on each C=C carbon."]}]},{"id":"h3","title":"Crude Oil, Natural Gas & Cracking","blocks":[{"type":"p","text":"Crude oil is a mixture of hundreds of hydrocarbons. On its own it's useless — you have to separate it into fractions with similar boiling points. That's done in a fractionating column, relying on the fact that smaller molecules have weaker Van der Waals forces and so boil first."},{"type":"d","caption":"Fractional distillation of crude oil"},{"type":"h","text":"The trick of fractionation"},{"type":"ul","items":["Crude is heated to ~350 °C. Everything vapourises except the heaviest residue (bitumen).","Vapours rise through the column. The column is HOT at the bottom, COOL at the top.","Each fraction condenses at its level — heaviest at the base, lightest at the top."]},{"type":"h","text":"Cracking — turning big into small"},{"type":"p","text":"Demand for petrol and alkenes far exceeds demand for kerosene, diesel, and heavier fractions. Cracking breaks long alkane chains into shorter alkanes + an alkene (which is also useful as a polymer feedstock)."},{"type":"d","caption":"Catalytic cracking of decane"},{"type":"ul","items":["Thermal cracking — high T, high P. Free-radical mechanism. More alkenes.","Catalytic cracking — Al₂O₃ / zeolite, ~700 °C. Carbocation mechanism. More branched alkanes for petrol."]},{"type":"callout","title":"Why cracking matters","body":"It converts low-demand heavy fractions into high-demand petrol and the alkene feedstock (ethene, propene) used to make plastics."}]},{"id":"h4","title":"Physical Properties","blocks":[{"type":"p","text":"Hydrocarbons are non-polar. Their physical properties are dictated by Van der Waals (dispersion) forces between molecules, which scale with surface area and electron count."},{"type":"h","text":"Trends along the homologous series"},{"type":"ul","items":["Boiling point rises by ~20–30 °C per CH₂ added (more electrons → stronger Van der Waals).","C₁–C₄ gases at room temp. C₅–C₁₆ liquids. C₁₇+ solids (waxes).","Viscosity ↑ with chain length. Flammability ↓.","Insoluble in water (non-polar), fully soluble in other hydrocarbons."]},{"type":"callout","title":"Chain branching","body":"Branched isomers have LOWER boiling points than straight-chain versions — they're more spherical, so surface contact between molecules is reduced. 2,2-dimethylpropane boils at 9 °C, pentane boils at 36 °C."}]},{"id":"h5","title":"Chemistry of Alkanes (Ethane)","blocks":[{"type":"p","text":"Alkanes are notoriously unreactive — they're often called paraffins (\\"having little affinity\\"). They have only strong, non-polar C-H and C-C bonds, so they're immune to most ionic reagents. The syllabus uses ethane (C₂H₆) as the exemplar. Two reactions matter: combustion, and halogenation by free-radical substitution with chlorine."},{"type":"h","text":"Combustion of ethane"},{"type":"ul","items":["Complete (excess O₂):   2C₂H₆ + 7O₂  →  4CO₂ + 6H₂O     (highly exothermic — use as fuel)","Incomplete (limited O₂): 2C₂H₆ + 5O₂ → 4CO + 6H₂O        (or further: 2C₂H₆ + 3O₂ → 4C + 6H₂O, producing soot)","CO is toxic — binds to haemoglobin ~250× more strongly than O₂, blocking oxygen transport."]},{"type":"h","text":"Free-radical substitution — ethane + Cl₂"},{"type":"p","text":"In UV light, ethane reacts with chlorine to give chloroethane. The mechanism is a three-stage chain reaction: initiation, propagation, termination."},{"type":"d","caption":"Free-radical chlorination of ethane"},{"type":"callout","title":"UV light is essential","body":"Without UV, Cl₂ doesn't homolyse. Without homolysis, no Cl• radicals. Without Cl• radicals, no reaction. \\"In the dark\\" = no product. Heat alone is not enough at A-level."},{"type":"callout","title":"Multiple substitution","body":"The product C₂H₅Cl can react further with Cl₂ to give C₂H₄Cl₂, C₂H₃Cl₃, and so on. Real reactions give a mixture — for mainly the monosubstituted product, use excess ethane."},{"type":"callout","title":"Bridge to Halogen Derivatives (OC-15)","body":"Chloroethane (C₂H₅Cl) is a halogenoalkane. In OC-15 you learn how it reacts with nucleophiles (hydrolysis to ethanol, reaction with NH₃ to give amines, formation of nitriles). Free-radical substitution is one of the two main ways to make halogenoalkanes; the other is electrophilic addition of HX to alkenes (CH.6)."},{"type":"takeaway","items":["Ethane burns (combustion) and substitutes (radical halogenation with UV).","3-step mechanism: initiation (UV homolysis), propagation (2-step chain), termination (2 radicals combine).","UV light is essential — no UV, no reaction.","The chloroethane product leads into OC-15 (Halogen Derivatives)."]}]},{"id":"h6","title":"Chemistry of Alkenes (Ethene)","blocks":[{"type":"p","text":"The C=C bond in alkenes is the reason they're reactive. The π electrons are exposed above and below the molecular plane — easy prey for electrophiles. The syllabus lists six specific reactions of ethene that you must know: halogenation, hydrohalogenation, catalytic hydrogenation, hydration, cold-dilute KMnO₄, hot-concentrated KMnO₄, plus polymerisation."},{"type":"h","text":"Test for unsaturation — bromine water"},{"type":"p","text":"Shake an unknown hydrocarbon with orange bromine water. If the colour vanishes, there's a C=C. If not, it's saturated (or aromatic)."},{"type":"d","caption":"Alkanes vs alkenes with Br₂(aq)"},{"type":"h","text":"The six reactions of ethene"},{"type":"ul","items":["1. Halogens — Br₂ or Cl₂ → 1,2-dihaloethane (electrophilic addition via bromonium ion).","2. Hydrogen halides — HCl, HBr, HI → haloethane (electrophilic addition, Markovnikov for unsymmetrical alkenes).","3. Catalytic hydrogenation — H₂, Ni catalyst, 150 °C → ethane. Industrial use: hardening vegetable oils into margarine.","4. Hydration (steam) — H₂O(g), H₃PO₄ catalyst, 300 °C, 60 atm → ethanol. Industrial route to ethanol.","5. Cold dilute alkaline KMnO₄ → ethane-1,2-diol (the diol). Purple → green/brown.","6. Hot concentrated acidic KMnO₄ → CO₂ + HCOOH (cleavage of C=C). Purple → colourless.","7. Polymerisation — high pressure, trace O₂ (or Ziegler-Natta) → polyethene."]},{"type":"h","text":"Mechanism — HBr + ethene (electrophilic addition)"},{"type":"d","caption":"HBr across ethene"},{"type":"h","text":"Mechanism — Br₂ + ethene (bromonium ion)"},{"type":"p","text":"Br₂ is non-polar at first, so how can it act as an electrophile? The answer: the π electrons of the alkene induce a dipole in the Br-Br bond as it approaches. This makes the nearer Br δ⁺ and the far Br δ⁻. The mechanism then proceeds through a cyclic bromonium ion intermediate, giving overall trans-addition."},{"type":"d","caption":"Br₂ addition via bromonium ion"},{"type":"h","text":"Markovnikov's rule"},{"type":"p","text":"When an unsymmetrical molecule like HBr adds to an unsymmetrical alkene like propene, there are two possible products. Markovnikov's rule tells you which is major: \\"the H goes to the carbon that already has more Hs.\\" The underlying reason is carbocation stability — tertiary > secondary > primary."},{"type":"d","caption":"HBr + propene"},{"type":"h","text":"Oxidation with KMnO₄"},{"type":"d","caption":"Cold vs hot KMnO₄"},{"type":"callout","title":"Bridge to Halogen Derivatives (OC-15)","body":"Electrophilic addition of HBr or Br₂ to an alkene is the second main route to halogenoalkanes. Use this when you need a specific regiochemistry (Markovnikov gives predominantly secondary/tertiary products). In OC-15 these halogenoalkanes become starting materials for nucleophilic substitution and elimination reactions."},{"type":"takeaway","items":["Alkenes react via electrophilic addition — π electrons attack δ⁺ species.","Markovnikov: more stable carbocation wins → major product.","Br₂ addition goes through a cyclic bromonium ion → trans product.","Bromine water is THE diagnostic test for C=C.","The seven reactions of ethene must be known cold — reagent AND conditions."]}]},{"id":"h7","title":"Benzene — Structure & Stability","blocks":[{"type":"p","text":"Benzene is C₆H₆ — a planar, symmetric, six-carbon ring. Kekulé's 1865 structure drew it with alternating single and double bonds, but experiments showed all six C-C bonds are identical (139 pm — halfway between 154 pm single and 134 pm double). The modern picture: six p orbitals overlap sideways to form a delocalised π system — a ring of six electrons circulating above and below the ring plane."},{"type":"d","caption":"Two ways of drawing benzene"},{"type":"h","text":"Evidence for delocalisation"},{"type":"ul","items":["All C-C bonds equal length (139 pm).","Enthalpy of hydrogenation of benzene (-208 kJ/mol) is ~150 kJ/mol LESS exothermic than 3 × cyclohexene (-360 kJ/mol). This \\"missing\\" energy is the delocalisation energy — extra stability.","Benzene doesn't decolourise bromine water without a catalyst — it doesn't behave like a typical alkene."]},{"type":"callout","title":"Why benzene substitutes, not adds","body":"Addition would break the aromatic ring and lose ~150 kJ/mol of delocalisation stability. Substitution preserves the ring and only swaps one H for another group — much more favourable."},{"type":"takeaway","items":["Benzene = six-membered planar ring with 6 delocalised π electrons.","All C-C bonds equivalent (139 pm). More stable than Kekulé predicts.","Reacts by substitution, NOT addition, to preserve aromaticity."]}]},{"id":"h8","title":"Reactions of Benzene","blocks":[{"type":"p","text":"Benzene undergoes electrophilic substitution: an electrophile (generated by a catalyst) replaces one of the H atoms on the ring. Every arene reaction follows the same three-step pattern: generate electrophile → electrophile attacks π → lose H⁺ to restore aromaticity."},{"type":"h","text":"Bromination"},{"type":"d","caption":"Br₂ + benzene with FeBr₃"},{"type":"h","text":"Nitration"},{"type":"d","caption":"Benzene + HNO₃ / H₂SO₄"},{"type":"h","text":"Catalytic hydrogenation (forcing conditions)"},{"type":"ul","items":["Conditions: H₂, Ni catalyst, 150 °C AND HIGH PRESSURE (~30 atm).","Product: cyclohexane C₆H₁₂.","Contrast with alkenes: hydrogenation of ethene needs only 1 atm H₂ at 150 °C. The extra pressure reflects benzene's extra stability."]},{"type":"takeaway","items":["Benzene always reacts by electrophilic substitution, preserving aromaticity.","Mechanism always: electrophile generated by catalyst → attacks π → H⁺ lost.","Hydrogenation of benzene is possible but requires high pressure."]}]},{"id":"h9","title":"Methylbenzene — Directing Effects","blocks":[{"type":"p","text":"When a substituent is already on the benzene ring, it influences both where AND how fast further substitution occurs. Methylbenzene (C₆H₅CH₃, historically \\"toluene\\") has a -CH₃ group. This group changes everything — it steers incoming electrophiles to specific positions, and it accelerates the ring's reactivity overall."},{"type":"d","caption":"The -CH₃ group is a 2,4-director (ortho/para director)"},{"type":"h","text":"Where does the next substituent go?"},{"type":"ul","items":["Numbering: the -CH₃ is at position 1. The two carbons next to it (2 and 6) are ORTHO. The carbon opposite (4) is PARA. Positions 3 and 5 are META.","The -CH₃ group directs incoming electrophiles to the ORTHO (2) and PARA (4) positions.","Mixture: roughly 60 % para + 35 % ortho + 5 % meta (para dominates for steric reasons — ortho is crowded next to the methyl)."]},{"type":"h","text":"Why ortho and para?"},{"type":"p","text":"The -CH₃ group is electron-donating through the inductive effect (it pushes electron density onto the ring). This stabilises the intermediate cation (cyclohexadienyl cation) formed after electrophile attack — but only when the cation's positive charge sits at a position where the methyl group is directly next door. Drawing out the intermediate, the + charge falls on carbons 2, 4, 6 (ortho and para to the attacking position) when the electrophile attacks at ortho or para, but on 1, 3, 5 (including meta) when attack is at meta. Only the ortho and para intermediates have the + charge adjacent to the methyl, so only they are stabilised. Meta is disfavoured."},{"type":"h","text":"Why faster than benzene?"},{"type":"p","text":"Same reason, simpler statement: the electron-donating -CH₃ raises the electron density in the ring. Higher electron density means the ring is more nucleophilic and more attractive to electrophiles. Methylbenzene brominates roughly 600 times faster than benzene and can undergo some reactions at milder conditions."},{"type":"h","text":"Nitration of methylbenzene"},{"type":"ul","items":["Conditions: conc. HNO₃ / conc. H₂SO₄ / 30 °C (LOWER than 55 °C used for benzene — because methylbenzene is more reactive).","Major products: 2-nitromethylbenzene and 4-nitromethylbenzene (ortho and para).","Overall: C₆H₅CH₃ + HNO₃ → CH₃C₆H₄NO₂ + H₂O."]},{"type":"h","text":"Ring bromination of methylbenzene"},{"type":"ul","items":["Conditions: Br₂, FeBr₃ (or AlBr₃) catalyst, dark, room temp.","Major products: 2-bromomethylbenzene and 4-bromomethylbenzene (ortho and para).","Can stop at monosubstitution or go further with more Br₂."]},{"type":"callout","title":"Activating vs deactivating groups","body":"Electron-donating groups (-CH₃, -OH, -NH₂, -OR) activate the ring and direct to ortho/para. Electron-withdrawing groups (-NO₂, -COOH, -CN, -SO₃H) deactivate the ring and direct to meta. This is worth knowing even though full coverage comes later in other topics."},{"type":"takeaway","items":["-CH₃ is an activating, ortho/para-directing group.","Reason: inductive electron donation stabilises intermediates where + charge is adjacent to CH₃.","Methylbenzene reacts faster than benzene under milder conditions.","Expect a mixture of ortho + para products (para usually majors)."]}]},{"id":"h10","title":"Ring vs Side-Chain Halogenation","blocks":[{"type":"p","text":"Methylbenzene has TWO sites where chlorine (or bromine) could attack: the ring, and the methyl side chain. Which one wins depends entirely on conditions. Get this wrong in an exam and you lose marks — the syllabus specifically flags this as a skill to master."},{"type":"d","caption":"Same reactants, different conditions, different products"},{"type":"h","text":"The two outcomes"},{"type":"ul","items":["RING halogenation — happens with a halogen carrier catalyst (FeCl₃, FeBr₃, AlCl₃), in the dark, cold. Mechanism: electrophilic substitution on the ring. Product: 2- or 4-chloromethylbenzene (o/p mixture).","SIDE-CHAIN halogenation — happens with UV light, NO catalyst, often hotter. Mechanism: free-radical substitution on the CH₃. Product: (chloromethyl)benzene, C₆H₅CH₂Cl."]},{"type":"h","text":"Why the split?"},{"type":"p","text":"A halogen carrier (FeCl₃) polarises Cl₂ into Cl⁺ + FeCl₄⁻. The Cl⁺ cation is an electrophile that attacks the most electron-rich site in the molecule — the π cloud of the aromatic ring. Without a catalyst but with UV, the Cl-Cl bond undergoes homolysis instead to give Cl• radicals. Radicals are unselective toward π clouds but highly selective toward the weakest C-H bonds. The C-H bonds on the CH₃ side chain (benzylic position) are weaker than those on the ring, because the resulting benzyl radical is resonance-stabilised by the ring. So radicals preferentially abstract benzylic Hs."},{"type":"callout","title":"Predicting the product — quick rules","body":"See a catalyst (FeCl₃, AlBr₃) mentioned? → RING substitution, o/p products. See \\"UV light\\" or \\"in sunlight\\"? → SIDE-CHAIN substitution. See neither? → probably no reaction under those conditions."},{"type":"callout","title":"Further halogenation of the side chain","body":"The side-chain product (C₆H₅CH₂Cl) can react with more Cl₂ under continued UV to give C₆H₅CHCl₂ (benzal chloride) then C₆H₅CCl₃ (benzotrichloride). Progressive substitution analogous to methane → CH₂Cl₂ → CHCl₃ → CCl₄."},{"type":"takeaway","items":["Halogen carrier + dark + cold → RING (electrophilic substitution).","UV + no catalyst → SIDE CHAIN (free-radical substitution).","The benzyl C-H bonds are weaker (resonance-stabilised radical) → radicals prefer them.","Read the conditions before you predict the product."]}]},{"id":"h11","title":"Side-Chain Oxidation","blocks":[{"type":"p","text":"The aromatic ring itself is remarkably resistant to oxidation — it survives most oxidising agents unchanged. But any alkyl side chain attached to the ring is vulnerable. Under strong oxidising conditions, the entire alkyl chain is stripped back to a single -COOH group, no matter how long the chain was. This is a powerful synthesis method and a common exam question."},{"type":"h","text":"The reaction"},{"type":"ul","items":["Reagents: hot alkaline KMnO₄, followed by acidification with dilute H₂SO₄.","C₆H₅-CH₃ (methylbenzene) → C₆H₅-COOH (benzoic acid).","C₆H₅-CH₂-CH₃ (ethylbenzene) → C₆H₅-COOH (benzoic acid!) — the ethyl chain is cleaved back.","C₆H₅-CH(CH₃)₂ (isopropylbenzene) → C₆H₅-COOH — same story.","Benzene itself — no reaction. No side chain, no -COOH."]},{"type":"callout","title":"The mechanism shortcut","body":"The benzylic C-H (attached to the carbon directly connected to the ring) is weaker than average, so it is attacked first. Once the first C-H is broken, successive oxidation keeps stripping atoms until you're left with just -COOH. The ring itself is untouched."},{"type":"callout","title":"Quaternary carbons resist","body":"If the benzylic carbon has NO hydrogens (e.g. tert-butylbenzene, C₆H₅-C(CH₃)₃), there is no benzylic H to abstract — the side chain is inert to KMnO₄. No -COOH forms."},{"type":"takeaway","items":["Hot alkaline KMnO₄ + H⁺ workup → any side chain with benzylic H becomes -COOH.","Ring itself is unreactive to oxidation at A-level.","No benzylic H (e.g. tert-butyl) → no reaction."]}]},{"id":"h12","title":"Industrial Uses & Environmental Impact","blocks":[{"type":"p","text":"Hydrocarbons are the foundation of the modern chemical industry. Every time you put fuel in a car, use a plastic bag, eat margarine, or drink industrial ethanol, you're using chemistry from this topic. This chapter links the lab reactions to real-world products and their environmental cost."},{"type":"h","text":"Industrial products from the reactions you know"},{"type":"ul","items":["Catalytic hydrogenation of alkenes → margarine. Unsaturated vegetable oils (liquid) are \\"hardened\\" by partial hydrogenation into semi-solid fats for spreads.","Hydration of ethene (H₃PO₄, 300 °C, 60 atm) → industrial ethanol for solvents, fuel blends, disinfectants.","Polymerisation of alkenes → plastics. Polythene (ethene), polypropene (propene), PVC (chloroethene), polystyrene (phenylethene), PTFE/Teflon (tetrafluoroethene).","Nitration of benzene → nitrobenzene → reduction (Sn/HCl) → aniline (phenylamine) → azo dyes and pharmaceutical intermediates.","Side-chain oxidation of methylbenzene → benzoic acid → food preservative (E210), part of salicylic-acid synthesis (aspirin)."]},{"type":"h","text":"Environmental concerns — combustion"},{"type":"ul","items":["Carbon dioxide (CO₂) — from complete combustion. Principal greenhouse gas driving climate change.","Carbon monoxide (CO) — from incomplete combustion. Binds haemoglobin ~250× stronger than O₂ → tissue hypoxia → death at high exposure.","Particulates (soot, C) — from very incomplete combustion. Respiratory and cardiovascular disease; visible as black smoke.","Oxides of nitrogen (NOₓ) — from the high combustion temperature, not from the fuel itself. Cause acid rain (with SO₂) and photochemical smog.","Unburnt hydrocarbons — escape into the atmosphere, react with NOₓ in sunlight to form ground-level ozone (smog) and PAN (peroxyacyl nitrates)."]},{"type":"h","text":"Mitigation — catalytic converters"},{"type":"p","text":"Modern cars fit three-way catalytic converters (Pt/Rh on ceramic honeycomb) that simultaneously: oxidise CO to CO₂, oxidise unburnt hydrocarbons to CO₂ and H₂O, and reduce NOₓ back to N₂. They do nothing about CO₂ itself, which is the main climate concern."},{"type":"h","text":"Environmental concerns — polymers"},{"type":"ul","items":["Non-biodegradable — C-C backbones are inert; polymers persist in landfills and oceans for centuries.","Microplastics — photodegradation breaks polymers into micro-fragments that enter the food chain.","Incineration — releases CO₂ (greenhouse); incinerating PVC produces HCl and dioxins.","Recycling — sorting is difficult (different polymer types don't mix); usually downcycled rather than properly recycled."]},{"type":"callout","title":"Greener alternatives","body":"Biofuels (ethanol from fermentation, biodiesel from vegetable oils), bioplastics (polylactic acid from corn starch, starch-based plastics), electrification (EVs shift emissions to the grid). Each has its own trade-offs — a common exam discussion point."},{"type":"takeaway","items":["Know one industrial use for each of the six ethene reactions.","Combustion pollutants: CO₂, CO, soot, NOₓ, unburnt hydrocarbons.","Catalytic converters fix CO, unburnt HCs, NOₓ — NOT CO₂.","Polymers: environmental cost is non-biodegradability."]}]},{"id":"h13","title":"Reaction Summary & Exam Technique","blocks":[{"type":"p","text":"This chapter is the one-page cheat sheet you use two nights before the exam. It's all reagents and conditions — the details you must know exactly."},{"type":"h","text":"Alkanes (ethane exemplar)"},{"type":"ul","items":["Combustion — excess O₂ → CO₂ + H₂O; limited O₂ → CO and/or C soot.","Chlorination — Cl₂ + UV light → C₂H₅Cl + HCl. Free-radical mechanism."]},{"type":"h","text":"Alkenes (ethene exemplar — SEVEN reactions)"},{"type":"ul","items":["Halogenation — Br₂ or Cl₂ → 1,2-dihaloethane. Decolourises Br₂(aq). Bromonium ion mechanism.","Hydrohalogenation — HBr (or HCl) → haloethane. Markovnikov if unsymmetrical.","Hydrogenation — H₂ + Ni, 150 °C → ethane. Used for margarine.","Hydration — H₂O(g) + H₃PO₄, 300 °C, 60 atm → ethanol.","Cold dilute alkaline KMnO₄ → diol. Purple → green/brown.","Hot conc. acidic KMnO₄ → cleavage to CO₂ + HCOOH.","Polymerisation — high P, trace O₂ → polyethene."]},{"type":"h","text":"Arenes (benzene + methylbenzene)"},{"type":"ul","items":["Bromination — Br₂ + FeBr₃, dark, cold → bromobenzene (or o/p-bromomethylbenzene).","Nitration — conc. HNO₃ / conc. H₂SO₄ / 55 °C (or 30 °C for methylbenzene) → nitroarene.","Hydrogenation — H₂ + Ni, 150 °C, HIGH pressure → cyclohexane.","Side-chain halogenation — Cl₂ + UV, no catalyst → (chloromethyl)benzene.","Side-chain oxidation — hot alkaline KMnO₄ → benzoic acid (any alkyl side chain with benzylic H)."]},{"type":"callout","title":"Exam trap #1 — bromine water test","body":"If a hydrocarbon decolourises bromine WATER WITHOUT a catalyst at room temperature, it's an alkene (has C=C). Benzene alone does not."},{"type":"callout","title":"Exam trap #2 — conditions change everything","body":"Same reactants (Cl₂ + methylbenzene) give different products at different conditions. ALWAYS state conditions. KMnO₄ has two sets of products depending on temperature and concentration — always specify which."},{"type":"callout","title":"Exam trap #3 — ortho/para direction","body":"When a ring already has an electron-donating group (-CH₃, -OH, -NH₂), the products are o/p mixtures, not a single compound. Write all major isomers."}]}]}`),transition:JSON.parse(`{"objectives":["Define a transition element in terms of d-block and partially-filled d subshell","Write electronic configurations of first-row transition elements and their ions","Compare physical properties of transition metals with calcium (typical s-block)","Explain variable oxidation states in terms of 3d/4s energy similarity","Describe complex ions: coordinate bonds, shapes (octahedral, tetrahedral, square planar, linear)","Identify types of isomerism in complexes (cis/trans, optical)","Explain ligand exchange and stability constants; apply the chelate effect","Explain the origin of colour in transition complexes (d-orbital splitting)","Relate magnetic properties to unpaired d electrons","Describe the chemistry, occurrence, and uses of V, Cr, Mn, Fe, Co, Ni, Cu","Describe the extraction and importance of platinum group metals"],"chapters":[{"id":"t1","title":"What Defines a Transition Element","blocks":[{"type":"p","text":"A d-block element is any element whose highest-energy electrons go into a d orbital. Not every d-block element is a transition element though — the syllabus-level definition is sharper."},{"type":"callout","title":"Transition element","body":"A d-block element that forms at least one stable ion with a partially-filled d subshell."},{"type":"h","text":"The exclusions"},{"type":"ul","items":["Scandium (Sc) — only forms Sc³⁺, which has a 3d⁰ configuration. No partially-filled d. Not a true TM.","Zinc (Zn) — only forms Zn²⁺, which is 3d¹⁰. Fully-filled d subshell, not partially filled. Not a true TM.","Sc and Zn are d-block but not transition elements. A common exam trap."]},{"type":"h","text":"The four characteristic properties"},{"type":"ul","items":["Variable oxidation states (e.g. Fe²⁺ and Fe³⁺, or Mn going +2, +4, +6, +7).","Form coloured ions and compounds.","Show catalytic activity (as elements and as ions).","Form complex ions with ligands."]},{"type":"callout","title":"These properties come from one source","body":"All four arise because transition elements have an incomplete d subshell in the ion. It's the partially-filled d electrons that give variable oxidation states, the d-d transitions that give colour, the empty d orbitals that allow ligand binding, and the variable oxidation states that enable catalysis."},{"type":"takeaway","items":["Transition metal = d-block + at least one ion with partly filled d.","Sc and Zn fail the test — they're d-block but NOT transition elements.","Four characteristic behaviours all trace back to partially-filled d orbitals."]}]},{"id":"t2","title":"Electronic Configurations","blocks":[{"type":"p","text":"Across the first-row transition series (Sc to Zn), the 3d subshell is being progressively filled. Two elements break the smooth pattern because half-filled and fully-filled d subshells are extra stable."},{"type":"d","caption":"Configurations across the first row"},{"type":"h","text":"Forming ions — 4s leaves first"},{"type":"p","text":"Even though 4s fills before 3d in the neutral atom (because 4s is slightly lower in energy), the 4s electrons leave FIRST when the atom is ionised. This is because once 3d starts filling, the 3d electrons actually become lower in energy than 4s."},{"type":"ul","items":["Fe:    [Ar] 3d⁶ 4s²      →    Fe²⁺: [Ar] 3d⁶      (remove both 4s)","Fe²⁺:  [Ar] 3d⁶          →    Fe³⁺: [Ar] 3d⁵      (then remove one 3d)","Cu:    [Ar] 3d¹⁰ 4s¹     →    Cu⁺:  [Ar] 3d¹⁰      (remove one 4s)","Cu⁺:   [Ar] 3d¹⁰         →    Cu²⁺: [Ar] 3d⁹      (then remove one 3d)"]},{"type":"callout","title":"Cr and Cu anomalies","body":"Cr is [Ar] 3d⁵ 4s¹ (not 3d⁴ 4s²) because a half-filled d subshell is unusually stable. Cu is [Ar] 3d¹⁰ 4s¹ (not 3d⁹ 4s²) because a fully-filled d subshell is unusually stable."},{"type":"takeaway","items":["4s fills first, but 4s empties first — write configurations accordingly.","Cr (3d⁵ 4s¹) and Cu (3d¹⁰ 4s¹) are anomalies — memorise these.","Common transition ions: Fe²⁺/Fe³⁺, Cu⁺/Cu²⁺, Mn²⁺ to Mn⁷⁺, Cr³⁺/Cr⁶⁺."]}]},{"id":"t3","title":"Physical Properties vs Calcium","blocks":[{"type":"p","text":"Transition metals are dense, hard, high-melting, and good conductors. Compared to calcium (a typical s-block metal sitting immediately before the TM series), the differences are striking — all traceable to d-electron involvement in metallic bonding."},{"type":"d","caption":"Physical-property contrast with Ca"},{"type":"h","text":"Why TMs are denser, harder, higher-melting"},{"type":"ul","items":["In Ca, only 4s electrons contribute to metallic bonding (two electrons per atom in the \\"sea\\").","In TMs, BOTH 4s and 3d electrons delocalise into the metallic bond. More delocalised electrons → stronger metallic bonds → higher m.p., higher density.","Atomic radii are smaller than Ca because nuclear charge is higher while electrons are added to the same inner shell."]},{"type":"h","text":"Why IE and atomic radius are relatively INVARIANT across the series"},{"type":"p","text":"Nuclear charge rises steadily across the period (+1 per element), pulling electrons inward. But the added electrons go into the 3d subshell — INSIDE the 4s. They shield the 4s electrons from the extra nuclear charge. The two effects roughly cancel, so first IE and atomic radius change only gradually from Sc to Zn. Contrast: across Period 3 (s and p block), IE and radius change dramatically."},{"type":"takeaway","items":["TMs: higher m.p./b.p., denser, smaller, less reactive than Ca.","Cause: d electrons add to metallic bonding.","First IE and atomic radius are relatively constant across first-row TMs."]}]},{"id":"t4","title":"Variable Oxidation States","blocks":[{"type":"p","text":"Transition elements form ions in multiple oxidation states because the energies of 4s and 3d electrons are similar — small amounts of energy can strip 3d electrons after the 4s are gone. The number and nature of accessible oxidation states depends on the element."},{"type":"h","text":"Common oxidation states"},{"type":"ul","items":["Ti — mainly +4 (TiO₂, TiCl₄)","V — +2, +3, +4, +5 (colour-rich chemistry)","Cr — +3 most stable; +6 (chromate CrO₄²⁻, dichromate Cr₂O₇²⁻)","Mn — +2 (most stable), +4 (MnO₂), +6 (MnO₄²⁻), +7 (MnO₄⁻)","Fe — +2, +3 (both important; +3 more stable in air)","Co — +2 most common, +3 in some complexes","Ni — +2 almost exclusively","Cu — +1 (unstable in water — disproportionates), +2 (most stable)"]},{"type":"callout","title":"Oxidation states rise left to right — then drop","body":"Maximum oxidation state peaks at Mn (+7 = all 7 valence electrons lost). After Mn, the 3d electrons are held too tightly by the increasing nuclear charge to be removed easily — so Fe goes only to +6 (rare), Co to +3, Ni to +2, Cu to +2."},{"type":"takeaway","items":["Variable oxidation states = multiple outer electrons at similar energies.","Maximum oxidation state peaks at Mn (+7), then declines.","+2 is a common oxidation state for most first-row TMs (from removing both 4s)."]}]},{"id":"t5","title":"Complex Ions — Bonding & Shape","blocks":[{"type":"p","text":"A complex ion is a transition-metal ion bonded to ligands. The bonds are dative (coordinate) — both electrons come from the ligand, donated into empty d orbitals on the metal. The number of ligands is the coordination number."},{"type":"callout","title":"Ligand","body":"A molecule or ion with a lone pair that can be donated to form a dative bond with a metal centre. Examples: H₂O, NH₃, Cl⁻, CN⁻, OH⁻."},{"type":"h","text":"Types of ligand"},{"type":"ul","items":["Monodentate — donates ONE lone pair. e.g. H₂O, NH₃, Cl⁻, CN⁻.","Bidentate — donates TWO lone pairs at two sites. e.g. ethylenediamine (en), ethanedioate (oxalate).","Polydentate (chelating) — donates multiple lone pairs. e.g. EDTA is hexadentate (6 donor sites)."]},{"type":"h","text":"Common shapes"},{"type":"d","caption":"Octahedral — 6 ligands (most common)"},{"type":"d","caption":"Tetrahedral — 4 ligands (especially with large ligands)"},{"type":"d","caption":"Square planar — 4 ligands (common for d⁸ ions like Ni²⁺, Pt²⁺)"},{"type":"callout","title":"Predicting the shape","body":"Coordination 6 → octahedral. Coordination 4 with small ligands → tetrahedral (e.g. [CoCl₄]²⁻ with Cl⁻). Coordination 4 with d⁸ metal → square planar (e.g. [Ni(CN)₄]²⁻, [PtCl₄]²⁻). Coordination 2 → linear (e.g. [Ag(NH₃)₂]⁺)."},{"type":"takeaway","items":["Complex = metal + ligands with dative bonds.","Coord 6 → octahedral; coord 4 → tetrahedral or square planar; coord 2 → linear.","d⁸ metals tend to be square planar."]}]},{"id":"t6","title":"Isomerism in Complexes","blocks":[{"type":"p","text":"Complexes with two or more different ligands can exist as different arrangements in space. Three types of isomerism matter at this level."},{"type":"h","text":"Cis / trans (geometric) isomerism"},{"type":"p","text":"Appears in square-planar complexes with two different kinds of ligand, and in octahedral complexes of the type [ML₄L'₂]."},{"type":"d","caption":"cis vs trans [Pt(NH₃)₂Cl₂] — one form is an anti-cancer drug, the other is not"},{"type":"h","text":"Optical isomerism"},{"type":"p","text":"Complexes with three bidentate ligands (e.g. [Ni(en)₃]²⁺) exist as non-superimposable mirror images — just like the classic tetrahedral carbon case in organic chemistry. The two forms rotate plane-polarised light in opposite directions."},{"type":"h","text":"Why it matters"},{"type":"ul","items":["cis-[Pt(NH₃)₂Cl₂] (cisplatin) binds DNA → used as a chemotherapy drug.","trans-[Pt(NH₃)₂Cl₂] is biologically inactive — the geometry changes function.","Stereochemistry of complexes is essential in modern medicinal chemistry."]},{"type":"takeaway","items":["cis/trans: square planar + octahedral complexes with different ligands.","Optical: complexes with ≥ 3 bidentate ligands form enantiomer pairs.","Geometry changes function — cisplatin is the textbook example."]}]},{"id":"t7","title":"Ligand Exchange & Stability Constants","blocks":[{"type":"p","text":"Ligands in a complex are not permanently attached. They can be swapped for other ligands if the new arrangement is more thermodynamically stable. The equilibrium constant for the exchange is called a stability constant (Kstab)."},{"type":"h","text":"Example — Cu²⁺"},{"type":"ul","items":["[Cu(H₂O)₆]²⁺ (pale blue) + 4NH₃ ⇌ [Cu(NH₃)₄(H₂O)₂]²⁺ (deep blue) + 4H₂O     (NH₃ displaces 4 H₂O)","[Cu(H₂O)₆]²⁺ + 4Cl⁻ ⇌ [CuCl₄]²⁻ (yellow-green) + 6H₂O     (Cl⁻ gives tetrahedral complex, changes colour AND shape)"]},{"type":"callout","title":"Stability constant (Kstab)","body":"The equilibrium constant for the formation of a complex from the aqua complex. A large Kstab means the product complex is very stable — the new ligand holds on tightly."},{"type":"h","text":"Typical Kstab values"},{"type":"ul","items":["[Cu(NH₃)₄(H₂O)₂]²⁺   Kstab ≈ 1.3 × 10¹³  (very stable)","[CuCl₄]²⁻                Kstab ≈ 4.2 × 10⁵  (moderately stable)","[CuEDTA]²⁻              Kstab ≈ 6.3 × 10¹⁸  (extremely stable — EDTA wraps around in 6 positions)"]},{"type":"callout","title":"Chelate effect","body":"Polydentate ligands (EDTA, en) form much more stable complexes than the equivalent number of monodentate ligands. Reason: entropy. One EDTA replaces 6 water molecules — six particles become seven (EDTA + 6 free H₂O) → ΔS is large and positive → ΔG more negative."},{"type":"takeaway","items":["Ligands exchange if the new complex is more stable (higher Kstab).","Polydentate ligands form very stable (chelate) complexes — entropy driver.","Ligand exchange can change colour AND shape simultaneously."]}]},{"id":"t8","title":"Colour of Transition Complexes","blocks":[{"type":"p","text":"When a ligand approaches a transition-metal ion, the five d orbitals that were degenerate (same energy) in the isolated ion are split into groups of slightly different energies. An electron can absorb a photon of visible light to jump from a lower to higher d orbital — the absorbed colour is removed from white light, and we see the complementary colour."},{"type":"d","caption":"d-orbital splitting in an octahedral field"},{"type":"d","caption":"Absorbed colour → complementary colour seen"},{"type":"h","text":"What sets the size of the splitting (Δ)?"},{"type":"ul","items":["Nature of the ligand — strong-field ligands (CN⁻, CO) cause large Δ → absorb high-energy blue/violet → complex looks red/orange. Weak-field ligands (F⁻, H₂O) cause small Δ → absorb red → complex looks blue-green.","Oxidation state of metal — higher oxidation state → larger Δ (electrons more tightly held).","Geometry — octahedral gives larger Δ than tetrahedral (same ligands)."]},{"type":"h","text":"The spectrochemical series (rough ligand-strength ranking)"},{"type":"p","text":"I⁻ < Br⁻ < Cl⁻ < F⁻ < OH⁻ < H₂O < NH₃ < en < CN⁻ < CO      (weak → strong field)"},{"type":"callout","title":"Why colour changes on ligand exchange","body":"Different ligands give different Δ values → different photons absorbed → different complementary colour seen. That's why [Cu(H₂O)₆]²⁺ is pale blue, [Cu(NH₃)₄(H₂O)₂]²⁺ is deep blue, and [CuCl₄]²⁻ is yellow-green."},{"type":"callout","title":"Why Sc³⁺, Zn²⁺, Cu⁺ are colourless","body":"No partly-filled d subshell means no d-d transition is possible. Sc³⁺ is d⁰, Zn²⁺ and Cu⁺ are d¹⁰. All three are colourless in solution."},{"type":"takeaway","items":["Colour comes from d-d electron transitions.","Δ depends on ligand strength, metal oxidation state, geometry.","Complementary-colour rule: seen ≈ complement of absorbed.","d⁰ and d¹⁰ ions are colourless."]}]},{"id":"t9","title":"Catalysis & Magnetism","blocks":[{"type":"h","text":"Catalytic activity"},{"type":"p","text":"Transition elements are excellent catalysts, in elemental form (heterogeneous) and as ions (homogeneous). Two reasons: variable oxidation states allow the catalyst to be both oxidised and reduced during a reaction cycle; the d orbitals can accept and donate electrons flexibly."},{"type":"h","text":"Important industrial examples"},{"type":"ul","items":["Fe — Haber process (N₂ + 3H₂ ⇌ 2NH₃). Heterogeneous, reactants adsorb on iron surface.","V₂O₅ — Contact process (2SO₂ + O₂ → 2SO₃). V₂O₅ oxidises SO₂ to SO₃, becomes V₂O₄, re-oxidised by O₂.","Ni — Catalytic hydrogenation of alkenes to alkanes (and oils to margarine).","Pt / Rh / Pd — three-way catalytic converter in cars; also hydrogenations and Haber-process alternatives.","MnO₂ — decomposition of H₂O₂ in the lab; Mn²⁺ catalyses redox of S₂O₈²⁻ + I⁻."]},{"type":"callout","title":"Homogeneous catalysis — change in oxidation state","body":"In Mn²⁺ catalysis of S₂O₈²⁻ + 2I⁻ → 2SO₄²⁻ + I₂: Mn²⁺ is oxidised to Mn³⁺ by S₂O₈²⁻, then Mn³⁺ reduces I⁻ to I₂, regenerating Mn²⁺. The catalyst shuttles between two oxidation states."},{"type":"h","text":"Magnetic properties"},{"type":"p","text":"The magnetic behaviour of a complex depends on the number of unpaired electrons in its d subshell."},{"type":"ul","items":["Diamagnetic — all d electrons paired. Weakly repelled by a magnetic field.","Paramagnetic — some d electrons unpaired. Weakly attracted to a magnetic field. Magnetic moment increases with more unpaired electrons."]},{"type":"h","text":"Predicting unpaired electrons"},{"type":"ul","items":["Zn²⁺ (d¹⁰) — 0 unpaired. Diamagnetic.","Cu²⁺ (d⁹) — 1 unpaired. Paramagnetic.","Fe²⁺ (d⁶) — up to 4 unpaired (high-spin) or 0 (low-spin). Depends on ligand.","Fe³⁺ (d⁵) — up to 5 unpaired. Strongly paramagnetic."]},{"type":"callout","title":"High-spin vs low-spin","body":"Weak ligands (H₂O, F⁻) give small Δ — electrons spread out to follow Hund's rule → high-spin → more unpaired. Strong ligands (CN⁻, CO) give large Δ — pairing is cheaper than jumping to the upper set → low-spin → fewer unpaired."},{"type":"takeaway","items":["Catalysis: variable oxidation states + flexible d-orbital involvement.","Paramagnetism scales with unpaired d electrons.","Strong ligands → low-spin; weak ligands → high-spin."]}]},{"id":"t10","title":"Vanadium — Colourful Redox","blocks":[{"type":"p","text":"Vanadium is the poster child for variable oxidation states — four common states, each a different colour. Reduction of VO₂⁺ (+5) with zinc in acid can be followed by colour through yellow → blue → green → violet."},{"type":"d","caption":"V oxidation states — one of the most-tested patterns"},{"type":"h","text":"Occurrence and uses"},{"type":"ul","items":["Occurs as vanadinite Pb₅(VO₄)₃Cl and carnotite K₂(UO₂)₂(VO₄)₂.","Ferrovanadium alloy — high-strength steels (tools, engine parts).","V₂O₅ — industrial catalyst in the Contact process for sulphuric acid (explains why vanadium is critical despite being rare)."]},{"type":"callout","title":"Observing the redox","body":"Add Zn metal to acidified VO₂⁺(aq). Yellow slowly turns blue (VO²⁺), then green (V³⁺), then pale violet (V²⁺). Each step is a one-electron reduction. Reverse by oxidising with KMnO₄ or air."}]},{"id":"t11","title":"Chromium — +3 and +6","blocks":[{"type":"p","text":"Chromium's important oxidation states at A-level are +3 (stable, green or violet) and +6 (yellow chromate or orange dichromate — strong oxidising agents)."},{"type":"h","text":"Chromate ⇌ dichromate equilibrium"},{"type":"d","caption":"Interconversion controlled by pH"},{"type":"ul","items":["2 CrO₄²⁻(aq) + 2 H⁺(aq) ⇌ Cr₂O₇²⁻(aq) + H₂O(l)","Add acid → shift right → orange (dichromate).","Add alkali → shift left → yellow (chromate).","Both species are Cr(VI). No change in oxidation state — only in structure."]},{"type":"h","text":"Dichromate as oxidising agent"},{"type":"p","text":"In acidic solution, Cr₂O₇²⁻ is reduced from orange (+6) to green Cr³⁺ (+3). Half-equation: Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O. Useful for oxidising:"},{"type":"ul","items":["Primary alcohols → aldehydes → carboxylic acids.","Secondary alcohols → ketones.","SO₂ → SO₄²⁻. Can be used as a test for SO₂: orange-to-green colour change.","Alcohol in breathalysers (traditional yellow-to-green test)."]},{"type":"h","text":"Occurrence and uses"},{"type":"ul","items":["Ore: chromite, FeCr₂O₄.","Used in stainless steel (Cr + Ni + Fe) — Cr forms a protective Cr₂O₃ layer.","Chrome plating — decorative and corrosion-resistant coating.","Cr₂O₃ as a green pigment; Cr₂O₇²⁻ historically as a cleaning oxidant (largely phased out due to Cr(VI) toxicity)."]},{"type":"callout","title":"Cr(VI) is toxic","body":"Chromates and dichromates are carcinogenic. Modern chemistry tries to avoid Cr(VI) oxidants, preferring greener alternatives (Jones oxidation replaced by Dess-Martin, etc.)."}]},{"id":"t12","title":"Manganese — The Redox Workhorse","blocks":[{"type":"p","text":"Manganese shows +2, +4, +6, +7. The most useful in the lab is MnO₄⁻ (permanganate), a dark purple strong oxidising agent."},{"type":"d","caption":"Key Mn oxidation states"},{"type":"h","text":"Permanganate as oxidising agent (acidic conditions)"},{"type":"ul","items":["Half-equation: MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O  (E° = +1.51 V)","Colour change: intense purple → almost colourless (Mn²⁺ pale pink).","Self-indicating in titrations — the first persistent pink marks the endpoint.","Used in titrations of: Fe²⁺ (→ Fe³⁺), ethanedioic acid (→ CO₂), H₂O₂ (→ O₂)."]},{"type":"h","text":"Disproportionation of MnO₄²⁻"},{"type":"p","text":"Manganate(VI) is unstable in acidic solution — it disproportionates into Mn(VII) and Mn(IV):"},{"type":"ul","items":["3 MnO₄²⁻ + 4 H⁺ → 2 MnO₄⁻ + MnO₂ + 2 H₂O","Same element (Mn) is both oxidised (+6 → +7) and reduced (+6 → +4).","MnO₂ is the brown-black solid (a classic disproportionation product)."]},{"type":"h","text":"MnO₂ as catalyst"},{"type":"p","text":"MnO₂ catalyses the decomposition of H₂O₂: 2 H₂O₂ → 2 H₂O + O₂. A safe classroom demonstration — add a pinch of MnO₂ to a bottle of dilute H₂O₂ and O₂ evolves vigorously."}]},{"id":"t13","title":"Iron — Extraction, Biology, Rusting","blocks":[{"type":"h","text":"Occurrence and extraction"},{"type":"p","text":"Iron ores include hematite (Fe₂O₃) and magnetite (Fe₃O₄). Extraction in a blast furnace uses coke (C), limestone (CaCO₃) and hot air:"},{"type":"ul","items":["C + O₂ → CO₂     (coke burns)","CO₂ + C → 2CO    (regeneration of reducing agent)","Fe₂O₃ + 3CO → 2Fe + 3CO₂   (reduction of ore)","CaCO₃ → CaO + CO₂   (decomposition of flux)","CaO + SiO₂ → CaSiO₃   (slag formation — removes impurities)"]},{"type":"h","text":"Fe²⁺ vs Fe³⁺ — tests and stability"},{"type":"ul","items":["Fe²⁺ + K₃[Fe(CN)₆] → deep blue (Turnbull's blue).","Fe³⁺ + K₄[Fe(CN)₆] → deep blue (Prussian blue).","Fe³⁺ + SCN⁻ → blood-red [Fe(SCN)(H₂O)₅]²⁺.","Fe²⁺ + NaOH(aq) → dirty-green Fe(OH)₂ ppt, darkens on standing (air-oxidation).","Fe³⁺ + NaOH(aq) → red-brown Fe(OH)₃ ppt."]},{"type":"callout","title":"Effect of pH and ligand on stability","body":"Fe³⁺ is more stable than Fe²⁺ in air (oxidised by O₂). BUT the standard electrode potential depends on the ligands. With CN⁻ ligand (strong field), [Fe(CN)₆]³⁻/[Fe(CN)₆]⁴⁻ has E° = +0.36 V — much less than Fe³⁺/Fe²⁺ (+0.77 V) — meaning CN⁻ stabilises Fe²⁺ more than Fe³⁺. Ligand choice changes which oxidation state is favoured."},{"type":"h","text":"Biological importance"},{"type":"d","caption":"Iron in haemoglobin"},{"type":"ul","items":["Haemoglobin — Fe²⁺ at the centre of a porphyrin ring, reversibly binding O₂ for transport.","Cytochromes — Fe²⁺/Fe³⁺ cycling in electron-transport chains (energy production).","Myoglobin — O₂ storage in muscle."]},{"type":"h","text":"Rusting"},{"type":"d","caption":"Electrochemical rusting needs O₂ AND water"},{"type":"h","text":"Rust prevention"},{"type":"ul","items":["Barrier methods — paint, grease, plastic coating, plating (Zn, Cr, Ni, Sn).","Galvanising — zinc coating. Zn is more reactive; even if scratched, Zn corrodes preferentially (sacrificial protection).","Cathodic protection — attach a block of Mg or Zn (sacrificial anode) to the iron; it oxidises in place of the iron. Used on ships, pipelines.","Alloying — stainless steel (Fe + Cr + Ni) forms passive Cr₂O₃ layer."]}]},{"id":"t14","title":"Co · Ni · Cu · Platinum Group Metals","blocks":[{"type":"h","text":"Cobalt — +2 and +3"},{"type":"d","caption":"Pink → blue cobalt on ligand/temperature change"},{"type":"ul","items":["[Co(H₂O)₆]²⁺ — pink, octahedral. Stable at room temperature in water.","[CoCl₄]²⁻ — blue, tetrahedral. Formed on adding conc. HCl and/or warming.","[Co(NH₃)₆]²⁺ — straw-coloured; oxidises in air to yellow [Co(NH₃)₆]³⁺ — NH₃ stabilises the +3 state.","Uses: alloys (alnico magnets), Vitamin B₁₂ (the only biologically essential Co compound), anhydrous CoCl₂ paper as a simple humidity/water indicator (blue → pink)."]},{"type":"h","text":"Nickel"},{"type":"ul","items":["Mainly +2 oxidation state; green [Ni(H₂O)₆]²⁺.","Extraction from pentlandite (Ni,Fe)₉S₈ — roasting, reduction, Mond process (volatilisation as Ni(CO)₄ then thermal decomposition).","Uses: stainless steel, alnico, coinage, Raney nickel and Ni/Al₂O₃ as hydrogenation catalysts (margarine, catalytic hydrogenation of alkenes)."]},{"type":"h","text":"Copper — +1 and +2"},{"type":"d","caption":"Cu⁺ disproportionation"},{"type":"ul","items":["Cu⁺ (d¹⁰) is colourless and unstable in water — disproportionates to Cu and Cu²⁺.","Cu⁺ is stabilised with certain ligands — CuI and [Cu(CN)₂]⁻ exist because of low solubility / strong ligand binding.","Cu²⁺ (d⁹) — the common state. Pale blue [Cu(H₂O)₆]²⁺; deep blue [Cu(NH₃)₄(H₂O)₂]²⁺; yellow-green [CuCl₄]²⁻."]},{"type":"h","text":"Cu²⁺ + I⁻ — unusual redox"},{"type":"p","text":"At first glance, Cu²⁺ should NOT oxidise I⁻ (E°(Cu²⁺/Cu⁺) = +0.15 V, E°(I₂/I⁻) = +0.54 V). But it does: 2Cu²⁺ + 4I⁻ → 2CuI(s) + I₂. Why? Because CuI is very insoluble — formation of solid CuI drives the equilibrium forward (Le Chatelier). Ligand/lattice effects on E° pay for the reaction."},{"type":"h","text":"Copper extraction & uses"},{"type":"ul","items":["Main ores: chalcopyrite (CuFeS₂), malachite (Cu₂CO₃(OH)₂).","Purification: electrolytic refining — impure Cu anode, pure Cu cathode, CuSO₄ electrolyte. Valuable impurities (Ag, Au) collect as anode slime.","Uses: electrical wiring (high conductivity), brass (Cu + Zn), bronze (Cu + Sn), Fehling's/Benedict's reagent for aldehydes (blue Cu²⁺ → brick-red Cu₂O)."]},{"type":"h","text":"Platinum Group Metals (PGMs)"},{"type":"ul","items":["Six elements: ruthenium, rhodium, palladium, osmium, iridium, platinum. Occur together in nature.","Main source: South African / Zimbabwean Great Dyke platinum-bearing ores; by-product of Ni mining.","Uses: catalytic converters (Pt/Pd/Rh), jewellery, electronics, industrial catalysts (Pt in Contact process before V₂O₅), medical (cisplatin for cancer chemotherapy).","High economic importance: PGMs are a significant export from Zimbabwe and South Africa."]},{"type":"takeaway","items":["Cobalt — pink H₂O, blue Cl⁻, NH₃ stabilises +3.","Nickel — almost always +2, major hydrogenation catalyst.","Copper — Cu⁺ disproportionates in water except when stabilised by special ligands.","PGMs — Zimbabwe's Great Dyke is a key world source."]}]}]}`),stoich:JSON.parse(`{"objectives":["Define and use relative atomic, isotopic, molecular and formula masses","Interpret mass spectra in terms of isotopic abundances and molecular fragments","Apply the mole concept and Avogadro constant","Determine empirical and molecular formulae from composition or combustion data","Construct balanced chemical equations including state symbols","Perform stoichiometric calculations involving masses, gas volumes, and solution concentrations","Carry out and analyse acid-base titrations including indicator choice","Calculate percentage yield and percentage purity"],"chapters":[{"id":"s1","title":"Relative Atomic, Isotopic, Molecular Mass","blocks":[{"type":"p","text":"Atomic masses are tiny — 10⁻²³ grams. Working with such numbers directly would be miserable, so chemists adopt RELATIVE masses on a scale where ¹²C = 12 exactly. The carbon-12 standard is just a definition; what matters is that all other atomic masses are then expressed as ratios to this."},{"type":"callout","title":"Relative atomic mass (Aᵣ)","body":"The weighted mean mass of an atom of an element, on a scale where the mass of one ¹²C atom is exactly 12. Has no units."},{"type":"callout","title":"Relative isotopic mass","body":"The mass of one isotope of an element relative to ¹²C = 12. Each isotope has a single isotopic mass; the element's Aᵣ is the weighted mean across all natural isotopes."},{"type":"callout","title":"Relative molecular mass (Mᵣ)","body":"The weighted mean mass of a molecule on the ¹²C scale. Found by adding the Aᵣ values of all atoms in the molecule."},{"type":"callout","title":"Relative formula mass","body":"Same idea as Mᵣ but used for ionic compounds (which have no discrete molecules). E.g. NaCl: 23 + 35.5 = 58.5."},{"type":"h","text":"Worked: H₂SO₄"},{"type":"p","text":"Mᵣ = 2(1) + 32 + 4(16) = 2 + 32 + 64 = 98."},{"type":"takeaway","items":["All masses are RELATIVE — on the ¹²C = 12 scale.","Aᵣ is the weighted mean over isotopes — usually NOT an integer.","Mᵣ = sum of Aᵣ values for all atoms in the formula."]}]},{"id":"s2","title":"Mass Spectra & Isotopic Abundances","blocks":[{"type":"p","text":"A mass spectrometer separates ionised particles by their mass-to-charge ratio (m/z). It tells us two important things: which isotopes an element has, and the exact masses of molecules and their fragments. The output is a graph of relative abundance vs m/z."},{"type":"d","caption":"Mass spectrum of chlorine (atoms and Cl₂ molecules)"},{"type":"h","text":"How a mass spectrometer works (overview)"},{"type":"ul","items":["IONISATION — the sample is bombarded with electrons (electron impact) or sprayed and protonated (electrospray). Result: positive ions.","ACCELERATION — a voltage accelerates the ions to a known kinetic energy.","DEFLECTION — a magnetic field bends the path; lighter ions deflect more.","DETECTION — a detector counts ions arriving at each m/z. Output: peaks at integer m/z values with relative heights = relative abundances."]},{"type":"h","text":"Reading the spectrum of an ELEMENT"},{"type":"p","text":"Each peak corresponds to one isotope of the element. Peak position = mass of the isotope (m/z, since z = +1 in most cases). Peak height = relative abundance. Use the data to calculate Aᵣ as a weighted mean."},{"type":"h","text":"Worked: chlorine"},{"type":"ul","items":["Two peaks: m/z = 35 (75 %) and m/z = 37 (25 %).","Aᵣ(Cl) = (35 × 75 + 37 × 25) / 100 = (2625 + 925) / 100 = 35.5.","Confirms the periodic-table value of 35.5."]},{"type":"h","text":"Reading the spectrum of a MOLECULE"},{"type":"p","text":"In addition to the isotope peaks at low m/z, a molecule also shows the molecular ion peak at m/z = Mᵣ — this is the parent molecule with one electron knocked off, M⁺. Fragments appear at lower m/z values (smaller pieces of the molecule). For Cl₂ you see peaks at m/z = 70 (³⁵Cl-³⁵Cl), 72 (³⁵Cl-³⁷Cl), 74 (³⁷Cl-³⁷Cl) in ratio 9:6:1 reflecting the 3:1 abundance ratio of the two Cl isotopes."},{"type":"callout","title":"M+1 peak from ¹³C","body":"Carbon is mostly ¹²C (98.9 %) but contains a small amount of ¹³C (1.1 %). For a molecule with n carbons, the M+1 peak is approximately 1.1 × n % of the M peak. Useful for counting carbons in unknown organics."},{"type":"callout","title":"M+2 peak signals Cl or Br","body":"A molecule containing one chlorine atom shows an M+2 peak about ⅓ the height of the M peak (³⁵Cl:³⁷Cl ≈ 3:1). One bromine: M+2 about equal to M (⁷⁹Br:⁸¹Br ≈ 1:1). This is a fast diagnostic."},{"type":"takeaway","items":["m/z = mass for singly-charged ions.","Peak height = relative abundance.","Aᵣ = Σ(mass × abundance) / 100.","M+1 hints at carbon count; M+2 signals Cl or Br."]}]},{"id":"s3","title":"The Mole and Avogadro Constant","blocks":[{"type":"p","text":"Atoms and molecules are too small to handle individually. Chemists use a counting unit, the mole, which packages exactly 6.022 × 10²³ particles together. The mole bridges the world of single atoms (which we cannot weigh) and the world of laboratory grams (which we can)."},{"type":"d","caption":"Definition of the mole"},{"type":"callout","title":"The mole","body":"A mole of any substance contains exactly Avogadro's number Nₐ = 6.022 × 10²³ elementary entities (atoms, molecules, ions, electrons — whichever is specified)."},{"type":"h","text":"Why 6.022 × 10²³?"},{"type":"p","text":"It is the number of carbon-12 atoms in exactly 12 grams of pure ¹²C. The unit was chosen so that the mass of one mole of an element in grams (the molar mass M) equals its relative atomic mass Aᵣ (a dimensionless number). This is a deliberate convenience."},{"type":"h","text":"Three key conversions"},{"type":"d","caption":"n = m / M"},{"type":"ul","items":["Mass ↔ moles:    n = m / M     (m in grams, M in g/mol)","Number ↔ moles:  N = n × Nₐ","Volume of gas ↔ moles (at RTP):  n = V / 24    (V in dm³)"]},{"type":"h","text":"Worked example"},{"type":"ul","items":["How many moles in 18 g of water?  n = 18 / 18 = 1 mol.","How many H₂O molecules?  N = 1 × 6.022 × 10²³ = 6.022 × 10²³.","How many H atoms?  Each H₂O has 2 H, so 2 × 6.022 × 10²³ = 1.2 × 10²⁴."]},{"type":"takeaway","items":["1 mol = Nₐ = 6.022 × 10²³ particles.","Molar mass M (g/mol) numerically equals Aᵣ or Mᵣ.","Master n = m/M — the gateway to all stoichiometry."]}]},{"id":"s4","title":"Empirical and Molecular Formulae","blocks":[{"type":"p","text":"The empirical formula is the simplest whole-number ratio of atoms in a compound. The molecular formula is the actual number of atoms in one molecule. Sometimes they are the same (CO₂); often they differ by a whole-number multiplier (empirical CH; molecular C₆H₆ = (CH)₆ for benzene)."},{"type":"d","caption":"The four-step procedure"},{"type":"h","text":"From composition by mass — worked"},{"type":"p","text":"A compound contains 40.0 % C, 6.7 % H, 53.3 % O. Find its empirical formula."},{"type":"ul","items":["STEP 1 — assume 100 g sample. Then 40.0 g C, 6.7 g H, 53.3 g O.","STEP 2 — divide by Aᵣ. nC = 40.0/12 = 3.33, nH = 6.7/1 = 6.7, nO = 53.3/16 = 3.33.","STEP 3 — divide by smallest (3.33). C : 1, H : 2.01, O : 1.","STEP 4 — round → CH₂O."]},{"type":"h","text":"From combustion data — worked"},{"type":"p","text":"Burning 1.50 g of an organic compound containing only C, H, and O gives 2.20 g CO₂ and 0.90 g H₂O. Find the empirical formula."},{"type":"ul","items":["Mass of C = 2.20 × (12/44) = 0.60 g (all C in CO₂ came from the compound).","Mass of H = 0.90 × (2/18) = 0.10 g (all H in H₂O came from the compound).","Mass of O in compound = 1.50 − 0.60 − 0.10 = 0.80 g.","Moles: C = 0.60/12 = 0.05, H = 0.10/1 = 0.10, O = 0.80/16 = 0.05.","Ratio: 1 : 2 : 1  →  empirical formula CH₂O."]},{"type":"h","text":"From empirical to molecular"},{"type":"p","text":"If you know the relative molecular mass Mᵣ:  ratio n = Mᵣ / (empirical-formula mass). Multiply each subscript in the empirical formula by n. Example: empirical CH₂O has mass 30. If Mᵣ = 180, then n = 180/30 = 6, so molecular formula is C₆H₁₂O₆ (glucose)."},{"type":"callout","title":"Common slip — non-integer ratios","body":"If after dividing by the smallest mole value you get something like 1 : 1.5, multiply ALL ratios by 2 to clear the fraction. 1 : 1.5 → 2 : 3. Don't round 1.5 to 2."},{"type":"takeaway","items":["Procedure: composition → moles → ratio → empirical.","Combustion: all C went to CO₂, all H went to H₂O, find O by difference.","Molecular = empirical × (Mᵣ ÷ empirical mass)."]}]},{"id":"s5","title":"Balanced Equations & Reaction Ratios","blocks":[{"type":"p","text":"A balanced chemical equation is the stoichiometric blueprint of a reaction. The coefficients tell you the mole ratio in which species react. Mass is always conserved — same total atoms either side. Charge is also conserved in ionic equations."},{"type":"d","caption":"Mass and atoms balance both sides"},{"type":"h","text":"Balancing — a simple workflow"},{"type":"ul","items":["Write reactants and products with correct formulae (don't alter formulae!).","Balance atoms one element at a time. Save H and O for last when an organic compound burns.","Use fractions if needed, then multiply to clear them.","Add state symbols (s), (l), (g), (aq) where required."]},{"type":"h","text":"Worked: combustion of propane"},{"type":"ul","items":["C₃H₈ + O₂ → CO₂ + H₂O.","Carbons: 3 CO₂. Hydrogens: 4 H₂O.","Oxygens on right: 3(2) + 4(1) = 10. Need 5 O₂.","Final: C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O."]},{"type":"h","text":"Reaction ratios — using the coefficients"},{"type":"p","text":"Once balanced, the coefficients ARE the mole ratio. For C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O: 1 mole of C₃H₈ requires 5 moles of O₂ and produces 3 moles of CO₂ and 4 moles of H₂O. Use this ratio to convert between any two reactants or products."},{"type":"h","text":"Worked: limiting reagent"},{"type":"p","text":"Mix 4 mol H₂ with 1 mol O₂ in 2H₂ + O₂ → 2H₂O. Which runs out first?"},{"type":"ul","items":["Stoichiometry needs 2 mol H₂ per 1 mol O₂.","4 mol H₂ requires 2 mol O₂. We only have 1 mol O₂. So O₂ is the limiting reagent.","O₂ runs out first; only 2 mol H₂ react; 2 mol H₂ left over; 2 mol H₂O produced."]},{"type":"callout","title":"Use the LIMITING reagent in calculations","body":"The limiting reagent dictates how much product can form. Excess reagent quantities are irrelevant for product calculation. Always identify limiting reagent first when amounts of both reactants are given."}]},{"id":"s6","title":"Calculations — Masses & Gas Volumes","blocks":[{"type":"p","text":"The link between balanced equations and laboratory measurements is the mole. The general workflow is: mass-or-volume → moles → use ratio → moles of unknown → mass-or-volume of unknown."},{"type":"d","caption":"Molar gas volume at standard conditions"},{"type":"h","text":"Worked: reacting masses"},{"type":"p","text":"What mass of CO₂ is produced when 11 g of propane is burned in excess oxygen?"},{"type":"ul","items":["Equation: C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O.","Moles of propane: n = 11 / 44 = 0.25 mol.","Ratio C₃H₈ : CO₂ = 1 : 3, so moles of CO₂ = 0.25 × 3 = 0.75 mol.","Mass of CO₂: m = n × M = 0.75 × 44 = 33 g."]},{"type":"h","text":"Worked: gas volumes at RTP"},{"type":"p","text":"What volume of CO₂ at RTP is produced from the propane above?"},{"type":"ul","items":["Moles of CO₂ = 0.75 mol (from above).","Volume = n × 24 = 0.75 × 24 = 18 dm³."]},{"type":"h","text":"Working with PV = nRT for non-standard conditions"},{"type":"ul","items":["Pressure P in Pa (or use kPa with R = 8.314 if V is in dm³).","Volume V in m³ (or dm³).","Temperature T in KELVIN — always convert (K = °C + 273).","R = 8.314 J K⁻¹ mol⁻¹."]},{"type":"h","text":"Worked: PV = nRT"},{"type":"p","text":"Calculate the volume of 0.50 mol O₂ at 27 °C and 100 kPa."},{"type":"ul","items":["T = 27 + 273 = 300 K. P = 100 000 Pa. n = 0.50.","V = nRT/P = 0.50 × 8.314 × 300 / 100 000 = 1247.1 / 100 000 = 0.01247 m³ = 12.47 dm³."]},{"type":"callout","title":"Unit hygiene","body":"The single biggest source of marks lost. ALWAYS write units alongside numbers in your working. Convert °C to K. Convert dm³ to m³ (or use kPa with R = 8.314 carefully). Quote answers to a sensible number of significant figures (usually 3 sf)."}]},{"id":"s7","title":"Concentrations & Titrations","blocks":[{"type":"p","text":"For solutions, concentration links volume to moles. Concentration c = n/V (V in dm³ for mol/dm³). Titrations use this relationship to determine an unknown concentration by reaction with a standard solution of known concentration."},{"type":"d","caption":"Titration setup"},{"type":"h","text":"The titration calculation"},{"type":"ul","items":["Identify the balanced equation and the mole ratio between titrant and analyte.","Use moles_titrant = c_titrant × V_titrant to find moles of titrant added.","Apply the mole ratio to find moles of analyte.","Divide by the analyte volume to get c_analyte."]},{"type":"h","text":"Worked: NaOH neutralised by HCl"},{"type":"p","text":"A 25.0 cm³ sample of NaOH(aq) of unknown concentration is titrated with 0.10 mol/dm³ HCl(aq). The endpoint is at 22.5 cm³ of HCl. Find [NaOH]."},{"type":"ul","items":["Equation: NaOH + HCl → NaCl + H₂O.   Ratio 1 : 1.","Moles HCl = c × V = 0.10 × (22.5/1000) = 0.10 × 0.0225 = 2.25 × 10⁻³ mol.","Moles NaOH = 2.25 × 10⁻³ mol (1:1 ratio).","[NaOH] = n / V = 2.25 × 10⁻³ / (25.0/1000) = 2.25 × 10⁻³ / 0.0250 = 0.090 mol/dm³."]},{"type":"h","text":"Choosing an indicator"},{"type":"ul","items":["Strong acid + strong base — wide pH jump — methyl orange OR phenolphthalein both work.","Strong acid + weak base — pH range mostly acidic — methyl orange.","Weak acid + strong base — pH range mostly alkaline — phenolphthalein.","Weak acid + weak base — no sharp jump — DON'T use indicators; use a pH meter."]},{"type":"callout","title":"Mind your units","body":"Concentration in mol/dm³ goes with volume in DM³, not cm³. Convert cm³ to dm³ by dividing by 1000. The most common arithmetic mistake on this topic is forgetting that division."},{"type":"h","text":"Standard solutions"},{"type":"p","text":"A primary standard is a substance that can be weighed accurately and dissolved to a known volume to give a precisely-known concentration. Examples: anhydrous Na₂CO₃, KIO₃, oxalic acid hydrate. Used to standardise reagents (like NaOH) which absorb moisture and CO₂ from air and so cannot be weighed precisely."},{"type":"takeaway","items":["c = n / V; remember V is in dm³ for mol/dm³.","Titration calc: moles titrant → ratio → moles analyte → concentration.","Indicator choice depends on the strengths of the acid and the base."]}]},{"id":"s8","title":"Percentage Yield & Percentage Purity","blocks":[{"type":"p","text":"Real reactions never produce 100 % of the predicted product, and starting materials are rarely 100 % pure. These two practical facts are quantified by percentage yield and percentage purity."},{"type":"d","caption":"The two key formulas"},{"type":"h","text":"Percentage yield"},{"type":"ul","items":["theoretical yield = mass of product expected from the balanced equation (assuming complete conversion).","actual yield = mass of product actually obtained from the experiment.","% yield = (actual ÷ theoretical) × 100."]},{"type":"h","text":"Why yield is rarely 100 %"},{"type":"ul","items":["Reaction may be reversible — equilibrium prevents complete conversion.","Side reactions consume some reactant but produce different products.","Loss during transfer, filtration, recrystallisation.","Some product remains dissolved or sticks to apparatus."]},{"type":"h","text":"Worked: yield"},{"type":"p","text":"4.0 g of CaCO₃ is heated until decomposition is complete. The CaO obtained is 1.96 g. Calculate the percentage yield."},{"type":"ul","items":["Equation: CaCO₃ → CaO + CO₂.","Moles CaCO₃ = 4.0 / 100 = 0.040 mol → theoretical moles CaO = 0.040.","Theoretical mass CaO = 0.040 × 56 = 2.24 g.","% yield = (1.96 / 2.24) × 100 = 87.5 %."]},{"type":"h","text":"Percentage purity"},{"type":"ul","items":["mass of pure substance / total mass of impure sample × 100.","Often determined by reacting a measured mass of impure sample with a standard reagent and back-calculating how much of the desired substance must have been present."]},{"type":"h","text":"Worked: purity"},{"type":"p","text":"5.00 g of impure NaOH is dissolved in water and titrated against 1.00 mol/dm³ HCl. The endpoint is at 100 cm³. Find the percentage purity."},{"type":"ul","items":["Moles HCl = c × V = 1.00 × (100/1000) = 0.100 mol.","Mole ratio NaOH : HCl = 1 : 1, so moles NaOH = 0.100 mol.","Mass of pure NaOH = 0.100 × 40 = 4.00 g.","% purity = (4.00 / 5.00) × 100 = 80.0 %."]},{"type":"callout","title":"Plausibility check","body":"Always sanity-check your answer. % purity should sit between 0 and 100. If it comes out as 1 % or 200 %, you have a units error somewhere — usually the cm³ → dm³ conversion."},{"type":"takeaway","items":["% yield = (actual ÷ theoretical) × 100. Honest values < 100 %.","% purity = (pure ÷ total impure) × 100. Use a quantitative reaction to back-calculate."]}]},{"id":"s9","title":"Calculation Strategy & Exam Tips","blocks":[{"type":"p","text":"Stoichiometry questions punish sloppy working and reward systematic technique. Internalise the workflow once, then it scales to every problem."},{"type":"h","text":"The universal recipe"},{"type":"ul","items":["1. WRITE the balanced equation. (Or balance it from scratch.)","2. EXTRACT the data: which masses, volumes, concentrations are given?","3. CONVERT every given quantity to MOLES using the right conversion (n=m/M, n=cV, n=V/24).","4. APPLY the mole ratio from the equation to find moles of the unknown.","5. CONVERT the unknown's moles back to mass, volume or concentration.","6. CHECK units, significant figures, and plausibility."]},{"type":"h","text":"Common pitfalls"},{"type":"ul","items":["Forgetting to divide cm³ by 1000 to convert to dm³.","Forgetting to convert °C to K when using PV = nRT.","Assuming a 1:1 mole ratio when the equation says otherwise.","Quoting answers to too many or too few significant figures.","Not identifying the limiting reagent when both reactant amounts are given.","Adding moles instead of using the ratio."]},{"type":"callout","title":"Significant figures","body":"Quote your final answer to the same number of sig figs as the LEAST precise piece of given data, usually 3 sig figs at A-level. Carry extra digits through working to avoid rounding error, only round at the end."}]}]}`),bonding:JSON.parse(`{"objectives":["Describe ionic bonding (NaCl, MgO, Al₂O₃) and draw dot-and-cross diagrams","Describe covalent bonding in terms of orbital overlap (σ and π); use H₂, O₂, Cl₂, CO₂, HCl, ethane, ethene, benzene as exemplars","Compare bond reactivity in terms of bond length, bond energy, bond polarity","Describe dative bonding in NH₄⁺ and Al₂Cl₆","Explain shapes and bond angles of molecules using VSEPR","Describe metallic bonding as a lattice of cations in a sea of mobile electrons","Describe intermolecular forces (van der Waals, permanent dipole-dipole, hydrogen bonding) and link to physical properties","Predict effects of bonding type on physical properties (m.p., conductivity, hardness, solubility)"],"chapters":[{"id":"b1","title":"Why Atoms Bond","blocks":[{"type":"p","text":"Almost no element exists naturally as isolated atoms. Apart from the noble gases (He, Ne, Ar...), atoms form bonds with one another. Why? Because bonded systems have LOWER energy than the separated atoms — and nature trends towards lower energy."},{"type":"callout","title":"The driving force","body":"Atoms bond to achieve a more stable electron arrangement, usually a noble-gas configuration (full outer shell). The energy released when bonds form (the bond energy) is what stabilises the new system."},{"type":"h","text":"Three main bond types"},{"type":"ul","items":["IONIC — electron transfer; metal + non-metal; produces +ve and −ve ions held by electrostatic attraction.","COVALENT — electron sharing; non-metal + non-metal; produces molecules with discrete bonded pairs.","METALLIC — electron pooling; metal + metal; produces a lattice of cations in a sea of mobile electrons."]},{"type":"h","text":"And then between molecules"},{"type":"p","text":"Once molecules exist, they can attract each other through weaker forces — van der Waals, permanent dipoles, and hydrogen bonds. These INTERMOLECULAR forces explain melting and boiling points, solubility, surface tension. They are NOT the same as the strong INTRAMOLECULAR bonds within the molecule."},{"type":"takeaway","items":["Bonds form because they LOWER total energy.","Three intramolecular types: ionic, covalent, metallic.","Intermolecular forces are separate, weaker attractions BETWEEN molecules."]}]},{"id":"b2","title":"Ionic Bonding","blocks":[{"type":"p","text":"Ionic bonding occurs when a metal donates one or more electrons to a non-metal. Both species end up with full outer shells. The resulting cation and anion are held together by strong electrostatic attraction."},{"type":"d","caption":"Sodium chloride — Na loses 1 e⁻, Cl gains 1 e⁻"},{"type":"h","text":"Examples to memorise"},{"type":"ul","items":["NaCl — Na (1 valence e⁻) loses to Cl (7 valence e⁻). Both attain 8.","MgO — Mg loses 2 e⁻ to O. Both attain 8.","Al₂O₃ — 2 Al each lose 3 e⁻; 3 O each gain 2 e⁻. Total electrons exchanged = 6 each side. Formula 2:3."]},{"type":"h","text":"Drawing dot-and-cross diagrams"},{"type":"ul","items":["Use crosses (×) for one element's electrons and dots (•) for the other.","Show only the OUTER shell.","Indicate the charge with [ ]ⁿ⁺ or [ ]ⁿ⁻ around the ion.","Make sure each ion has 8 in its outer shell (or 2 for H, Li⁺, Be²⁺)."]},{"type":"h","text":"Properties of ionic compounds"},{"type":"ul","items":["High melting and boiling points — strong electrostatic forces throughout the lattice.","Hard but brittle — like-charges align under stress, then repel and crack.","Conduct electricity when MOLTEN or DISSOLVED — ions become mobile. Solid: ions fixed, no conduction.","Often soluble in polar solvents like water (which can stabilise the separated ions)."]},{"type":"callout","title":"Ionic radius vs atomic radius","body":"A cation is SMALLER than its parent atom (lost an outer shell, plus higher Z_eff for remaining electrons). An anion is LARGER than its parent atom (gained an electron, more inter-electron repulsion in the outer shell)."},{"type":"takeaway","items":["Ionic = electron transfer + electrostatic attraction.","Both ions reach a noble-gas configuration.","High m.p., conducts when molten/dissolved, brittle."]}]},{"id":"b3","title":"Covalent Bonding","blocks":[{"type":"p","text":"A covalent bond is a SHARED pair of electrons between two atoms — usually two non-metals. Both atoms count the shared pair towards their outer-shell octet (or duet for H), so both achieve a noble-gas configuration without a net charge transfer."},{"type":"h","text":"Single, double, triple bonds"},{"type":"ul","items":["Single bond — one shared pair (e.g. H–H, Cl–Cl, H–Cl). Two electrons total in the bond.","Double bond — two shared pairs (e.g. O=O, C=O). Four electrons total.","Triple bond — three shared pairs (e.g. N≡N, C≡C). Six electrons total."]},{"type":"h","text":"Sigma (σ) and pi (π) bonds — orbital overlap"},{"type":"d","caption":"Two ways orbitals overlap"},{"type":"ul","items":["σ bond — orbitals overlap HEAD-ON along the line between the nuclei. Strong; allows free rotation.","π bond — orbitals overlap SIDEWAYS, with electron density above and below the bond axis. Weaker; prevents rotation (so cis/trans isomerism in alkenes).","A single bond is 1 σ. A double bond is 1 σ + 1 π. A triple bond is 1 σ + 2 π."]},{"type":"h","text":"Worked examples — drawing dot-and-cross"},{"type":"ul","items":["H₂ — each H contributes 1 e⁻ to a single shared pair. Each H has 2 in its \\"shell\\".","O₂ — each O has 6 outer; share 2 pairs (double bond). Each O has 8.","CO₂ — C shares 2 pairs with EACH O (two double bonds). All atoms hit 8.","HCl — H shares 1 with Cl. Cl has 6 lone + 1 bonded pair = 8. H has 2.","C₂H₆ (ethane) — single C–C, six C–H. All carbons have 8.","C₂H₄ (ethene) — C=C double bond, four C–H. Planar around each C."]},{"type":"d","caption":"Benzene — a special case"},{"type":"h","text":"Benzene — delocalised system"},{"type":"p","text":"Benzene (C₆H₆) is special. Each C is sp² hybridised: it forms three σ bonds (to two neighbouring C and one H) using sp² hybrid orbitals in a plane. The remaining p-orbital, with one electron, is perpendicular to the plane. The six p-orbitals overlap sideways, forming a continuous DELOCALISED π cloud above and below the ring. All six C–C bonds are equal length (139 pm — between single 154 and double 134), and the molecule has extra stability beyond what 3 separate double bonds would give."},{"type":"callout","title":"Why benzene matters","body":"The delocalised π system makes benzene unusually stable — about 150 kJ/mol more stable than the hypothetical \\"cyclohexatriene\\" with 3 isolated double bonds. This is the resonance / aromatic stabilisation energy. It explains why benzene resists addition (which would break the ring's aromaticity) and prefers substitution."},{"type":"takeaway","items":["Covalent bond = shared pair, achieving full outer shell for both.","1 bond = 1 σ; double = 1σ + 1π; triple = 1σ + 2π.","σ allows rotation; π locks geometry.","Benzene's 6 C have a single delocalised π system → extra stability."]}]},{"id":"b4","title":"Bond Reactivity — Length, Energy, Polarity","blocks":[{"type":"p","text":"Not all covalent bonds are equally strong. Three properties — bond length, bond energy, and bond polarity — determine how readily a bond breaks and what kind of reactions follow."},{"type":"h","text":"Bond length"},{"type":"ul","items":["The distance between the two bonded nuclei.","Single bonds are LONGER than double, which are longer than triple (between the same two atoms).","C–C: 154 pm  ;  C=C: 134 pm  ;  C≡C: 120 pm.","Longer bonds are generally weaker."]},{"type":"h","text":"Bond energy (bond enthalpy)"},{"type":"callout","title":"Bond energy","body":"The energy required to break ONE MOLE of a particular bond in the GAS phase. Always positive (breaking bonds costs energy)."},{"type":"ul","items":["C–C ≈ 348 kJ/mol  ;  C=C ≈ 612  ;  C≡C ≈ 838.","Higher bond energy = stronger bond = harder to break = less reactive at that site.","Weak bonds are reactive sites — e.g. the π component of C=C is the reactive part in alkene addition."]},{"type":"h","text":"Bond polarity"},{"type":"d","caption":"Polar covalent bond"},{"type":"ul","items":["Caused by a difference in electronegativity (EN) between the bonded atoms.","The more electronegative atom acquires δ− (partial negative); the less electronegative atom is δ+.","EN trends: increases across a period, decreases down a group. F is the most electronegative element (4.0).","ΔEN = 0 → pure non-polar covalent (H–H, Cl–Cl).","ΔEN = 0.4 to 1.7 → polar covalent (H–Cl, C=O).","ΔEN > 1.7 → ionic (Na–Cl)."]},{"type":"h","text":"Polarity drives reactivity"},{"type":"p","text":"Polar bonds have an electron-deficient (δ+) end and an electron-rich (δ−) end. This sets up sites that attract incoming reagents:"},{"type":"ul","items":["Nucleophiles (electron-rich, e.g. OH⁻, NH₃) attack the δ+ atom.","Electrophiles (electron-poor, e.g. Br⁺, NO₂⁺) attack the δ− atom or electron-rich π bonds.","This is why halogenoalkanes (C–X bonds polar towards X) undergo nucleophilic substitution at C."]},{"type":"callout","title":"Polar bond ≠ polar molecule","body":"A molecule with polar bonds may still be NON-POLAR if the dipoles cancel by symmetry. Example: CO₂ has two polar C=O bonds but they point in opposite directions (linear molecule), so the molecule has no net dipole moment. Same for CCl₄ (tetrahedral). Compare with H₂O: two polar O–H bonds, but the molecule is BENT, dipoles add, water IS polar."},{"type":"takeaway","items":["Length: triple < double < single (between same atoms).","Energy: triple > double > single. Higher energy = harder to break.","Polarity: arises from ΔEN; sets up attack sites for nucleophiles/electrophiles.","Net molecular dipole depends on shape, not just bonds."]}]},{"id":"b5","title":"Dative (Coordinate) Bonding","blocks":[{"type":"p","text":"A dative bond (also called a coordinate bond) is a covalent bond in which BOTH bonding electrons come from the SAME atom. Once formed, a dative bond is identical to any other covalent bond — only its origin is different."},{"type":"callout","title":"Dative bond","body":"A shared electron pair where both electrons originate on one atom (the donor). Drawn with an arrow from donor to acceptor, or shown using \\"lone pair × lone pair\\" notation."},{"type":"d","caption":"NH₃ + H⁺ → NH₄⁺"},{"type":"h","text":"NH₄⁺ — formation"},{"type":"p","text":"In NH₃, the N atom has 3 bonded pairs (to 3 H) and 1 LONE pair. When NH₃ meets H⁺ (a bare proton with empty 1s orbital), the lone pair on N is donated into the H⁺'s 1s orbital. The result is a fourth N–H bond with both electrons from N. NH₄⁺ has FOUR equivalent N–H bonds — once formed, you cannot tell which one is \\"the dative bond\\". The +1 charge is shared across the whole ion."},{"type":"h","text":"Al₂Cl₆ — the dimer of AlCl₃"},{"type":"p","text":"AlCl₃ has only 6 electrons around Al — short of an octet. In the gas phase or non-polar solvents, two AlCl₃ molecules join via two dative bonds. Each bridging Cl donates a lone pair into the empty orbital on the OTHER Al."},{"type":"ul","items":["Each Al has 4 Cl around it (octet completed).","Two of those Cl atoms BRIDGE between the two Al — they form 2 dative bonds.","This is a common A-level diagram; learn to draw it with the chlorine bridges."]},{"type":"h","text":"Other examples worth knowing"},{"type":"ul","items":["BF₃·NH₃ — the lone pair on N donates into B's empty p orbital.","CO — one of the three C–O bonds in carbon monoxide is a dative bond from O to C, giving C a full octet.","Transition metal complexes — every M–L bond in [Cu(H₂O)₆]²⁺ etc. is a dative bond from the ligand.","H₃O⁺ — the third O–H bond in the hydroxonium ion is dative (O donates lone pair to H⁺)."]},{"type":"takeaway","items":["Both bonding electrons come from one atom (the donor with a lone pair).","Acceptor needs an empty orbital (e.g. H⁺, B in BF₃, Al in AlCl₃).","Once formed, indistinguishable from a regular covalent bond."]}]},{"id":"b6","title":"Shapes of Molecules — VSEPR","blocks":[{"type":"p","text":"The shape of a molecule is determined by the arrangement of electron pairs around its central atom. Electron pairs repel each other — they arrange themselves as far apart as possible. This is Valence Shell Electron Pair Repulsion theory (VSEPR)."},{"type":"d","caption":"The five most-tested shapes"},{"type":"h","text":"The repulsion ranking"},{"type":"p","text":"Not all electron pairs repel equally. Lone pairs (LP) sit closer to the central atom (only one nucleus pulling them) while bonding pairs (BP) are stretched between two nuclei. Hence:"},{"type":"ul","items":["LP–LP repulsion >  LP–BP  >  BP–BP.","Each lone pair \\"squeezes\\" the bond angles slightly smaller than the ideal."]},{"type":"h","text":"Shapes you must know"},{"type":"ul","items":["2 BP — LINEAR — 180° — e.g. CO₂, BeCl₂, HCN.","3 BP — TRIGONAL PLANAR — 120° — e.g. BF₃, BCl₃.","4 BP — TETRAHEDRAL — 109.5° — e.g. CH₄, NH₄⁺, SiH₄.","3 BP + 1 LP — TRIGONAL PYRAMIDAL — ~107° — e.g. NH₃, PH₃. Lone pair compresses to slightly less than 109.5°.","2 BP + 2 LP — BENT — ~104.5° — e.g. H₂O. Two lone pairs compress further.","5 BP — TRIGONAL BIPYRAMIDAL — 120° equatorial, 90° axial — e.g. PCl₅.","6 BP — OCTAHEDRAL — 90° — e.g. SF₆, [Co(NH₃)₆]³⁺."]},{"type":"h","text":"Workflow for any molecule"},{"type":"ul","items":["1. Count valence electrons on the central atom.","2. Add 1 e⁻ per atom bonded (for halogens, H — they donate 1 to the bond).","3. Add or subtract for charge (cation: subtract; anion: add).","4. Divide by 2 to get total ELECTRON pairs (bonding + lone).","5. Subtract bonded atoms to find LONE PAIRS.","6. Match (BP, LP) pattern to the standard shape."]},{"type":"h","text":"Worked: H₂O"},{"type":"ul","items":["Central atom O: 6 valence e⁻.","Bonded atoms: 2 H × 1 = 2 e⁻ contributed.","Total = 6 + 2 = 8 e⁻ → 4 pairs.","Bonded pairs = 2 (one to each H). Lone pairs = 4 − 2 = 2.","Pattern: 2 BP + 2 LP → BENT. Bond angle ~104.5°."]},{"type":"h","text":"Worked: SF₆"},{"type":"ul","items":["S: 6 valence e⁻. 6 F × 1 = 6 e⁻. Total = 12 e⁻ → 6 pairs.","6 BP, 0 LP → OCTAHEDRAL, all bond angles 90°.","Yes, S can have more than 8 electrons (expanded octet — only Period 3 and below, where empty d orbitals are accessible)."]},{"type":"callout","title":"Don't forget multiple bonds count as ONE region","body":"For VSEPR purposes, a double or triple bond counts as ONE electron-pair region (because all the electrons are between the same two nuclei). Example: CO₂ has 2 double bonds = 2 regions = LINEAR. SO₂ has 2 double bonds + 1 lone pair = 3 regions = BENT (~120°)."},{"type":"takeaway","items":["Electron pairs arrange to minimise repulsion.","Lone pairs repel more strongly → squeeze bond angles smaller.","Multiple bonds count as one region for VSEPR.","Memorise the (BP, LP) pattern → shape mapping."]}]},{"id":"b7","title":"Metallic Bonding","blocks":[{"type":"p","text":"In a metal, the outer-shell electrons are not held by any individual atom. They drift freely through the entire piece of metal — the famous \\"sea of delocalised electrons\\". The atoms have effectively become positive ions (cations), arranged in a regular lattice, with the electron sea binding them all together."},{"type":"d","caption":"Lattice of cations in a sea of mobile electrons"},{"type":"h","text":"Why metals do what they do"},{"type":"ul","items":["GOOD ELECTRICAL CONDUCTORS — delocalised electrons move freely under an applied voltage.","GOOD THERMAL CONDUCTORS — kinetic energy passes rapidly through the mobile-electron network.","MALLEABLE AND DUCTILE — layers of cations can slide past each other; the electron sea adjusts and the bond is preserved. (Compare ionic compounds, which crack under stress.)","HIGH M.P. AND B.P. — many electrostatic attractions throughout the lattice.","LUSTROUS — free electrons absorb and re-emit photons of visible light."]},{"type":"h","text":"What controls the strength of a metallic bond?"},{"type":"ul","items":["Number of valence electrons donated to the sea — more electrons = stronger bond. Group I metals (1 valence e⁻) have lower m.p. than Group II (2). Transition metals donate up to 6 electrons (4s + several 3d) → much stronger bonds, much higher m.p.","Charge density of the cation — smaller, more highly charged cations bind the electron sea more tightly. Mg²⁺ > Na⁺ in metallic-bond strength."]},{"type":"callout","title":"Why TMs have higher m.p. than Group I/II","body":"Transition metals contribute BOTH 4s and (some) 3d electrons to the metallic bond. With more electrons in the sea AND a higher cation charge, the bonding is much stronger. Compare Na (m.p. 98 °C) with Fe (1538 °C). Pure delocalised d electrons are why TMs are dense, hard, and high-melting."}]},{"id":"b8","title":"Intermolecular Forces","blocks":[{"type":"p","text":"Intermolecular forces are the attractions BETWEEN separate molecules. They are MUCH weaker than the intramolecular bonds (covalent, ionic, metallic) inside a molecule, but they are responsible for melting points, boiling points, surface tension, viscosity, and miscibility — most of the everyday physical behaviour of substances."},{"type":"h","text":"Three types — in ascending strength"},{"type":"ul","items":["1. Van der Waals (London / dispersion) forces — between ALL molecules.","2. Permanent dipole-dipole — between POLAR molecules.","3. Hydrogen bonding — between molecules with H bonded to N, O, or F."]},{"type":"h","text":"Van der Waals (induced dipole — induced dipole)"},{"type":"p","text":"Even a non-polar molecule has electrons in constant motion. At any instant the electron cloud may be slightly more on one side, creating a TEMPORARY dipole. This induces an opposite dipole in a neighbouring molecule, and the two attract weakly. The bigger the molecule (more electrons, larger surface area), the stronger the vdW."},{"type":"ul","items":["Always present, between every pair of molecules.","STRENGTH increases with: more electrons, larger molecule, longer chain.","Branched isomers have weaker vdW than straight chains (less surface contact).","Examples: explains why I₂ (large) is a solid but Cl₂ (smaller) is a gas at room temp; why butane is a gas but pentane a liquid."]},{"type":"h","text":"Permanent dipole — permanent dipole"},{"type":"p","text":"Polar molecules have permanent δ+ and δ− regions. The δ+ end of one molecule attracts the δ− end of a neighbour. Stronger than vdW (because dipoles are permanent, not fluctuating)."},{"type":"ul","items":["Examples: HCl, ICl, CHCl₃, propanone (CH₃COCH₃).","Boost m.p. and b.p. compared to non-polar molecules of similar size.","Compare propane (M = 44, b.p. −42 °C) with propanone (M = 58, b.p. 56 °C) — almost 100 °C difference, mostly from permanent dipoles."]},{"type":"h","text":"Hydrogen bonding — the special case"},{"type":"d","caption":"H-bonding in water"},{"type":"ul","items":["A hydrogen atom bonded to N, O or F (very electronegative) becomes strongly δ+.","It is attracted to a LONE PAIR on N, O or F of a NEIGHBOURING molecule.","Roughly 5–10× stronger than ordinary dipole-dipole, but still weaker than covalent bonds (which are ~100× stronger).","Drawn as a dotted line: X—H ··· :Y where X, Y ∈ {N, O, F}."]},{"type":"h","text":"Why hydrogen bonding matters"},{"type":"d","caption":"Ice less dense than water — vital for aquatic life"},{"type":"ul","items":["Water has anomalously high m.p. and b.p. for its molecular mass.","Ice has lower density than liquid water — fish survive winter under ice.","NH₃, HF also have unusually high b.p. compared to PH₃, HCl in their respective groups.","DNA double helix: the two strands are held together by H-bonds between base pairs (A-T two H-bonds, G-C three).","Proteins: secondary structure (α-helix, β-sheet) maintained by backbone H-bonds."]},{"type":"callout","title":"How to tell which IMF is dominant","body":"List the molecule's features in order: (1) Does it have H bonded to N/O/F? → H-bonding (strongest). (2) Otherwise, is it polar? → permanent dipole-dipole. (3) Otherwise → only vdW. The strongest force present is what mostly determines b.p."}]},{"id":"b9","title":"Effect of Bonding on Properties","blocks":[{"type":"p","text":"Substances fall into four broad structural types. Each has a characteristic profile of physical properties — melting point, conductivity, hardness, solubility — that traces directly back to its bonding."},{"type":"d","caption":"Four lattice structures, four behaviour profiles"},{"type":"h","text":"IONIC LATTICE (e.g. NaCl)"},{"type":"ul","items":["High m.p. (NaCl 801 °C) and b.p. — strong electrostatic forces in 3-D throughout the lattice.","Hard but brittle — like-charges repel under stress, lattice cracks.","Conducts when MOLTEN or DISSOLVED but not when solid.","Often soluble in water; insoluble in non-polar solvents."]},{"type":"h","text":"SIMPLE MOLECULAR (e.g. I₂, CO₂, ice)"},{"type":"ul","items":["Low m.p. and b.p. — only weak intermolecular forces holding the molecules together.","Soft solids; some sublime (CO₂(s) → CO₂(g) directly).","Do NOT conduct electricity (no free charges; even when molten).","Soluble in non-polar solvents; polar molecules also dissolve in water if H-bonding is possible (e.g. ethanol)."]},{"type":"h","text":"GIANT COVALENT (e.g. diamond, graphite, SiO₂)"},{"type":"ul","items":["VERY high m.p. — covalent bonds extend through the whole solid; melting requires breaking covalent bonds.","Diamond: each C tetrahedral, every C–C bond covalent → hardest natural material; insulator (no free electrons).","Graphite: layers of hexagons, weak vdW between layers (slippery), one delocalised electron per C → conducts.","SiO₂ (quartz): tetrahedral SiO₄ units linked → very high m.p., insulator."]},{"type":"h","text":"METALLIC (e.g. Cu, Fe, Mg)"},{"type":"ul","items":["High m.p., dense, hard, lustrous.","Conducts heat and electricity even when SOLID — delocalised electrons.","Malleable and ductile — layers slide while electron sea adjusts."]},{"type":"callout","title":"Diagnostic — given properties, deduce structure","body":"High m.p. + conducts when molten only → IONIC. Low m.p. + non-conductor → MOLECULAR. Very high m.p. + non-conductor (or graphite, conducts in one direction) → GIANT COVALENT. High m.p. + conducts as solid + malleable → METALLIC."}]},{"id":"b10","title":"Bonding & Periodicity Link","blocks":[{"type":"p","text":"A foreshadow of Period 3 chemistry. As you cross from Group I to Group VII, the bonding type of the binary chloride or oxide changes from ionic to covalent. This shift drives every other property change you will meet later (PC-09 Periodicity)."},{"type":"h","text":"Period 3 chlorides — bonding shift"},{"type":"ul","items":["NaCl, MgCl₂ — ionic. White crystalline solids, dissolve in water giving neutral or slightly acidic solutions.","AlCl₃ — borderline. Ionic with covalent character; dimer in vapour as Al₂Cl₆.","SiCl₄, PCl₅, SCl₂, Cl₂ — molecular covalent. Volatile, often hydrolysed by water to acidic solutions."]},{"type":"h","text":"Period 3 oxides — bonding shift"},{"type":"ul","items":["Na₂O, MgO — ionic. Basic (or neutral / alkaline in water).","Al₂O₃ — amphoteric (reacts with both acids and bases).","SiO₂ — giant covalent; weakly acidic (reacts with hot conc. NaOH).","P₄O₁₀, SO₂, SO₃, Cl₂O — molecular covalent; acidic in water."]},{"type":"callout","title":"The pattern","body":"Across Period 3: bonding goes ionic → covalent; oxide character goes basic → amphoteric → acidic. This is one of the most important threads through inorganic chemistry; you will revisit it when you study periodicity."}]},{"id":"b11","title":"Exam Technique & Diagnostics","blocks":[{"type":"p","text":"A few high-leverage habits get most bonding marks."},{"type":"h","text":"Drawing dot-and-cross — the rules"},{"type":"ul","items":["Show ONLY the outer shell.","Use × for one element's electrons, • for the other (consistent throughout).","For ions, show charges with [ ]ⁿ⁺ or [ ]ⁿ⁻ around the brackets.","For dative bonds, indicate the donor (some teachers use an arrow; check your exam board's convention).","Make sure each atom's outer shell totals 8 (or 2 for H, Li, Be)."]},{"type":"h","text":"Predicting shape — exam-ready procedure"},{"type":"ul","items":["1. Identify central atom.","2. Count electron pairs (bonded + lone) using the workflow from chapter 6.","3. Place pairs as far apart as possible (the \\"parent\\" geometry).","4. Identify which pairs are lone — they're NOT in the molecule's shape but they SQUEEZE the bond angles.","5. State both the SHAPE and the BOND ANGLE; account for any squeeze from lone pairs."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Saying \\"trigonal planar\\" for NH₃ — it's pyramidal because N has a lone pair.","Forgetting that double bonds count as ONE region for VSEPR.","Stating CO₂ is polar — bonds ARE polar but the linear shape cancels them.","Calling all dative bonds \\"ionic\\" — they're covalent (just both electrons from one donor).","Ignoring that diamond and graphite are both giant covalent — diamond hardest, graphite conducts because of delocalised electrons."]},{"type":"callout","title":"A quick deduction trick","body":"For \\"what is the shape of XY₄?\\" with no further info: if X is in Group IV (4 valence e⁻), no lone pair → tetrahedral. If X is in Group V (5 valence e⁻), one bond uses 4 of those + still 1 lone pair → see-saw or similar (5 regions). Always count electrons on the CENTRAL atom; this turns shape questions into 3-step arithmetic."}]}]}`),states:JSON.parse(`{"objectives":["Describe particle arrangement in solid, liquid, and gas","State assumptions of an ideal gas; explain real-gas deviations","Apply PV = nRT in calculations of P, V, T, n, and Mᵣ","Sketch and interpret the Maxwell-Boltzmann distribution","Distinguish ionic, simple molecular, giant covalent, hydrogen-bonded, and metallic lattices","Describe and contrast NaCl, I₂, ice, diamond, graphite, SiO₂, and metals (e.g. Cu)","Link bonding type to physical properties (m.p., conductivity, hardness, solubility)","Interpret phase diagrams (triple point, critical point, normal m.p./b.p.)"],"chapters":[{"id":"st1","title":"The Three States — Particle View","blocks":[{"type":"p","text":"All matter at A-level temperatures and pressures exists as solid, liquid, or gas. The three states differ in how the particles are arranged and how freely they move. Heat is the link — adding energy fights the inter-particle forces."},{"type":"d","caption":"Particle arrangement in each state"},{"type":"h","text":"The summary table"},{"type":"ul","items":["SOLID — particles in fixed lattice positions; vibrate only; definite shape and volume.","LIQUID — particles close together but can slip past each other; flows; definite volume but adopts container shape.","GAS — particles far apart, fast and random; fills the container completely; compressible."]},{"type":"h","text":"Energy and the changes of state"},{"type":"ul","items":["MELTING (solid → liquid) — partial breakdown of lattice; energy in.","BOILING (liquid → gas) — full separation of molecules; energy in (much larger than melting).","SUBLIMATION (solid → gas directly) — happens when intermolecular forces are weak relative to thermal motion (e.g. CO₂(s), I₂).","CONDENSATION, FREEZING, DEPOSITION — reverse processes; energy out."]},{"type":"callout","title":"Why is enthalpy of vaporisation > enthalpy of fusion?","body":"Melting only loosens the lattice — the molecules stay close. Boiling fully separates the molecules into the gas phase, against ALL the intermolecular forces. So vaporisation costs much more energy. For water: ΔH_fus = 6.0 kJ/mol vs ΔH_vap = 41 kJ/mol — almost 7× larger."}]},{"id":"st2","title":"Kinetic Theory of Gases","blocks":[{"type":"p","text":"Kinetic theory pictures a gas as a swarm of tiny particles in constant random motion. The macroscopic behaviour we measure (pressure, temperature, volume) is a statistical average over an enormous number of particles."},{"type":"h","text":"Assumptions of an IDEAL GAS"},{"type":"ul","items":["Particles are point masses — they have negligible volume compared to the container.","Particles have NO intermolecular forces between them.","Collisions between particles, and between particles and walls, are PERFECTLY ELASTIC (no kinetic energy lost).","Particles are in continuous random motion.","The average kinetic energy is directly proportional to absolute temperature (T in K)."]},{"type":"callout","title":"Pressure (kinetic-theory view)","body":"The result of countless particle collisions with the container walls per second. More collisions, or more energetic ones, means higher pressure."},{"type":"h","text":"Maxwell-Boltzmann distribution"},{"type":"d","caption":"Speed distribution at two temperatures"},{"type":"p","text":"Gas particles do NOT all move at the same speed. There is a distribution: some move slowly, most move at moderate speed, a few move very fast. The full distribution is the Maxwell-Boltzmann curve."},{"type":"ul","items":["The peak of the curve is the MOST PROBABLE speed.","The mean speed is slightly higher than the most probable.","Higher T: peak shifts to the right and curve flattens — more fast particles, fewer slow ones.","The AREA under the curve = total number of particles (constant if no particles are added/removed)."]},{"type":"callout","title":"Why this matters for kinetics","body":"In Reaction Kinetics (PC-08), we will draw the Maxwell-Boltzmann curve again to show why higher temperature speeds up reactions: more particles have energy ≥ activation energy. Get this picture firmly in your head now."}]},{"id":"st3","title":"The Ideal Gas Equation","blocks":[{"type":"p","text":"Combining Boyle's, Charles's, and Avogadro's laws gives the ideal gas equation. It links pressure, volume, temperature and amount of gas in a single relationship — and it works astonishingly well for most gases at room conditions."},{"type":"callout","title":"Ideal gas equation","body":"PV = nRT  where P is pressure, V is volume, n is moles, R is the gas constant (8.314 J K⁻¹ mol⁻¹), T is temperature in KELVIN."},{"type":"h","text":"Units — must match"},{"type":"ul","items":["P in pascals (Pa). 1 atm = 101 325 Pa = 101.325 kPa.","V in m³. 1 dm³ = 10⁻³ m³, 1 cm³ = 10⁻⁶ m³.","n in mol.","R = 8.314 J K⁻¹ mol⁻¹.","T in KELVIN. K = °C + 273."]},{"type":"h","text":"Common simplifications"},{"type":"ul","items":["AT STP (273 K, 100 kPa): 1 mole of gas occupies 22.4 dm³.","AT RTP (298 K, 100 kPa): 1 mole of gas occupies 24.0 dm³.","For quick answers under standard lab conditions, use n = V / 24."]},{"type":"h","text":"Variations — Boyle, Charles, Avogadro"},{"type":"ul","items":["Boyle's law (constant T, n): P × V = constant. Halve V → double P.","Charles's law (constant P, n): V / T = constant. Double T (in K) → double V.","Avogadro's law (constant P, T): V / n = constant. Double n → double V."]},{"type":"h","text":"Worked: PV = nRT"},{"type":"p","text":"Calculate the volume of 0.50 mol of N₂ at 27 °C and 100 kPa."},{"type":"ul","items":["P = 100 000 Pa. T = 27 + 273 = 300 K. n = 0.50. R = 8.314.","V = nRT / P = 0.50 × 8.314 × 300 / 100 000 = 0.01247 m³.","Convert: 0.01247 m³ × 1000 = 12.47 dm³."]},{"type":"callout","title":"Single biggest mistake","body":"Forgetting to convert temperature to KELVIN. Always do K = °C + 273 first. Second biggest: mixing P in kPa with V in dm³ and R in standard SI units. If P is in Pa, V must be in m³."},{"type":"d","caption":"Molar volumes at standard conditions"},{"type":"h","text":"Determining Mr from gas density"},{"type":"p","text":"PV = nRT can be rearranged: n = m/M_r, so PV = (m/M_r)RT, giving M_r = mRT/(PV) = (m/V)·RT/P. Density ρ = m/V, so M_r = ρRT/P. Useful in lab to find molar mass from gas density measurements."}]},{"id":"st4","title":"Real Gases — Where Ideal Fails","blocks":[{"type":"p","text":"Real gases deviate from ideal behaviour at LOW temperatures and HIGH pressures — exactly the conditions where intermolecular forces matter and where particles are close enough to each other that their finite size is no longer negligible."},{"type":"d","caption":"PV/nRT departs from 1 at high P or low T"},{"type":"h","text":"Why real gases deviate"},{"type":"ul","items":["INTERMOLECULAR FORCES (vdW, dipoles) — assumed zero in ideal model. Actually, attractive forces pull molecules together → smaller volume → PV/nRT < 1.","PARTICLE VOLUME — assumed negligible. Actually, at very high P, the particles' OWN volume becomes significant compared to the container → effective space larger → PV/nRT > 1."]},{"type":"callout","title":"When does ideal-gas behaviour FAIL?","body":"At LOW temperature: kinetic energy is small, intermolecular attractions dominate → gases nearly liquefy → big deviations. At HIGH pressure: molecules forced close together; their finite volumes matter; intermolecular forces strong. Between these extremes (ordinary lab conditions), the ideal gas approximation is excellent for most non-polar gases like N₂, O₂, He."},{"type":"h","text":"When ideal gas works very well"},{"type":"ul","items":["Low pressure (atmospheric or below).","Moderate to high temperature.","Non-polar gases with small molecules (He, Ne, H₂, N₂, O₂)."]},{"type":"h","text":"When deviation is significant"},{"type":"ul","items":["Polar gases (H₂O, NH₃) — strong dipole forces.","Large molecules — significant own-volume.","Gases near their boiling point — very prone to liquefying."]},{"type":"callout","title":"For exam purposes","body":"Unless the question explicitly states \\"non-ideal\\" or shows a plot, you should USE the ideal gas equation. Mention deviations only when asked, or when conditions clearly call for it (very high P, near liquefaction)."}]},{"id":"st5","title":"The Liquid State","blocks":[{"type":"p","text":"A liquid sits between solid and gas — particles are close together (like a solid) but free to move past one another (unlike a solid). Intermolecular forces are still important; without them, the liquid would boil away."},{"type":"h","text":"Properties of liquids"},{"type":"ul","items":["Definite VOLUME, no fixed shape. Adopts the container.","Slightly compressible (much less than gas).","Density much closer to solid than to gas.","Viscosity (resistance to flow) varies hugely with intermolecular forces — water is fluid, glycerol is sticky, motor oils are designed to be viscous.","Surface tension — molecules at the surface have neighbours only below and to the sides; net inward pull creates a \\"skin\\"."]},{"type":"h","text":"Boiling vs evaporation"},{"type":"ul","items":["EVAPORATION — happens at any temperature, only at the SURFACE; faster molecules escape into vapour.","BOILING — happens at a specific temperature when the liquid's vapour pressure equals the surrounding atmospheric pressure; bubbles form THROUGHOUT the liquid.","Boiling point depends on pressure — water boils at 100 °C at 1 atm but only ~70 °C on Mount Everest (lower atmospheric pressure)."]},{"type":"callout","title":"Vapour pressure","body":"In a closed container, some liquid molecules escape to vapour while others condense back. At equilibrium, the partial pressure of the vapour is the SATURATED vapour pressure. Higher T → more molecules with enough KE to escape → higher vapour pressure. When vapour pressure = external pressure, the liquid boils."}]},{"id":"st6","title":"Solid State — Ionic & Molecular Lattices","blocks":[{"type":"p","text":"Most solids at A-level fall into one of four lattice categories: ionic, simple molecular, giant covalent, or metallic. Each has a distinctive arrangement and a distinctive property profile."},{"type":"h","text":"IONIC LATTICE — NaCl"},{"type":"d","caption":"Sodium chloride — alternating cations and anions"},{"type":"ul","items":["Each Na⁺ is surrounded by 6 Cl⁻ (octahedral coordination); each Cl⁻ by 6 Na⁺.","Strong electrostatic attraction extends throughout the lattice.","High m.p. (NaCl 801 °C), high b.p., hard but BRITTLE (under stress, like-charges align and repel — lattice cleaves).","Soluble in polar solvents (water can hydrate the separated ions).","Conducts when MOLTEN or in solution (mobile ions). Solid: ions fixed → no conduction."]},{"type":"h","text":"SIMPLE MOLECULAR — I₂"},{"type":"d","caption":"Iodine — discrete I₂ molecules in a soft lattice"},{"type":"ul","items":["Discrete I₂ molecules held in a regular array by VAN DER WAALS forces only.","Within each I₂: strong covalent bond.","BETWEEN I₂ molecules: weak vdW.","Low m.p. (I₂ 114 °C), soft, sublimes when warmed (purple vapour).","Insoluble in water (non-polar); soluble in non-polar solvents (hexane, CCl₄).","Does NOT conduct (no free charges)."]},{"type":"h","text":"HYDROGEN-BONDED MOLECULAR — ICE"},{"type":"d","caption":"Ice — water molecules held in an open hexagonal lattice by H-bonds"},{"type":"ul","items":["A special case of simple molecular — H-bonds replace ordinary vdW.","Each O atom hydrogen-bonds to 4 others tetrahedrally.","OPEN HEXAGONAL lattice with measurable empty spaces.","Density 0.92 g/cm³ — LESS than liquid water (1.00 g/cm³). Ice floats.","Higher m.p. than expected for a molecule of mass 18 (compare with H₂S, b.p. −60 °C)."]},{"type":"callout","title":"Why ice is less dense than water","body":"In the solid, every molecule has 4 specific H-bonded partners arranged tetrahedrally. This rigid geometry creates gaps. In the liquid, molecules tumble and re-form H-bonds with various neighbours — they pack together more closely. So liquid density > ice density."}]},{"id":"st7","title":"Giant Covalent & Metallic Lattices","blocks":[{"type":"h","text":"GIANT COVALENT — DIAMOND"},{"type":"d","caption":"Diamond — every C bonded to 4 others tetrahedrally"},{"type":"ul","items":["Every C atom is sp³ hybridised, covalently bonded to 4 others in a tetrahedral arrangement.","Bonds extend throughout the entire crystal — no discrete molecules.","EXTREMELY HIGH m.p. ({\\">\\"}3500 °C) — to melt, you must break C–C covalent bonds throughout the structure.","Hardest natural material; used in cutting tools, drill bits.","Insulator — every electron is in a localised σ bond, none free to move.","Insoluble in everything."]},{"type":"h","text":"GIANT COVALENT — GRAPHITE"},{"type":"d","caption":"Graphite — hexagonal layers with delocalised π electrons"},{"type":"ul","items":["Each C atom is sp² hybridised, covalently bonded to 3 others in a planar hexagonal sheet.","The fourth electron from each C goes into a p-orbital perpendicular to the sheet — these overlap to form a DELOCALISED π system spread across the whole layer.","Layers are held together by WEAK vdW forces only.","CONDUCTS electricity — but only IN THE PLANE of the layers (delocalised electrons there); poor conductor perpendicular.","Soft and slippery — layers slide past each other (lubricant; pencil \\"lead\\").","Used in electrodes, lubricants, pencils, structural composites."]},{"type":"h","text":"GIANT COVALENT — SILICON DIOXIDE (SiO₂)"},{"type":"d","caption":"Quartz — Si tetrahedrally bonded to 4 O"},{"type":"ul","items":["Si bonded to 4 O atoms tetrahedrally; each O bridges to 2 Si.","Empirical formula SiO₂ (Si:O = 1:2).","Found in sand, quartz, glass.","Very high m.p. (~1700 °C); insulator; insoluble."]},{"type":"h","text":"METALLIC LATTICE — Cu, Fe, Mg"},{"type":"ul","items":["Lattice of cations in a \\"sea\\" of delocalised valence electrons.","High m.p. (Cu 1085 °C, Fe 1538 °C); densities high; lustrous.","Conducts heat AND electricity even when SOLID — delocalised electrons are mobile.","Malleable and ductile — layers slide; electron sea adapts.","Metallic-bond strength depends on charge density of cation and number of valence electrons donated."]},{"type":"callout","title":"Diamond vs Graphite — same element, very different properties","body":"Both are giant covalent allotropes of pure carbon. Diamond: 4 σ-bonds per C, no free electrons → hardest, insulator. Graphite: 3 σ-bonds per C + 1 delocalised π electron → conducts in the plane, slippery. The structural difference (3-D network vs 2-D layers) drives all the property differences."}]},{"id":"st8","title":"Interconversion of States — Phase Diagrams","blocks":[{"type":"p","text":"A phase diagram shows which state is stable at each combination of temperature and pressure. The lines on the diagram are PHASE BOUNDARIES — at any point on a line, two phases coexist in equilibrium."},{"type":"d","caption":"Schematic phase diagram (water-like)"},{"type":"h","text":"Key features"},{"type":"ul","items":["TRIPLE POINT — single (T, P) where solid, liquid and gas all coexist. For water: 0.01 °C, 0.6 kPa.","CRITICAL POINT — beyond this T, no amount of pressure can liquefy the gas. Above critical, the substance is a \\"supercritical fluid\\".","NORMAL MELTING POINT — temperature on the solid-liquid line at 1 atm pressure.","NORMAL BOILING POINT — temperature on the liquid-gas line at 1 atm pressure."]},{"type":"h","text":"Water is unusual"},{"type":"p","text":"For most substances, the solid-liquid line slopes slightly to the RIGHT (higher P → higher m.p.). For water, the line slopes to the LEFT (higher P → LOWER m.p.). Why? Because ice is less dense than liquid water — applying pressure pushes water to the denser phase, which is LIQUID, not solid. This is why ice skating works."},{"type":"h","text":"Sublimation"},{"type":"p","text":"If atmospheric pressure is below the triple point pressure, the substance has NO liquid phase at that pressure — solid sublimes directly to gas. CO₂ at 1 atm has a triple point at 5.1 atm, so dry ice (CO₂(s)) sublimes rather than melting under normal conditions."}]},{"id":"st9","title":"Strategy & Property-Structure Mapping","blocks":[{"type":"p","text":"Most \\"states of matter\\" questions test three things: identifying lattice type from properties, applying PV=nRT, and explaining behaviour from particle pictures. A few habits clean up most marks."},{"type":"h","text":"Diagnostic — given m.p./conductivity/solubility, identify the lattice"},{"type":"ul","items":["Very high m.p. + non-conductor (or graphite-conducts-in-plane) → GIANT COVALENT.","High m.p. + conducts in solid + malleable → METALLIC.","High m.p. + conducts when molten/aq only → IONIC.","Low m.p. + non-conductor → SIMPLE MOLECULAR (with possible H-bonds if extra-high b.p. for size)."]},{"type":"h","text":"PV = nRT — recipe"},{"type":"ul","items":["1. Convert ALL units: T to K, P to Pa, V to m³ (or use kPa with V in dm³ if R is the convenient form).","2. Identify the unknown — usually V, T, n, or sometimes a missing P.","3. Substitute and solve.","4. Convert the answer back to the question's preferred unit (often dm³)."]},{"type":"h","text":"Comparing two states or two substances — be precise"},{"type":"ul","items":["Always say which forces are strong/weak and what they're between (e.g. \\"vdW BETWEEN I₂ molecules\\", \\"covalent bonds WITHIN diamond\\"). Distinguish intra- from inter-molecular.","For physical-property questions, name the lattice type.","For boiling-point trends, identify the IMF (vdW, dipole-dipole, H-bond) and compare strengths."]},{"type":"callout","title":"A common trap","body":"When asked \\"explain why diamond has a high m.p.\\", do NOT say \\"strong intermolecular forces\\". Diamond has NO intermolecular forces — the entire crystal is ONE molecule, held by covalent bonds. Saying \\"strong covalent bonds throughout the structure\\" earns the mark."}]}]}`),energetics:JSON.parse(`{"objectives":["Explain exothermic and endothermic reactions in terms of enthalpy changes and energy profiles","Define standard enthalpy changes: formation, combustion, neutralisation, atomisation, hydration, solution, lattice energy and electron affinity","Calculate enthalpy changes using q = mcΔT (calorimetry)","Apply Hess's Law to construct energy cycles using ΔHf° and ΔHc° data","Construct and use Born-Haber cycles to calculate lattice energies","Calculate enthalpy changes from mean bond energy data","Explain how charge density (ionic charge and radius) affects lattice energy","Describe thermometric titrations and identify endpoints from temperature-volume graphs"],"chapters":[{"id":"e1","title":"Why Energy Matters in Chemistry","blocks":[{"type":"p","text":"Every chemical reaction involves an energy change. Bonds must break (costs energy) and new bonds form (releases energy). The NET energy change determines whether the reaction gives out heat to its surroundings or absorbs heat from them. This net change is called the ENTHALPY CHANGE, symbol ΔH."},{"type":"h","text":"System and surroundings"},{"type":"ul","items":["The SYSTEM is the chemicals undergoing the reaction — the reactants turning into products.","The SURROUNDINGS are everything else: the solvent, the container, the air, the thermometer, you.","In an exothermic reaction, energy flows FROM the system TO the surroundings; the surroundings warm up, ΔH is negative.","In an endothermic reaction, energy flows FROM the surroundings INTO the system; the surroundings cool down, ΔH is positive."]},{"type":"d","caption":"Exothermic vs endothermic energy profiles"},{"type":"callout","title":"Sign convention","body":"ΔH < 0 means exothermic (heat out). ΔH > 0 means endothermic (heat in). This is from the system's perspective: the system loses energy when exothermic."},{"type":"h","text":"Standard conditions"},{"type":"p","text":"To compare enthalpy values fairly we measure them under STANDARD CONDITIONS: temperature 298 K (25 °C), pressure 100 kPa, all substances in their standard states (the most stable physical form at 298 K and 100 kPa). Standard enthalpy changes are denoted with the symbol °, e.g. ΔH°."},{"type":"takeaway","items":["Enthalpy change ΔH = energy change at constant pressure.","Exothermic: ΔH < 0, surroundings heat up.","Endothermic: ΔH > 0, surroundings cool down.","Standard conditions: 298 K, 100 kPa, standard states."]}]},{"id":"e2","title":"Standard Enthalpy Changes","blocks":[{"type":"p","text":"The syllabus requires you to know several specific enthalpy changes. Each is defined as the enthalpy change per mole of a key participant, under standard conditions."},{"type":"d","caption":"Summary of all standard enthalpy changes"},{"type":"h","text":"Formation (ΔHf°)"},{"type":"p","text":"The enthalpy change when ONE MOLE of a compound is formed from its constituent elements, each in their standard states, under standard conditions. For example: C(graphite) + O₂(g) → CO₂(g), ΔHf° = −394 kJ mol⁻¹."},{"type":"callout","title":"Key rule","body":"The standard enthalpy of formation of any element in its standard state is ZERO by definition. So ΔHf°[O₂(g)] = 0, ΔHf°[C(graphite)] = 0, ΔHf°[Na(s)] = 0."},{"type":"d","caption":"Enthalpy level diagram for formation"},{"type":"h","text":"Combustion (ΔHc°)"},{"type":"p","text":"The enthalpy change when ONE MOLE of a substance is completely burned in excess oxygen under standard conditions. Combustion values are always NEGATIVE (exothermic). For example: CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l), ΔHc° = −890 kJ mol⁻¹."},{"type":"h","text":"Neutralisation (ΔHneut)"},{"type":"p","text":"The enthalpy change when an acid and a base react to form ONE MOLE of water, under standard conditions. For strong acid + strong base, the value is approximately −57.1 kJ mol⁻¹, since the net ionic equation is always: H⁺(aq) + OH⁻(aq) → H₂O(l). Weak acids or bases give slightly less exothermic values because energy is also used to dissociate them."},{"type":"h","text":"Atomisation (ΔHat)"},{"type":"p","text":"The enthalpy change when ONE MOLE of gaseous atoms is formed from the element in its standard state. Always endothermic (positive). For example: ½Cl₂(g) → Cl(g), ΔHat = +121 kJ mol⁻¹. For metals: Na(s) → Na(g), ΔHat = +107 kJ mol⁻¹."},{"type":"takeaway","items":["Each standard enthalpy change is defined per mole of a specific participant.","ΔHf° of all elements in standard states = 0.","ΔHc° is always negative.","ΔHneut ≈ −57 kJ mol⁻¹ for strong acid + strong base.","ΔHat is always positive (bond-breaking requires energy)."]}]},{"id":"e3","title":"Calorimetry: Measuring ΔH","blocks":[{"type":"p","text":"In the lab, we measure enthalpy changes using CALORIMETRY. The basic idea: carry out the reaction in solution, measure the temperature change, and calculate the heat transferred using q = mcΔT."},{"type":"d","caption":"Simple calorimetry apparatus"},{"type":"h","text":"The calculation"},{"type":"ul","items":["Measure the temperature before and after the reaction: ΔT = T_final − T_initial.","Calculate q = m × c × ΔT, where m is the mass of solution (not solid), c is the specific heat capacity of water (4.18 J g⁻¹ K⁻¹), and ΔT is in Kelvin or °C (same magnitude for differences).","q gives the heat absorbed by the solution. For an exothermic reaction the solution warms up, so q is positive — but ΔH for the reaction is NEGATIVE (energy left the system).","Convert to molar: ΔH = −q ÷ (moles of limiting reagent). The sign flip accounts for the system/surroundings convention."]},{"type":"callout","title":"Common exam error","body":"Students often forget the negative sign when converting q to ΔH. If the solution temperature goes UP, the reaction is exothermic, so ΔH must be NEGATIVE. Always check: warm surroundings = exothermic = negative ΔH."},{"type":"h","text":"Sources of error in calorimetry"},{"type":"ul","items":["Heat loss to the surroundings — the main error. Polystyrene cups and lids help, but cannot eliminate it entirely.","Incomplete reaction — if not all the reactant reacts, the measured ΔT is too small.","Assuming the specific heat capacity of the solution equals that of water — reasonable for dilute aqueous solutions, but less accurate for concentrated ones.","Assuming density of solution = 1.00 g cm⁻³ — again, reasonable for dilute solutions."]},{"type":"takeaway","items":["q = mcΔT gives heat absorbed by the solution.","ΔH = −q / n, where n is moles of limiting reagent.","Heat loss is the main source of error.","Polystyrene cup + lid minimises but doesn't eliminate error."]}]},{"id":"e4","title":"Neutralisation, Hydration & Solution","blocks":[{"type":"p","text":"Three more enthalpy changes that the syllabus requires: neutralisation, hydration and solution. They are connected to each other by a Hess cycle that is frequently examined."},{"type":"h","text":"Enthalpy of neutralisation"},{"type":"p","text":"Defined as the enthalpy change when an acid reacts with a base to produce ONE MOLE of water under standard conditions. For any strong acid + strong base, the reaction effectively reduces to H⁺(aq) + OH⁻(aq) → H₂O(l), so ΔHneut ≈ −57.1 kJ mol⁻¹ regardless of which strong acid or base is used."},{"type":"ul","items":["HCl(aq) + NaOH(aq) → NaCl(aq) + H₂O(l), ΔH ≈ −57.1 kJ mol⁻¹.","HNO₃(aq) + KOH(aq) → KNO₃(aq) + H₂O(l), ΔH ≈ −57.1 kJ mol⁻¹.","With a weak acid (e.g. CH₃COOH), ΔHneut is less exothermic (e.g. −55.2 kJ mol⁻¹) because some energy is used to fully dissociate the weak acid."]},{"type":"h","text":"Enthalpy of hydration (ΔHhyd)"},{"type":"p","text":"The enthalpy change when ONE MOLE of a gaseous ion is dissolved in water to form an aqueous ion, under standard conditions: Na⁺(g) → Na⁺(aq). Always exothermic (negative), because ion-dipole attractions form between the ion and water molecules."},{"type":"ul","items":["Hydration enthalpy becomes MORE exothermic with higher charge density — smaller ions and more highly charged ions attract water more strongly.","Trend: Li⁺ > Na⁺ > K⁺ > Rb⁺ (more exothermic for smaller cations).","For anions: F⁻ > Cl⁻ > Br⁻ > I⁻."]},{"type":"h","text":"Enthalpy of solution (ΔHsol)"},{"type":"p","text":"The enthalpy change when ONE MOLE of a solute is dissolved in a solvent (usually water) to form an infinitely dilute solution. The sign can be positive or negative — it depends on the balance between lattice energy and hydration energy."},{"type":"d","caption":"Hess cycle connecting solution, lattice and hydration enthalpies"},{"type":"callout","title":"The key relationship","body":"ΔHsol = −ΔHlatt + ΔHhyd (sum of cation and anion hydration). If hydration releases more energy than it costs to break the lattice, ΔHsol is negative (exothermic dissolving). If not, ΔHsol is positive (endothermic dissolving)."},{"type":"takeaway","items":["ΔHneut ≈ −57 kJ mol⁻¹ for strong acid + strong base; less exothermic for weak.","ΔHhyd is always negative; more exothermic for smaller/more charged ions.","ΔHsol = −ΔHlatt + ΔHhyd (cation + anion) — sign depends on balance."]}]},{"id":"e5","title":"Bond Energy Calculations","blocks":[{"type":"p","text":"Bond energy (also called bond dissociation enthalpy) is the energy required to break ONE MOLE of a specific covalent bond in the GAS PHASE, forming two free radicals. It is always positive (endothermic). We can estimate ΔH for a reaction by comparing the total energy needed to break ALL bonds in the reactants with the energy released when ALL bonds in the products form."},{"type":"d","caption":"Bond energy calculation for combustion of methane"},{"type":"h","text":"The method"},{"type":"ul","items":["Step 1: Draw out full structural formulae so you can count every bond.","Step 2: Sum the energies of ALL bonds broken in the reactants — this total is positive.","Step 3: Sum the energies of ALL bonds formed in the products — this total is negative.","Step 4: ΔH ≈ Σ(bonds broken) − Σ(bonds formed). If the answer is negative, the reaction is exothermic."]},{"type":"callout","title":"Why \\"approximate\\"?","body":"Bond energies are MEAN values averaged over many different molecules. The actual C–H bond energy in CH₄ is slightly different from C–H in CH₃OH. So bond-energy calculations give estimates, not exact values. Hess's Law calculations with formation or combustion data are more accurate."},{"type":"h","text":"Useful bond energies to know"},{"type":"ul","items":["C–H: 412 kJ mol⁻¹, C–C: 348, C=C: 612, C≡C: 837.","O=O: 496, O–H: 463, C=O (in CO₂): 805.","C–O: 360, C=O (in aldehydes/ketones): 740.","H–H: 436, Cl–Cl: 242, N≡N: 944.","You do NOT need to memorise these — they will be given in a data table. But familiarity speeds you up."]},{"type":"takeaway","items":["Bond energy = energy to break 1 mol of bond in gas phase (always +ve).","ΔH ≈ Σ(broken) − Σ(formed).","This gives APPROXIMATE answers because mean bond energies are used.","Draw full structural formulae to count bonds correctly."]}]},{"id":"e6","title":"Hess's Law & Energy Cycles","blocks":[{"type":"p","text":"Hess's Law states that the total enthalpy change for a reaction is independent of the route taken, provided the initial and final conditions are the same. This is a direct consequence of the conservation of energy. It allows us to calculate enthalpy changes that cannot be measured directly by constructing energy CYCLES."},{"type":"d","caption":"General Hess cycle"},{"type":"h","text":"Cycle using enthalpies of formation"},{"type":"p","text":"To find ΔH for a reaction: ΔH = Σ ΔHf°(products) − Σ ΔHf°(reactants). This is the most common Hess cycle at A-level. The \\"intermediates\\" at the bottom of the cycle are the ELEMENTS in their standard states (all with ΔHf° = 0)."},{"type":"ul","items":["Example: CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l).","ΔH = [ΔHf°(CO₂) + 2 × ΔHf°(H₂O)] − [ΔHf°(CH₄) + 2 × ΔHf°(O₂)].","ΔH = [(−394) + 2(−286)] − [(−75) + 2(0)] = −966 − (−75) = −891 kJ mol⁻¹."]},{"type":"h","text":"Cycle using enthalpies of combustion"},{"type":"p","text":"Useful when you know combustion data but not formation data: ΔH = Σ ΔHc°(reactants) − Σ ΔHc°(products). Note the REVERSAL: reactants on top, products on bottom — the arrows flip compared to the formation cycle."},{"type":"ul","items":["Example: C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l) — this IS the combustion equation for ethanol directly.","But to find ΔHf°(ethanol), construct: ΔHf° = [2 × ΔHc°(C) + 3 × ΔHc°(H₂)] − ΔHc°(C₂H₅OH).","This gives the formation enthalpy of ethanol from combustion data of carbon, hydrogen and ethanol."]},{"type":"callout","title":"Arrow direction matters","body":"When you reverse a reaction, you reverse the sign of ΔH. When you multiply a reaction by a coefficient, you multiply ΔH by the same coefficient. These two rules, plus Hess's Law, let you calculate ANY unknown ΔH from known values."},{"type":"takeaway","items":["Hess's Law: ΔH is independent of route.","Using ΔHf°: ΔH = Σ ΔHf°(products) − Σ ΔHf°(reactants).","Using ΔHc°: ΔH = Σ ΔHc°(reactants) − Σ ΔHc°(products).","Reversing a reaction reverses the sign of ΔH."]}]},{"id":"e7","title":"Born-Haber Cycles","blocks":[{"type":"p","text":"A Born-Haber cycle is a special Hess cycle used to calculate LATTICE ENERGY — the enthalpy change when ONE MOLE of an ionic compound is formed from its gaseous ions. Lattice energy cannot be measured directly, so we compute it from quantities that CAN be measured: atomisation, ionisation, electron affinity and formation."},{"type":"d","caption":"Born-Haber cycle for NaCl"},{"type":"h","text":"Building the cycle step by step"},{"type":"ul","items":["Start with elements in standard states: Na(s) + ½Cl₂(g).","Step 1 — Atomise: convert each element to gaseous atoms. Na(s) → Na(g), ΔHat = +107 kJ. ½Cl₂(g) → Cl(g), ΔHat = +121 kJ.","Step 2 — Ionise the metal: Na(g) → Na⁺(g) + e⁻, IE₁ = +496 kJ.","Step 3 — Add electron to non-metal: Cl(g) + e⁻ → Cl⁻(g), EA₁ = −349 kJ (exothermic — Cl gains stability).","Step 4 — Form the lattice: Na⁺(g) + Cl⁻(g) → NaCl(s), ΔHlatt = ? (this is what we're calculating).","The whole cycle connects back to ΔHf°[NaCl] = −411 kJ mol⁻¹."]},{"type":"h","text":"Applying Hess's Law"},{"type":"p","text":"By Hess's Law, the direct route (formation) must equal the sum of all the individual steps: ΔHf° = ΔHat(Na) + ΔHat(Cl) + IE₁(Na) + EA₁(Cl) + ΔHlatt. Rearranging: ΔHlatt = ΔHf° − ΔHat(Na) − ΔHat(Cl) − IE₁(Na) − EA₁(Cl)."},{"type":"ul","items":["ΔHlatt(NaCl) = (−411) − (+107) − (+121) − (+496) − (−349)","= −411 − 107 − 121 − 496 + 349 = −786 kJ mol⁻¹.","The large negative value confirms the strong electrostatic attraction in the NaCl lattice."]},{"type":"callout","title":"For MgO and Al₂O₃","body":"Compounds with higher-charged ions (Mg²⁺, O²⁻, Al³⁺) have MUCH larger lattice energies because the cycle includes IE₁ + IE₂ (for Mg) or IE₁ + IE₂ + IE₃ (for Al), and the second electron affinity for O²⁻ (which is endothermic: O⁻(g) + e⁻ → O²⁻(g), ΔH ≈ +798 kJ). Despite this cost, the enormous lattice energy of MgO (−3850 kJ mol⁻¹) more than compensates."},{"type":"h","text":"Electron affinity details"},{"type":"ul","items":["First electron affinity (EA₁): adding the first electron to a neutral gaseous atom — usually exothermic (atom gains a full/half-full subshell).","Second electron affinity (EA₂): adding a second electron to an already negative ion — always endothermic because you are forcing an electron onto a species that already repels it.","For oxygen: O(g) + e⁻ → O⁻(g), EA₁ = −141 kJ. O⁻(g) + e⁻ → O²⁻(g), EA₂ = +798 kJ. The O²⁻ ion only exists in lattices because the lattice energy compensates for the endothermic EA₂."]},{"type":"takeaway","items":["Born-Haber cycles link ΔHf°, ΔHat, IE, EA and ΔHlatt.","Lattice energy is always large and negative (exothermic formation of lattice).","Rearrange: ΔHlatt = ΔHf° − (all the other steps).","2nd electron affinities are endothermic, but lattice energy compensates."]}]},{"id":"e8","title":"Charge Density & Lattice Energy Factors","blocks":[{"type":"p","text":"Lattice energy depends on the electrostatic attraction between the ions in the lattice. Two factors control this: the CHARGE on the ions and the SIZE (radius) of the ions. Together, these determine the CHARGE DENSITY."},{"type":"d","caption":"Charge density: small + highly charged = stronger attraction"},{"type":"h","text":"Factors affecting lattice energy"},{"type":"ul","items":["IONIC CHARGE: higher charges create stronger electrostatic attraction. MgO (Mg²⁺ and O²⁻) has a much larger lattice energy than NaCl (Na⁺ and Cl⁻), because the 2+ and 2− charges multiply the force.","IONIC RADIUS: smaller ions bring their charges closer together, increasing the force. LiF has a larger lattice energy than NaF because Li⁺ (76 pm) is smaller than Na⁺ (102 pm).","Combined effect — charge density = charge / (ionic radius)². High charge density → strong attraction → large |ΔHlatt|."]},{"type":"h","text":"Comparing lattice energies"},{"type":"ul","items":["NaF (−923) vs NaCl (−786) vs NaBr (−747) vs NaI (−704) kJ mol⁻¹: as the anion gets LARGER, lattice energy decreases in magnitude.","LiCl (−861) vs NaCl (−786) vs KCl (−717) vs RbCl (−689) kJ mol⁻¹: as the cation gets LARGER, lattice energy decreases.","NaCl (−786) vs MgO (−3850) kJ mol⁻¹: doubling the charges roughly quadruples the attraction (Coulomb's law: F ∝ q₁q₂/r²)."]},{"type":"callout","title":"Coulomb's Law link","body":"Lattice energy ∝ (q⁺ × q⁻) / (r⁺ + r⁻). Higher charges in the numerator and smaller radii in the denominator both increase lattice energy. This single relationship explains ALL the trends."},{"type":"takeaway","items":["Lattice energy increases with higher ionic charges.","Lattice energy increases with smaller ionic radii.","Charge density = charge / volume; high charge density → large lattice energy.","Coulomb's Law: ΔHlatt ∝ q⁺q⁻ / (r⁺ + r⁻)."]}]},{"id":"e9","title":"Thermometric Titrations","blocks":[{"type":"p","text":"A thermometric titration is a way to find the endpoint of a reaction by tracking temperature change instead of using an indicator. It works because the reaction is exothermic: as the reactant is added, the temperature rises. Once the endpoint is passed, no more reaction occurs and the excess reagent simply dilutes and cools the mixture."},{"type":"d","caption":"Thermometric titration curve"},{"type":"h","text":"How to read the curve"},{"type":"ul","items":["The temperature rises steadily during the reaction — each added drop of reagent reacts exothermically.","At the ENDPOINT, all the other reagent has been consumed. The peak temperature marks this point.","After the endpoint, adding more reagent produces no reaction. The solution cools because the added liquid dilutes it.","Draw tangent lines to the rising and falling portions of the curve; their intersection gives the endpoint volume."]},{"type":"h","text":"Why use a thermometric titration?"},{"type":"ul","items":["Useful when no suitable indicator exists for the reaction.","Can be used for any exothermic (or endothermic) reaction, not just acid-base.","The method is often used for neutralisation, displacement reactions, and precipitation reactions.","Errors come from heat loss (makes the peak less sharp) and from not stirring fast enough."]},{"type":"takeaway","items":["Plot T against volume of reagent added.","Endpoint = peak temperature (tangent intersection).","Works for any reaction with a measurable heat change."]}]},{"id":"e10","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Energetics questions span calculation, definition and explanation. Here are the most common exam-question types and how to approach them."},{"type":"h","text":"Definitions — get the wording right"},{"type":"ul","items":["Every definition must include: \\"per mole of ...\\" and \\"under standard conditions (298 K, 100 kPa)\\".","Formation: \\"... ONE MOLE of the compound from its ELEMENTS in their STANDARD STATES.\\"","Combustion: \\"... ONE MOLE of the substance is completely burned in EXCESS OXYGEN.\\"","Lattice energy: \\"... when ONE MOLE of the ionic compound is formed from its constituent GASEOUS IONS.\\" (Some syllabi define it in the reverse direction; ZIMSEC uses formation direction.)"]},{"type":"h","text":"Born-Haber calculation — the routine"},{"type":"ul","items":["1. Write the formation equation for the compound.","2. List ALL the steps: atomisation of each element, ionisation of the metal, electron affinities for the non-metal, lattice energy.","3. Apply Hess's Law: ΔHf° = sum of all steps.","4. Rearrange for the unknown (usually lattice energy).","5. Watch signs: IE is always +ve, EA₁ is usually −ve, EA₂ for O is +ve."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Forgetting to halve Cl₂ or O₂ when writing atomisation steps for 1 mol of compound containing one Cl or one O.","Using the wrong sign for electron affinity — the first EA for halogens is exothermic (negative).","In q = mcΔT, using the mass of the SOLID instead of the mass of the SOLUTION.","Confusing bond energy calculations (approximate) with Hess's Law calculations (exact for the given data).","Not stating \\"under standard conditions\\" in definitions."]},{"type":"callout","title":"Mark-scheme tip","body":"For a \\"define\\" question, the three elements that typically earn marks are: (1) \\"one mole of ...\\", (2) the correct specification of reactants/products, and (3) \\"under standard conditions\\". Missing any one of these usually costs a mark."},{"type":"takeaway","items":["Definitions must state \\"per mole\\" and \\"standard conditions\\".","Born-Haber: list all steps, apply Hess, solve for unknown.","q = mcΔT uses mass of SOLUTION, not solid.","Bond energy ≠ Hess cycle accuracy."]}]}]}`),electrochem:JSON.parse(`{"objectives":["Describe redox processes in terms of electron transfer and oxidation state changes","Write and balance half-equations in acidic solution","Describe the standard hydrogen electrode and explain how standard electrode potentials are measured","Use E° values to predict the feasibility of reactions (E°cell = E°cathode − E°anode)","Describe electrolysis of acidified water, copper purification, aluminium extraction and brine","Predict the products of electrolysis of aqueous solutions using E° and concentration","Perform redox titrations (KMnO₄/Fe²⁺ and I₂/thiosulphate) and calculations","Describe hydrogen-oxygen fuel cells and compare with conventional cells","Use Faraday's laws for quantitative electrolysis calculations (Q = It, n = Q/F, F = Le)"],"chapters":[{"id":"ec1","title":"Oxidation & Reduction Revisited","blocks":[{"type":"p","text":"At O-level you met oxidation as gaining oxygen and reduction as losing it. At A-level, we use a more powerful definition based on ELECTRON TRANSFER. Oxidation is LOSS of electrons; reduction is GAIN of electrons. The mnemonic OIL RIG captures this: Oxidation Is Loss, Reduction Is Gain."},{"type":"h","text":"Oxidation states (numbers)"},{"type":"p","text":"An oxidation state is a bookkeeping tool that tracks how many electrons an atom has effectively gained or lost in a compound. By comparing oxidation states before and after a reaction, you can instantly see which species is oxidised and which is reduced."},{"type":"d","caption":"Oxidation state assignment rules"},{"type":"h","text":"Applying the rules"},{"type":"ul","items":["In MnO₂: let Mn = x. x + 2(−2) = 0, so x = +4. Manganese is in the +4 oxidation state.","In Cr₂O₇²⁻: let Cr = x. 2x + 7(−2) = −2, so 2x = +12, x = +6.","An increase in oxidation state = oxidation (electrons lost). A decrease = reduction (electrons gained)."]},{"type":"h","text":"Redox reactions"},{"type":"p","text":"In every redox reaction, one species is oxidised while another is reduced. The oxidised species is the REDUCING AGENT (it donates electrons). The reduced species is the OXIDISING AGENT (it accepts electrons). They always come in pairs."},{"type":"callout","title":"Key terms","body":"Oxidising agent: accepts electrons, is itself reduced. Reducing agent: donates electrons, is itself oxidised. These definitions are the opposite of what the name suggests — a common exam trap."},{"type":"takeaway","items":["Oxidation = loss of electrons = increase in oxidation state.","Reduction = gain of electrons = decrease in oxidation state.","OIL RIG. Reducing agent is oxidised; oxidising agent is reduced."]}]},{"id":"ec2","title":"Writing Half-Equations","blocks":[{"type":"p","text":"A half-equation shows the electron transfer for just ONE species in a redox reaction. Every redox reaction can be split into two half-equations: one for oxidation and one for reduction. Combining them gives the overall ionic equation."},{"type":"h","text":"Balancing half-equations"},{"type":"ul","items":["Step 1: Write the species being oxidised or reduced on each side, showing the change in oxidation state.","Step 2: Balance the change in oxidation state by adding electrons. Electrons go on the LEFT for reduction, on the RIGHT for oxidation.","Step 3: In acidic solution, balance O by adding H₂O, then balance H by adding H⁺.","Step 4: Check that charge balances on both sides."]},{"type":"h","text":"Example: MnO₄⁻ reduction in acid"},{"type":"ul","items":["Mn goes from +7 to +2 — gains 5 electrons: MnO₄⁻ + 5e⁻ → Mn²⁺.","Balance O: add 4H₂O on the right (to account for 4 O atoms): MnO₄⁻ + 5e⁻ → Mn²⁺ + 4H₂O.","Balance H: add 8H⁺ on the left: MnO₄⁻ + 8H⁺ + 5e⁻ → Mn²⁺ + 4H₂O.","Check charge: left = (−1) + 8(+1) + 5(−1) = +2. Right = +2. Balanced."]},{"type":"h","text":"Combining half-equations"},{"type":"p","text":"To get the overall equation, multiply each half-equation so the electrons cancel. For MnO₄⁻ + Fe²⁺: the Mn half needs 5e⁻, the Fe half produces 1e⁻, so multiply the Fe half by 5: MnO₄⁻ + 8H⁺ + 5Fe²⁺ → Mn²⁺ + 4H₂O + 5Fe³⁺."},{"type":"takeaway","items":["Half-equations isolate the oxidation or reduction process.","Balance: atoms first (O with H₂O, H with H⁺), then charge with electrons.","Combine by scaling so electrons cancel."]}]},{"id":"ec3","title":"Standard Electrode Potentials","blocks":[{"type":"p","text":"Every metal (or non-metal) in contact with its ions has a tendency to gain or lose electrons. This tendency is measured as the STANDARD ELECTRODE POTENTIAL (E°), in volts, relative to the Standard Hydrogen Electrode (SHE)."},{"type":"d","caption":"The Standard Hydrogen Electrode — reference point (0.00 V)"},{"type":"h","text":"Measuring E°"},{"type":"ul","items":["Connect the half-cell of interest (e.g. Zn in ZnSO₄) to the SHE via a salt bridge and external wire.","Measure the voltage with a high-resistance voltmeter.","The sign tells you the direction: a negative E° means the half-cell has a greater tendency to lose electrons (more reactive metal); a positive E° means a greater tendency to gain electrons.","All solutions must be 1 mol dm⁻³, temperature 298 K, gas pressures 100 kPa."]},{"type":"h","text":"The electrochemical series"},{"type":"ul","items":["E°(Li⁺/Li) = −3.04 V, E°(Zn²⁺/Zn) = −0.76 V, E°(H⁺/H₂) = 0.00 V, E°(Cu²⁺/Cu) = +0.34 V, E°(Ag⁺/Ag) = +0.80 V, E°(F₂/2F⁻) = +2.87 V.","More negative E° → stronger reducing agent (readily loses electrons).","More positive E° → stronger oxidising agent (readily gains electrons)."]},{"type":"callout","title":"Predicting feasibility","body":"A reaction is thermodynamically feasible if E°cell > 0. E°cell = E°(cathode, the more positive) − E°(anode, the more negative). A positive E°cell means electrons flow spontaneously. BUT feasibility ≠ rate — some feasible reactions are kinetically slow."},{"type":"d","caption":"Zn-Cu cell: E°cell = +1.10 V — feasible and spontaneous"},{"type":"takeaway","items":["E° is measured relative to SHE (0.00 V).","More negative E° = better reducing agent.","E°cell = E°(cathode) − E°(anode); positive → feasible.","Feasibility ≠ speed (kinetics may still be slow)."]}]},{"id":"ec4","title":"Electrolysis: Forcing Non-Spontaneous Reactions","blocks":[{"type":"p","text":"Electrolysis uses electrical energy to drive a non-spontaneous redox reaction. A direct current (DC) supply pushes electrons into the cathode (negative electrode) and pulls them from the anode (positive electrode). Cations migrate to the cathode; anions migrate to the anode."},{"type":"h","text":"Key differences: cell vs electrolysis"},{"type":"ul","items":["In an electrochemical CELL, a spontaneous reaction generates electricity. In ELECTROLYSIS, external electricity forces a reaction.","In both, reduction occurs at the cathode and oxidation at the anode.","In a cell: anode is negative, cathode is positive. In electrolysis: anode is positive, cathode is negative (because the external supply assigns the polarity)."]},{"type":"h","text":"Predicting products of electrolysis"},{"type":"ul","items":["At the cathode: the cation that is EASIEST to reduce (most positive E°) is discharged first. For aqueous solutions, H⁺ may be reduced instead of the metal cation if the metal is very reactive.","At the anode: the anion that is EASIEST to oxidise (most negative E°) is discharged first. For dilute solutions with SO₄²⁻ or NO₃⁻, water is oxidised instead.","Concentration matters: concentrated Cl⁻ is discharged at the anode even though E° suggests water should be preferentially oxidised — kinetic/concentration effects override."]},{"type":"callout","title":"Don't confuse polarity","body":"In electrolysis, the ANODE is POSITIVE (connected to the + terminal of the battery). This is the OPPOSITE of a galvanic cell where the anode is negative. The cathode is always where REDUCTION occurs — that rule never changes."},{"type":"takeaway","items":["Electrolysis: external DC forces a non-spontaneous reaction.","Cathode (−): reduction. Anode (+): oxidation.","Product depends on E° values and concentration of ions."]}]},{"id":"ec5","title":"Electrolysis of Acidified Water","blocks":[{"type":"p","text":"Pure water is a very poor conductor. Adding dilute sulphuric acid provides mobile H⁺ and SO₄²⁻ ions, allowing electrolysis. The acid is NOT consumed — it acts as a catalyst for the decomposition of water into hydrogen and oxygen."},{"type":"d","caption":"Electrolysis of acidified water"},{"type":"h","text":"Electrode reactions"},{"type":"ul","items":["Cathode (−): 2H⁺(aq) + 2e⁻ → H₂(g). Hydrogen gas is produced.","Anode (+): 2H₂O(l) → O₂(g) + 4H⁺(aq) + 4e⁻. Oxygen gas is produced (SO₄²⁻ is NOT discharged because it would require breaking strong S–O bonds).","Overall: 2H₂O(l) → 2H₂(g) + O₂(g). Pure decomposition of water.","Volume of H₂ is DOUBLE the volume of O₂ (2:1 ratio), matching the formula H₂O."]},{"type":"callout","title":"Why not SO₄²⁻?","body":"SO₄²⁻ has a very positive E° for its oxidation — it is extremely difficult to oxidise. Water is much easier to oxidise, so O₂ is produced at the anode instead. This is a common exam question."},{"type":"takeaway","items":["Dilute H₂SO₄ provides ions; acid is NOT consumed.","H₂ at cathode, O₂ at anode, 2:1 volume ratio.","SO₄²⁻ is too stable to be discharged."]}]},{"id":"ec6","title":"Industrial Electrolysis: Al, Cu, Cl₂","blocks":[{"type":"p","text":"Three major industrial electrolysis processes are on the ZIMSEC syllabus: extraction of aluminium, purification of copper, and production of chlorine from brine."},{"type":"h","text":"Extraction of aluminium"},{"type":"d","caption":"The Hall-Héroult process"},{"type":"ul","items":["Aluminium ore (bauxite) is purified to give alumina (Al₂O₃), which has a very high melting point (~2072 °C).","Cryolite (Na₃AlF₆) is added to lower the melting point to ~960 °C, reducing energy costs enormously.","Cathode: Al³⁺ + 3e⁻ → Al. Molten aluminium collects at the bottom of the cell.","Anode: 2O²⁻ → O₂ + 4e⁻. The oxygen produced reacts with the carbon anodes: C + O₂ → CO₂, so anodes must be replaced regularly.","The process is extremely energy-intensive, which is why aluminium smelters are located near cheap electricity (e.g. hydroelectric)."]},{"type":"h","text":"Purification of copper (and nickel)"},{"type":"d","caption":"Electrolytic refining of copper"},{"type":"ul","items":["Anode: impure copper. Cathode: thin sheet of pure copper. Electrolyte: CuSO₄(aq).","Anode: Cu(s) → Cu²⁺(aq) + 2e⁻. Copper dissolves from the impure anode.","Cathode: Cu²⁺(aq) + 2e⁻ → Cu(s). Pure copper is deposited on the cathode.","Impurities less reactive than Cu (Ag, Au, Pt) do not dissolve — they fall to the bottom as \\"anode sludge\\" (valuable!).","Impurities more reactive than Cu (Zn, Fe) dissolve but are NOT deposited (their E° is more negative than Cu²⁺/Cu).","The same principle works for nickel purification using NiSO₄(aq)."]},{"type":"h","text":"Production of chlorine from brine"},{"type":"d","caption":"Membrane cell for brine electrolysis"},{"type":"ul","items":["Concentrated NaCl(aq) — brine — is electrolysed in a membrane cell.","Anode: 2Cl⁻(aq) → Cl₂(g) + 2e⁻. Chlorine gas collected.","Cathode: 2H₂O(l) + 2e⁻ → H₂(g) + 2OH⁻(aq). Hydrogen gas + sodium hydroxide.","The membrane allows Na⁺ to pass through but blocks Cl₂ and OH⁻, preventing them from mixing (which would produce bleach).","Three valuable products: Cl₂ (for bleach, PVC, disinfection), H₂ (fuel, margarine), NaOH (soap, paper)."]},{"type":"takeaway","items":["Al extraction: cryolite lowers m.p.; carbon anodes burn away.","Cu purification: impure anode dissolves, pure Cu deposits on cathode.","Brine: three products — Cl₂, H₂, NaOH. Membrane keeps them separate."]}]},{"id":"ec7","title":"Redox Titrations","blocks":[{"type":"p","text":"A redox titration determines the concentration of a reducing agent (or oxidising agent) by reacting it with a standard solution of an oxidising agent (or reducing agent). The most common A-level redox titrations involve potassium manganate(VII), KMnO₄, or iodine/sodium thiosulphate."},{"type":"d","caption":"KMnO₄ titrated into Fe²⁺ in acid"},{"type":"h","text":"KMnO₄ / Fe²⁺ titration"},{"type":"ul","items":["MnO₄⁻ is purple. Fe²⁺ is pale green. The reaction: MnO₄⁻ + 8H⁺ + 5Fe²⁺ → Mn²⁺ + 4H₂O + 5Fe³⁺.","As KMnO₄ is added to Fe²⁺ (acidified with dilute H₂SO₄), the purple colour disappears instantly as MnO₄⁻ is reduced to colourless Mn²⁺.","At the endpoint, all Fe²⁺ has been consumed. The NEXT DROP of KMnO₄ gives a permanent pale pink colour.","No indicator needed — KMnO₄ is its own indicator."]},{"type":"h","text":"Iodine / thiosulphate titration"},{"type":"ul","items":["Iodine (I₂) is titrated with sodium thiosulphate (Na₂S₂O₃): I₂ + 2S₂O₃²⁻ → 2I⁻ + S₄O₆²⁻.","The brown iodine colour fades as I₂ is consumed. When the solution is pale yellow, add starch indicator.","Starch + I₂ gives a deep blue-black colour. The endpoint is when the blue-black disappears.","This titration is often used to determine the amount of an oxidising agent indirectly: the oxidising agent is first reacted with excess KI to liberate I₂, then the I₂ is titrated with thiosulphate."]},{"type":"callout","title":"Calculation strategy","body":"From the titration: moles of titrant = c × V/1000. Use the stoichiometric ratio from the balanced equation to find moles of analyte. Then calculate concentration or mass as required."},{"type":"takeaway","items":["KMnO₄/Fe²⁺: self-indicating (pink endpoint). Ratio = 1:5.","I₂/thiosulphate: starch indicator (blue → colourless). Ratio = 1:2.","Always use the balanced equation for stoichiometric ratios."]}]},{"id":"ec8","title":"Fuel Cells","blocks":[{"type":"p","text":"A fuel cell converts chemical energy directly into electrical energy, without combustion. The most common type is the hydrogen-oxygen fuel cell, which combines H₂ and O₂ to produce water and electricity."},{"type":"d","caption":"Hydrogen-oxygen fuel cell"},{"type":"h","text":"How it works"},{"type":"ul","items":["Hydrogen gas is fed to the anode. Oxygen gas (or air) is fed to the cathode.","Anode: H₂(g) → 2H⁺(aq) + 2e⁻. Hydrogen is oxidised.","Cathode: O₂(g) + 4H⁺(aq) + 4e⁻ → 2H₂O(l). Oxygen is reduced.","Overall: 2H₂(g) + O₂(g) → 2H₂O(l). The only product is water.","Electrons flow through the external circuit from anode to cathode, doing useful work."]},{"type":"h","text":"Advantages over conventional cells and engines"},{"type":"ul","items":["Clean — only product is water (no CO₂, no pollutants).","Higher efficiency — direct conversion of chemical to electrical energy avoids the thermodynamic losses of combustion engines (Carnot limit).","Continuous operation — as long as fuel is supplied (unlike batteries, which run out).","Quiet operation, no moving parts in the cell itself."]},{"type":"h","text":"Disadvantages and limitations"},{"type":"ul","items":["Hydrogen storage is difficult — it is a low-density gas, requiring compression or cryogenic cooling.","Hydrogen production currently often relies on fossil fuels (steam reforming of natural gas), which produces CO₂.","Platinum catalysts are expensive and limited in supply.","Infrastructure for hydrogen distribution is not widely developed."]},{"type":"takeaway","items":["Fuel cells convert chemical energy directly to electricity.","H₂/O₂ cell: only product is water — clean energy.","Advantages: efficient, clean, continuous.","Challenges: H₂ storage, Pt cost, infrastructure."]}]},{"id":"ec9","title":"Quantitative Electrolysis (Faraday)","blocks":[{"type":"p","text":"Faraday's laws of electrolysis relate the amount of substance deposited or liberated to the quantity of electric charge passed. These calculations connect current, time and moles."},{"type":"d","caption":"The key relationships in quantitative electrolysis"},{"type":"h","text":"The Faraday constant"},{"type":"ul","items":["One Faraday (F) = the charge carried by one mole of electrons = 96 485 C mol⁻¹ ≈ 96 500 C mol⁻¹.","F = L × e, where L = Avogadro constant (6.022 × 10²³ mol⁻¹) and e = charge on one electron (1.602 × 10⁻¹⁹ C).","So F = 6.022 × 10²³ × 1.602 × 10⁻¹⁹ = 96 485 C mol⁻¹."]},{"type":"h","text":"Calculation method"},{"type":"ul","items":["Step 1: Calculate the total charge: Q = I × t (current in amps × time in seconds).","Step 2: Find moles of electrons: n(e⁻) = Q / F.","Step 3: Use the electrode equation to find moles of substance. For Cu²⁺ + 2e⁻ → Cu, every 2 mol e⁻ deposits 1 mol Cu.","Step 4: Convert to mass (m = n × M) or volume (V = n × 24000 cm³ at RTP) as needed."]},{"type":"h","text":"Finding Avogadro's constant experimentally"},{"type":"p","text":"By electrolysing CuSO₄(aq) and measuring the mass of Cu deposited, the current and the time, you can calculate L: L = Q / (n × e), where n is the moles of Cu deposited (from mass/M_r) × 2 (since 2 electrons per Cu atom). This is a common practical in the syllabus."},{"type":"callout","title":"Units check","body":"Current must be in AMPS (not mA) and time must be in SECONDS (not minutes). Q = I × t gives charge in COULOMBS. F ≈ 96 500 C mol⁻¹. These are the most common unit errors in electrolysis calculations."},{"type":"takeaway","items":["Q = I × t (charge = current × time in seconds).","n(e⁻) = Q / F, where F = 96 485 C mol⁻¹.","Use electrode equation stoichiometry to find mass/volume.","Can determine L by electrolysis experiment: L = Q / (n_atoms × e)."]}]},{"id":"ec10","title":"Predicting Electrolysis Products","blocks":[{"type":"p","text":"In aqueous electrolysis, multiple ions compete for discharge. The product at each electrode depends on the E° values AND the concentration of the ions present."},{"type":"h","text":"At the cathode (reduction)"},{"type":"ul","items":["The ion with the MORE POSITIVE E° is preferentially reduced. For metals below hydrogen in the series (Cu²⁺, Ag⁺), the metal is deposited.","For metals above hydrogen (Na⁺, K⁺, Ca²⁺, Al³⁺), H₂O (or H⁺) is reduced instead, producing H₂. The reactive metal ion stays in solution.","Rule of thumb: if the metal is reactive (Group I/II, Al), expect H₂. If it is less reactive (Cu, Ag), expect metal deposition."]},{"type":"h","text":"At the anode (oxidation)"},{"type":"ul","items":["The ion with the MORE NEGATIVE E° is preferentially oxidised. Halide ions (Cl⁻, Br⁻, I⁻) are often discharged.","SO₄²⁻ and NO₃⁻ are NOT discharged — water is oxidised instead, giving O₂.","Exception: in DILUTE Cl⁻ solutions, water may be oxidised preferentially (giving O₂ instead of Cl₂). In CONCENTRATED Cl⁻, chlorine is produced — concentration overrides E° in this case."]},{"type":"callout","title":"Concentration effect","body":"The discharge of Cl⁻ vs H₂O at the anode is a favourite exam question. In concentrated NaCl (brine), Cl₂ is produced. In dilute NaCl, O₂ is produced. Always state the concentration when predicting products."},{"type":"takeaway","items":["Cathode: most positive E° ion is reduced. Reactive metals → H₂ instead.","Anode: most negative E° ion is oxidised. SO₄²⁻/NO₃⁻ → O₂ from water.","Concentration can override E° (especially for Cl⁻ vs H₂O)."]}]},{"id":"ec11","title":"Rusting & Corrosion Prevention","blocks":[{"type":"p","text":"Rusting is an electrochemical process. Iron in contact with water and oxygen forms an electrochemical cell on the metal surface, leading to oxidation of Fe and reduction of O₂. Understanding this helps explain prevention methods."},{"type":"h","text":"The rusting process"},{"type":"ul","items":["Anodic region (where iron dissolves): Fe(s) → Fe²⁺(aq) + 2e⁻.","Cathodic region (where oxygen is reduced): O₂(aq) + 2H₂O(l) + 4e⁻ → 4OH⁻(aq).","Fe²⁺ and OH⁻ combine: Fe²⁺ + 2OH⁻ → Fe(OH)₂, which is further oxidised by air to Fe₂O₃·xH₂O (rust).","Both WATER and OXYGEN are needed. Iron does not rust in dry air or in boiled (oxygen-free) water."]},{"type":"h","text":"Prevention methods"},{"type":"ul","items":["Barrier methods: paint, oil, plastic coating, tin plating — keep water and oxygen away from the iron surface.","Galvanising: coating with zinc. Even if the zinc layer is scratched, zinc is more reactive and is preferentially oxidised (sacrificial protection).","Sacrificial protection: attaching blocks of zinc or magnesium to iron structures (e.g. ship hulls, pipelines). The more reactive metal corrodes instead of the iron.","Stainless steel: alloying iron with chromium (and nickel) forms a protective Cr₂O₃ layer."]},{"type":"takeaway","items":["Rusting = electrochemical oxidation of Fe requiring water + O₂.","Barrier methods block access. Sacrificial protection uses a more reactive metal.","Galvanising (Zn coating) provides both barrier and sacrificial protection."]}]},{"id":"ec12","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Electrochemistry spans redox definitions, electrode potentials, electrolysis, fuel cells and calculations. Here are the key exam patterns and mistakes to avoid."},{"type":"h","text":"Half-equation questions"},{"type":"ul","items":["Always balance atoms first, then charge. Show your working — marks are given for the method.","In acidic solution, use H₂O and H⁺ to balance O and H. In alkaline solution (rare at ZIMSEC), you may need OH⁻.","Check your final equation: total charge on the left must equal total charge on the right."]},{"type":"h","text":"E° cell calculation mistakes"},{"type":"ul","items":["E°cell = E°(cathode) − E°(anode). The cathode is the MORE POSITIVE half-cell.","Do NOT double or halve E° values when scaling half-equations. E° is an intensive property — it does NOT change when you multiply the equation by a coefficient.","A positive E°cell means the reaction is feasible. A negative value means the REVERSE is feasible."]},{"type":"h","text":"Electrolysis calculation errors"},{"type":"ul","items":["Convert time to SECONDS before using Q = It.","Use the correct number of electrons from the half-equation (e.g. 2e⁻ for Cu²⁺, 3e⁻ for Al³⁺).","If asked for volume of gas, use n × 24 000 cm³ at RTP (or n × 22 400 cm³ at STP if specified)."]},{"type":"h","text":"Fuel cell questions"},{"type":"ul","items":["Write both electrode equations and the overall equation.","Know at least two advantages and two disadvantages.","Compare with conventional cells: fuel cells are NOT rechargeable — they are continuously fed fuel."]},{"type":"callout","title":"Frequently tested","body":"The \\"why is Cl₂ produced from concentrated NaCl but O₂ from dilute NaCl?\\" question appears regularly. Your answer needs to mention the concentration effect overriding E° predictions."},{"type":"takeaway","items":["Balance half-equations: atoms first, then charge.","E° is intensive — never multiply it by stoichiometric coefficients.","Q = It; convert to seconds; use F = 96 500.","Fuel cells: continuous feed, water only product, Pt catalyst limitation."]}]}]}`),equilibria:JSON.parse(`{"objectives":["Explain reversible reactions and dynamic equilibrium in a closed system","Deduce Kc and Kp expressions and calculate their values from equilibrium data","Apply Le Chatelier's principle to predict the effect of changes in concentration, pressure and temperature","Define acids and bases using the Brønsted-Lowry theory; distinguish strong from weak","Calculate pH and pOH for strong and weak acids/bases using Ka, Kb and Kw","Describe and interpret titration curves for all four acid-base combinations","Choose appropriate indicators based on titration curve shape and pKin","Explain buffer action and calculate buffer pH using Henderson-Hasselbalch","Apply solubility product (Ksp) to calculate solubility and predict precipitation","Explain the common ion effect on solubility"],"chapters":[{"id":"eq1","title":"Reversible Reactions & Dynamic Equilibrium","blocks":[{"type":"p","text":"Many reactions do not go to completion. Instead, the forward reaction produces products while the reverse reaction simultaneously converts products back to reactants. When these two rates become EQUAL, the system reaches DYNAMIC EQUILIBRIUM: the concentrations of all species stop changing, even though both reactions continue."},{"type":"d","caption":"Rate vs time: equilibrium is reached when forward rate = reverse rate"},{"type":"h","text":"Characteristics of dynamic equilibrium"},{"type":"ul","items":["The reaction has NOT stopped — both forward and reverse reactions continue at equal rates.","Macroscopic properties (concentrations, colour, pressure) remain CONSTANT.","It can only be established in a CLOSED SYSTEM (nothing enters or leaves).","The position of equilibrium may favour products or reactants — the equilibrium constant tells you which."]},{"type":"callout","title":"Dynamic equilibrium","body":"A state in which the rate of the forward reaction equals the rate of the reverse reaction, so that the concentrations of reactants and products remain constant. The system must be closed."},{"type":"h","text":"Open vs closed systems"},{"type":"p","text":"An open system allows matter to enter or leave (e.g. an open beaker where gas escapes). Equilibrium cannot be established because products are continually removed. A closed system (sealed container) keeps everything in, allowing equilibrium to develop."},{"type":"takeaway","items":["Dynamic equilibrium: rate forward = rate reverse in a closed system.","Concentrations stay constant but reactions continue.","Position can favour products or reactants."]}]},{"id":"eq2","title":"The Equilibrium Constant Kc","blocks":[{"type":"p","text":"For the general equilibrium aA + bB ⇌ cC + dD, the equilibrium constant in terms of concentrations is Kc = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ, where each concentration is the value AT EQUILIBRIUM."},{"type":"d","caption":"The Kc expression"},{"type":"h","text":"Key rules"},{"type":"ul","items":["Products on top, reactants on bottom — always.","Each concentration is raised to the power of its stoichiometric coefficient.","PURE SOLIDS and PURE LIQUIDS are omitted (their activity = 1). Water is omitted when it is the solvent.","Kc has units that depend on the overall change in moles. Work them out from the expression.","Kc changes ONLY when TEMPERATURE changes. Changing concentration, pressure or adding a catalyst does NOT change Kc."]},{"type":"h","text":"What Kc tells you"},{"type":"ul","items":["Kc >> 1: equilibrium lies far to the RIGHT (products dominate).","Kc << 1: equilibrium lies far to the LEFT (reactants dominate).","Kc ≈ 1: significant amounts of both present."]},{"type":"h","text":"Calculating Kc — the ICE table method"},{"type":"p","text":"Set up a table with rows for Initial concentration, Change, and Equilibrium concentration. Use stoichiometry to express the changes in terms of a single variable x. Substitute the equilibrium values into the Kc expression and solve."},{"type":"callout","title":"Units of Kc","body":"If Δn = (c + d) − (a + b) = 0, Kc has no units. If Δn = 1, units are mol dm⁻³. If Δn = −1, units are mol⁻¹ dm³. Always work out units explicitly from the expression."},{"type":"takeaway","items":["Kc = products over reactants, each raised to its coefficient.","Omit pure solids and liquids.","Kc changes only with temperature.","Large Kc = products favoured; small Kc = reactants favoured."]}]},{"id":"eq3","title":"The Equilibrium Constant Kp","blocks":[{"type":"p","text":"For equilibria involving gases, we often express the equilibrium constant in terms of PARTIAL PRESSURES rather than concentrations. This is Kp."},{"type":"d","caption":"The Kp expression"},{"type":"h","text":"Partial pressures"},{"type":"ul","items":["The partial pressure of gas X = (mole fraction of X) × (total pressure).","Mole fraction of X = moles of X / total moles of gas at equilibrium.","The sum of all partial pressures = total pressure (Dalton's Law)."]},{"type":"h","text":"Calculating Kp — example"},{"type":"p","text":"Consider: N₂(g) + 3H₂(g) ⇌ 2NH₃(g). At equilibrium in a sealed vessel at 500 K and 200 atm, the mole fractions are: N₂ = 0.20, H₂ = 0.60, NH₃ = 0.20."},{"type":"ul","items":["Partial pressures: pN₂ = 0.20 × 200 = 40 atm, pH₂ = 0.60 × 200 = 120 atm, pNH₃ = 0.20 × 200 = 40 atm.","Kp = (pNH₃)² / [(pN₂)(pH₂)³] = (40)² / [(40)(120)³] = 1600 / (40 × 1 728 000) = 1600 / 69 120 000 = 2.31 × 10⁻⁵ atm⁻².","Δn = 2 − (1 + 3) = −2, so units are atm⁻² (or Pa⁻² if using pascals)."]},{"type":"callout","title":"Kp vs Kc","body":"Kp uses partial pressures (gases only). Kc uses molar concentrations. They are related by Kp = Kc(RT)^Δn but you rarely need to convert between them at ZIMSEC level — just use whichever the question specifies."},{"type":"takeaway","items":["Kp applies to gaseous equilibria using partial pressures.","pX = mole fraction × total pressure.","Units of Kp depend on Δn.","Kp changes only with temperature."]}]},{"id":"eq4","title":"Le Chatelier's Principle","blocks":[{"type":"p","text":"Le Chatelier's Principle states: when a system at equilibrium is subjected to a change in concentration, temperature or pressure, the equilibrium shifts in the direction that tends to OPPOSE the change."},{"type":"d","caption":"Summary of Le Chatelier's responses"},{"type":"h","text":"Concentration changes"},{"type":"ul","items":["Adding more of a reactant: equilibrium shifts RIGHT to use it up. More product is formed.","Removing a product (e.g. condensing it out): equilibrium shifts RIGHT to replace it.","These changes alter the POSITION of equilibrium but NOT the value of Kc (temperature unchanged)."]},{"type":"h","text":"Pressure changes (gaseous systems only)"},{"type":"ul","items":["Increasing pressure: equilibrium shifts towards the side with FEWER moles of gas.","Decreasing pressure: shifts towards the side with MORE moles of gas.","If both sides have the same number of gas moles (e.g. H₂ + I₂ ⇌ 2HI), pressure changes have NO effect on position.","Adding an INERT GAS at constant volume does NOT change partial pressures of reactants or products, so NO shift."]},{"type":"h","text":"Temperature changes"},{"type":"ul","items":["Increasing temperature favours the ENDOTHERMIC direction (the system absorbs the extra heat).","For an exothermic forward reaction: ↑T shifts equilibrium LEFT (Kc decreases).","For an endothermic forward reaction: ↑T shifts equilibrium RIGHT (Kc increases).","Temperature is the ONLY factor that changes the VALUE of K."]},{"type":"h","text":"Catalysts"},{"type":"p","text":"A catalyst speeds up both the forward AND reverse reactions equally. It does NOT change the position of equilibrium or the value of K. It only makes equilibrium reached FASTER."},{"type":"takeaway","items":["System opposes the imposed change.","Concentration/pressure changes shift position but NOT K.","Temperature changes shift position AND change K.","Catalyst: faster equilibrium, no shift, no K change."]}]},{"id":"eq5","title":"Brønsted-Lowry Acids & Bases","blocks":[{"type":"p","text":"The Brønsted-Lowry definition is broader than the Arrhenius one. A Brønsted-Lowry ACID is a proton (H⁺) DONOR. A Brønsted-Lowry BASE is a proton ACCEPTOR. Every acid-base reaction involves the transfer of a proton from the acid to the base."},{"type":"h","text":"Conjugate acid-base pairs"},{"type":"ul","items":["When an acid HA donates a proton, it forms its conjugate base A⁻: HA → H⁺ + A⁻.","When a base B accepts a proton, it forms its conjugate acid BH⁺: B + H⁺ → BH⁺.","Every acid-base reaction has TWO conjugate pairs. For HCl + NH₃ → NH₄⁺ + Cl⁻: pair 1 is HCl/Cl⁻, pair 2 is NH₄⁺/NH₃.","Water is AMPHOTERIC — it can act as both acid (donating H⁺ to form OH⁻) and base (accepting H⁺ to form H₃O⁺)."]},{"type":"h","text":"Strong vs weak acids and bases"},{"type":"ul","items":["A STRONG acid is completely dissociated in aqueous solution: HCl(aq) → H⁺(aq) + Cl⁻(aq) (100%). Examples: HCl, HNO₃, H₂SO₄.","A WEAK acid is partially dissociated: CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq) (equilibrium, typically < 5% dissociated). Example: ethanoic acid.","A STRONG base is completely dissociated: NaOH(aq) → Na⁺(aq) + OH⁻(aq).","A WEAK base is partially protonated: NH₃(aq) + H₂O(l) ⇌ NH₄⁺(aq) + OH⁻(aq).","Strong ≠ concentrated. Concentrated refers to amount per volume; strong refers to degree of dissociation."]},{"type":"callout","title":"Exam favourite","body":"\\"Strong\\" means fully dissociated (all molecules donate/accept H⁺). \\"Weak\\" means only partially dissociated (equilibrium lies to the left). \\"Concentrated\\" means high molarity. A DILUTE STRONG acid (e.g. 0.001 mol dm⁻³ HCl) is still 100% dissociated."},{"type":"takeaway","items":["Acid = H⁺ donor; Base = H⁺ acceptor (Brønsted-Lowry).","Conjugate pairs differ by one H⁺.","Strong = fully dissociated; Weak = partially dissociated.","Strong ≠ concentrated."]}]},{"id":"eq6","title":"pH, pOH and the Ionic Product of Water","blocks":[{"type":"p","text":"pH is a logarithmic scale that measures the concentration of hydrogen ions in solution. The lower the pH, the more acidic the solution."},{"type":"d","caption":"The pH scale and key formulas"},{"type":"h","text":"Key relationships"},{"type":"ul","items":["pH = −log₁₀[H⁺]. So [H⁺] = 10⁻ᵖᴴ.","pOH = −log₁₀[OH⁻]. So [OH⁻] = 10⁻ᵖᴼᴴ.","The ionic product of water: Kw = [H⁺][OH⁻] = 1.00 × 10⁻¹⁴ mol² dm⁻⁶ at 298 K.","pKw = pH + pOH = 14.0 at 298 K."]},{"type":"h","text":"pH of strong acids"},{"type":"ul","items":["Monobasic strong acid (e.g. HCl): [H⁺] = concentration of the acid. pH = −log[acid].","Dibasic strong acid (e.g. H₂SO₄): [H⁺] = 2 × concentration. pH = −log(2 × [acid]).","Example: 0.010 mol dm⁻³ HCl → [H⁺] = 0.010 → pH = −log(0.010) = 2.0."]},{"type":"h","text":"pH of strong bases"},{"type":"ul","items":["Strong base (e.g. NaOH): [OH⁻] = concentration. Find [H⁺] = Kw/[OH⁻], then pH = −log[H⁺].","Or find pOH first, then pH = 14 − pOH.","Example: 0.010 mol dm⁻³ NaOH → [OH⁻] = 0.010 → pOH = 2.0 → pH = 12.0."]},{"type":"callout","title":"Temperature dependence of Kw","body":"Kw increases with temperature because the dissociation of water is endothermic. At higher temperatures, [H⁺] and [OH⁻] are both larger, so pH of pure water falls below 7. But the water is still neutral because [H⁺] = [OH⁻]."},{"type":"takeaway","items":["pH = −log[H⁺]; pOH = −log[OH⁻]; pH + pOH = 14 at 298 K.","Kw = [H⁺][OH⁻] = 1.0 × 10⁻¹⁴ at 298 K.","Strong acid: [H⁺] = acid concentration directly.","Strong base: find [OH⁻] first, then [H⁺] = Kw/[OH⁻]."]}]},{"id":"eq7","title":"Ka, pKa, Kb, pKb — Weak Acid & Base Calculations","blocks":[{"type":"p","text":"Weak acids and bases establish an equilibrium in solution. The extent of their dissociation is quantified by the acid dissociation constant Ka (for acids) or the base dissociation constant Kb (for bases)."},{"type":"h","text":"Ka — acid dissociation constant"},{"type":"ul","items":["For a weak acid HA ⇌ H⁺ + A⁻: Ka = [H⁺][A⁻] / [HA].","pKa = −log₁₀Ka. A smaller pKa means a STRONGER weak acid (more dissociated).","Assumption for calculations: since dissociation is small, [HA]_equilibrium ≈ [HA]_initial. This simplifies the algebra.","From Ka and [HA]: [H⁺] = √(Ka × [HA]). Then pH = −log[H⁺]."]},{"type":"h","text":"Example: pH of 0.100 mol dm⁻³ CH₃COOH (Ka = 1.74 × 10⁻⁵)"},{"type":"ul","items":["[H⁺] = √(1.74 × 10⁻⁵ × 0.100) = √(1.74 × 10⁻⁶) = 1.32 × 10⁻³ mol dm⁻³.","pH = −log(1.32 × 10⁻³) = 2.88.","Check assumption: % dissociation = (1.32 × 10⁻³ / 0.100) × 100 = 1.3%. This is < 5%, so the approximation is valid."]},{"type":"h","text":"Kb — base dissociation constant"},{"type":"ul","items":["For a weak base B + H₂O ⇌ BH⁺ + OH⁻: Kb = [BH⁺][OH⁻] / [B].","pKb = −log₁₀Kb. Smaller pKb = stronger weak base.","[OH⁻] = √(Kb × [B]). Then pOH = −log[OH⁻], and pH = 14 − pOH."]},{"type":"h","text":"Relationship between Ka, Kb and Kw"},{"type":"p","text":"For a conjugate acid-base pair: Ka × Kb = Kw = 1.0 × 10⁻¹⁴ at 298 K. Equivalently: pKa + pKb = pKw = 14.0. This means a strong acid has a weak conjugate base, and vice versa."},{"type":"callout","title":"The √(Ka·c) shortcut","body":"For a weak acid of concentration c: [H⁺] ≈ √(Ka × c), provided c/Ka > 100 (so that the % dissociation is small enough for the approximation). If this condition fails, solve the quadratic exactly."},{"type":"takeaway","items":["Ka = [H⁺][A⁻]/[HA]; pKa = −logKa.","Weak acid pH: [H⁺] ≈ √(Ka × c).","Kb = [BH⁺][OH⁻]/[B]; pKb = −logKb.","Ka × Kb = Kw; pKa + pKb = 14."]}]},{"id":"eq8","title":"Titration Curves","blocks":[{"type":"p","text":"A titration curve plots pH against volume of titrant added. The shape of the curve tells you the strengths of the acid and base involved, and it determines which indicator is suitable."},{"type":"d","caption":"The four types of acid-base titration curve"},{"type":"h","text":"Reading the curves"},{"type":"ul","items":["Strong acid + strong base: starts low (pH ≈ 1), very steep vertical jump at equivalence through pH 7, finishes high (pH ≈ 13). The equivalence point is at pH 7.","Weak acid + strong base: starts higher (pH ≈ 3–4 for a typical weak acid), has a BUFFER REGION before the equivalence point, steep jump at equivalence above pH 7 (pH ≈ 8–10). Equivalence point is ABOVE 7 because the conjugate base A⁻ hydrolyses.","Strong acid + weak base: starts low, steep jump at equivalence below pH 7 (pH ≈ 4–6). The conjugate acid BH⁺ is slightly acidic.","Weak acid + weak base: very gradual change, no sharp vertical section. No suitable simple indicator exists — use a different method (e.g. conductimetric or potentiometric titration)."]},{"type":"h","text":"Half-equivalence point"},{"type":"p","text":"At the half-equivalence point, exactly HALF the acid has been neutralised. At this point [HA] = [A⁻], so the Henderson-Hasselbalch equation gives pH = pKa. This is a quick way to read pKa from a titration curve — find the pH at half the equivalence volume."},{"type":"callout","title":"Buffer region","body":"On the weak acid + strong base curve, the relatively flat region BEFORE the equivalence point is a buffer region. Here, both HA and A⁻ are present in comparable amounts, and the pH resists change. The half-equivalence point is in the middle of this region, where pH = pKa."},{"type":"takeaway","items":["SA+SB: equivalence at pH 7; sharp jump; any indicator works.","WA+SB: equivalence above pH 7; phenolphthalein.","SA+WB: equivalence below pH 7; methyl orange.","WA+WB: no sharp jump; no simple indicator.","Half-equivalence: pH = pKa."]}]},{"id":"eq9","title":"Choice of Indicators","blocks":[{"type":"p","text":"An acid-base indicator is itself a weak acid (HIn) whose conjugate base (In⁻) has a DIFFERENT COLOUR. The indicator changes colour over a narrow pH range (about 2 pH units) centred on its pKin."},{"type":"d","caption":"Indicator pH ranges"},{"type":"h","text":"How indicators work"},{"type":"ul","items":["HIn(aq) ⇌ H⁺(aq) + In⁻(aq). HIn has colour A; In⁻ has colour B.","In acid (excess H⁺), equilibrium lies LEFT → mostly HIn → colour A dominates.","In base (low H⁺), equilibrium lies RIGHT → mostly In⁻ → colour B dominates.","The colour change occurs over a pH range of approximately pKin ± 1."]},{"type":"h","text":"Matching indicator to titration"},{"type":"ul","items":["The indicator's colour-change range must fall within the STEEP (vertical) part of the titration curve.","Strong acid + strong base: the steep section spans pH ≈ 3–11. Almost any indicator works.","Weak acid + strong base: steep section is pH ≈ 7–11. Use phenolphthalein (range 8.3–10.0).","Strong acid + weak base: steep section is pH ≈ 3–7. Use methyl orange (range 3.1–4.4).","Weak acid + weak base: no steep section → no simple indicator works."]},{"type":"takeaway","items":["Indicator = weak acid with differently coloured conjugate base.","Change occurs at pH ≈ pKin ± 1.","Match the indicator's range to the steep part of the titration curve."]}]},{"id":"eq10","title":"Buffer Solutions","blocks":[{"type":"p","text":"A buffer solution resists changes in pH when small amounts of acid or base are added. It consists of a WEAK ACID and its CONJUGATE BASE (acidic buffer) or a WEAK BASE and its CONJUGATE ACID (basic buffer), both present in significant amounts."},{"type":"d","caption":"How an acidic buffer resists pH change"},{"type":"h","text":"Making an acidic buffer"},{"type":"ul","items":["Mix a weak acid with a salt of its conjugate base. Example: CH₃COOH + CH₃COONa gives a buffer at pH ≈ 4.7.","Alternatively, partially neutralise a weak acid with a strong base: some HA is converted to A⁻, leaving a mixture of both.","The large reservoir of HA can neutralise added OH⁻. The large reservoir of A⁻ can neutralise added H⁺."]},{"type":"h","text":"Calculating buffer pH"},{"type":"ul","items":["Henderson-Hasselbalch equation: pH = pKa + log₁₀([A⁻]/[HA]).","When [A⁻] = [HA], pH = pKa. This is the optimal buffer point (maximum buffering capacity).","A buffer works effectively within about 1 pH unit either side of pKa.","To use the equation: find the moles of HA and A⁻ present, then substitute."]},{"type":"h","text":"Buffer in biological systems"},{"type":"ul","items":["Blood is buffered at pH 7.4 by the carbonic acid / hydrogencarbonate system: H₂CO₃ / HCO₃⁻.","Soil pH is buffered by various organic acid / conjugate base systems — critical for plant growth.","Enzyme activity depends on pH; buffers maintain the narrow range where enzymes function optimally."]},{"type":"callout","title":"Exam approach","body":"Buffer pH calculation: (1) Find moles of HA and A⁻ after mixing. (2) Substitute into pH = pKa + log([A⁻]/[HA]). Note: because the ratio is moles divided by moles, volumes cancel — you can use moles directly."},{"type":"takeaway","items":["Buffer = weak acid + conjugate base (or weak base + conjugate acid).","pH = pKa + log([A⁻]/[HA]).","At [A⁻] = [HA], pH = pKa (maximum buffer capacity).","Blood buffered at pH 7.4 by H₂CO₃/HCO₃⁻."]}]},{"id":"eq11","title":"Solubility Product Ksp","blocks":[{"type":"p","text":"For sparingly soluble salts, the equilibrium between the solid and its dissolved ions is described by the solubility product, Ksp. It applies only to salts that are SLIGHTLY soluble — not to highly soluble salts like NaCl."},{"type":"d","caption":"Ksp and the precipitation rule"},{"type":"h","text":"Writing Ksp expressions"},{"type":"ul","items":["AgCl(s) ⇌ Ag⁺(aq) + Cl⁻(aq): Ksp = [Ag⁺][Cl⁻].","PbI₂(s) ⇌ Pb²⁺(aq) + 2I⁻(aq): Ksp = [Pb²⁺][I⁻]².","Ca₃(PO₄)₂(s) ⇌ 3Ca²⁺(aq) + 2PO₄³⁻(aq): Ksp = [Ca²⁺]³[PO₄³⁻]².","The solid is omitted (activity = 1)."]},{"type":"h","text":"Calculating solubility from Ksp"},{"type":"ul","items":["Let solubility = s mol dm⁻³. For AgCl: [Ag⁺] = s, [Cl⁻] = s. So Ksp = s², giving s = √Ksp.","For PbI₂: [Pb²⁺] = s, [I⁻] = 2s. So Ksp = s × (2s)² = 4s³, giving s = ∛(Ksp/4).","Always define s clearly and link each ion's concentration to s using the stoichiometry."]},{"type":"h","text":"Predicting precipitation"},{"type":"ul","items":["Calculate the ionic product (IP) by substituting the actual ion concentrations (not equilibrium).","If IP > Ksp: solution is supersaturated → precipitation occurs until IP = Ksp.","If IP < Ksp: unsaturated → no precipitate; more solid could dissolve.","If IP = Ksp: saturated → system is at equilibrium."]},{"type":"takeaway","items":["Ksp = product of ion concentrations raised to stoichiometric powers.","Solubility s relates to Ksp via stoichiometry.","IP > Ksp → precipitate forms; IP < Ksp → no precipitate."]}]},{"id":"eq12","title":"The Common Ion Effect","blocks":[{"type":"p","text":"The common ion effect describes how the solubility of a sparingly soluble salt DECREASES when a common ion (one already present in the equilibrium) is added from an external source."},{"type":"d","caption":"Common ion effect on AgCl solubility"},{"type":"h","text":"How it works"},{"type":"ul","items":["AgCl(s) ⇌ Ag⁺(aq) + Cl⁻(aq), Ksp = 1.8 × 10⁻¹⁰.","In pure water: s = √(1.8 × 10⁻¹⁰) = 1.34 × 10⁻⁵ mol dm⁻³.","Now dissolve AgCl in 0.10 mol dm⁻³ NaCl. The NaCl provides a large concentration of Cl⁻.","Ksp = [Ag⁺] × [Cl⁻] still = 1.8 × 10⁻¹⁰. But [Cl⁻] ≈ 0.10 (from NaCl, much larger than s).","So [Ag⁺] = Ksp / [Cl⁻] = 1.8 × 10⁻¹⁰ / 0.10 = 1.8 × 10⁻⁹ mol dm⁻³.","Solubility has dropped from 1.34 × 10⁻⁵ to 1.8 × 10⁻⁹ — roughly 7500× less soluble."]},{"type":"h","text":"Application"},{"type":"ul","items":["Common ion effect is used in qualitative analysis: adding HCl to precipitate AgCl from a solution of Ag⁺.","Also used to suppress dissociation of weak acids: adding NaCH₃COO to CH₃COOH reduces [H⁺] (and this is how a buffer works — the common ion A⁻ suppresses dissociation of HA)."]},{"type":"takeaway","items":["Adding a common ion decreases solubility of a sparingly soluble salt.","Ksp does NOT change — it is a constant at a given temperature.","The equilibrium shifts left (Le Chatelier) to maintain Ksp."]}]},{"id":"eq13","title":"Putting It All Together — Calculations","blocks":[{"type":"p","text":"Equilibria calculations at A-level fall into clear patterns. Here is a summary of the main types and the approach for each."},{"type":"h","text":"Type 1: Find Kc from equilibrium data"},{"type":"ul","items":["You are given initial amounts and the equilibrium amount of one species.","Use stoichiometry to find the equilibrium amounts of all species.","Divide by volume to get concentrations (if needed).","Substitute into the Kc expression."]},{"type":"h","text":"Type 2: Find equilibrium amounts from Kc"},{"type":"ul","items":["Set up an ICE table with x as the unknown change.","Substitute equilibrium expressions into Kc = ... and solve for x.","Often gives a quadratic equation; use the formula or trial-and-improvement."]},{"type":"h","text":"Type 3: pH of weak acid/base"},{"type":"ul","items":["Weak acid: [H⁺] = √(Ka × c). Then pH = −log[H⁺].","Weak base: [OH⁻] = √(Kb × c). Then pOH = −log[OH⁻]; pH = 14 − pOH.","Always check: % dissociation < 5% for the approximation to hold."]},{"type":"h","text":"Type 4: Buffer pH"},{"type":"ul","items":["Find moles of HA and A⁻ after any reaction.","pH = pKa + log([A⁻]/[HA]). Volumes cancel so use moles directly."]},{"type":"h","text":"Type 5: Ksp and solubility"},{"type":"ul","items":["Define s, express each ion in terms of s, substitute into Ksp.","With common ion: one ion concentration comes from the external source; s is only the contribution from the sparingly soluble salt."]},{"type":"takeaway","items":["ICE tables for Kc; √(Ka·c) for weak acid pH; Henderson-Hasselbalch for buffers.","Define variables clearly and show units.","Always check approximations are valid."]}]},{"id":"eq14","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Equilibria is one of the highest-weighted topics in the exam. Here are the common traps and how to avoid them."},{"type":"h","text":"Definition traps"},{"type":"ul","items":["Strong ≠ concentrated. The question \\"distinguish between strong and concentrated\\" appears regularly — define both precisely.","Dynamic equilibrium must state \\"rates are equal\\" AND \\"in a closed system\\". Both are required for the mark.","Le Chatelier: say \\"the equilibrium shifts to ...\\" not \\"the reaction speeds up\\". Shifts describe position, not rate."]},{"type":"h","text":"Calculation traps"},{"type":"ul","items":["Units of Kc: always work them out. Examiners often give a value with units and ask you to verify the expression.","Kp: remember to convert moles to mole fractions FIRST, then to partial pressures.","pH: for strong bases, find pOH first. For weak acids, use Ka. Do NOT use Ka for strong acids.","Buffer: after adding strong acid/base, recalculate moles of HA and A⁻ (some will have reacted). Then apply Henderson-Hasselbalch."]},{"type":"h","text":"Le Chatelier traps"},{"type":"ul","items":["Adding a catalyst does NOT shift equilibrium — this is one of the most common wrong answers.","Adding inert gas at constant VOLUME does not shift equilibrium (partial pressures unchanged). At constant PRESSURE it would increase volume and decrease partial pressures.","Temperature is the ONLY thing that changes K."]},{"type":"callout","title":"High-value exam tip","body":"When explaining buffer action, always describe BOTH cases: what happens when H⁺ is added AND what happens when OH⁻ is added. The mark scheme almost always requires both."},{"type":"takeaway","items":["Strong ≠ concentrated. Dynamic = equal rates in closed system.","Catalyst changes rate, NOT position or K.","Buffer: show both H⁺ and OH⁻ scenarios.","Always state units of Kc and Kp."]}]}]}`),kinetics:JSON.parse(`{"objectives":["Describe methods of measuring reaction rate (gas collection, mass loss, colorimetry, titration, clock)","Define rate of reaction, order, rate constant, half-life, activation energy, rate-determining step","Construct rate equations of the form rate = k[A]ᵐ[B]ⁿ for m, n = 0, 1, or 2","Determine order using the initial rate method and concentration-time graphs","Show graphically that first-order half-life is constant; calculate k from t½","Explain effects of concentration, temperature and catalysts using collision theory and Boltzmann distributions","Explain that a catalyst provides a different mechanism with lower activation energy","Deduce reaction mechanisms from rate equations and identify rate-determining steps","Describe homogeneous catalysis (Fe²⁺ in I⁻/S₂O₈²⁻, NOₓ in SO₂ oxidation) and heterogeneous catalysis (Fe in Haber, Pt in catalytic converters)"],"chapters":[{"id":"rk1","title":"Measuring Reaction Rates","blocks":[{"type":"p","text":"The rate of a reaction is the change in concentration of a reactant or product per unit time. A fast reaction has a large rate; a slow reaction has a small rate. Rate is always positive — if we track a reactant (whose concentration decreases), we include a negative sign in the definition to keep the value positive: rate = −d[A]/dt."},{"type":"h","text":"Experimental techniques"},{"type":"ul","items":["Gas collection: measure the volume of gas produced over time. Suitable for reactions producing CO₂, H₂, O₂.","Mass loss: place the reaction on a balance and record mass at intervals. Gas escapes, so mass decreases.","Colorimetry: measure the absorbance or transmission of light through the solution. Useful when a coloured reactant/product is involved (e.g. MnO₄⁻ decolourises).","Titration (quenching): withdraw samples at intervals, quench the reaction (e.g. by cooling or adding a stopping reagent), and titrate to find the concentration at that moment.","Clock reactions: measure the time to a fixed visual change (e.g. a cross disappearing). Rate ∝ 1/time."]},{"type":"callout","title":"Rate of reaction","body":"Rate = change in concentration / time = −d[reactant]/dt = +d[product]/dt. Units: mol dm⁻³ s⁻¹."},{"type":"h","text":"Initial rate"},{"type":"p","text":"The initial rate is the rate at the very start of the reaction (t = 0), before any significant amount of reactant is consumed. It is found from the tangent to the concentration-time curve at t = 0. Initial rates are used in the \\"initial rate method\\" to determine order."},{"type":"takeaway","items":["Rate = −d[A]/dt, units mol dm⁻³ s⁻¹.","Measured by gas volume, mass loss, colorimetry, titration, or clock methods.","Initial rate = tangent gradient at t = 0."]}]},{"id":"rk2","title":"Rate Equations & Order of Reaction","blocks":[{"type":"p","text":"The rate equation links the rate of reaction to the concentrations of the reactants. It takes the form: rate = k[A]ᵐ[B]ⁿ, where k is the rate constant, m is the order with respect to A, and n is the order with respect to B. The OVERALL ORDER is m + n."},{"type":"d","caption":"The general rate equation"},{"type":"h","text":"What is order?"},{"type":"ul","items":["Order with respect to A: the power to which [A] is raised in the rate equation.","Zero order in A: rate is independent of [A]. Doubling [A] has no effect on rate.","First order in A: rate is directly proportional to [A]. Doubling [A] doubles the rate.","Second order in A: rate ∝ [A]². Doubling [A] quadruples the rate."]},{"type":"h","text":"Order is determined by experiment"},{"type":"p","text":"You CANNOT deduce order from the balanced equation. The balanced equation shows the OVERALL stoichiometry, but the rate equation reflects the MECHANISM — specifically, the species involved in the rate-determining step. These are often different."},{"type":"h","text":"The rate constant k"},{"type":"ul","items":["k is constant at a given temperature. It increases with temperature (Arrhenius).","Units of k depend on the overall order. For overall order n: units = mol¹⁻ⁿ dm³⁽ⁿ⁻¹⁾ s⁻¹.","Zero order: k in mol dm⁻³ s⁻¹. First order: k in s⁻¹. Second order: k in mol⁻¹ dm³ s⁻¹."]},{"type":"callout","title":"Key misconception","body":"The stoichiometric coefficients in the balanced equation do NOT give the orders. For example, 2NO₂ + F₂ → 2NO₂F has experimental rate = k[NO₂][F₂] (both first order), not k[NO₂]²[F₂]."},{"type":"takeaway","items":["rate = k[A]ᵐ[B]ⁿ where m, n are found by experiment.","Zero order: rate unaffected. First: rate ∝ [A]. Second: rate ∝ [A]².","Order ≠ coefficient from the balanced equation.","k units depend on overall order."]}]},{"id":"rk3","title":"Finding Order: Initial Rate & Graphical Methods","blocks":[{"type":"p","text":"There are two main methods for determining order: the initial rate method (from tabulated data) and the graphical method (from concentration-time curves)."},{"type":"d","caption":"Initial rate method — systematic comparison"},{"type":"h","text":"Initial rate method"},{"type":"ul","items":["Set up experiments where only ONE concentration changes at a time (others held constant).","Compare the factor by which rate changes when a concentration is changed by a known factor.","If [A] doubles and rate doubles → first order in A. If rate quadruples → second order. If rate unchanged → zero order.","Mathematically: if [A] changes by factor x and rate changes by factor xᵐ, then m = log(rate factor) / log(concentration factor)."]},{"type":"h","text":"Graphical method — concentration vs time"},{"type":"d","caption":"Shapes of [A]-time curves for different orders"},{"type":"ul","items":["Zero order: [A] vs t is a straight line (constant rate of decrease).","First order: [A] vs t is an exponential decay curve with CONSTANT half-life.","Second order: [A] vs t is a curve, but 1/[A] vs t is a straight line."]},{"type":"h","text":"The half-life test for first order"},{"type":"p","text":"Measure successive half-lives from the [A]-time graph. If each half-life is the SAME (within experimental error), the reaction is first order. If t½ increases as [A] drops, it is second order. If t½ decreases as [A] drops, it is zero order."},{"type":"takeaway","items":["Initial rate method: compare experiments where one variable changes.","Graphical: [A] vs t straight → zero; exponential with constant t½ → first; 1/[A] linear → second.","Constant half-life is the diagnostic for first order."]}]},{"id":"rk4","title":"Half-Life & First-Order Kinetics","blocks":[{"type":"p","text":"The half-life (t½) is the time taken for the concentration of a reactant to fall to HALF its initial value. For a first-order reaction, t½ is CONSTANT — independent of concentration. This is a unique and diagnostic property of first-order kinetics."},{"type":"d","caption":"First-order decay: each successive t½ is the same"},{"type":"h","text":"First-order half-life formula"},{"type":"ul","items":["t½ = ln2 / k = 0.693 / k. This relates half-life to the rate constant k.","Rearranging: k = 0.693 / t½. If you know the half-life, you can find k.","Note: this formula applies ONLY to first-order reactions."]},{"type":"h","text":"Using half-lives to find concentration"},{"type":"ul","items":["After 1 half-life: [A] = [A]₀ / 2.","After 2 half-lives: [A] = [A]₀ / 4.","After 3 half-lives: [A] = [A]₀ / 8.","After n half-lives: [A] = [A]₀ / 2ⁿ.","Example: radioactive decay follows first-order kinetics. If t½ = 5730 years (C-14), after 11460 years (2 half-lives), ¼ of the original C-14 remains."]},{"type":"callout","title":"Half-life for other orders","body":"For zero order: t½ = [A]₀ / 2k (depends on initial concentration, gets shorter). For second order: t½ = 1 / (k[A]₀) (also depends on [A]₀, gets longer as [A] drops). Only first order has constant t½."},{"type":"takeaway","items":["First order: t½ = 0.693 / k (constant, independent of concentration).","After n half-lives: [A] = [A]₀ / 2ⁿ.","Constant t½ is the hallmark of first-order kinetics."]}]},{"id":"rk5","title":"Collision Theory & Factors Affecting Rate","blocks":[{"type":"p","text":"For a reaction to occur, reactant particles must COLLIDE with sufficient ENERGY (≥ activation energy, Ea) and correct ORIENTATION. Anything that increases the frequency of effective collisions increases the rate."},{"type":"h","text":"Factors affecting rate"},{"type":"ul","items":["CONCENTRATION: higher concentration → more particles per unit volume → more frequent collisions → higher rate.","PRESSURE (gases): increasing pressure is equivalent to increasing concentration for gases.","TEMPERATURE: higher temperature → particles move faster → (1) more frequent collisions AND (2) a greater fraction have energy ≥ Ea. The second effect is more important.","SURFACE AREA: for heterogeneous reactions, smaller particles (powder vs lump) expose more surface → more collisions at the interface.","CATALYST: provides an alternative pathway with lower Ea → more particles can overcome the energy barrier."]},{"type":"h","text":"The Boltzmann distribution"},{"type":"d","caption":"Effect of temperature on the distribution of molecular energies"},{"type":"ul","items":["The Boltzmann distribution shows the number of molecules at each energy level.","At higher temperature, the curve flattens and shifts RIGHT — the peak is lower and the area under the curve to the RIGHT of Ea increases.","This means MORE molecules have energy ≥ Ea, so the rate increases.","A catalyst LOWERS Ea (moves the Ea line to the LEFT) — same effect: more molecules can now react."]},{"type":"callout","title":"Why temperature is so powerful","body":"A 10 °C rise in temperature roughly doubles the rate for many reactions. This is because even a small shift in the Boltzmann distribution greatly increases the fraction of molecules above Ea — the effect is exponential (Arrhenius)."},{"type":"takeaway","items":["Effective collision = sufficient energy + correct orientation.","Concentration, pressure, temperature, surface area, catalyst all increase rate.","Temperature: more molecules above Ea (Boltzmann shift).","Catalyst: lowers Ea without changing ΔH or K."]}]},{"id":"rk6","title":"Activation Energy & Catalysts","blocks":[{"type":"p","text":"Activation energy (Ea) is the minimum energy that colliding particles must possess for a reaction to occur. It is the \\"energy barrier\\" between reactants and products. A catalyst provides an ALTERNATIVE PATHWAY with a LOWER Ea."},{"type":"d","caption":"Energy profile: catalyst provides a lower Ea route"},{"type":"h","text":"Key points about catalysts"},{"type":"ul","items":["A catalyst speeds up the reaction by lowering Ea — more molecules have enough energy to react.","The catalyst is NOT consumed — it is regenerated at the end of the catalytic cycle.","A catalyst does NOT change ΔH (the enthalpy change of the reaction is the same).","A catalyst does NOT change the equilibrium position or the value of K — it only speeds up the attainment of equilibrium.","A catalyst provides a DIFFERENT MECHANISM — the reaction goes via a different set of steps, with a lower maximum energy barrier."]},{"type":"h","text":"The Arrhenius equation (awareness)"},{"type":"p","text":"The rate constant k depends on temperature according to k = Ae^(−Ea/RT), where A is the pre-exponential factor (related to collision frequency and orientation), Ea is the activation energy, R is the gas constant, and T is temperature in Kelvin. This equation explains why rate increases exponentially with temperature."},{"type":"takeaway","items":["Ea = minimum collision energy for reaction.","Catalyst lowers Ea via an alternative mechanism.","Catalyst: unchanged by reaction; does not change ΔH or K.","k = Ae^(−Ea/RT) — rate increases exponentially with T."]}]},{"id":"rk7","title":"Reaction Mechanisms","blocks":[{"type":"p","text":"A mechanism is a step-by-step description of how a reaction actually occurs at the molecular level. Most reactions do not happen in a single step — instead, they proceed through a series of elementary steps, each involving the collision of a small number of species."},{"type":"d","caption":"Two-step mechanism for NO₂ + CO"},{"type":"h","text":"The rate-determining step (RDS)"},{"type":"ul","items":["The RDS is the SLOWEST step in the mechanism. It controls the overall rate, like a bottleneck in a production line.","The rate equation reflects only the species involved in the RDS (and any earlier equilibria).","Species that appear AFTER the RDS do not appear in the rate equation."]},{"type":"h","text":"Deducing mechanism from rate equation"},{"type":"ul","items":["If rate = k[A][B], the RDS involves one molecule of A and one of B colliding.","If rate = k[A]², the RDS involves two molecules of A colliding (or A appears twice in steps up to and including the RDS).","If rate = k[A] (B absent), then B is not involved until AFTER the RDS."]},{"type":"h","text":"Intermediates"},{"type":"ul","items":["An intermediate is a species that is FORMED in one step and CONSUMED in a subsequent step. It does not appear in the overall equation.","Example: in the NO₂ + CO mechanism, NO₃ is an intermediate (formed in step 1, consumed in step 2).","Intermediates are often unstable and short-lived, which is why the slow step matters."]},{"type":"callout","title":"Exam approach","body":"Given a rate equation, propose a mechanism: (1) the RDS must involve the species in the rate equation with the correct molecularity. (2) The steps must add up to the overall equation. (3) Any extra species are intermediates."},{"type":"takeaway","items":["Mechanism = set of elementary steps that sum to the overall equation.","Rate-determining step (slowest) controls the rate equation.","Species in the rate equation are those in or before the RDS.","Intermediates: formed in one step, consumed in another."]}]},{"id":"rk8","title":"Homogeneous & Heterogeneous Catalysis","blocks":[{"type":"p","text":"The ZIMSEC syllabus requires detailed knowledge of two types of catalysis, with specific industrial and environmental examples."},{"type":"d","caption":"Comparing homogeneous and heterogeneous catalysis"},{"type":"h","text":"Heterogeneous catalysis"},{"type":"ul","items":["Catalyst is in a DIFFERENT phase from the reactants (usually solid catalyst + gas or liquid reactants).","Mechanism: (1) Reactant molecules ADSORB onto the catalyst surface (bonds weaken). (2) Reaction occurs on the surface (lower Ea). (3) Products DESORB from the surface.","Example 1: Fe(s) catalyst in the Haber process (N₂ + 3H₂ → 2NH₃). N₂ and H₂ adsorb onto Fe, N≡N bond is weakened, facilitating reaction.","Example 2: catalytic converter in car exhausts — Pt/Pd/Rh catalyse the removal of NOₓ: 2NO → N₂ + O₂, and the oxidation of CO: 2CO + O₂ → 2CO₂.","Catalyst poisoning: impurities (e.g. lead, sulphur) adsorb onto active sites and block them. This is why leaded petrol damages catalytic converters."]},{"type":"h","text":"Homogeneous catalysis"},{"type":"ul","items":["Catalyst is in the SAME phase as the reactants (all in solution, or all gaseous).","The catalyst reacts with one reactant to form an INTERMEDIATE, which then reacts with the second reactant, regenerating the catalyst.","Example 1: Fe²⁺(aq) catalyses the reaction between I⁻(aq) and S₂O₈²⁻(aq). Step 1: 2Fe²⁺ + S₂O₈²⁻ → 2Fe³⁺ + 2SO₄²⁻ (Fe²⁺ oxidised). Step 2: 2Fe³⁺ + 2I⁻ → 2Fe²⁺ + I₂ (Fe²⁺ regenerated). Fe²⁺ acts as an electron-transfer agent.","Example 2: NOₓ in the atmosphere catalyses the oxidation of SO₂: NO₂ + SO₂ → NO + SO₃; then NO + ½O₂ → NO₂ (regenerated). This contributes to acid rain."]},{"type":"callout","title":"Why Fe²⁺ works as a catalyst","body":"The direct reaction I⁻ + S₂O₈²⁻ requires collision of two negative ions — they repel each other, giving a high Ea. Fe²⁺ provides a pathway where each step involves ions of opposite charge colliding (lower Ea). The overall Ea is reduced, so the reaction is faster."},{"type":"takeaway","items":["Heterogeneous: different phase; adsorb → react → desorb.","Homogeneous: same phase; catalyst forms intermediate, then regenerated.","Fe(s) in Haber, Pt in catalytic converters (heterogeneous).","Fe²⁺ in I⁻/S₂O₈²⁻, NOₓ in SO₂ oxidation (homogeneous)."]}]},{"id":"rk9","title":"Calculating k & Using Rate Equations","blocks":[{"type":"p","text":"Once you know the order, you can calculate k from experimental data and use the rate equation to predict rates at different concentrations."},{"type":"h","text":"Finding k from initial rate data"},{"type":"ul","items":["Step 1: Determine the orders (initial rate method or graphical method).","Step 2: Write the rate equation: rate = k[A]ᵐ[B]ⁿ.","Step 3: Substitute data from ANY experiment into the rate equation and solve for k.","Example: rate = k[A]²[B]. Using experiment 1: 2.0 × 10⁻³ = k(0.10)²(0.10). k = 2.0 × 10⁻³ / (0.010 × 0.10) = 2.0 mol⁻² dm⁶ s⁻¹."]},{"type":"h","text":"Finding k from half-life (first order)"},{"type":"ul","items":["k = 0.693 / t½.","Example: if t½ = 346 s, then k = 0.693 / 346 = 2.00 × 10⁻³ s⁻¹."]},{"type":"h","text":"Predicting rate at a new concentration"},{"type":"p","text":"Once k is known, substitute any new set of concentrations into rate = k[A]ᵐ[B]ⁿ to predict the rate. This is a common exam calculation — straightforward once orders and k are established."},{"type":"callout","title":"Units of k","body":"Overall order 0: mol dm⁻³ s⁻¹. Order 1: s⁻¹. Order 2: mol⁻¹ dm³ s⁻¹. Order 3: mol⁻² dm⁶ s⁻¹. Always derive units from the rate equation."},{"type":"takeaway","items":["Find k by substituting known data into the rate equation.","First order: k = 0.693 / t½.","Use k to predict rates at new concentrations.","Always state units of k."]}]},{"id":"rk10","title":"Graphical Analysis in Kinetics","blocks":[{"type":"p","text":"Exam questions frequently ask you to sketch or interpret concentration-time and rate-concentration graphs. Here is a systematic approach."},{"type":"h","text":"[A] vs time"},{"type":"ul","items":["Zero order: straight line going down. Gradient = −k.","First order: exponential decay. Successive half-lives are equal.","Second order: curve that levels off more slowly than first order. Plot 1/[A] vs t for a straight line."]},{"type":"h","text":"Rate vs [A]"},{"type":"ul","items":["Zero order: horizontal line (rate constant regardless of [A]).","First order: straight line through the origin (rate ∝ [A]).","Second order: upward curve (parabola through origin, rate ∝ [A]²)."]},{"type":"h","text":"Rate vs time"},{"type":"ul","items":["For all orders, rate generally decreases over time as reactants are consumed.","Zero order: rate stays constant until [A] reaches zero, then drops to zero abruptly.","First order: rate decreases exponentially (same shape as [A] vs t)."]},{"type":"callout","title":"Gradient = initial rate","body":"The tangent to the [A]-time curve at any point gives the instantaneous rate at that moment. At t = 0, this tangent gives the initial rate. Practice drawing tangents accurately — a ruler and pencil are essential in the exam."},{"type":"takeaway","items":["Zero: [A]-t linear. First: [A]-t exponential (constant t½). Second: 1/[A]-t linear.","Rate vs [A]: horizontal (0th), linear (1st), parabolic (2nd).","Tangent to [A]-t curve = instantaneous rate."]}]},{"id":"rk11","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Kinetics questions combine graphical interpretation, calculation, and mechanistic reasoning. Here are the key patterns."},{"type":"h","text":"Order determination from data tables"},{"type":"ul","items":["Always isolate ONE variable at a time. Find two experiments where only [A] changes.","Calculate the ratio of rates and the ratio of concentrations. If rate ratio = (conc ratio)ᵐ, then m is the order.","If the ratios are not clean multiples (e.g. rate × 2.9 when [A] × 1.7), use m = log(rate ratio) / log(conc ratio)."]},{"type":"h","text":"Mechanism questions"},{"type":"ul","items":["If asked to \\"suggest a mechanism consistent with the rate equation\\": make the RDS involve the species in the rate equation with the correct powers.","All steps must add up to the overall equation.","Mark any species that appears in one step and disappears in another as an INTERMEDIATE."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Confusing order with stoichiometric coefficient — they are NOT the same.","Forgetting to convert time to seconds when calculating k.","Not stating units of k (always required).","Saying a catalyst \\"gives the molecules more energy\\" — WRONG. A catalyst lowers Ea; it does not increase molecular energy.","Claiming a catalyst shifts equilibrium — it does NOT."]},{"type":"callout","title":"The catalyst myth","body":"A catalyst does NOT give molecules more energy. It does NOT shift equilibrium. It provides an alternative pathway with lower Ea. It speeds up both forward and reverse reactions equally. State these precisely in the exam."},{"type":"takeaway","items":["Isolate variables when finding order from data.","Mechanism RDS must match the rate equation.","Catalyst: lowers Ea, alternative pathway, does NOT shift equilibrium.","Always state units of k."]}]}]}`),periodicity:JSON.parse(`{"objectives":["Describe and explain trends in atomic radius, ionic radius and first ionisation energy across Period 3","Explain the dips in IE₁ at Al and S using subshell and pairing arguments","Interpret melting point and electrical conductivity trends in terms of bonding and structure","Write equations for the reactions of Period 3 elements with O₂, Cl₂ and H₂O","State the oxidation states of Period 3 elements in their oxides and chlorides","Describe and explain the acid-base behaviour of Period 3 oxides (basic → amphoteric → acidic)","Explain why ionic chlorides dissolve but covalent chlorides hydrolyse","Deduce the type of bonding in oxides and chlorides from physical and chemical data"],"chapters":[{"id":"pd1","title":"What Is Periodicity?","blocks":[{"type":"p","text":"Periodicity is the repeating pattern of physical and chemical properties as you move across a period of the periodic table. Period 3 runs from sodium (Na, Z = 11) to argon (Ar, Z = 18). These eight elements show a complete transition from reactive metal to noble gas, and every trend can be explained by changes in electronic structure."},{"type":"h","text":"The elements of Period 3"},{"type":"ul","items":["Na (2,8,1) — reactive metal, Group I.","Mg (2,8,2) — reactive metal, Group II.","Al (2,8,3) — metal with some amphoteric character, Group III.","Si (2,8,4) — metalloid/semiconductor, Group IV.","P (2,8,5) — non-metal, Group V.","S (2,8,6) — non-metal, Group VI.","Cl (2,8,7) — non-metal/halogen, Group VII.","Ar (2,8,8) — noble gas, Group 0."]},{"type":"p","text":"All Period 3 elements have the same number of electron shells (3), but the number of protons in the nucleus increases from 11 to 18. This increasing nuclear charge, with constant shielding from the inner two shells, drives all the trends across the period."},{"type":"takeaway","items":["Period 3: Na to Ar (8 elements, all with 3 electron shells).","Nuclear charge increases left to right; shielding stays the same.","This drives all physical and chemical trends."]}]},{"id":"pd2","title":"Atomic & Ionic Radius Trends","blocks":[{"type":"p","text":"The atomic radius DECREASES across Period 3 from Na to Cl. This is because the nuclear charge increases while the shielding from inner electrons stays essentially the same (all elements have the same 1s²2s²2p⁶ inner core). The increasing effective nuclear charge pulls the outer electrons closer to the nucleus."},{"type":"d","caption":"Atomic radius decreases across Period 3"},{"type":"h","text":"Why the decrease?"},{"type":"ul","items":["Na has 11 protons pulling on 1 outer electron (3s¹). Cl has 17 protons pulling on 7 outer electrons (3s²3p⁵).","Although Cl has more electrons, the extra electrons go into the SAME shell (n = 3) and provide poor shielding from each other.","The dominant factor is the increasing nuclear charge → smaller radius."]},{"type":"h","text":"Ionic radius"},{"type":"ul","items":["Cations (Na⁺, Mg²⁺, Al³⁺) are SMALLER than their parent atoms — they have lost their outer shell entirely. The remaining electrons are pulled in more tightly by the nucleus.","Anions (P³⁻, S²⁻, Cl⁻) are LARGER than their parent atoms — extra electrons increase electron-electron repulsion, expanding the electron cloud.","For isoelectronic species (e.g. O²⁻, F⁻, Na⁺, Mg²⁺, Al³⁺ — all with 10 electrons): more protons → smaller radius. So Al³⁺ < Mg²⁺ < Na⁺ < F⁻ < O²⁻."]},{"type":"callout","title":"Exam favourite","body":"Explain why Na⁺ is smaller than Na: Na⁺ has lost the 3s electron — only 2 shells remain. The 10 remaining electrons are attracted by 11 protons, giving a very small, tightly held ion."},{"type":"takeaway","items":["Atomic radius decreases left to right (↑ nuclear charge, same shielding).","Cations < parent atoms; anions > parent atoms.","Isoelectronic: more protons → smaller radius."]}]},{"id":"pd3","title":"First Ionisation Energy Trend","blocks":[{"type":"p","text":"The first ionisation energy (IE₁) generally INCREASES across Period 3, with two notable dips at aluminium and sulphur. IE₁ is the energy required to remove one electron from a gaseous atom: X(g) → X⁺(g) + e⁻."},{"type":"d","caption":"IE₁ trend across Period 3 with dips at Al and S"},{"type":"h","text":"General increase"},{"type":"p","text":"Across the period, nuclear charge increases while shielding is approximately constant. The outer electron is more strongly attracted to the nucleus and harder to remove. This is the same reasoning as for atomic radius — both trends are driven by effective nuclear charge."},{"type":"h","text":"The aluminium dip"},{"type":"ul","items":["Mg: [Ne] 3s². The electron removed is from a FULL 3s subshell.","Al: [Ne] 3s² 3p¹. The electron removed is from the 3p subshell, which is slightly HIGHER in energy and FURTHER from the nucleus than 3s.","The 3p electron in Al is easier to remove than the 3s electron in Mg, despite Al having one more proton.","Result: IE₁(Al) < IE₁(Mg)."]},{"type":"h","text":"The sulphur dip"},{"type":"ul","items":["P: [Ne] 3s² 3p³. All three 3p electrons are UNPAIRED (one in each 3p orbital).","S: [Ne] 3s² 3p⁴. One 3p orbital now has a PAIR of electrons.","The paired electron in S experiences extra electron-electron REPULSION within the same orbital, making it easier to remove.","Result: IE₁(S) < IE₁(P)."]},{"type":"callout","title":"Two dips, two reasons","body":"Al dip: 3p electron is higher energy than 3s (subshell effect). S dip: paired 3p electron has extra repulsion (pairing effect). These are frequently examined — learn both explanations precisely."},{"type":"takeaway","items":["IE₁ generally increases across Period 3.","Al dip: 3p¹ electron easier to remove than Mg's 3s².","S dip: paired 3p⁴ electron experiences repulsion."]}]},{"id":"pd4","title":"Melting Points & Electrical Conductivity","blocks":[{"type":"p","text":"The melting point pattern across Period 3 is NOT a simple increase or decrease — it depends on the TYPE OF BONDING and STRUCTURE, which changes dramatically across the period."},{"type":"d","caption":"Melting points reflect bonding type"},{"type":"h","text":"Explaining the pattern"},{"type":"ul","items":["Na, Mg, Al: METALLIC bonding. Strong attraction between positive metal ions and a sea of delocalised electrons. M.p. increases Na → Mg → Al because: (1) charge on the cation increases (+1, +2, +3), (2) number of delocalised electrons increases, (3) ionic radius decreases. All three factors strengthen the metallic bond.","Si: GIANT COVALENT structure (like diamond). Each Si atom is bonded to 4 others in a 3D network. Very strong covalent bonds throughout → very high m.p. (1687 °C).","P₄, S₈, Cl₂, Ar: SIMPLE MOLECULAR structures held together by weak VAN DER WAALS (London) forces between molecules. Very low m.p. S₈ > P₄ > Cl₂ > Ar because S₈ has the most electrons → strongest London forces."]},{"type":"d","caption":"Only the metals (and Si partially) conduct electricity"},{"type":"h","text":"Electrical conductivity"},{"type":"ul","items":["Na, Mg, Al: good conductors — delocalised electrons carry charge. Al is the best conductor of the three.","Si: semiconductor — a small number of electrons can be promoted to the conduction band. Conductivity increases with temperature (opposite to metals).","P, S, Cl, Ar: non-conductors — no free electrons or mobile ions."]},{"type":"takeaway","items":["M.p. Na < Mg < Al (metallic, increasing charge). Si very high (giant covalent).","P₄, S₈, Cl₂, Ar: low m.p. (simple molecular, weak London forces).","Conductivity: metals conduct; Si is a semiconductor; non-metals do not conduct."]}]},{"id":"pd5","title":"Reactions of Period 3 Elements with Oxygen","blocks":[{"type":"p","text":"All Period 3 elements (except Ar) react with oxygen to form oxides. The oxidation state in the oxide generally equals the group number, which increases from +1 (Na) to +6 (S, in SO₃)."},{"type":"d","caption":"Products and oxidation states when Period 3 elements burn in O₂"},{"type":"h","text":"Observations"},{"type":"ul","items":["Na burns with a YELLOW flame → white solid Na₂O (also forms Na₂O₂ peroxide in excess O₂).","Mg burns with a brilliant WHITE flame → white powder MgO.","Al burns only when powdered (oxide layer protects it) → white powder Al₂O₃.","Si reacts slowly at very high temperatures → SiO₂ (quartz).","P₄ burns spontaneously in air (white phosphorus) → white fumes of P₄O₁₀.","S burns with a BLUE flame → colourless gas SO₂ (pungent smell).","Cl₂ and Ar do not form stable oxides under normal conditions."]},{"type":"h","text":"Oxidation state pattern"},{"type":"p","text":"The maximum oxidation state in the oxide matches the group number: Na (+1), Mg (+2), Al (+3), Si (+4), P (+5), S (+6 in SO₃, +4 in SO₂). This reflects the number of electrons available for bonding in the outer shell."},{"type":"takeaway","items":["All Period 3 elements (except Ar) form oxides with O₂.","Oxidation state = group number in the highest oxide.","Observations vary: flames (Na yellow, Mg white, S blue), products (solids, gases)."]}]},{"id":"pd6","title":"Reactions with Chlorine & Water","blocks":[{"type":"p","text":"Period 3 elements also react with chlorine to form chlorides, and some react with water (cold or steam)."},{"type":"h","text":"Reactions with chlorine"},{"type":"ul","items":["2Na + Cl₂ → 2NaCl (ionic, white solid, m.p. 801 °C).","Mg + Cl₂ → MgCl₂ (ionic, white solid, m.p. 714 °C).","2Al + 3Cl₂ → 2AlCl₃ (covalent when anhydrous; exists as Al₂Cl₆ dimer; sublimes at 178 °C).","Si + 2Cl₂ → SiCl₄ (covalent liquid, b.p. 57 °C).","P₄ + 6Cl₂ → 4PCl₃ (or P₄ + 10Cl₂ → 4PCl₅ in excess Cl₂). Both covalent.","Oxidation state in chloride = group number: NaCl (+1), MgCl₂ (+2), AlCl₃ (+3), SiCl₄ (+4), PCl₅ (+5)."]},{"type":"h","text":"Reactions with water"},{"type":"ul","items":["Na reacts VIGOROUSLY with cold water: 2Na + 2H₂O → 2NaOH + H₂. Fizzes, moves on the surface, may ignite.","Mg reacts SLOWLY with cold water: Mg + 2H₂O → Mg(OH)₂ + H₂. Reacts faster with steam: Mg + H₂O → MgO + H₂.","Al does NOT react with water under normal conditions — its oxide layer protects it. Will react with steam if the oxide layer is removed.","Si, P, S, Cl, Ar: do not react with water (though Cl₂ disproportionates — covered in Group VII)."]},{"type":"callout","title":"Sodium in water","body":"Na + water is extremely vigorous. The syllabus notes that sodium explodes in water — handle with extreme care in demonstrations. Never use large pieces."},{"type":"takeaway","items":["Chloride oxidation state = group number.","Bonding: NaCl/MgCl₂ ionic; AlCl₃/SiCl₄/PCl₃ covalent.","Na reacts vigorously with cold water; Mg slowly; Al protected by oxide layer."]}]},{"id":"pd7","title":"Acid-Base Behaviour of Period 3 Oxides","blocks":[{"type":"p","text":"The oxides of Period 3 show a clear trend in acid-base character: from strongly BASIC on the left, through AMPHOTERIC in the middle, to strongly ACIDIC on the right."},{"type":"d","caption":"Acid-base character transitions across Period 3"},{"type":"h","text":"Basic oxides: Na₂O and MgO"},{"type":"ul","items":["Na₂O dissolves in water to give NaOH (strong alkali): Na₂O + H₂O → 2NaOH, pH ≈ 14.","MgO is only slightly soluble — forms Mg(OH)₂ (weak base): MgO + H₂O → Mg(OH)₂, pH ≈ 9–10.","Both react with acids: Na₂O + 2HCl → 2NaCl + H₂O; MgO + 2HCl → MgCl₂ + H₂O."]},{"type":"h","text":"Amphoteric oxide: Al₂O₃"},{"type":"ul","items":["Al₂O₃ does NOT dissolve in water.","It reacts with ACIDS: Al₂O₃ + 6HCl → 2AlCl₃ + 3H₂O (behaving as a base).","It reacts with BASES: Al₂O₃ + 2NaOH + 3H₂O → 2Na[Al(OH)₄]⁻ (behaving as an acid).","Amphoteric = reacts with both acids AND bases."]},{"type":"h","text":"Acidic oxides: SiO₂, P₄O₁₀, SO₂, SO₃"},{"type":"ul","items":["SiO₂ does NOT dissolve in water (giant covalent, insoluble). But it reacts with hot NaOH: SiO₂ + 2NaOH → Na₂SiO₃ + H₂O.","P₄O₁₀ dissolves in water: P₄O₁₀ + 6H₂O → 4H₃PO₄ (phosphoric acid), pH ≈ 1.","SO₂ dissolves: SO₂ + H₂O → H₂SO₃ (sulphurous acid), pH ≈ 2–3.","SO₃ dissolves: SO₃ + H₂O → H₂SO₄ (sulphuric acid), pH ≈ 1."]},{"type":"callout","title":"Why the trend?","body":"Metal oxides are ionic (Na₂O, MgO) — the O²⁻ ion acts as a base (accepts H⁺). Non-metal oxides are covalent — they react with water to form acidic solutions by generating H⁺ ions. Al₂O₃ sits at the transition point with intermediate character."},{"type":"takeaway","items":["Left (Na₂O, MgO): basic. Middle (Al₂O₃): amphoteric. Right (SiO₂, P₄O₁₀, SO₃): acidic.","Metal oxides have ionic bonding → basic. Non-metal oxides have covalent bonding → acidic.","Al₂O₃ reacts with both acids AND bases."]}]},{"id":"pd8","title":"Chlorides with Water — Dissolve or Hydrolyse?","blocks":[{"type":"p","text":"The chlorides of Period 3 fall into two categories when added to water: the ionic ones DISSOLVE peacefully, while the covalent ones HYDROLYSE vigorously, producing HCl fumes and acidic solutions."},{"type":"d","caption":"Period 3 chlorides: bonding, behaviour with water, pH"},{"type":"h","text":"Ionic chlorides: NaCl, MgCl₂"},{"type":"ul","items":["NaCl dissolves in water → Na⁺(aq) + Cl⁻(aq). Neutral solution, pH ≈ 7.","MgCl₂ dissolves → Mg²⁺(aq) + 2Cl⁻(aq). Slightly acidic (pH ≈ 6.5) because Mg²⁺ is small and highly charged — it polarises surrounding water molecules, releasing some H⁺.","No HCl fumes — the ions simply separate and hydrate."]},{"type":"h","text":"Covalent chlorides: AlCl₃, SiCl₄, PCl₃, PCl₅"},{"type":"ul","items":["These undergo HYDROLYSIS — the covalent bond to Cl is broken by water, producing HCl.","AlCl₃ + 3H₂O → Al(OH)₃ + 3HCl. White fumes of HCl, strongly acidic solution (pH ≈ 3).","SiCl₄ + 2H₂O → SiO₂ + 4HCl. Very vigorous, white fumes, strongly acidic (pH ≈ 2).","PCl₃ + 3H₂O → H₃PO₃ + 3HCl. White fumes.","PCl₅ + 4H₂O → H₃PO₄ + 5HCl. Even more vigorous."]},{"type":"h","text":"Why the difference?"},{"type":"p","text":"Ionic chlorides have strong ion-ion bonding that is broken by hydration (water surrounds the ions). No new bonds to water are formed by the chloride ion. Covalent chlorides have a central atom with vacant orbitals — water can attack (nucleophilic substitution), breaking the M–Cl bond and forming M–OH and H–Cl. This is hydrolysis."},{"type":"takeaway","items":["Ionic chlorides (NaCl, MgCl₂): dissolve, neutral to slightly acidic.","Covalent chlorides (AlCl₃, SiCl₄, PCl₅): hydrolyse, produce HCl fumes, strongly acidic.","Hydrolysis occurs because the central atom has accessible vacant orbitals."]}]},{"id":"pd9","title":"Deducing Bonding from Physical & Chemical Properties","blocks":[{"type":"p","text":"A common exam question gives you data for an unknown oxide or chloride and asks you to deduce the type of bonding. Here is the systematic approach."},{"type":"h","text":"Physical property clues"},{"type":"ul","items":["HIGH melting point (>1000 °C) + conducts when molten → IONIC (e.g. NaCl, MgO).","VERY HIGH melting point + does NOT conduct when molten → GIANT COVALENT (e.g. SiO₂, diamond).","LOW melting point + does NOT conduct → SIMPLE MOLECULAR (e.g. P₄O₁₀, SiCl₄, SO₂).","Conducts as solid → METALLIC (delocalised electrons)."]},{"type":"h","text":"Chemical property clues"},{"type":"ul","items":["Dissolves in water to give neutral/alkaline solution → ionic oxide or chloride of a metal.","Reacts with water producing HCl fumes / acidic solution → covalent chloride.","Dissolves in water to give acidic solution → covalent oxide of a non-metal.","Insoluble in water but reacts with both acid and base → amphoteric (Al₂O₃)."]},{"type":"callout","title":"Exam approach","body":"When given data: (1) Check m.p. — high or low? (2) Check conductivity — solid and/or molten? (3) Check pH of aqueous solution — acidic or alkaline? (4) Match to bonding type. Present your reasoning step by step for full marks."},{"type":"takeaway","items":["High m.p. + conducts molten → ionic. Very high m.p. + no conductivity → giant covalent.","Low m.p. + no conductivity → simple molecular.","pH of aqueous solution: alkaline → metal oxide; acidic → non-metal oxide."]}]},{"id":"pd10","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Periodicity questions involve trends, explanations, and data interpretation. Here are the key exam patterns."},{"type":"h","text":"Trend explanations — what earns marks"},{"type":"ul","items":["Atomic radius: state \\"nuclear charge increases\\" AND \\"shielding stays approximately the same\\" AND \\"greater effective nuclear charge pulls electrons closer\\". All three points are typically needed.","IE₁ dips: for Al, state \\"electron removed from 3p not 3s\\" and \\"3p is higher energy\\". For S, state \\"electron removed from a paired 3p orbital\\" and \\"electron-electron repulsion\\".","Melting points: identify the bonding type FIRST, then explain why that bonding gives high or low m.p."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Saying \\"more shielding across the period\\" — WRONG. Shielding is approximately constant (same inner core).","Confusing dissolving with hydrolysis. NaCl dissolves (ions separate); SiCl₄ hydrolyses (bonds break, HCl forms).","Forgetting that Al₂O₃ is AMPHOTERIC, not just basic or just acidic.","Not specifying the oxidation state when writing formulas for oxides and chlorides."]},{"type":"h","text":"Data interpretation questions"},{"type":"ul","items":["If given a table of m.p. and conductivity data, group the elements by bonding type first.","If asked to \\"sketch a graph\\" of IE₁ or m.p., include the dips/discontinuities — a smooth curve without them loses marks.","When asked to predict, use the pattern to infer the answer for an element not explicitly covered."]},{"type":"takeaway","items":["Always state both \\"↑ nuclear charge\\" AND \\"same shielding\\" for radius/IE trends.","Dissolving ≠ hydrolysis. Know the difference.","Al₂O₃ is amphoteric — this is a guaranteed exam point."]}]}]}`),group2:JSON.parse(`{"objectives":["Describe and explain trends in atomic radius, ionisation energy and reactivity down Group II","Write equations for Group II elements reacting with oxygen and water","Describe the behaviour of Group II oxides with water (basic character increases)","Explain the variation in thermal decomposition temperature of Group II carbonates and nitrates using charge density and polarisation","Describe the variation in solubility of Group II sulphates (decreases) and hydroxides (increases)","State the properties and uses of key Group II compounds (MgO, Mg(OH)₂, CaO, Ca(OH)₂, CaCO₃, CaSO₄, MgSO₄, BaSO₄, magnesium trisilicate)"],"chapters":[{"id":"g21","title":"The Alkaline Earth Metals","blocks":[{"type":"p","text":"Group II contains beryllium (Be), magnesium (Mg), calcium (Ca), strontium (Sr) and barium (Ba). They are called the alkaline earth metals because their oxides and hydroxides are alkaline (basic) and many of their compounds are found in the earth's crust. All Group II elements have the electron configuration [noble gas] ns², meaning they have TWO electrons in their outer shell and form 2+ ions."},{"type":"h","text":"Common features"},{"type":"ul","items":["All are metals — silvery, relatively soft, good conductors.","All form M²⁺ ions by losing their two outer s electrons.","All have relatively low densities compared to transition metals.","Reactivity INCREASES down the group (Be is least reactive, Ba most reactive).","Their compounds are often white solids."]},{"type":"callout","title":"Alkaline earth metals","body":"Group II elements: Be, Mg, Ca, Sr, Ba. Configuration: ns². Form M²⁺ ions. Called \\"alkaline earth\\" because their oxides are basic and naturally abundant in the earth."},{"type":"takeaway","items":["Group II: Be, Mg, Ca, Sr, Ba — all form M²⁺.","Reactivity increases down the group.","Compounds are typically white ionic solids."]}]},{"id":"g22","title":"Trends in Physical Properties","blocks":[{"type":"p","text":"As you go down Group II, the atoms get larger, the ionisation energy decreases, and the elements become more reactive. The melting point trend is less regular."},{"type":"d","caption":"Key physical properties of Group II elements"},{"type":"h","text":"Atomic radius increases"},{"type":"p","text":"Each successive element has one more electron shell. The extra shielding from inner electrons outweighs the increase in nuclear charge, so the outer electrons are held less tightly and the atom is larger."},{"type":"h","text":"Ionisation energy decreases"},{"type":"ul","items":["Going down: the outer electrons are further from the nucleus AND more shielded by inner shells.","Both factors reduce the effective nuclear charge felt by the outer electrons.","It becomes easier to remove the two outer electrons → IE₁ and IE₂ both decrease.","This is why reactivity increases: it's easier to form M²⁺."]},{"type":"h","text":"Melting point"},{"type":"p","text":"The melting point trend is NOT regular across Group II. It generally decreases (Ba < Sr < Ca) but with exceptions. This is because the m.p. depends on the balance between ionic radius (affecting inter-ionic distance), charge (constant at +2) and the crystal structure, which varies. The exam usually does not ask you to explain the m.p. trend in detail — focus on atomic radius and IE."},{"type":"takeaway","items":["Atomic radius increases down Group II (more shells, more shielding).","IE₁ decreases (outer electrons further from nucleus and more shielded).","Reactivity increases because M²⁺ formation becomes easier."]}]},{"id":"g23","title":"Reactions with Oxygen","blocks":[{"type":"p","text":"All Group II elements burn in oxygen to form white ionic oxides with the formula MO, where M is the Group II metal. The reaction becomes more vigorous down the group."},{"type":"h","text":"Equations and observations"},{"type":"ul","items":["2Mg + O₂ → 2MgO. Burns with a brilliant WHITE flame. Product is a white powder.","2Ca + O₂ → 2CaO. Burns with a BRICK RED flame.","2Sr + O₂ → 2SrO. Burns with a RED flame.","2Ba + O₂ → 2BaO (also forms BaO₂ peroxide in excess O₂). Burns with a GREEN flame.","Be reacts only at high temperatures (oxide layer protects it, like Al)."]},{"type":"h","text":"Flame colours"},{"type":"p","text":"The characteristic flame colours of Group II metals are used in flame tests: Mg — no distinctive colour (white/silver), Ca — brick red, Sr — crimson red, Ba — apple green. These colours arise from electronic transitions when the metal ions are heated in the flame."},{"type":"takeaway","items":["All form MO oxides (white ionic solids).","Vigour increases: Be < Mg < Ca < Sr < Ba.","Flame colours: Ca red, Sr crimson, Ba green."]}]},{"id":"g24","title":"Reactions with Water","blocks":[{"type":"p","text":"Group II metals react with water to form hydroxides and hydrogen gas. The vigour increases down the group — from no reaction (Be) to very vigorous effervescence (Ba)."},{"type":"d","caption":"Reactivity with water increases down Group II"},{"type":"h","text":"General equation"},{"type":"p","text":"M(s) + 2H₂O(l) → M(OH)₂(aq) + H₂(g). The hydroxide dissolves (to varying extents) and the solution is alkaline."},{"type":"h","text":"Details for each element"},{"type":"ul","items":["Be: no reaction with cold water or steam. Its oxide layer is very resistant.","Mg: very slow with cold water — a few tiny bubbles of H₂ over hours. Faster with hot water. Vigorous with STEAM: Mg + H₂O(g) → MgO + H₂ (note: oxide formed with steam, hydroxide with liquid water).","Ca: steady reaction with cold water. Ca sinks, hydrogen bubbles off steadily. Solution turns milky (Ca(OH)₂ is sparingly soluble — limewater).","Sr: more vigorous than Ca. Fizzes readily.","Ba: very vigorous effervescence. Ba(OH)₂ is quite soluble → strongly alkaline solution."]},{"type":"h","text":"Why does reactivity increase?"},{"type":"p","text":"Going down the group, IE₁ and IE₂ decrease because the outer electrons are further from the nucleus and more shielded. It becomes progressively easier for the metal to lose its two outer electrons and form M²⁺, so the reaction with water becomes more vigorous."},{"type":"takeaway","items":["M + 2H₂O → M(OH)₂ + H₂ (general equation).","Mg: steam gives MgO; cold water very slow.","Ca: steady with cold water. Ba: vigorous.","Reactivity ↑ because IE ↓ down the group."]}]},{"id":"g25","title":"Oxides with Water","blocks":[{"type":"p","text":"Group II oxides are BASIC — they react with water to form alkaline hydroxide solutions. The strength of the base increases down the group because the hydroxides become more soluble."},{"type":"h","text":"Equations"},{"type":"ul","items":["MgO + H₂O → Mg(OH)₂. Mg(OH)₂ is only SLIGHTLY soluble — suspension is milky. pH ≈ 9–10.","CaO + H₂O → Ca(OH)₂. Ca(OH)₂ is SPARINGLY soluble — cloudy/milky solution. pH ≈ 12–13.","SrO + H₂O → Sr(OH)₂. More soluble → higher pH.","BaO + H₂O → Ba(OH)₂. Most soluble → strongly alkaline. pH ≈ 13–14."]},{"type":"h","text":"The trend in basicity"},{"type":"p","text":"All Group II oxides are basic, but the alkalinity of the resulting solution INCREASES down the group because the hydroxides become MORE SOLUBLE. More dissolved OH⁻ → higher pH → stronger base in practice."},{"type":"callout","title":"Hydroxide solubility trend","body":"Mg(OH)₂ < Ca(OH)₂ < Sr(OH)₂ < Ba(OH)₂ in terms of solubility. This is the OPPOSITE of the sulphate solubility trend. Both trends are commonly examined together."},{"type":"d","caption":"Hydroxide solubility increases down Group II"},{"type":"takeaway","items":["All Group II oxides are basic: MO + H₂O → M(OH)₂.","Basicity of solution increases down group (hydroxides more soluble).","Hydroxide solubility: Mg(OH)₂ < Ca(OH)₂ < Ba(OH)₂."]}]},{"id":"g26","title":"Thermal Decomposition of Carbonates & Nitrates","blocks":[{"type":"p","text":"Group II carbonates decompose on heating to give the oxide and CO₂. Group II nitrates decompose to give the oxide, NO₂ (brown gas) and O₂. The temperature required for decomposition INCREASES down the group."},{"type":"h","text":"Carbonates: MCO₃ → MO + CO₂"},{"type":"d","caption":"Decomposition temperatures increase down the group"},{"type":"ul","items":["BeCO₃ decomposes at ~100 °C (very easy).","MgCO₃ at ~540 °C.","CaCO₃ at ~900 °C (lime kiln temperature).","SrCO₃ at ~1290 °C.","BaCO₃ at ~1360 °C (very difficult)."]},{"type":"h","text":"Nitrates: 2M(NO₃)₂ → 2MO + 4NO₂ + O₂"},{"type":"ul","items":["The same trend applies: Be(NO₃)₂ decomposes at the lowest temperature, Ba(NO₃)₂ at the highest.","Products: metal oxide + brown NO₂ gas + O₂.","Test for NO₂: brown gas, turns damp blue litmus red.","Test for CO₂: bubbles through limewater → milky."]},{"type":"h","text":"Why the trend?"},{"type":"d","caption":"Polarising power explains the decomposition trend"},{"type":"ul","items":["Small cations (Be²⁺, Mg²⁺) have HIGH charge density (high polarising power).","They strongly POLARISE the large, easily distorted CO₃²⁻ (or NO₃⁻) anion.","Polarisation weakens the C–O bonds (or N–O bonds) in the anion, making decomposition easier.","Large cations (Ba²⁺) have LOW charge density → less polarisation → harder to decompose → higher temperature needed."]},{"type":"callout","title":"The polarisation argument","body":"Charge density of the cation = charge/radius². Smaller cation → higher charge density → more polarisation of the anion → weaker bonds in the anion → lower decomposition temperature. This is the core argument for both carbonates AND nitrates."},{"type":"takeaway","items":["MCO₃ → MO + CO₂; decomposition T increases down the group.","2M(NO₃)₂ → 2MO + 4NO₂ + O₂; same trend.","Explanation: smaller cation → higher polarising power → easier decomposition."]}]},{"id":"g27","title":"Solubility of Group II Sulphates","blocks":[{"type":"p","text":"The solubility of Group II sulphates DECREASES down the group. MgSO₄ is very soluble; BaSO₄ is virtually insoluble. This is the OPPOSITE of the hydroxide trend."},{"type":"d","caption":"Sulphate solubility decreases down Group II"},{"type":"h","text":"The data"},{"type":"ul","items":["MgSO₄: very soluble (35.7 g per 100 cm³ water) — sold as Epsom salts.","CaSO₄: slightly soluble (0.20 g per 100 cm³) — gypsum.","SrSO₄: sparingly soluble.","BaSO₄: insoluble (0.00024 g per 100 cm³) — used in barium meals."]},{"type":"h","text":"Application: testing for sulphate ions"},{"type":"ul","items":["To test for SO₄²⁻: add dilute HCl (to remove any CO₃²⁻ that would give a false positive), then add BaCl₂(aq).","If SO₄²⁻ is present: a white precipitate of BaSO₄ forms. Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s).","The precipitate is insoluble in excess HCl, confirming it is BaSO₄ (not BaCO₃, which would dissolve)."]},{"type":"callout","title":"Why opposite trends?","body":"Dissolving involves breaking the lattice (endothermic) and hydrating the ions (exothermic). For hydroxides, the hydration enthalpy dominates down the group → more soluble. For sulphates, the lattice enthalpy changes less steeply than hydration → less soluble. The exam rarely asks you to explain WHY the trends are opposite — just know the trends."},{"type":"takeaway","items":["Sulphate solubility: MgSO₄ > CaSO₄ > SrSO₄ > BaSO₄.","Hydroxide solubility: opposite (increases down group).","Test for SO₄²⁻: add HCl then BaCl₂ → white ppt of BaSO₄."]}]},{"id":"g28","title":"Properties & Uses of Group II Compounds","blocks":[{"type":"p","text":"Group II compounds have many important industrial, medical and agricultural applications. The syllabus specifically lists several compounds and their uses."},{"type":"d","caption":"Key uses of Group II compounds"},{"type":"h","text":"Medical uses"},{"type":"ul","items":["Mg(OH)₂ (milk of magnesia): antacid — neutralises excess stomach acid (HCl). Mg(OH)₂ + 2HCl → MgCl₂ + 2H₂O.","Magnesium trisilicate (MMT): another antacid, used for indigestion and heartburn.","MgSO₄ (Epsom salts): laxative, muscle relaxant, bath soaking.","BaSO₄: \\"barium meal\\" — swallowed before X-ray to make the digestive tract visible. Safe because BaSO₄ is insoluble → Ba²⁺ ions (which are toxic) are NOT released into the body.","CaSO₄: plaster of Paris for setting broken bones."]},{"type":"h","text":"Agricultural and industrial uses"},{"type":"ul","items":["CaO (quicklime): spread on acidic soil to neutralise it. Also used in cement manufacture.","Ca(OH)₂ (slaked lime): neutralises acidic soil and water. Used in mortar.","CaCO₃ (limestone): building material, raw material for cement and glass. Also used in blast furnace to remove impurities.","MgO: refractory lining in furnaces (very high m.p. ~2850 °C), antacid."]},{"type":"callout","title":"BaSO₄ safety","body":"Barium ions are toxic, but BaSO₄ is safe to ingest because it is so insoluble that no Ba²⁺ dissolves. BaCO₃ would be dangerous because it could react with stomach acid to release Ba²⁺."},{"type":"takeaway","items":["Antacids: Mg(OH)₂, MgO, magnesium trisilicate.","Agriculture: CaO, Ca(OH)₂ — neutralise acidic soil.","Medical imaging: BaSO₄ barium meal (safe because insoluble).","Construction: CaCO₃, CaSO₄."]}]},{"id":"g29","title":"Solubility Trends Compared","blocks":[{"type":"p","text":"Two solubility trends run in OPPOSITE directions down Group II, and you must know both for the exam."},{"type":"h","text":"Hydroxides: solubility INCREASES down"},{"type":"ul","items":["Mg(OH)₂ is barely soluble (milk of magnesia is a suspension).","Ca(OH)₂ is sparingly soluble (limewater).","Ba(OH)₂ is quite soluble (clear solution, strongly alkaline)."]},{"type":"h","text":"Sulphates: solubility DECREASES down"},{"type":"ul","items":["MgSO₄ is very soluble.","CaSO₄ is slightly soluble.","BaSO₄ is virtually insoluble."]},{"type":"h","text":"Quick memory aid"},{"type":"p","text":"Think: \\"HOH goes up, SULPH goes down.\\" Hydroxides get more soluble going down; sulphates get less soluble going down. If you can remember one, you know the other is the opposite."},{"type":"callout","title":"Exam implications","body":"This is why Ca(OH)₂ makes a useful limewater test for CO₂ — it is sparingly soluble (just enough in solution to react). And why BaSO₄ is used as the test for SO₄²⁻ — its extreme insolubility makes the precipitate unmistakable."},{"type":"takeaway","items":["Hydroxides: MORE soluble down the group.","Sulphates: LESS soluble down the group.","Opposite trends — learn both."]}]},{"id":"g210","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Group II questions are very predictable — trends, explanations, equations and uses. Here is how to maximise marks."},{"type":"h","text":"Trend explanations"},{"type":"ul","items":["Reactivity increase: \\"IE decreases because atomic radius increases and shielding increases\\" → \\"easier to form M²⁺\\".","Thermal decomposition: \\"charge density of cation decreases down the group\\" → \\"less polarisation of CO₃²⁻/NO₃⁻ anion\\" → \\"stronger C-O/N-O bonds\\" → \\"higher temperature needed\\".","Always link charge density to polarisation to bond weakness to decomposition temperature."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Confusing hydroxide and sulphate solubility trends — they go in opposite directions!","Writing M(OH)₂ for the product of Mg + steam — it is MgO with steam, not Mg(OH)₂.","Saying \\"Ba²⁺ is safe\\" — Ba²⁺ ions are TOXIC. BaSO₄ is safe because it is insoluble.","Forgetting to state that the thermal decomposition explanation involves polarisation of the anion, not just \\"the cation is smaller\\"."]},{"type":"h","text":"Equations you must know"},{"type":"ul","items":["M + O₂ → MO (burning in oxygen).","M + 2H₂O → M(OH)₂ + H₂ (reaction with water).","Mg + H₂O(g) → MgO + H₂ (Mg with steam specifically).","MO + H₂O → M(OH)₂ (oxide dissolving).","MCO₃ → MO + CO₂ (carbonate decomposition).","2M(NO₃)₂ → 2MO + 4NO₂ + O₂ (nitrate decomposition)."]},{"type":"takeaway","items":["Link charge density → polarisation → decomposition T.","Hydroxides up, sulphates down (solubility).","Mg + steam → MgO (not hydroxide).","Ba²⁺ is toxic; BaSO₄ is safe because insoluble."]}]}]}`),group4:JSON.parse(`{"objectives":["Describe and explain the variations in melting point and electrical conductivity of Group IV elements","Compare the structures and properties of diamond, graphite and fullerenes","Explain the inert pair effect and its consequences for the stability of +4 and +2 oxidation states","Describe the bonding, acid-base character and thermal stability of Group IV oxides (II and IV)","Describe the bonding, molecular shape, volatility and hydrolysis of Group IV tetrachlorides","Explain why CCl₄ does not hydrolyse (no d orbitals) but SiCl₄ does (3d orbitals available)","Describe the redox behaviour of Sn²⁺ (reducing agent) and PbO₂ (oxidising agent)","State the properties and uses of Group IV elements and compounds (diamond, graphite, SiO₂, glass, ceramics, CCl₄)"],"chapters":[{"id":"g41","title":"Group IV: Carbon to Lead","blocks":[{"type":"p","text":"Group IV contains carbon (C), silicon (Si), germanium (Ge), tin (Sn) and lead (Pb). These five elements show a dramatic transition from non-metal (C) through metalloid (Si, Ge) to metal (Sn, Pb). All have the outer electron configuration ns²np², giving them the possibility of oxidation states +4 (using all four outer electrons) or +2 (using only the two p electrons)."},{"type":"h","text":"The key theme: increasing metallic character"},{"type":"ul","items":["Carbon: non-metal. Forms covalent bonds. Allotropes include diamond (giant covalent, insulator) and graphite (giant covalent, conductor along layers).","Silicon: metalloid / semiconductor. Giant covalent structure like diamond.","Germanium: metalloid / semiconductor. Used in electronics.","Tin: metal. Has two allotropes (white tin = metallic, grey tin = semi-metallic).","Lead: metal. Dense, soft, low m.p. Strong tendency to form Pb²⁺ (not Pb⁴⁺)."]},{"type":"callout","title":"The big idea","body":"Going down Group IV, the +2 oxidation state becomes MORE stable relative to the +4 state. This is the INERT PAIR EFFECT — the two s electrons become increasingly reluctant to participate in bonding. For Pb, the +2 state is dominant; PbO₂ (Pb⁴⁺) is a strong oxidising agent because Pb \\"wants\\" to return to +2."},{"type":"takeaway","items":["Group IV: C, Si, Ge, Sn, Pb — configuration ns²np².","Non-metal → metalloid → metal down the group.","+2 state becomes more stable going down (inert pair effect)."]}]},{"id":"g42","title":"Melting Points & Electrical Conductivity","blocks":[{"type":"p","text":"The physical properties of Group IV elements reflect the change in bonding and structure from giant covalent at the top to metallic at the bottom."},{"type":"d","caption":"Physical properties across Group IV"},{"type":"h","text":"Melting point trend"},{"type":"ul","items":["C (diamond) and Si have very HIGH melting points because they have giant covalent structures — strong covalent bonds must be broken throughout the entire 3D lattice.","C has a higher m.p. than Si because C–C bonds (348 kJ mol⁻¹) are shorter and stronger than Si–Si bonds (226 kJ mol⁻¹).","Ge still has a giant covalent structure but with even weaker bonds → lower m.p.","Sn and Pb have METALLIC structures. Metallic bonds are weaker than the giant covalent bonds of C/Si → much lower melting points.","Overall: m.p. DECREASES down the group (with the transition from giant covalent to metallic bonding)."]},{"type":"h","text":"Electrical conductivity"},{"type":"ul","items":["Diamond: non-conductor — all four electrons per carbon are in localised covalent bonds.","Graphite: conducts along the layers — each C uses only 3 electrons for σ bonds; the 4th is delocalised in π orbitals above and below the layers.","Si, Ge: semiconductors — small band gap allows some electrons to be promoted to the conduction band (conductivity increases with temperature).","Sn, Pb: good metallic conductors — delocalised electrons carry charge."]},{"type":"takeaway","items":["M.p. decreases: giant covalent (C, Si, Ge) → metallic (Sn, Pb).","Conductivity increases: insulator/semiconductor → metal.","Graphite is the exception among non-metals: it conducts along layers."]}]},{"id":"g43","title":"Diamond, Graphite & Fullerenes","blocks":[{"type":"p","text":"Carbon exists in several allotropes — different structural forms of the same element. The two most important for A-level are diamond and graphite, with fullerenes (e.g. C₆₀ buckminsterfullerene) as additional interest."},{"type":"d","caption":"Comparing diamond and graphite structures"},{"type":"h","text":"Diamond"},{"type":"ul","items":["Each C atom is sp³ hybridised, bonded to 4 others in a tetrahedral arrangement.","Giant covalent 3D network — all bonds are strong C–C σ bonds (348 kJ mol⁻¹).","Properties: extremely hard (hardest natural substance), very high m.p. (3550 °C), does NOT conduct electricity (all electrons localised), transparent and colourless, insoluble in all solvents.","Uses: cutting tools, drill bits, jewellery, abrasives."]},{"type":"h","text":"Graphite"},{"type":"ul","items":["Each C is sp² hybridised, bonded to 3 others in flat hexagonal LAYERS.","The 4th electron on each C is delocalised in a π system that extends across the layer.","Layers are held together by weak VAN DER WAALS forces → layers slide over each other.","Properties: soft and slippery, high m.p. (sublimes ~3650 °C), conducts electricity ALONG layers (delocalised π electrons), opaque and grey-black.","Uses: pencil \\"lead\\", lubricant, electrodes (inert, conducts, high m.p.)."]},{"type":"h","text":"Fullerenes and nanotubes"},{"type":"p","text":"C₆₀ (buckminsterfullerene) is a spherical molecule of 60 carbon atoms arranged in pentagons and hexagons (like a football). Carbon nanotubes are rolled-up graphene sheets with remarkable strength and conductivity. Both are examples of simple molecular carbon allotropes."},{"type":"takeaway","items":["Diamond: 4 bonds, tetrahedral, hard, insulator.","Graphite: 3 bonds + delocalised π, layers, soft, conducts.","Both are giant covalent with very high m.p.","Graphite conducts because of delocalised electrons between layers."]}]},{"id":"g44","title":"The Inert Pair Effect","blocks":[{"type":"p","text":"The inert pair effect is the tendency of the two s electrons in the outermost shell to remain UNBONDED (as a \\"lone pair\\") in heavier Group IV elements. This means the +2 oxidation state becomes increasingly stable relative to +4 as you go down the group."},{"type":"d","caption":"Stability of +4 vs +2 changes down Group IV"},{"type":"h","text":"Why does it happen?"},{"type":"ul","items":["All Group IV atoms have the configuration ns²np². In carbon, the energy needed to promote the 2s electrons and use all four for bonding is easily repaid by the energy of the four strong bonds formed.","Going down the group, the ns electrons become harder to utilise in bonding. The bonds formed by heavier elements are WEAKER (because the atoms are larger and overlap less effectively), so the energy benefit of using all four electrons decreases.","For Pb, the energy cost of promoting the 6s² electrons is NOT repaid by the weak Pb–X bonds, so Pb prefers to keep its 6s² pair inert and form only 2 bonds → Pb²⁺ is the stable oxidation state."]},{"type":"h","text":"Consequences"},{"type":"ul","items":["Carbon: +4 is overwhelmingly dominant (CO₂, CCl₄, CH₄). +2 exists only in CO.","Silicon: +4 is dominant (SiO₂, SiCl₄). +2 is very rare.","Tin: BOTH +4 and +2 exist. Sn²⁺ is a good reducing agent (it wants to become Sn⁴⁺).","Lead: +2 is dominant (PbO, PbCl₂, Pb(NO₃)₂). +4 is unstable — PbO₂ and PbCl₄ are powerful oxidising agents because Pb⁴⁺ wants to return to Pb²⁺."]},{"type":"callout","title":"Exam statement","body":"State: \\"Down Group IV, the +2 oxidation state becomes more stable relative to the +4 state due to the inert pair effect. The ns² electrons become increasingly reluctant to participate in bonding because the bonds formed by larger atoms are weaker and do not compensate for the promotion energy.\\""},{"type":"takeaway","items":["Inert pair effect: ns² electrons reluctant to bond in heavier elements.","C, Si: +4 dominant. Sn: both. Pb: +2 dominant.","Sn²⁺ is a reducing agent (→ Sn⁴⁺). Pb⁴⁺ is an oxidising agent (→ Pb²⁺)."]}]},{"id":"g45","title":"Oxides of Group IV","blocks":[{"type":"p","text":"Group IV elements form oxides in both +4 and +2 oxidation states. The bonding, acid-base character and thermal stability of these oxides show clear trends down the group."},{"type":"d","caption":"Summary of Group IV oxides"},{"type":"h","text":"Bonding trend"},{"type":"ul","items":["CO₂: simple molecular (O=C=O, linear). Covalent, gas at room temperature.","SiO₂: giant covalent (each Si bonded to 4 O atoms). Very high m.p., insoluble.","GeO₂, SnO₂, PbO₂: increasingly ionic character. Higher m.p. solids.","SnO, PbO: ionic solids.","Trend: covalent → ionic character increases down the group (as metallic character increases)."]},{"type":"h","text":"Acid-base character"},{"type":"ul","items":["CO₂: acidic — dissolves in water to form carbonic acid (H₂CO₃). Reacts with bases: CO₂ + 2NaOH → Na₂CO₃ + H₂O.","SiO₂: acidic — insoluble in water but reacts with hot concentrated NaOH or fused NaOH: SiO₂ + 2NaOH → Na₂SiO₃ + H₂O.","GeO₂, SnO₂: amphoteric — react with both acids and bases.","SnO, PbO, PbO₂: amphoteric.","Trend: acidic at the top → amphoteric at the bottom."]},{"type":"h","text":"Thermal stability"},{"type":"ul","items":["The +4 oxides become LESS thermally stable going down the group (inert pair effect).","PbO₂ decomposes on heating: 2PbO₂ → 2PbO + O₂. This is because Pb⁴⁺ is unstable and the compound reverts to the more stable Pb²⁺ state.","CO₂ and SiO₂ are very thermally stable — they do not decompose easily.","SnO₂ is stable but can be reduced by carbon at high temperatures (tin smelting)."]},{"type":"takeaway","items":["Bonding: covalent (CO₂) → giant covalent (SiO₂) → ionic (SnO₂, PbO).","Acid-base: acidic (CO₂, SiO₂) → amphoteric (SnO₂, PbO).","+4 oxides become less stable down group (PbO₂ decomposes → PbO + O₂)."]}]},{"id":"g46","title":"Tetrachlorides: Bonding, Shape & Hydrolysis","blocks":[{"type":"p","text":"All Group IV elements form tetrachlorides (MCl₄). These are all COVALENT, volatile liquids (or gases) with a TETRAHEDRAL molecular shape. Their behaviour with water is a key exam topic."},{"type":"d","caption":"Group IV tetrachlorides — properties and hydrolysis"},{"type":"h","text":"Bonding and shape"},{"type":"ul","items":["All MCl₄ molecules have 4 bonding pairs around the central atom and no lone pairs.","VSEPR predicts a TETRAHEDRAL shape with bond angles of 109.5°.","All are covalent — the central atom shares electrons with four Cl atoms.","They are volatile liquids because they are simple molecular substances held by weak London forces."]},{"type":"h","text":"Reaction with water — the crucial difference"},{"type":"ul","items":["CCl₄ does NOT react with water. Carbon has no accessible d orbitals — water cannot attack the central C atom. CCl₄ is used as a non-polar solvent and is stable in aqueous conditions.","SiCl₄ hydrolyses RAPIDLY: SiCl₄ + 2H₂O → SiO₂ + 4HCl. White fumes of HCl are produced. Silicon has accessible 3d orbitals → water lone pairs can attack, initiating nucleophilic substitution.","GeCl₄, SnCl₄: also hydrolyse, but less vigorously than SiCl₄.","PbCl₄: very unstable (inert pair effect) — decomposes to PbCl₂ + Cl₂ before hydrolysis can occur."]},{"type":"h","text":"Reaction with organic solvents"},{"type":"p","text":"All tetrachlorides dissolve in non-polar organic solvents like hexane because they are covalent molecules with similar intermolecular forces. This is a useful test: if a chloride dissolves in hexane but fumes with water, it is covalent."},{"type":"callout","title":"Why CCl₄ doesn't hydrolyse","body":"Carbon has NO accessible d orbitals in its outer shell (period 2 elements never have d orbitals available). Water cannot form a 5th bond to C as an intermediate. Silicon, being in period 3, has empty 3d orbitals that can accept the lone pair from water → hydrolysis proceeds. This is the single most important difference."},{"type":"takeaway","items":["All MCl₄ are tetrahedral, covalent, volatile.","CCl₄ does NOT hydrolyse (no d orbitals on C).","SiCl₄ hydrolyses rapidly (3d orbitals available).","PbCl₄ is too unstable (decomposes to PbCl₂ + Cl₂)."]}]},{"id":"g47","title":"Redox: Sn²⁺ as Reducer, Pb⁴⁺ as Oxidiser","blocks":[{"type":"p","text":"The inert pair effect creates opposite redox tendencies for tin and lead compounds. Sn²⁺ is a good REDUCING agent (it wants to become Sn⁴⁺, the more stable state for Sn). Pb⁴⁺ is a good OXIDISING agent (it wants to become Pb²⁺, the more stable state for Pb)."},{"type":"d","caption":"PbO₂ oxidises HCl to Cl₂; SnO reduces to form Sn⁴⁺"},{"type":"h","text":"Tin: +2 → +4 (reducing agent)"},{"type":"ul","items":["Sn²⁺ readily loses 2 more electrons to become Sn⁴⁺ (the more stable state for Sn).","SnCl₂ reduces Fe³⁺ to Fe²⁺: SnCl₂ + 2FeCl₃ → SnCl₄ + 2FeCl₂.","Sn²⁺ is oxidised (Sn: +2 → +4), Fe³⁺ is reduced (Fe: +3 → +2).","SnCl₂ is used in analytical chemistry as a reducing agent."]},{"type":"h","text":"Lead: +4 → +2 (oxidising agent)"},{"type":"ul","items":["Pb⁴⁺ readily gains 2 electrons to become Pb²⁺ (the more stable state for Pb).","PbO₂ + 4HCl → PbCl₂ + Cl₂ + 2H₂O. Lead is reduced (+4 → +2) and chloride is oxidised (−1 → 0).","PbO₂ is a strong enough oxidising agent to oxidise concentrated HCl to Cl₂.","This reaction is used to demonstrate the oxidising power of Pb(IV)."]},{"type":"callout","title":"Mirror image behaviour","body":"Sn²⁺ is a reducing agent because +4 is more stable for Sn. Pb⁴⁺ is an oxidising agent because +2 is more stable for Pb. This mirror-image behaviour is a direct consequence of the inert pair effect becoming dominant at Pb but not yet at Sn."},{"type":"takeaway","items":["Sn²⁺ → Sn⁴⁺: reducing agent (Sn prefers +4).","Pb⁴⁺ → Pb²⁺: oxidising agent (Pb prefers +2).","PbO₂ + 4HCl → PbCl₂ + Cl₂ + 2H₂O."]}]},{"id":"g48","title":"Properties & Uses of Group IV Elements & Compounds","blocks":[{"type":"p","text":"The syllabus requires you to know the properties and uses of several Group IV elements and compounds."},{"type":"h","text":"Elements"},{"type":"ul","items":["Diamond: cutting tools, abrasives, jewellery, drill bits, surgical scalpels (extreme hardness).","Graphite: pencils, lubricant, electrodes for electrolysis, nuclear reactor moderator (layers slide, conducts, high m.p.).","Silicon: semiconductor chips, solar cells (dominant semiconductor material).","Tin: tin plating (coating iron/steel to prevent corrosion), solder (Sn-Pb alloy), bronze (Cu-Sn alloy).","Lead: lead-acid batteries, radiation shielding, formerly used in pipes and paint (now largely banned due to toxicity)."]},{"type":"h","text":"Compounds"},{"type":"ul","items":["SiO₂ (silicon dioxide / silica): glass manufacture, ceramics, optical fibres. Quartz crystals in watches and electronics.","CCl₄ (carbon tetrachloride): formerly used as a solvent and dry-cleaning agent. Now restricted due to environmental concerns (ozone depletion, toxicity).","Glass: made by fusing SiO₂ with Na₂CO₃ and CaCO₃. Borosilicate glass (Pyrex) contains B₂O₃ for heat resistance.","Ceramics: made from clay (aluminosilicates) fired at high temperature. Hard, heat-resistant, electrical insulators.","Tin(II) fluoride (SnF₂): in toothpaste to prevent tooth decay.","Lead(II) oxide (PbO, litharge): used in lead-acid batteries and as a drying agent in paints/varnishes."]},{"type":"takeaway","items":["Diamond: hardness applications. Graphite: lubricant + electrodes.","Si: semiconductors. SiO₂: glass and ceramics.","CCl₄: solvent (restricted). Sn: tin plating, solder. Pb: batteries."]}]},{"id":"g49","title":"Comparing Chlorides: MCl₄ vs MCl₂","blocks":[{"type":"p","text":"Group IV forms both tetrachlorides (MCl₄, +4 state) and dichlorides (MCl₂, +2 state). The relative stability of these follows the inert pair effect."},{"type":"h","text":"Tetrachlorides (MCl₄)"},{"type":"ul","items":["CCl₄: very stable, does not hydrolyse, non-polar liquid. Used as a solvent.","SiCl₄: stable but hydrolyses readily with water. Colourless liquid, fumes in moist air.","SnCl₄: stable liquid. Hydrolyses in water. Can be reduced to SnCl₂.","PbCl₄: UNSTABLE — decomposes at room temperature to PbCl₂ + Cl₂. This instability reflects the inert pair effect (Pb⁴⁺ is very unstable)."]},{"type":"h","text":"Dichlorides (MCl₂)"},{"type":"ul","items":["CCl₂ (dichlorocarbene): extremely reactive, exists only as a fleeting intermediate.","SnCl₂: stable ionic solid. Good reducing agent (Sn²⁺ → Sn⁴⁺). Dissolves in water.","PbCl₂: stable ionic solid. White precipitate when Cl⁻ is added to Pb²⁺(aq). Slightly soluble in hot water."]},{"type":"h","text":"Stability comparison"},{"type":"p","text":"Going down the group: MCl₄ becomes less stable (PbCl₄ decomposes) while MCl₂ becomes more stable (PbCl₂ is the preferred chloride of lead). This is the inert pair effect in action."},{"type":"takeaway","items":["MCl₄ stability decreases down the group (PbCl₄ decomposes).","MCl₂ stability increases down the group (PbCl₂ is preferred).","SnCl₂ is a reducing agent; PbCl₄ is an oxidising agent."]}]},{"id":"g410","title":"Why SiCl₄ Hydrolyses But CCl₄ Does Not","blocks":[{"type":"p","text":"This is one of the most frequently examined comparisons in inorganic chemistry. The answer hinges on the availability of d orbitals."},{"type":"h","text":"CCl₄: no hydrolysis"},{"type":"ul","items":["Carbon is in Period 2. Its outer shell (n = 2) has only 2s and 2p orbitals — no 2d orbitals exist.","Carbon already has 4 bonds and cannot expand its octet. There is no way for water to form a temporary 5th bond as an intermediate.","Without this intermediate, hydrolysis cannot occur. CCl₄ is kinetically stable in water."]},{"type":"h","text":"SiCl₄: rapid hydrolysis"},{"type":"ul","items":["Silicon is in Period 3. It has empty 3d orbitals that can accept a lone pair from water.","Water attacks the Si centre, forming a temporary 5-coordinate intermediate (trigonal bipyramidal).","A Cl⁻ is then displaced. The process repeats until all 4 Cl atoms are replaced.","Overall: SiCl₄ + 2H₂O → SiO₂ + 4HCl."]},{"type":"callout","title":"The d-orbital argument","body":"This explanation applies beyond Group IV: any chloride whose central atom has accessible d orbitals can hydrolyse (AlCl₃, PCl₃, PCl₅, SiCl₄). Those without d orbitals (CCl₄, NCl₃) do not hydrolyse, or hydrolyse by a different mechanism. Always state: \\"Si has vacant 3d orbitals; C does not have accessible d orbitals.\\""},{"type":"takeaway","items":["CCl₄: no d orbitals → cannot form 5-coordinate intermediate → no hydrolysis.","SiCl₄: empty 3d orbitals → water attacks → rapid hydrolysis → SiO₂ + 4HCl.","This is the key mechanistic explanation."]}]},{"id":"g411","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Group IV questions focus on trends, comparisons, and the inert pair effect. Here are the key patterns."},{"type":"h","text":"Trend explanations"},{"type":"ul","items":["M.p. decrease: \\"change from giant covalent (strong covalent bonds) to metallic (weaker metallic bonds)\\".","Acid-base of oxides: \\"CO₂ and SiO₂ are acidic; SnO₂ and PbO are amphoteric\\".","Inert pair: \\"the ns² electrons become increasingly reluctant to bond because the M–X bonds formed by heavier atoms are weaker and do not compensate for the promotion energy\\"."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Saying \\"CCl₄ doesn't hydrolyse because C–Cl bonds are too strong\\" — WRONG. The actual reason is that C has no d orbitals for water to attack.","Confusing the stability order: Sn²⁺ is a reducing agent (wants to become Sn⁴⁺). Pb⁴⁺ is an oxidising agent (wants to become Pb²⁺). Students often get these reversed.","Forgetting that SiO₂ is ACIDIC, not amphoteric. It reacts with NaOH but not with acids.","Writing PbCl₄ as stable — it decomposes spontaneously."]},{"type":"h","text":"Equations to know"},{"type":"ul","items":["SiCl₄ + 2H₂O → SiO₂ + 4HCl (hydrolysis of SiCl₄).","PbO₂ + 4HCl → PbCl₂ + Cl₂ + 2H₂O (PbO₂ as oxidising agent).","2PbO₂ → 2PbO + O₂ (thermal decomposition).","SiO₂ + 2NaOH → Na₂SiO₃ + H₂O (SiO₂ as acidic oxide).","SnCl₂ + Cl₂ → SnCl₄ (SnCl₂ as reducing agent)."]},{"type":"takeaway","items":["CCl₄ no hydrolysis = no d orbitals (NOT strong bonds).","Sn²⁺ reduces; Pb⁴⁺ oxidises. Don't reverse them.","SiO₂ is acidic, not amphoteric."]}]}]}`),group7:JSON.parse(`{"objectives":["Describe the trends in volatility and colour of Cl₂, Br₂ and I₂ using van der Waals forces","Explain the relative reactivity of halogens as oxidising agents using E° values","Write equations for displacement reactions of halogens with halide solutions","Explain the relative thermal stabilities of HCl, HBr and HI in terms of bond energies","Describe the reactions of halide ions with AgNO₃ and subsequent ammonia tests","Describe and explain the reactions of halide ions with concentrated H₂SO₄","Write equations for the disproportionation of Cl₂ with cold and hot NaOH","Explain the industrial importance (water purification, bleach, PVC) and environmental significance (CFCs, ozone depletion) of halogens and their compounds"],"chapters":[{"id":"g71","title":"The Halogens: Cl₂, Br₂ & I₂","blocks":[{"type":"p","text":"Group VII contains fluorine (F), chlorine (Cl), bromine (Br), iodine (I) and astatine (At). The ZIMSEC syllabus focuses on Cl₂, Br₂ and I₂. These are called the HALOGENS (Greek: \\"salt-formers\\") because they react with metals to form salts. All have the outer electron configuration ns²np⁵ — they need just ONE more electron to achieve a noble gas configuration, which is why they are powerful oxidising agents."},{"type":"h","text":"Key features"},{"type":"ul","items":["All exist as diatomic molecules: F₂, Cl₂, Br₂, I₂.","All are coloured and toxic.","They are the most electronegative elements (F is the most electronegative of all).","Reactivity DECREASES down the group (opposite to Groups I and II).","They form −1 ions (halide ions: Cl⁻, Br⁻, I⁻)."]},{"type":"takeaway","items":["Group VII: F, Cl, Br, I — configuration ns²np⁵.","Exist as X₂ molecules. Reactivity decreases down.","Powerful oxidising agents: X₂ + 2e⁻ → 2X⁻."]}]},{"id":"g72","title":"Colour, Volatility & Van der Waals Forces","blocks":[{"type":"p","text":"The halogens show a clear trend in physical appearance: colour deepens and volatility decreases going down the group."},{"type":"d","caption":"Physical properties of halogens"},{"type":"h","text":"Colour trend"},{"type":"ul","items":["F₂: pale yellow gas.","Cl₂: yellow-green gas (pungent, choking smell).","Br₂: red-brown volatile liquid (fuming at room temperature).","I₂: grey-black solid with a shiny lustre. Sublimes to give PURPLE vapour. Brown when dissolved in organic solvents; brown-yellow in aqueous solution."]},{"type":"h","text":"Why volatility decreases"},{"type":"ul","items":["All halogens are simple molecular (X₂) with non-polar covalent bonds.","The intermolecular forces are VAN DER WAALS (London dispersion) forces only.","Going down: molecular size and number of electrons INCREASE → London forces get STRONGER.","Stronger intermolecular forces → higher boiling point → less volatile.","F₂ (gas) → Cl₂ (gas) → Br₂ (liquid) → I₂ (solid) at room temperature."]},{"type":"callout","title":"Volatility = ease of evaporation","body":"High volatility means low boiling point. F₂ is the most volatile halogen (b.p. −188 °C) because it has the fewest electrons and weakest London forces. I₂ is the least volatile (b.p. +184 °C) with the strongest London forces."},{"type":"takeaway","items":["Colour deepens: pale yellow → yellow-green → red-brown → grey-black.","Volatility decreases (b.p. increases): more electrons → stronger London forces.","All are simple molecular — only London forces between X₂ molecules."]}]},{"id":"g73","title":"Reactivity & E° Values","blocks":[{"type":"p","text":"Halogens are oxidising agents — they accept electrons to form halide ions: X₂ + 2e⁻ → 2X⁻. Reactivity as oxidising agents DECREASES down the group: F₂ > Cl₂ > Br₂ > I₂."},{"type":"d","caption":"E° values decrease down Group VII"},{"type":"h","text":"Why reactivity decreases"},{"type":"ul","items":["Going down: atomic radius INCREASES. The incoming electron is added to a shell further from the nucleus.","More inner shells provide greater SHIELDING of the nuclear charge.","The effective nuclear attraction for the incoming electron is WEAKER.","Therefore it becomes harder for the halogen to gain an electron → lower E° → weaker oxidising agent."]},{"type":"h","text":"Displacement reactions"},{"type":"d","caption":"A more reactive halogen displaces a less reactive halide from solution"},{"type":"ul","items":["Cl₂ + 2KBr → 2KCl + Br₂. Cl₂ oxidises Br⁻ to Br₂. Solution turns ORANGE/BROWN.","Cl₂ + 2KI → 2KCl + I₂. Cl₂ oxidises I⁻ to I₂. Solution turns BROWN (then dark/purple with starch).","Br₂ + 2KI → 2KBr + I₂. Br₂ oxidises I⁻. Solution turns brown/black.","I₂ cannot displace Cl⁻ or Br⁻ — it is the weakest oxidising agent."]},{"type":"callout","title":"Using E° to predict","body":"E°cell = E°(oxidiser) − E°(reducer). Cl₂/Cl⁻ = +1.36 V and Br₂/Br⁻ = +1.07 V. E°cell = 1.36 − 1.07 = +0.29 V > 0 → Cl₂ WILL oxidise Br⁻. But Br₂ cannot oxidise Cl⁻ because E°cell would be negative."},{"type":"takeaway","items":["Reactivity as oxidising agents: F₂ > Cl₂ > Br₂ > I₂.","Explained by increasing atomic radius and shielding down the group.","A more reactive halogen displaces a less reactive halide."]}]},{"id":"g74","title":"Hydrogen Halides & Thermal Stability","blocks":[{"type":"p","text":"All halogens react with hydrogen to form hydrogen halides (HX). The vigour of the reaction decreases down the group, and the thermal stability of the product also decreases."},{"type":"h","text":"Reactions with hydrogen"},{"type":"ul","items":["H₂ + F₂ → 2HF. EXPLOSIVE, even in the dark and at low temperatures.","H₂ + Cl₂ → 2HCl. Explosive in UV light or at high temperatures. Slow in the dark.","H₂ + Br₂ → 2HBr. Requires heating. Less vigorous.","H₂ + I₂ ⇌ 2HI. Slow, requires a catalyst (Pt), and the reaction is REVERSIBLE."]},{"type":"d","caption":"Thermal stability of hydrogen halides decreases down the group"},{"type":"h","text":"Why stability decreases"},{"type":"ul","items":["H–F bond is very short and strong (568 kJ mol⁻¹) → HF is extremely stable.","H–Cl: 432 kJ mol⁻¹. H–Br: 366 kJ mol⁻¹. H–I: 298 kJ mol⁻¹.","Going down: the H–X bond gets LONGER and WEAKER because the halogen atom is larger.","Weaker bonds are easier to break → HI decomposes at relatively low temperatures; HF is essentially unbreakable thermally."]},{"type":"callout","title":"Bond strength explains both trends","body":"The decreasing bond energy H–F > H–Cl > H–Br > H–I explains both (1) the decreasing vigour of the H₂ + X₂ reaction (less energy released as the bond formed is weaker) and (2) the decreasing thermal stability (weaker bonds break more easily)."},{"type":"takeaway","items":["Vigour of H₂ + X₂ decreases: F₂ explosive → I₂ slow/reversible.","Thermal stability: HF > HCl > HBr > HI.","Explained by decreasing H–X bond energy down the group."]}]},{"id":"g75","title":"Testing for Halide Ions: Ag⁺ & NH₃","blocks":[{"type":"p","text":"The standard test for halide ions uses silver nitrate solution followed by ammonia. Each halide gives a different coloured precipitate with different solubility in ammonia."},{"type":"d","caption":"The Ag⁺/NH₃ test distinguishes Cl⁻, Br⁻ and I⁻"},{"type":"h","text":"Procedure"},{"type":"ul","items":["Step 1: Acidify the solution with DILUTE NITRIC ACID (HNO₃). This removes interfering ions like CO₃²⁻ and SO₃²⁻ that would also give precipitates with Ag⁺.","Step 2: Add silver nitrate solution, AgNO₃(aq).","Step 3: Observe the precipitate colour: white (Cl⁻), cream (Br⁻), yellow (I⁻).","Step 4: Add dilute ammonia (NH₃) to confirm: AgCl dissolves (soluble), AgBr does not dissolve.","Step 5: Add concentrated ammonia: AgBr now dissolves, but AgI still does not."]},{"type":"h","text":"Equations"},{"type":"ul","items":["Ag⁺(aq) + Cl⁻(aq) → AgCl(s) — white precipitate.","Ag⁺(aq) + Br⁻(aq) → AgBr(s) — cream precipitate.","Ag⁺(aq) + I⁻(aq) → AgI(s) — yellow precipitate.","AgCl dissolves in dilute NH₃: AgCl + 2NH₃ → [Ag(NH₃)₂]⁺ + Cl⁻ (diamminesilver(I) complex)."]},{"type":"callout","title":"Why HNO₃ not HCl?","body":"You must use nitric acid, NOT hydrochloric acid. HCl would introduce Cl⁻ ions, giving a false positive for chloride. HNO₃ does not contain any halide ions."},{"type":"takeaway","items":["Acidify with HNO₃, then add AgNO₃.","White = Cl⁻ (dissolves in dil. NH₃). Cream = Br⁻ (dissolves in conc. NH₃). Yellow = I⁻ (insoluble in NH₃).","Use HNO₃, never HCl, to acidify."]}]},{"id":"g76","title":"Halide Ions + Concentrated H₂SO₄","blocks":[{"type":"p","text":"When solid sodium halides are treated with concentrated sulphuric acid, the products depend on whether the hydrogen halide (HX) is a strong enough reducing agent to reduce H₂SO₄."},{"type":"d","caption":"Products depend on reducing power of the halide"},{"type":"h","text":"NaCl + conc. H₂SO₄"},{"type":"ul","items":["NaCl + H₂SO₄ → NaHSO₄ + HCl. White fumes of HCl.","HCl is NOT a strong enough reducing agent to reduce H₂SO₄ further.","This is a simple acid-base reaction (not redox). H₂SO₄ acts as an acid, donating H⁺ to Cl⁻."]},{"type":"h","text":"NaBr + conc. H₂SO₄"},{"type":"ul","items":["Initially: NaBr + H₂SO₄ → NaHSO₄ + HBr (acid-base, steamy fumes).","But HBr IS a reducing agent. It reduces H₂SO₄: 2HBr + H₂SO₄ → Br₂ + SO₂ + 2H₂O.","Observations: brown/orange fumes of Br₂, pungent SO₂ gas.","Br⁻ is oxidised from −1 to 0; S is reduced from +6 to +4."]},{"type":"h","text":"NaI + conc. H₂SO₄"},{"type":"ul","items":["Initially: NaI + H₂SO₄ → NaHSO₄ + HI.","HI is a VERY strong reducing agent. It reduces H₂SO₄ all the way to H₂S:","8HI + H₂SO₄ → 4I₂ + H₂S + 4H₂O.","Observations: purple/black I₂ solid/vapour, rotten egg smell of H₂S.","I⁻ is oxidised from −1 to 0; S is reduced from +6 to −2 (a 8-electron change!).","Also produces SO₂ and S as intermediate reduction products."]},{"type":"callout","title":"Reducing power increases","body":"Cl⁻: no reduction of H₂SO₄. Br⁻: reduces to SO₂ (S: +6→+4). I⁻: reduces to H₂S (S: +6→−2). This is because the reducing power of X⁻ increases down the group — larger ions hold their outer electrons less tightly and lose them more easily."},{"type":"takeaway","items":["NaCl: HCl only (white fumes, no redox).","NaBr: HBr then Br₂ + SO₂ (brown fumes).","NaI: HI then I₂ + H₂S (purple/black, rotten egg smell).","Reducing power: I⁻ > Br⁻ > Cl⁻."]}]},{"id":"g77","title":"Disproportionation of Cl₂ with NaOH","blocks":[{"type":"p","text":"Chlorine reacts with sodium hydroxide in a DISPROPORTIONATION reaction — the same element (Cl) is simultaneously oxidised AND reduced. The products depend on the temperature."},{"type":"d","caption":"Cold vs hot NaOH gives different products"},{"type":"h","text":"Cold dilute NaOH"},{"type":"ul","items":["Cl₂ + 2NaOH → NaCl + NaClO + H₂O.","Chlorine (oxidation state 0) → Cl⁻ (−1, reduced) and ClO⁻ (+1, oxidised).","NaClO is sodium chlorate(I) = bleach (sodium hypochlorite).","This reaction is the basis of household bleach manufacture."]},{"type":"h","text":"Hot concentrated NaOH"},{"type":"ul","items":["3Cl₂ + 6NaOH → 5NaCl + NaClO₃ + 3H₂O.","Chlorine (0) → Cl⁻ (−1, reduced) and ClO₃⁻ (+5, oxidised).","NaClO₃ is sodium chlorate(V) — used as a weedkiller.","The higher temperature allows further oxidation of Cl to the +5 state."]},{"type":"h","text":"Cl₂ in cold water"},{"type":"ul","items":["Cl₂ + H₂O ⇌ HCl + HClO (or H⁺ + Cl⁻ + HClO).","Also a disproportionation: Cl₂ (0) → Cl⁻ (−1) + HClO (+1).","HClO (chloric(I) acid) is the active disinfecting agent in chlorinated water.","This equilibrium explains why chlorine both acidifies water AND acts as a bleach/disinfectant."]},{"type":"callout","title":"Disproportionation","body":"A reaction in which the SAME element is simultaneously OXIDISED and REDUCED. Cl₂ → Cl⁻ (reduction, −1) + ClO⁻ (oxidation, +1). The element goes to both a higher AND lower oxidation state."},{"type":"takeaway","items":["Cold NaOH: Cl₂ → NaCl + NaClO (bleach). Cl: 0 → −1 and +1.","Hot NaOH: Cl₂ → NaCl + NaClO₃. Cl: 0 → −1 and +5.","Cold water: Cl₂ → HCl + HClO (disinfectant).","All are disproportionation reactions."]}]},{"id":"g78","title":"Industrial Importance & Environmental Significance","blocks":[{"type":"p","text":"The halogens and their compounds have enormous industrial importance but also raise significant environmental concerns."},{"type":"h","text":"Uses of chlorine and its compounds"},{"type":"ul","items":["Water purification: Cl₂ or NaClO kills bacteria by oxidation. Used in drinking water and swimming pools.","Bleach manufacture: Cl₂ + 2NaOH → NaCl + NaClO.","PVC production: Cl₂ is used to make chloroethene (vinyl chloride), which is polymerised to PVC — a major construction and packaging plastic.","Halogenated hydrocarbons: used as solvents (e.g. dichloromethane), refrigerants, and anaesthetics."]},{"type":"h","text":"Environmental concerns"},{"type":"ul","items":["CFCs (chlorofluorocarbons): formerly used as refrigerants and aerosol propellants. Extremely stable → persist in the atmosphere → reach the ozone layer.","In the stratosphere, UV light breaks C–Cl bonds: CFCl₃ → CFCl₂ + Cl•. The chlorine radical catalytically destroys ozone: Cl• + O₃ → ClO• + O₂, then ClO• + O₃ → Cl• + 2O₂. One Cl• can destroy thousands of O₃ molecules.","HFCs and HCFCs are now used as replacements — they break down in the lower atmosphere before reaching the ozone layer.","Chlorinated solvents: can contaminate groundwater. Many are now restricted or banned."]},{"type":"h","text":"Uses of bromine and iodine"},{"type":"ul","items":["Br₂: fire retardants, photographic chemicals, pharmaceuticals.","I₂: antiseptic (tincture of iodine), iodised salt (prevents goitre/thyroid deficiency), medical contrast agents.","AgBr: used in traditional photographic film (decomposes in light to form Ag metal)."]},{"type":"takeaway","items":["Cl₂: water purification, bleach, PVC.","CFCs destroy ozone layer — now banned under Montreal Protocol.","I₂: antiseptic, iodised salt."]}]},{"id":"g79","title":"Halogen Oxidation States & Thiosulphate","blocks":[{"type":"p","text":"Halogens typically have oxidation state −1 in halides, but chlorine can also show +1 (in ClO⁻), +5 (in ClO₃⁻) and +7 (in ClO₄⁻). The exam may also involve the halogen–thiosulphate reaction used in iodometric titrations."},{"type":"h","text":"Oxidation states of chlorine"},{"type":"ul","items":["Cl₂: 0 (elemental).","Cl⁻: −1 (in HCl, NaCl).","ClO⁻ (hypochlorite): +1 (in bleach, NaClO).","ClO₃⁻ (chlorate): +5 (in NaClO₃).","ClO₄⁻ (perchlorate): +7."]},{"type":"h","text":"Reaction of halogens with Na₂S₂O₃"},{"type":"ul","items":["I₂ + 2Na₂S₂O₃ → 2NaI + Na₂S₄O₆ (iodine–thiosulphate titration).","I₂ is reduced (0 → −1); S₂O₃²⁻ is oxidised (+2 → +2.5 average in S₄O₆²⁻).","This is the basis of iodometric analysis — widely used in quantitative chemistry.","Starch indicator: turns blue-black with I₂; colourless at endpoint when all I₂ consumed."]},{"type":"h","text":"Change in oxidation state for Cl₂ + NaOH"},{"type":"p","text":"In cold NaOH: Cl goes from 0 to both −1 (Cl⁻) and +1 (ClO⁻). In hot NaOH: from 0 to −1 (Cl⁻) and +5 (ClO₃⁻). These changes are used to calculate the mole ratios in the equations."},{"type":"takeaway","items":["Cl can be −1, 0, +1, +5, +7.","I₂ + 2S₂O₃²⁻ → 2I⁻ + S₄O₆²⁻ (iodometric titration).","Disproportionation: 0 → −1 and +1 (cold) or +5 (hot)."]}]},{"id":"g710","title":"Halide Ions as Reducing Agents","blocks":[{"type":"p","text":"While halogens are OXIDISING agents, halide ions (X⁻) are REDUCING agents. Their reducing power INCREASES down the group: I⁻ > Br⁻ > Cl⁻ > F⁻."},{"type":"h","text":"Why reducing power increases"},{"type":"ul","items":["Going down: ionic radius INCREASES. The outer electron in the halide ion is further from the nucleus and more shielded.","It is easier to REMOVE this electron (lower ionisation energy for X⁻ → X + e⁻).","Therefore I⁻ is the most easily oxidised halide → strongest reducing agent."]},{"type":"h","text":"Evidence from conc. H₂SO₄ reactions"},{"type":"ul","items":["Cl⁻: cannot reduce H₂SO₄ at all → only HCl produced.","Br⁻: reduces H₂SO₄ to SO₂ (+6 → +4) → Br₂ produced.","I⁻: reduces H₂SO₄ to H₂S (+6 → −2) → I₂ produced.","This dramatic difference is direct evidence for increasing reducing power down the group."]},{"type":"callout","title":"Don't confuse the two trends","body":"Halogens (X₂) are oxidising agents — strength DECREASES down. Halide ions (X⁻) are reducing agents — strength INCREASES down. These are opposite trends for the same reason: electron affinity/IE of the species involved."},{"type":"takeaway","items":["Reducing power of X⁻ increases: F⁻ < Cl⁻ < Br⁻ < I⁻.","Evidence: reactions with conc. H₂SO₄ show I⁻ is strongest reducer.","Opposite trend to halogen oxidising power."]}]},{"id":"g711","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Group VII questions combine trend explanations, testing procedures, equations, and redox analysis. Here are the key patterns."},{"type":"h","text":"Must-know equations"},{"type":"ul","items":["Cl₂ + 2KBr → 2KCl + Br₂ (displacement).","Cl₂ + 2NaOH → NaCl + NaClO + H₂O (cold — bleach).","3Cl₂ + 6NaOH → 5NaCl + NaClO₃ + 3H₂O (hot).","Ag⁺ + X⁻ → AgX (precipitate test).","NaCl + H₂SO₄ → NaHSO₄ + HCl.","2HBr + H₂SO₄ → Br₂ + SO₂ + 2H₂O.","8HI + H₂SO₄ → 4I₂ + H₂S + 4H₂O."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Saying \\"reactivity increases down Group VII\\" — WRONG. Oxidising power (reactivity of X₂) DECREASES. Reducing power (of X⁻) INCREASES.","Using HCl to acidify in the halide test — use HNO₃ only.","Forgetting to state temperature for Cl₂ + NaOH reactions (cold → ClO⁻; hot → ClO₃⁻).","Writing the wrong products for NaI + conc. H₂SO₄ — there are MULTIPLE products (I₂, H₂S, S, SO₂) because I⁻ is such a strong reducer."]},{"type":"h","text":"Colour observations to state in exams"},{"type":"ul","items":["Cl₂ displaces Br⁻: solution turns ORANGE/BROWN.","Cl₂ displaces I⁻: solution turns BROWN (dark) or add starch for BLUE-BLACK.","AgCl: WHITE ppt. AgBr: CREAM ppt. AgI: YELLOW ppt.","Br₂ fumes: brown/orange. I₂ vapour: purple."]},{"type":"takeaway","items":["Oxidising power decreases down (X₂); reducing power increases down (X⁻).","Use HNO₃ to acidify, never HCl.","State temperature for Cl₂ + NaOH.","Know ALL observation colours."]}]}]}`),nsulphur:JSON.parse(`{"objectives":["Explain the lack of reactivity of nitrogen in terms of the N≡N triple bond energy","Describe the formation and structure of the ammonium ion (dative bond) and its reaction with alkalis","Explain the Haber process conditions (450°C, 200 atm, Fe) using principles of kinetics and equilibria","Explain the Contact process conditions (450°C, 1–2 atm, V₂O₅) using principles of kinetics and equilibria","Recognise the industrial importance of NH₃ (fertilisers, nitric acid) and H₂SO₄ (fertilisers, detergents, batteries)","Describe environmental consequences of NOₓ (acid rain, smog, eutrophication) and SO₂ (acid rain, respiratory problems)","Explain the catalytic removal of NOₓ in car exhausts and methods of controlling SO₂ emissions","Describe the use of SO₂ in food preservation"],"chapters":[{"id":"ns1","title":"Why Is Nitrogen So Unreactive?","blocks":[{"type":"p","text":"Nitrogen gas (N₂) makes up 78% of the atmosphere yet is remarkably unreactive at room temperature. This is because the two nitrogen atoms are joined by a TRIPLE BOND (N≡N) with a bond energy of 944 kJ mol⁻¹ — one of the strongest covalent bonds known. The very high activation energy required to break this bond makes N₂ kinetically inert."},{"type":"d","caption":"The N≡N triple bond is exceptionally strong"},{"type":"h","text":"Chemical properties of nitrogen"},{"type":"ul","items":["N₂ reacts with H₂ at high temperature and pressure, with a catalyst: N₂ + 3H₂ ⇌ 2NH₃ (Haber process).","N₂ reacts with O₂ only at very high temperatures (>2000 °C), such as in lightning or car engines: N₂ + O₂ → 2NO.","N₂ reacts with some reactive metals (Li, Mg) when heated: 3Mg + N₂ → Mg₃N₂ (magnesium nitride).","Overall, the high bond dissociation energy of N≡N means most reactions involving N₂ require extreme conditions."]},{"type":"h","text":"Comparison with oxygen"},{"type":"p","text":"O₂ has a double bond (O=O, 496 kJ mol⁻¹) which is much weaker than N≡N. This is why oxygen is far more reactive than nitrogen at room temperature — it supports combustion, rusting and respiration, while nitrogen is essentially inert under the same conditions."},{"type":"takeaway","items":["N₂ has a triple bond (944 kJ mol⁻¹) — very strong, very high Ea.","N₂ reacts only at high T/P or with very reactive metals.","Kinetically inert despite being thermodynamically reactive in some cases."]}]},{"id":"ns2","title":"Ammonia & the Ammonium Ion","blocks":[{"type":"p","text":"Ammonia (NH₃) is a colourless gas with a pungent smell. It is the primary nitrogen compound of industrial importance. NH₃ has a lone pair on nitrogen which makes it a BASE (proton acceptor) and allows it to form the ammonium ion (NH₄⁺) by dative bonding."},{"type":"d","caption":"Formation and structure of NH₄⁺"},{"type":"h","text":"Formation of the ammonium ion"},{"type":"ul","items":["NH₃ has a lone pair on N. When NH₃ acts as a base, it donates this lone pair to an H⁺ ion: NH₃ + H⁺ → NH₄⁺.","The bond formed is a DATIVE (coordinate) bond — both electrons come from the N lone pair.","Once formed, all four N–H bonds in NH₄⁺ are identical and indistinguishable.","NH₄⁺ is tetrahedral with bond angle 109.5°."]},{"type":"h","text":"Reactions of NH₄⁺ with alkalis"},{"type":"ul","items":["NH₄⁺ salts react with alkalis on heating to release ammonia gas:","NH₄Cl + NaOH → NaCl + H₂O + NH₃↑ (test: damp red litmus turns blue).","This is the standard test for ammonium ions.","General equation: NH₄⁺ + OH⁻ → NH₃ + H₂O."]},{"type":"h","text":"Laboratory preparation of ammonia"},{"type":"p","text":"Heat any ammonium salt with a strong base (e.g. Ca(OH)₂): 2NH₄Cl + Ca(OH)₂ → CaCl₂ + 2H₂O + 2NH₃↑. Collect by upward delivery (NH₃ is less dense than air). Dry over CaO (not CaCl₂, which reacts with NH₃)."},{"type":"takeaway","items":["NH₃ + H⁺ → NH₄⁺ via dative bond from N lone pair.","NH₄⁺ is tetrahedral (109.5°).","Test: NH₄⁺ + OH⁻ → NH₃ (turns damp red litmus blue)."]}]},{"id":"ns3","title":"The Haber Process","blocks":[{"type":"p","text":"The Haber process manufactures ammonia from nitrogen and hydrogen: N₂(g) + 3H₂(g) ⇌ 2NH₃(g), ΔH = −92 kJ mol⁻¹. It is one of the most important industrial processes in the world — ammonia is used to make fertilisers, nitric acid, explosives and nylon."},{"type":"d","caption":"Haber process: conditions and rationale"},{"type":"h","text":"Conditions explained using equilibria"},{"type":"ul","items":["TEMPERATURE: the forward reaction is EXOTHERMIC. Le Chatelier says low temperature favours products (more NH₃). But at low temperature, the rate is too slow (particles lack energy to overcome the very high Ea of breaking N≡N). The compromise is 450 °C — fast enough for industry, reasonable yield.","PRESSURE: 4 moles of gas on the left, 2 on the right. High pressure shifts equilibrium RIGHT (fewer moles). 200 atm is used — higher would give more yield but is too expensive and dangerous.","CATALYST: iron (Fe) catalyst lowers the Ea so equilibrium is reached faster. It does NOT change the position of equilibrium or the value of K.","REMOVAL: NH₃ is continuously cooled and condensed out as a liquid. Removing product shifts equilibrium RIGHT. Unreacted N₂ and H₂ are RECYCLED."]},{"type":"h","text":"Conditions explained using kinetics"},{"type":"ul","items":["The N≡N bond (944 kJ mol⁻¹) has a very high Ea to break. Without the catalyst, the reaction would be impossibly slow.","The iron catalyst provides a surface for N₂ and H₂ to ADSORB. The N≡N bond is weakened on the surface (heterogeneous catalysis), allowing reaction at a feasible temperature.","At 450 °C, enough molecules have energy ≥ Ea (Boltzmann distribution) for a workable rate.","Yield per pass is only about 15%, but recycling gives an overall conversion of about 98%."]},{"type":"callout","title":"Exam template","body":"For any \\"explain the conditions\\" question, address THREE factors: (1) Temperature — compromise between yield and rate. (2) Pressure — Le Chatelier and cost/safety. (3) Catalyst — increases rate via lower Ea, does NOT change K or yield."},{"type":"takeaway","items":["450 °C (compromise: rate vs yield), 200 atm (fewer gas moles), Fe catalyst (speeds up).","NH₃ condensed and removed; unreacted gases recycled.","Yield per pass ~15%; overall ~98% with recycling."]}]},{"id":"ns4","title":"The Contact Process","blocks":[{"type":"p","text":"The Contact Process manufactures sulphuric acid (H₂SO₄) — the most widely used industrial chemical. It has three stages, with the second (catalytic oxidation of SO₂) being the key equilibrium step."},{"type":"d","caption":"Three stages of the Contact Process"},{"type":"h","text":"Stage 1: Burn sulphur"},{"type":"p","text":"S(s) + O₂(g) → SO₂(g). Sulphur is burned in excess air. This is exothermic and goes to completion (not reversible). The SO₂ is purified to prevent catalyst poisoning."},{"type":"h","text":"Stage 2: Catalytic oxidation (key step)"},{"type":"ul","items":["2SO₂(g) + O₂(g) ⇌ 2SO₃(g), ΔH = −196 kJ mol⁻¹.","Temperature: 450 °C — compromise (exothermic forward, so low T gives high yield, but rate too slow at low T).","Pressure: 1–2 atm is sufficient because Kp is already large (equilibrium strongly favours SO₃). Higher pressure is unnecessary and expensive.","Catalyst: vanadium(V) oxide (V₂O₅). Heterogeneous catalyst — SO₂ and O₂ adsorb on its surface.","Conversion is about 96–98% in modern multi-bed converters."]},{"type":"h","text":"Stage 3: Absorption"},{"type":"ul","items":["SO₃ is dissolved in CONCENTRATED H₂SO₄ (not water!) to form oleum (H₂S₂O₇): SO₃ + H₂SO₄ → H₂S₂O₇.","Oleum is then carefully diluted with water: H₂S₂O₇ + H₂O → 2H₂SO₄.","Why not dissolve SO₃ directly in water? Because SO₃ + H₂O is extremely exothermic and produces a dangerous acid MIST that is difficult to contain. Dissolving in conc. H₂SO₄ is controllable and safe."]},{"type":"takeaway","items":["Stage 1: S + O₂ → SO₂. Stage 2: 2SO₂ + O₂ ⇌ 2SO₃ (V₂O₅, 450°C, 1–2 atm). Stage 3: SO₃ → oleum → H₂SO₄.","Low pressure works because Kp is large.","SO₃ dissolved in H₂SO₄, not water (avoids acid mist)."]}]},{"id":"ns5","title":"Industrial Importance of NH₃ & H₂SO₄","blocks":[{"type":"p","text":"Ammonia and sulphuric acid are among the most produced chemicals globally. Their uses span agriculture, manufacturing and defence."},{"type":"h","text":"Uses of ammonia"},{"type":"ul","items":["FERTILISERS (by far the largest use): ammonium nitrate (NH₄NO₃), ammonium sulphate ((NH₄)₂SO₄), urea ((NH₂)₂CO). These provide nitrogen for plant growth.","Nitric acid manufacture (Ostwald process): 4NH₃ + 5O₂ → 4NO + 6H₂O (Pt catalyst), followed by oxidation of NO to NO₂ and dissolution in water.","Nylon production: ammonia is a starting material for hexanediamine.","Cleaning products: ammonia solution is a household cleaner and degreaser.","Explosives: ammonium nitrate is used as an explosive in mining."]},{"type":"h","text":"Uses of sulphuric acid"},{"type":"ul","items":["FERTILISERS: ammonium sulphate, superphosphate (treating rock phosphate with H₂SO₄).","Detergents and soaps.","Paints and pigments (TiO₂ production).","Lead-acid car batteries (electrolyte is dilute H₂SO₄).","Manufacturing other chemicals: HCl, HF, phosphoric acid.","Steel pickling: removing rust/scale from steel surfaces."]},{"type":"takeaway","items":["NH₃: fertilisers (main), nitric acid, nylon, explosives, cleaning.","H₂SO₄: fertilisers, detergents, paints, batteries, chemical manufacture."]}]},{"id":"ns6","title":"Environmental Impacts of N & S Compounds","blocks":[{"type":"p","text":"Compounds of nitrogen and sulphur released into the atmosphere cause acid rain, smog, and damage to health and ecosystems. Understanding these impacts is a significant part of the syllabus."},{"type":"d","caption":"Environmental impacts and solutions"},{"type":"h","text":"Nitrogen oxides (NOₓ)"},{"type":"ul","items":["Sources: car engines (N₂ + O₂ → 2NO at high T), power stations, lightning.","NO is colourless; it reacts with O₂ to form NO₂ (brown, toxic): 2NO + O₂ → 2NO₂.","NO₂ dissolves in water to form nitric acid: 4NO₂ + O₂ + 2H₂O → 4HNO₃ (acid rain).","NO₂ contributes to PHOTOCHEMICAL SMOG — a brown haze over cities, causing respiratory problems.","Nitrates from fertilisers leach into waterways causing EUTROPHICATION: algal bloom → algae die → bacteria decompose algae using O₂ → aquatic life suffocates."]},{"type":"h","text":"Sulphur dioxide (SO₂)"},{"type":"ul","items":["Sources: burning fossil fuels (coal and oil contain sulphur impurities), volcanic emissions, smelting sulphide ores.","SO₂ dissolves in water: SO₂ + H₂O → H₂SO₃ (sulphurous acid).","In the atmosphere, SO₂ is oxidised to SO₃ (catalysed by NOₓ): SO₂ + ½O₂ → SO₃, then SO₃ + H₂O → H₂SO₄.","H₂SO₃ and H₂SO₄ in rain → ACID RAIN: corrodes limestone buildings, damages forests, acidifies lakes (kills fish).","SO₂ is a respiratory irritant — causes breathing difficulties, worsens asthma."]},{"type":"takeaway","items":["NOₓ: acid rain (HNO₃), photochemical smog, eutrophication from nitrate runoff.","SO₂/SO₃: acid rain (H₂SO₃/H₂SO₄), corrosion, respiratory irritant."]}]},{"id":"ns7","title":"Catalytic Removal of NOₓ","blocks":[{"type":"p","text":"Catalytic converters in car exhausts are the primary method for removing NOₓ emissions. They use precious metal catalysts (Pt, Pd, Rh) to convert toxic gases into harmless ones."},{"type":"d","caption":"Catalytic converter: heterogeneous catalysis"},{"type":"h","text":"Key reactions in the catalytic converter"},{"type":"ul","items":["2CO(g) + 2NO(g) → 2CO₂(g) + N₂(g). CO and NO are both removed — CO is oxidised, NO is reduced.","Unburnt hydrocarbons + O₂ → CO₂ + H₂O. Complete combustion of unburned fuel.","The catalyst (Pt/Pd/Rh) provides a large surface area (honeycomb structure) for adsorption of gases.","This is HETEROGENEOUS catalysis: solid catalyst, gaseous reactants."]},{"type":"h","text":"Other NOₓ reduction methods"},{"type":"ul","items":["Lean-burn engines: use a high air-to-fuel ratio. The lower combustion temperature produces less NOₓ (N₂ + O₂ reaction is less favoured at lower T).","Exhaust gas recirculation (EGR): recirculates some exhaust back into the engine, reducing peak flame temperature.","Selective catalytic reduction (SCR): injects urea solution into the exhaust, which reacts with NOₓ on a catalyst to produce N₂ and H₂O."]},{"type":"callout","title":"Catalyst poisoning","body":"Lead in petrol POISONS the Pt/Rh catalyst by adsorbing onto active sites and blocking them. This is why leaded petrol has been banned in most countries — it would destroy the catalytic converter."},{"type":"takeaway","items":["Catalytic converter: 2CO + 2NO → 2CO₂ + N₂ (Pt/Pd/Rh surface).","Lean-burn engines: lower T → less NOₓ.","Lead poisons the catalyst → leaded petrol banned."]}]},{"id":"ns8","title":"SO₂ in Food Preservation & Emission Control","blocks":[{"type":"p","text":"Sulphur dioxide has a dual role: it is an environmental pollutant but also a useful chemical in food preservation."},{"type":"h","text":"SO₂ as a food preservative"},{"type":"ul","items":["SO₂ (or sulphites like Na₂SO₃) is added to dried fruits, wine, fruit juices and some processed foods.","It acts as an ANTIOXIDANT — it reacts with oxygen before the food can, preventing browning and spoilage.","It also has ANTIMICROBIAL properties — it inhibits the growth of bacteria and moulds.","Labelled on food packaging as E220 (SO₂) or E221-E228 (various sulphites).","Some people are sensitive to sulphites — they can trigger asthma attacks."]},{"type":"h","text":"Controlling SO₂ emissions"},{"type":"ul","items":["Flue gas desulphurisation (FGD): SO₂ in power station exhaust is removed by reacting with CaO or CaCO₃.","CaO + SO₂ → CaSO₃. Or: CaCO₃ + SO₂ → CaSO₃ + CO₂.","Alkaline scrubbing: SO₂ + 2NaOH → Na₂SO₃ + H₂O.","Limestone-based fluidised beds: powdered CaCO₃ is mixed with the fuel so SO₂ is absorbed as it forms.","Using low-sulphur fuels or switching to natural gas (which contains almost no sulphur)."]},{"type":"takeaway","items":["SO₂ preserves food: antioxidant + antimicrobial.","FGD: CaO/CaCO₃ + SO₂ → CaSO₃. Alkaline scrubbing: NaOH + SO₂ → Na₂SO₃.","Low-sulphur fuels reduce emissions at source."]}]},{"id":"ns9","title":"Preparing Ammonium Sulphate","blocks":[{"type":"p","text":"Ammonium sulphate ((NH₄)₂SO₄) is an important nitrogenous fertiliser. It can be made in the lab by reacting ammonia solution with dilute sulphuric acid."},{"type":"h","text":"Laboratory preparation"},{"type":"ul","items":["Equation: 2NH₃(aq) + H₂SO₄(aq) → (NH₄)₂SO₄(aq).","Method: titrate NH₃ solution with dilute H₂SO₄ using a suitable indicator (methyl orange) to find the endpoint.","Repeat WITHOUT indicator using the measured volumes to get a pure solution.","Evaporate carefully to crystallisation point, then cool to collect crystals.","Filter, wash with a little cold distilled water, and dry between filter papers."]},{"type":"h","text":"Why ammonium sulphate is a good fertiliser"},{"type":"ul","items":["Contains nitrogen in a form (NH₄⁺) that plants can directly absorb through their roots.","Also contains sulphur (as SO₄²⁻), which is a secondary nutrient for plants.","Soluble in water → readily reaches plant roots.","Relatively stable — does not decompose or evaporate easily."]},{"type":"takeaway","items":["2NH₃ + H₂SO₄ → (NH₄)₂SO₄ (acid-base neutralisation).","Lab method: titration → repeat without indicator → crystallise.","Important fertiliser: provides N (as NH₄⁺) and S (as SO₄²⁻)."]}]},{"id":"ns10","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"N & S questions combine industrial processes, equilibria/kinetics, and environmental chemistry. Here are the key patterns."},{"type":"h","text":"Process conditions — the template"},{"type":"ul","items":["For BOTH Haber and Contact: the answer template is: (1) Temperature is a COMPROMISE between rate and yield. (2) Pressure effect explained by Le Chatelier and moles of gas. (3) Catalyst speeds up attainment of equilibrium but does NOT change K or yield.","Haber: 450 °C, 200 atm, Fe. Contact: 450 °C, 1–2 atm, V₂O₅.","Key difference: Contact process uses LOW pressure because Kp is already favourable."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Saying the catalyst \\"increases yield\\" — WRONG. It increases RATE only.","Confusing the Contact process catalyst (V₂O₅) with the Haber catalyst (Fe).","Forgetting that SO₃ is dissolved in H₂SO₄ (not water) in Stage 3 of Contact.","Not mentioning RECYCLING of unreacted gases in the Haber process.","Describing eutrophication without explaining the full chain: nitrate → algal bloom → decay → O₂ depletion → aquatic death."]},{"type":"h","text":"Environmental equations to know"},{"type":"ul","items":["Catalytic converter: 2CO + 2NO → 2CO₂ + N₂.","FGD: CaO + SO₂ → CaSO₃.","Alkaline scrubbing: SO₂ + 2NaOH → Na₂SO₃ + H₂O.","Acid rain formation: SO₂ + H₂O → H₂SO₃; 4NO₂ + O₂ + 2H₂O → 4HNO₃."]},{"type":"takeaway","items":["Catalyst ≠ more yield. Catalyst = faster equilibrium.","Haber: Fe, 200 atm. Contact: V₂O₅, 1–2 atm.","SO₃ into H₂SO₄ (not water). Unreacted gases recycled."]}]}]}`),halogen:JSON.parse(`{"objectives":["Name halogenoalkanes using IUPAC nomenclature; classify as 1°, 2° or 3°","Describe isomerism in halogenoalkanes including optical isomerism at chiral centres","Write equations and conditions for nucleophilic substitution: hydrolysis (NaOH(aq)), nitrile formation (KCN/alc), and primary amine formation (excess NH₃)","Outline the SN1 and SN2 mechanisms with curly arrows; explain when each is preferred","Describe the elimination of HBr from 2-bromopropane using hot concentrated alcoholic KOH","Compare reactivities of halogenoalkanes and chlorobenzene; explain in terms of C–Hal bond strength and π-overlap","Explain the inertness of fluoroalkanes and uses of CFCs as refrigerants/aerosols","Describe the mechanism by which CFCs destroy the ozone layer and the role of HFCs as replacements"],"chapters":[{"id":"hd1","title":"Halogenoalkanes: Naming & Classification","blocks":[{"type":"p","text":"Halogenoalkanes (also called haloalkanes) are alkanes in which one or more hydrogen atoms have been replaced by a halogen (F, Cl, Br or I). They have the general formula CₙH₂ₙ₊₁X. Their behaviour is dominated by the polar C–X bond, where carbon carries a partial positive charge (δ+) and the halogen carries a partial negative charge (δ−)."},{"type":"h","text":"Nomenclature (IUPAC rules)"},{"type":"ul","items":["Identify the longest carbon chain containing the halogen.","Number from the end nearest the halogen to give the lowest locant.","Name the halogen as a prefix: fluoro, chloro, bromo, iodo.","For multiple halogens: list alphabetically (bromo before chloro), use di-/tri-/tetra- for multiples of the same halogen.","Examples: CH₃CH₂Br = bromoethane; (CH₃)₂CHCl = 2-chloropropane; CHCl₃ = trichloromethane (chloroform); CCl₄ = tetrachloromethane."]},{"type":"h","text":"Classification: 1°, 2° and 3°"},{"type":"d","caption":"Three classes of halogenoalkanes"},{"type":"ul","items":["PRIMARY (1°): the carbon bearing the halogen is bonded to ONE other carbon (or none, e.g. CH₃X). General form R–CH₂–X.","SECONDARY (2°): the C–X carbon is bonded to TWO other carbons. General form R₂CH–X.","TERTIARY (3°): the C–X carbon is bonded to THREE other carbons. General form R₃C–X.","This classification matters because it controls which substitution mechanism (SN1 or SN2) is preferred."]},{"type":"callout","title":"Why polarity matters","body":"The C–X bond is polar because halogens are more electronegative than carbon. This δ+ on carbon makes it a target for NUCLEOPHILES (electron-rich species like OH⁻, CN⁻, NH₃). Most reactions of halogenoalkanes are nucleophilic substitutions or eliminations driven by this polarity."},{"type":"takeaway","items":["Halogenoalkanes have a polar C–X bond (δ+ on C).","Classified as 1°, 2°, 3° based on substitution at the C–X carbon.","Class controls the mechanism (SN1 vs SN2)."]}]},{"id":"hd2","title":"Isomerism in Halogenoalkanes","blocks":[{"type":"p","text":"Halogenoalkanes show several types of isomerism: chain isomerism, position isomerism, and (for chiral molecules) optical isomerism."},{"type":"h","text":"Chain isomerism"},{"type":"p","text":"Different carbon skeletons. Example: C₄H₉Br can be 1-bromobutane (CH₃CH₂CH₂CH₂Br) or 1-bromo-2-methylpropane ((CH₃)₂CHCH₂Br) — same molecular formula, different chain."},{"type":"h","text":"Position isomerism"},{"type":"p","text":"Same chain, halogen in different positions. Example: C₃H₇Cl exists as 1-chloropropane (CH₃CH₂CH₂Cl) and 2-chloropropane ((CH₃)₂CHCl). They have very different reactivities — 2-chloropropane is secondary, more prone to SN1."},{"type":"h","text":"Optical isomerism"},{"type":"ul","items":["Occurs when the C bearing the halogen has 4 DIFFERENT groups attached (a chiral centre or stereocentre).","Example: 2-bromobutane, CH₃CHBrCH₂CH₃. The middle C has H, Br, CH₃ and C₂H₅ — four different groups.","Two non-superimposable mirror image forms exist (enantiomers).","Enantiomers rotate plane-polarised light in opposite directions (one (+), one (−)).","A 1:1 mixture is called a RACEMIC mixture and is optically inactive (rotations cancel)."]},{"type":"callout","title":"SN1 gives racemic products","body":"Because SN1 goes through a planar carbocation intermediate, the nucleophile can attack from either face equally → produces a 50:50 mixture of both enantiomers (racemic). SN2, by contrast, gives INVERSION of configuration (Walden inversion) — only one stereoisomer is produced."},{"type":"takeaway","items":["Chain, position and optical isomerism all possible.","Optical isomerism requires a chiral centre (4 different groups on C–X).","SN1 → racemic; SN2 → inversion of configuration."]}]},{"id":"hd3","title":"Nucleophilic Substitution: Hydrolysis","blocks":[{"type":"p","text":"Hydrolysis is the reaction of a halogenoalkane with water (or aqueous OH⁻) to form an alcohol. It is the prototypical nucleophilic substitution reaction at A-level."},{"type":"h","text":"The reaction"},{"type":"ul","items":["CH₃CH₂Br + NaOH(aq) → CH₃CH₂OH + NaBr.","Conditions: AQUEOUS NaOH, REFLUX (gentle heating with condenser to prevent loss of volatile reactant).","Mechanism: nucleophilic substitution. OH⁻ attacks the δ+ carbon and displaces Br⁻.","The OH⁻ ion is a good nucleophile because it has a lone pair on the oxygen and a negative charge."]},{"type":"h","text":"Hydrolysis without OH⁻"},{"type":"p","text":"Even pure water can hydrolyse halogenoalkanes, though more slowly. This is the basis of the silver nitrate test for halogenoalkanes:"},{"type":"ul","items":["Add ethanol (to dissolve the halogenoalkane) and aqueous AgNO₃.","Warm gently. The halogenoalkane hydrolyses: R–X + H₂O → R–OH + HX.","The X⁻ ions react with Ag⁺: Ag⁺ + Cl⁻ → AgCl (white), Ag⁺ + Br⁻ → AgBr (cream), Ag⁺ + I⁻ → AgI (yellow).","The TIME taken for the precipitate to appear measures the rate of hydrolysis."]},{"type":"h","text":"Order of reactivity: I > Br > Cl > F"},{"type":"d","caption":"C–Hal bond energies determine reactivity"},{"type":"ul","items":["C–F is the strongest (484 kJ mol⁻¹) — fluoroalkanes are essentially unreactive.","C–Cl: 338 kJ mol⁻¹.","C–Br: 285 kJ mol⁻¹.","C–I: 213 kJ mol⁻¹ — the weakest, easiest to break.","Reactivity is therefore: iodoalkanes > bromoalkanes > chloroalkanes >> fluoroalkanes.","Bond strength matters more than bond polarity here — although C–F is the most polar, it is so strong that hydrolysis is impractical."]},{"type":"takeaway","items":["R–Br + NaOH(aq) → R–OH + NaBr (reflux in water).","Reactivity order: R–I > R–Br > R–Cl >> R–F.","Determined by C–Hal bond strength (weaker = more reactive)."]}]},{"id":"hd4","title":"SN2 Mechanism (Bimolecular)","blocks":[{"type":"p","text":"SN2 stands for Substitution Nucleophilic Bimolecular. The reaction occurs in a SINGLE STEP — the nucleophile attacks the carbon at the same time as the halide leaves."},{"type":"d","caption":"SN2 — concerted single step via transition state"},{"type":"h","text":"Key features of SN2"},{"type":"ul","items":["The nucleophile attacks from the OPPOSITE side to the halogen (\\"backside attack\\").","A 5-coordinate transition state forms briefly — partial Nu–C bond and partial C–X bond.","The molecule undergoes WALDEN INVERSION — like an umbrella turning inside out.","Rate equation: rate = k[R-X][Nu⁻]. The reaction is SECOND ORDER overall (first order in each reactant).","SN2 is favoured by PRIMARY halogenoalkanes (R–CH₂–X). Less steric hindrance allows the nucleophile to approach."]},{"type":"h","text":"Why SN2 disfavours tertiary"},{"type":"ul","items":["Tertiary carbons (R₃C–X) are surrounded by three large alkyl groups.","These bulky groups physically BLOCK the nucleophile from attacking.","The transition state would be highly crowded — too high in energy.","Tertiary halogenoalkanes therefore prefer SN1 (no nucleophile attack on the crowded carbon)."]},{"type":"callout","title":"SN2 = \\"S two\\": single step, two species in RDS","body":"In SN2, the rate-determining step (the only step) involves both the halogenoalkane AND the nucleophile. Doubling either concentration doubles the rate. This is the diagnostic feature."},{"type":"takeaway","items":["SN2: one step, backside attack, Walden inversion.","Rate = k[R-X][Nu⁻] — bimolecular.","Favoured by 1° halogenoalkanes (no steric hindrance)."]}]},{"id":"hd5","title":"SN1 Mechanism (Unimolecular)","blocks":[{"type":"p","text":"SN1 stands for Substitution Nucleophilic Unimolecular. The reaction occurs in TWO STEPS, with formation of a CARBOCATION intermediate."},{"type":"d","caption":"SN1 — two steps via carbocation intermediate"},{"type":"h","text":"The two steps"},{"type":"ul","items":["Step 1 (slow, RDS): the C–X bond breaks heterolytically. Both electrons go to the halogen, leaving a CARBOCATION (R₃C⁺) and a halide ion. This is the rate-determining step.","Step 2 (fast): the nucleophile attacks the carbocation: R₃C⁺ + Nu⁻ → R₃C–Nu.","Rate equation: rate = k[R-X]. The reaction is FIRST ORDER overall — only the halogenoalkane appears in the rate law because the nucleophile is not in the RDS."]},{"type":"h","text":"Why SN1 favours tertiary"},{"type":"ul","items":["Tertiary carbocations (R₃C⁺) are STABILISED by three alkyl groups donating electron density (positive inductive effect).","More substitution → more stabilisation → easier carbocation formation → faster SN1.","Stability order: 3° > 2° > 1° > methyl carbocation.","Primary carbocations are very unstable and almost never form — primary halogenoalkanes go via SN2 instead."]},{"type":"h","text":"Stereochemistry consequence"},{"type":"p","text":"The carbocation is PLANAR (sp² hybridised). The nucleophile can attack from either face with equal probability. If the starting material had a chiral centre, the product is a 50:50 RACEMIC MIXTURE — the original stereochemistry is lost."},{"type":"callout","title":"SN1 vs SN2 summary","body":"SN2: 1° halogenoalkanes, single step, Walden inversion, rate = k[R-X][Nu⁻]. SN1: 3° halogenoalkanes, two steps, racemisation, rate = k[R-X]. Secondary (2°) can go either way depending on conditions."},{"type":"takeaway","items":["SN1: two steps, carbocation intermediate, racemisation.","Rate = k[R-X] only — unimolecular RDS.","Favoured by 3° halogenoalkanes (carbocation stabilised by alkyl groups)."]}]},{"id":"hd6","title":"Nitriles & Amines from Halogenoalkanes","blocks":[{"type":"p","text":"Halogenoalkanes are versatile starting materials for synthesis. Two key transformations are conversion to NITRILES (using KCN) and to PRIMARY AMINES (using NH₃)."},{"type":"d","caption":"Key reactions of bromoethane"},{"type":"h","text":"Formation of nitriles"},{"type":"ul","items":["Reagent: KCN (potassium cyanide) dissolved in ETHANOL (alcoholic conditions).","Mechanism: nucleophilic substitution. CN⁻ attacks the δ+ carbon, displacing X⁻.","Equation: CH₃CH₂Br + KCN → CH₃CH₂CN + KBr.","The product is propanenitrile (CH₃CH₂CN). NOTE: the carbon chain has GROWN BY ONE — this is a useful way to extend a carbon skeleton.","Conditions: REFLUX in ethanol. Use ethanol (not water) to prevent hydrolysis competing.","WARNING: KCN is extremely toxic."]},{"type":"h","text":"Formation of primary amines"},{"type":"ul","items":["Reagent: EXCESS NH₃ in ethanol, in a SEALED TUBE under pressure (because NH₃ is a gas).","Mechanism: nucleophilic substitution. The lone pair on N attacks the δ+ carbon.","Equation: CH₃CH₂Br + NH₃ → CH₃CH₂NH₂ + HBr (HBr immediately neutralised by excess NH₃ to form NH₄Br).","Excess NH₃ is essential — otherwise the primary amine reacts further to give secondary (R₂NH) and tertiary (R₃N) amines, and even quaternary ammonium salts (R₄N⁺X⁻).","The product is ethanamine (CH₃CH₂NH₂). The carbon chain length is unchanged."]},{"type":"callout","title":"Why excess NH₃?","body":"The primary amine product (R-NH₂) is itself a nucleophile — even better than NH₃ because alkyl groups are electron-donating. So it can attack another R-X molecule, giving R₂NH (secondary). This continues to R₃N and R₄N⁺. Excess NH₃ ensures NH₃ is the most likely nucleophile to attack first."},{"type":"takeaway","items":["R-X + KCN (alc) → R-CN (nitrile) — chain extends by 1.","R-X + excess NH₃ (alc, sealed) → R-NH₂ (primary amine).","Both are nucleophilic substitutions."]}]},{"id":"hd7","title":"Elimination: Forming Alkenes","blocks":[{"type":"p","text":"When a halogenoalkane is heated with HOT, CONCENTRATED, ALCOHOLIC KOH (or NaOH), it undergoes ELIMINATION instead of substitution. The product is an alkene, formed by loss of HX (here, HBr) from adjacent carbons."},{"type":"d","caption":"Elimination of HBr from 2-bromopropane"},{"type":"h","text":"The reaction"},{"type":"ul","items":["CH₃CHBrCH₃ + KOH (alc, hot, conc) → CH₃CH=CH₂ + KBr + H₂O.","2-bromopropane → propene.","Conditions: alcoholic KOH (in ethanol), hot, concentrated.","OH⁻ acts as a BASE in this reaction (removes H⁺), not as a nucleophile."]},{"type":"h","text":"Substitution vs elimination — same reagent, different conditions"},{"type":"ul","items":["AQUEOUS NaOH, warm → SUBSTITUTION → alcohol (OH⁻ acts as nucleophile).","ALCOHOLIC NaOH, hot, concentrated → ELIMINATION → alkene (OH⁻ acts as base).","The same reagent (OH⁻) gives different products depending on the solvent and conditions.","In aqueous solution, OH⁻ is highly solvated → less nucleophilic and behaves more as a base."]},{"type":"h","text":"The mechanism (E2)"},{"type":"ul","items":["OH⁻ removes a proton (H⁺) from a carbon ADJACENT to the C–Br carbon.","Simultaneously, the C–Br bond breaks, with both electrons going to Br⁻.","The two electrons released by the C–H bond form the new C=C double bond.","This is a single-step concerted mechanism (similar concept to SN2)."]},{"type":"h","text":"When more than one alkene is possible"},{"type":"p","text":"For 2-bromobutane, elimination can produce either but-1-ene (CH₂=CHCH₂CH₃) or but-2-ene (CH₃CH=CHCH₃). The more substituted alkene (but-2-ene) is generally the major product (Saytzeff's rule), because it is more thermodynamically stable."},{"type":"takeaway","items":["Hot conc. alcoholic KOH → ELIMINATION → alkene.","Aqueous KOH → SUBSTITUTION → alcohol.","OH⁻ as BASE (elim) vs NUCLEOPHILE (sub).","Saytzeff: more substituted alkene is the major product."]}]},{"id":"hd8","title":"Halogenoalkanes vs Chlorobenzene","blocks":[{"type":"p","text":"Chloroalkanes (e.g. chloroethane) hydrolyse readily. Chlorobenzene (where Cl is attached to a benzene ring) does NOT hydrolyse under normal conditions. This is one of the most asked exam comparisons."},{"type":"d","caption":"Why chlorobenzene resists hydrolysis"},{"type":"h","text":"Reactivity comparison"},{"type":"ul","items":["CH₃CH₂Cl + NaOH(aq) → CH₃CH₂OH + NaCl (works under reflux).","C₆H₅Cl + NaOH(aq) → NO REACTION under normal conditions.","Chlorobenzene only hydrolyses under EXTREME conditions: 300 °C and 200 atm with concentrated NaOH."]},{"type":"h","text":"Why is chlorobenzene unreactive?"},{"type":"ul","items":["In chlorobenzene, the Cl atom's lone pair OVERLAPS with the π electron system of the benzene ring.","This creates partial double-bond character in the C–Cl bond — the bond is shorter and stronger than in chloroalkanes.","The C–Cl bond energy in chlorobenzene (~399 kJ mol⁻¹) is significantly higher than in chloroethane (~338 kJ mol⁻¹).","The delocalisation of the chlorine lone pair into the ring makes it harder to displace Cl⁻.","Additionally, the benzene ring is electron-rich (π electrons) — it REPELS nucleophiles, making attack at the C–Cl carbon difficult."]},{"type":"callout","title":"The resonance argument","body":"Draw the lone pair on Cl overlapping with the ring π system. The C–Cl bond gains partial double-bond character. This stabilisation is lost if Cl is displaced, so the activation energy for substitution is much higher than in chloroalkanes. State this clearly in exams."},{"type":"takeaway","items":["Chlorobenzene does NOT hydrolyse under normal conditions.","Cl lone pair overlaps with benzene π → partial double-bond character.","C–Cl bond is stronger and shorter → harder to break.","Electron-rich ring also repels nucleophiles."]}]},{"id":"hd9","title":"Fluoroalkanes & CFCs","blocks":[{"type":"p","text":"Fluoroalkanes (and chlorofluorocarbons, CFCs) have unique properties due to the very strong, very inert C–F bond. This makes them useful for many applications, but also caused a major environmental crisis."},{"type":"h","text":"Why fluoroalkanes are unreactive"},{"type":"ul","items":["C–F bond energy: 484 kJ mol⁻¹ (compared to C–H = 412, C–Cl = 338).","C–F is the strongest single bond in organic chemistry.","F is the most electronegative element → bond is highly polar but also extremely strong.","Hydrolysis, oxidation and most other reactions are impractically slow at normal temperatures.","Examples of inertness: PTFE (Teflon, (CF₂CF₂)ₙ) is used as a non-stick coating because nothing sticks to it or reacts with it."]},{"type":"h","text":"Uses of fluoroalkanes and CFCs"},{"type":"ul","items":["Refrigerants (CFCs like CFCl₃, CF₂Cl₂): low boiling points, non-flammable, non-toxic to humans.","Aerosol propellants: easily liquefiable, chemically inert.","Fire extinguishers (e.g. halons like CF₃Br).","Solvents and degreasing agents.","PTFE (Teflon): non-stick cookware, gaskets, lab tubing.","HFCs (no Cl, e.g. CH₂F-CF₃): modern refrigerant replacements for CFCs."]},{"type":"d","caption":"CFCs catalytically destroy ozone"},{"type":"h","text":"CFCs and ozone depletion"},{"type":"ul","items":["CFCs are so stable they reach the stratosphere over decades without breaking down.","High-energy UV radiation in the stratosphere breaks the relatively weaker C–Cl bond (homolytic fission): CFCl₃ → •CFCl₂ + Cl•.","The chlorine radical destroys ozone in a catalytic cycle: Cl• + O₃ → ClO• + O₂; ClO• + O₃ → Cl• + 2O₂.","One Cl• can destroy thousands of O₃ molecules before being removed.","Ozone depletion → \\"ozone hole\\" over Antarctica → more UV reaches Earth's surface → increased skin cancer, cataracts, ecosystem damage."]},{"type":"h","text":"The Montreal Protocol (1987)"},{"type":"p","text":"International agreement to phase out CFCs. Replacements include HFCs (hydrofluorocarbons — no chlorine, so no ozone damage) and HCFCs (hydrochlorofluorocarbons — less stable, mostly destroyed before reaching stratosphere). The ozone layer is now slowly recovering."},{"type":"takeaway","items":["Fluoroalkanes: very inert (strong C–F bond) → useful in refrigerants, PTFE, propellants.","CFCs destroy ozone via Cl• catalytic cycle (1 Cl• → 1000s of O₃ destroyed).","Montreal Protocol replaced CFCs with HFCs (no Cl)."]}]},{"id":"hd10","title":"Synthesis Pathways via Halogenoalkanes","blocks":[{"type":"p","text":"Halogenoalkanes are central to organic synthesis because they can be converted into so many functional groups. Here is a summary \\"synthesis map\\"."},{"type":"h","text":"From halogenoalkane (R-X) you can make:"},{"type":"ul","items":["Alcohol: R-X + NaOH(aq), reflux → R-OH.","Alkene: R-X + KOH(alc, hot, conc) → alkene + HX.","Nitrile: R-X + KCN(alc), reflux → R-CN. Adds one carbon.","Primary amine: R-X + excess NH₃(alc, sealed) → R-NH₂.","Ether: R-X + R'O⁻Na⁺ → R-O-R' (Williamson synthesis — beyond syllabus but useful).","Grignard reagent: R-X + Mg(dry ether) → R-MgX. Used in C-C bond formation (advanced)."]},{"type":"h","text":"Going further from these intermediates"},{"type":"ul","items":["Nitrile (R-CN) can be HYDROLYSED to a carboxylic acid: R-CN + 2H₂O + HCl → R-COOH + NH₄Cl. This is the standard way to make a carboxylic acid with one more carbon than the starting material.","Nitrile (R-CN) can be REDUCED with H₂/Ni or LiAlH₄ to give a primary amine: R-CN → R-CH₂NH₂.","Alcohol can be oxidised to aldehyde or carboxylic acid (1°), or ketone (2°).","Alkene undergoes addition reactions (covered in hydrocarbons)."]},{"type":"callout","title":"Building longer chains","body":"The KCN reaction is a key chain-extending step. R-X (n carbons) + CN⁻ → R-CN (n+1 carbons) → hydrolysis to R-COOH (n+1 carbons), or reduction to R-CH₂NH₂ (n+1 carbons). This is the only common way at A-level to make a chain longer."},{"type":"takeaway","items":["R-X is a synthetic hub: → alcohols, alkenes, nitriles, amines.","KCN extends chain by 1: R-X → R-CN → R-COOH or R-CH₂NH₂.","Conditions select between substitution (alcohol) and elimination (alkene)."]}]},{"id":"hd11","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Halogenoalkane questions test mechanism, conditions, and product prediction. Here are the patterns."},{"type":"h","text":"Mechanism questions"},{"type":"ul","items":["When asked to \\"show the mechanism\\", use CURLY ARROWS correctly. Each arrow shows the movement of an electron PAIR, from where it is to where it goes.","Show lone pairs on the nucleophile (e.g. on OH⁻ or NH₃) before they attack.","Show partial charges (δ+ on C, δ− on X) on the C–X bond.","For SN2: ONE concerted arrow (from Nu to C, simultaneously another from C–X bond to X).","For SN1: TWO steps. Step 1: arrow from C–X bond to X (leaving). Step 2: arrow from Nu lone pair to C+."]},{"type":"h","text":"Conditions matter — read the question"},{"type":"ul","items":["Aqueous NaOH/KOH → SUBSTITUTION → alcohol.","Alcoholic NaOH/KOH (hot, conc) → ELIMINATION → alkene.","Alcoholic KCN → SUBSTITUTION → nitrile (chain +1).","NH₃ in ethanol, sealed tube → SUBSTITUTION → primary amine.","Stating the wrong conditions costs marks even if the equation is correct."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Forgetting that NH₃ must be in EXCESS (otherwise multiple substitutions occur).","Saying CN⁻ \\"attacks the H\\" (wrong — it attacks the C).","Using \\"nucleophile\\" and \\"base\\" interchangeably. OH⁻ can be both, but in different contexts.","Drawing chlorobenzene undergoing hydrolysis (it doesn't under normal conditions).","Confusing Walden inversion (SN2) with racemisation (SN1).","Not stating that KCN is in ALCOHOLIC solution (water would compete via hydrolysis)."]},{"type":"callout","title":"The classification → mechanism rule","body":"Primary halogenoalkane → SN2 (no steric issue, no carbocation stability). Tertiary → SN1 (carbocation stabilised, but too crowded for SN2). Secondary → can go either way depending on conditions. State this in exam answers."},{"type":"takeaway","items":["Aqueous → substitution; alcoholic + hot + conc → elimination.","1° → SN2; 3° → SN1; 2° → either.","Use curly arrows correctly; show lone pairs and partial charges.","NH₃ must be in excess for clean primary amine."]}]}]}`),hydroxy:JSON.parse(`{"objectives":["Name and classify alcohols (1°, 2°, 3°) using IUPAC nomenclature","Describe isomerism in alcohols including chain, position, functional group and optical isomerism","Describe the manufacture of ethanol by fermentation and by hydration of ethene","Explain the physical properties of alcohols (high b.p., water solubility) in terms of hydrogen bonding","Describe the reactions of alcohols: combustion, sodium, halogenation (PCl₅, SOCl₂, HBr, red P + I₂)","Describe the oxidation of primary, secondary and tertiary alcohols by acidified K₂Cr₂O₇","Describe dehydration to alkenes and esterification with carboxylic acids","Describe the iodoform test and identify which compounds give a positive result","Describe the reactions of phenol with Na, NaOH, Br₂(aq) and HNO₃","Compare the acidities of water, phenol and ethanol using conjugate base stability arguments"],"chapters":[{"id":"hy1","title":"Naming & Classifying Alcohols","blocks":[{"type":"p","text":"Hydroxy compounds contain the –OH (hydroxyl) functional group. The two main types are ALCOHOLS, where –OH is attached to a saturated (sp³) carbon, and PHENOLS, where –OH is attached directly to a benzene ring. Their chemistry is very different — phenols are acidic, alcohols are not."},{"type":"h","text":"Naming alcohols (IUPAC)"},{"type":"ul","items":["Find the longest carbon chain containing the –OH group.","Number from the end nearest the –OH to give it the lowest locant.","Replace the final \\"-e\\" of the alkane with \\"-ol\\", with the locant for –OH in front.","Examples: CH₃OH = methanol; CH₃CH₂OH = ethanol; (CH₃)₂CHOH = propan-2-ol; CH₂(OH)CH(OH)CH₂(OH) = propane-1,2,3-triol (glycerol).","Branched: HOCH₂CH(CH₃)CH₃ = 2-methylpropan-1-ol."]},{"type":"h","text":"Classifying alcohols"},{"type":"d","caption":"Primary, secondary and tertiary alcohols"},{"type":"ul","items":["PRIMARY (1°): C bearing –OH bonded to ONE other carbon. R–CH₂–OH. Example: ethanol.","SECONDARY (2°): C bearing –OH bonded to TWO other carbons. R₂CH–OH. Example: propan-2-ol.","TERTIARY (3°): C bearing –OH bonded to THREE other carbons. R₃C–OH. Example: 2-methylpropan-2-ol.","Methanol (CH₃OH) has 0 other carbons; reactions usually grouped with primary alcohols."]},{"type":"callout","title":"Why classification matters","body":"The class of alcohol determines its OXIDATION behaviour: 1° → aldehyde → carboxylic acid; 2° → ketone (no further); 3° → no oxidation. One of the most heavily examined topics in organic chemistry."},{"type":"takeaway","items":["Alcohols: –OH on sp³ C. Phenols: –OH on aromatic ring.","Classify by number of C–C bonds at the C–OH carbon.","1° → aldehyde/acid; 2° → ketone; 3° → no oxidation."]}]},{"id":"hy2","title":"Isomerism in Alcohols","blocks":[{"type":"p","text":"Alcohols can show several types of isomerism: chain, position, functional group, and optical isomerism."},{"type":"h","text":"Chain isomerism"},{"type":"p","text":"Same molecular formula, different carbon skeletons. C₄H₉OH has chain isomers butan-1-ol (CH₃CH₂CH₂CH₂OH, straight) and 2-methylpropan-1-ol (HOCH₂CH(CH₃)CH₃, branched)."},{"type":"h","text":"Position isomerism"},{"type":"p","text":"Same chain, –OH in different positions. C₃H₇OH gives propan-1-ol (CH₃CH₂CH₂OH, primary) and propan-2-ol ((CH₃)₂CHOH, secondary). They have very different reactivities."},{"type":"h","text":"Functional group isomerism"},{"type":"p","text":"Same molecular formula, different functional groups. Alcohols (R–OH) are isomeric with ETHERS (R–O–R'). C₂H₆O is either ethanol (b.p. 78 °C, H-bonding) or methoxymethane (CH₃OCH₃, b.p. −24 °C, no H-bonding)."},{"type":"h","text":"Optical isomerism"},{"type":"ul","items":["Occurs when the C bearing –OH has 4 DIFFERENT groups attached.","Example: butan-2-ol (CH₃CH(OH)CH₂CH₃) — middle C has H, OH, CH₃, C₂H₅ — chiral.","Two enantiomers: (R)-butan-2-ol and (S)-butan-2-ol; rotate plane-polarised light oppositely.","A 1:1 racemic mixture is optically inactive."]},{"type":"callout","title":"Spotting chirality","body":"Look at the C bearing –OH. Count the groups — if all four are DIFFERENT, the molecule is chiral. If any two are the same, it is not chiral."},{"type":"takeaway","items":["Chain, position, functional group, optical — all possible.","Alcohols are functional group isomers of ethers.","Chirality: 4 different groups on the C–OH carbon."]}]},{"id":"hy3","title":"Manufacture of Ethanol","blocks":[{"type":"p","text":"Ethanol is the most industrially important alcohol. Two main routes: FERMENTATION (biological) and HYDRATION OF ETHENE (petrochemical)."},{"type":"h","text":"Method 1: Fermentation"},{"type":"ul","items":["Sugars (glucose) from grains, fruits, sugar cane, baobab, marula are broken down by yeast (anaerobic).","Equation: C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂.","Conditions: 25–37 °C, anaerobic (no O₂ — otherwise ethanol oxidises to ethanoic acid), pH ≈ 3–5.","Yeast (Saccharomyces cerevisiae) provides the enzyme zymase as biological catalyst.","Reaction stops at ~13–15% ethanol — yeast killed by alcohol.","Concentration increased by FRACTIONAL DISTILLATION (max ~96% — azeotrope with water)."]},{"type":"h","text":"Method 2: Hydration of ethene"},{"type":"ul","items":["Ethene (from cracking petroleum) reacts with steam over phosphoric acid catalyst.","Equation: CH₂=CH₂ + H₂O → CH₃CH₂OH.","Conditions: 300 °C, 60 atm, H₃PO₄ catalyst on solid silica support.","Reversible — only ~5% conversion per pass; unreacted ethene recycled.","Produces very pure ethanol (no fermentation by-products)."]},{"type":"h","text":"Comparing the two methods"},{"type":"ul","items":["Fermentation: RENEWABLE (biomass). Slow batch process. Lower purity. Suited to biomass-rich countries (Zimbabwe, Brazil).","Hydration: NON-RENEWABLE (petroleum). Fast continuous. Very pure. Suited to industrialised oil-rich economies.","Drinking alcohol: only fermentation allowed.","Industrial ethanol (solvent, fuel additive): both methods used."]},{"type":"takeaway","items":["Fermentation: glucose → ethanol + CO₂ (yeast, 25–37 °C, anaerobic).","Hydration: ethene + H₂O → ethanol (H₃PO₄, 300 °C, 60 atm).","Fermentation = renewable but slow; hydration = fast but uses oil."]}]},{"id":"hy4","title":"Physical Properties: H-Bonding Effects","blocks":[{"type":"p","text":"Alcohols have unusually high boiling points and high water solubility (for small alcohols) compared with hydrocarbons of similar molecular mass. Both effects are due to HYDROGEN BONDING between –OH groups."},{"type":"d","caption":"H-bonding raises b.p. and gives water solubility"},{"type":"h","text":"Boiling points"},{"type":"ul","items":["Ethane (Mr = 30): b.p. −89 °C — only weak London forces between CH₃CH₃.","Methanol (Mr = 32): b.p. +65 °C — extensive H-bonding raises b.p. by over 150 °C vs ethane.","Ethanol (Mr = 46): b.p. +78 °C — H-bonding plus longer chain (more London).","B.p. increases as alkyl chain lengthens (greater London forces add to H-bonding)."]},{"type":"h","text":"Water solubility"},{"type":"ul","items":["Small alcohols (methanol, ethanol, propan-1-ol, propan-2-ol) MISCIBLE with water in all proportions — H-bond with water molecules.","As alkyl chain lengthens, solubility DECREASES — long hydrocarbon tail disrupts water structure.","Hexan-1-ol: only slightly soluble. Octan-1-ol: essentially insoluble.","Polyols (multiple OHs) like glycerol very soluble due to multiple H-bonds."]},{"type":"callout","title":"Two H-bonds per OH","body":"Each –OH can act as both H-bond DONOR (the O–H...O bond) and H-bond ACCEPTOR (a lone pair on O accepting another H). This is why alcohols form extensive 3D H-bonding networks similar to water."},{"type":"takeaway","items":["Alcohols have high b.p. due to H-bonding.","Small alcohols miscible with water (H-bond with water).","Solubility decreases as alkyl chain lengthens."]}]},{"id":"hy5","title":"Combustion, Halogenation & Sodium","blocks":[{"type":"p","text":"Simple reactions of alcohols include combustion (burning in air) and reactions involving the O–H bond (with sodium) or replacement of –OH (halogenation)."},{"type":"h","text":"Combustion"},{"type":"ul","items":["Alcohols burn cleanly in excess air to give CO₂ and H₂O.","Equation for ethanol: C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O.","Highly exothermic — ethanol used as fuel additive (gasohol) and biofuel.","Cleaner burning than petrol (no sulphur, less particulate matter)."]},{"type":"h","text":"Reaction with sodium"},{"type":"ul","items":["Alcohols react with Na to release H₂ — similar to (but slower than) water with Na.","Equation: 2CH₃CH₂OH + 2Na → 2CH₃CH₂O⁻Na⁺ + H₂.","Product CH₃CH₂O⁻Na⁺ = sodium ethoxide — strong base, soluble in ethanol.","Observation: gentle effervescence (slower than water). Na dissolves but does not melt.","Shows alcohols have weakly acidic O–H bonds — but FAR less acidic than water (does not turn litmus red)."]},{"type":"h","text":"Halogenation: replacing OH with X"},{"type":"ul","items":["OH can be replaced by Cl, Br or I to give a halogenoalkane.","With HCl + ZnCl₂ catalyst (Lucas reagent): 1° slow, 3° fast — used as a test.","With PCl₃ or PCl₅: ROH + PCl₅ → RCl + HCl + POCl₃. Convenient lab method.","With SOCl₂ (thionyl chloride): cleanest — by-products are gases (HCl + SO₂).","With HBr (in situ from KBr + H₂SO₄): R-OH + HBr → R-Br + H₂O.","With red P + I₂: produces PI₃ in situ which converts ROH to R-I."]},{"type":"callout","title":"Identifying alcohols","body":"Add Na metal — effervescence (H₂) confirms an OH group (could be alcohol, water, phenol or carboxylic acid; distinguish further). Always dry the alcohol first to avoid Na reacting with water."},{"type":"takeaway","items":["Combustion: CₙH₂ₙ₊₁OH + O₂ → CO₂ + H₂O.","2ROH + 2Na → 2RO⁻Na⁺ + H₂ (sodium alkoxide).","OH → X using PCl₅, SOCl₂, HBr, or red P + I₂."]}]},{"id":"hy6","title":"Oxidation of Alcohols","blocks":[{"type":"p","text":"Oxidation of alcohols is one of the most important reactions in organic chemistry. Behaviour depends on class — primary, secondary or tertiary. Standard oxidising agent: acidified potassium dichromate(VI), K₂Cr₂O₇/H₂SO₄, ORANGE turning GREEN (Cr³⁺) when reduced."},{"type":"d","caption":"Oxidation pathways for primary, secondary and tertiary alcohols"},{"type":"h","text":"Primary alcohols"},{"type":"ul","items":["Step 1: 1° R-CH₂-OH → R-CHO (aldehyde). To stop here, DISTIL the aldehyde out as it forms (lower b.p. than alcohols).","Step 2: With excess oxidising agent and continued heating (REFLUX), aldehyde → R-COOH (carboxylic acid).","Equations: CH₃CH₂OH + [O] → CH₃CHO + H₂O; CH₃CHO + [O] → CH₃COOH.","Colour change: orange Cr₂O₇²⁻ → green Cr³⁺."]},{"type":"h","text":"Secondary alcohols"},{"type":"ul","items":["2° R₂CH-OH → R₂C=O (ketone). Single oxidation only — ketones not further oxidised under these conditions.","Example: (CH₃)₂CHOH + [O] → (CH₃)₂C=O + H₂O. Propan-2-ol → propanone.","Conditions: reflux with acidified K₂Cr₂O₇.","Colour change: orange → green."]},{"type":"h","text":"Tertiary alcohols"},{"type":"ul","items":["3° R₃C-OH → NO REACTION (no H atom on the C bearing –OH).","No colour change — orange stays orange.","Key DIAGNOSTIC test to distinguish 3° from 1°/2°."]},{"type":"h","text":"Distinguishing alcohols experimentally"},{"type":"ul","items":["Add acidified K₂Cr₂O₇ and warm. If colour stays orange → tertiary.","If green → either 1° or 2°. To distinguish: add Tollens' or Fehling's to the product. Positive (silver mirror or red ppt) → original was primary (gave aldehyde).","Alternatively: mild distillation to collect volatile aldehyde (1°) or just observe ketone (2°)."]},{"type":"callout","title":"Why tertiary cannot oxidise","body":"Oxidation of an alcohol involves breaking BOTH the O-H bond AND the C-H bond on the C bearing the OH. In 3° alcohols, that carbon has no H atom (it is bonded to three carbons + OH). So oxidation cannot proceed without breaking C-C bonds, which requires far harsher conditions."},{"type":"takeaway","items":["1° → aldehyde (distil) → carboxylic acid (reflux).","2° → ketone (reflux); not further oxidised.","3° → no reaction (no H on C-OH).","Orange Cr₂O₇²⁻ → green Cr³⁺ when oxidation occurs."]}]},{"id":"hy7","title":"Dehydration & Esterification","blocks":[{"type":"p","text":"Two more important reactions: DEHYDRATION (loss of water → alkene) and ESTERIFICATION (with carboxylic acid → ester)."},{"type":"h","text":"Dehydration"},{"type":"d","caption":"Dehydration of alcohols to alkenes"},{"type":"ul","items":["Conditions: concentrated sulphuric acid at 170 °C, OR aluminium oxide (Al₂O₃) at 350 °C.","Mechanism: protonation of OH → loss of water gives carbocation → loss of H⁺ from adjacent C → alkene.","Example: CH₃CH₂OH → CH₂=CH₂ + H₂O (ethanol → ethene).","Ease of dehydration: 3° > 2° > 1° (carbocation stability — 3° most stable).","Saytzeff's rule: when more than one alkene is possible, the more substituted alkene is the major product."]},{"type":"h","text":"Esterification"},{"type":"d","caption":"Alcohol + carboxylic acid → ester (reversible)"},{"type":"ul","items":["Reaction: R-OH + R'-COOH ⇌ R'-COO-R + H₂O.","Conditions: concentrated H₂SO₄ catalyst, REFLUX.","Reversible (equilibrium): use excess of one reactant or remove water to drive equilibrium right.","Example: ethanol + ethanoic acid → ethyl ethanoate + water.","Esters: FRUITY, SWEET smells — flavourings (banana, pineapple, pear) and perfumes."]},{"type":"h","text":"Reactions with acyl chlorides (faster esterification)"},{"type":"p","text":"Acyl chlorides (R-COCl) react with alcohols MUCH faster than acids, irreversibly: R-OH + R'-COCl → R'-COO-R + HCl. Useful when ester yield needs to be high. (Detail in Carboxylic Acids topic.)"},{"type":"takeaway","items":["Dehydration: alcohol → alkene + H₂O (conc. H₂SO₄, 170 °C).","Esterification: alcohol + acid ⇌ ester + H₂O (conc. H₂SO₄, reflux). Reversible.","Acyl chlorides give faster, irreversible esterification."]}]},{"id":"hy8","title":"The Iodoform Test","blocks":[{"type":"p","text":"The iodoform test (triiodomethane test) identifies a particular structural feature: the CH₃-CH(OH)- group (or CH₃-C(=O)- group). Positive test = yellow precipitate of triiodomethane (CHI₃, \\"iodoform\\")."},{"type":"h","text":"The reagent and conditions"},{"type":"ul","items":["Reagent: ALKALINE iodine — I₂ in NaOH(aq), or KI₃ in NaOH(aq).","Conditions: warm gently. Mixture starts brown (I₂) and turns paler as iodine is consumed.","Positive: yellow precipitate of CHI₃ appears.","Smell: distinctive antiseptic."]},{"type":"h","text":"Which compounds give a positive test?"},{"type":"ul","items":["Methyl secondary alcohols — contain CH₃-CH(OH)-. Examples: ethanol (CH₃CH₂OH), propan-2-ol (CH₃CH(OH)CH₃), butan-2-ol (CH₃CH(OH)CH₂CH₃).","Methyl ketones — contain CH₃-C(=O)-. Examples: propanone (CH₃COCH₃), butanone (CH₃COCH₂CH₃). And ethanal (CH₃CHO).","NEGATIVE: methanol (no CH₃-CH(OH)-), propan-1-ol, most other ketones, phenol."]},{"type":"h","text":"Mechanism (overview)"},{"type":"ul","items":["Step 1: alkaline iodine OXIDISES the secondary alcohol to a methyl ketone.","Step 2: three H atoms of the CH₃ group sequentially replaced by I → CI₃.","Step 3: alkaline hydrolysis cleaves C-C bond between CI₃ and C=O → CHI₃ (yellow ppt).","Overall: CH₃CH(OH)R + 4I₂ + 6NaOH → CHI₃ + RCOO⁻Na⁺ + 5NaI + 5H₂O."]},{"type":"callout","title":"Diagnostic value","body":"The iodoform test specifically detects CH₃-CH(OH)- and CH₃-C=O substructures. One of the few simple chemical tests that identifies a specific structural feature beyond just a functional group. Frequent exam: \\"Will compound X give a positive iodoform test?\\""},{"type":"takeaway","items":["Reagent: I₂ + NaOH(aq), warm.","Yellow ppt of CHI₃ = positive.","Detects CH₃-CH(OH)- (methyl 2° alcohol) or CH₃-C=O (methyl ketone).","Also positive for ethanol and ethanal."]}]},{"id":"hy9","title":"Phenol: Reactions & Uses","blocks":[{"type":"p","text":"Phenol (C₆H₅OH) is structurally similar to alcohols but its chemistry is very different — acidic, and its benzene ring is highly activated towards electrophilic substitution."},{"type":"d","caption":"Key reactions of phenol"},{"type":"h","text":"Reactions involving the OH group"},{"type":"ul","items":["With sodium: 2C₆H₅OH + 2Na → 2C₆H₅O⁻Na⁺ + H₂. Sodium phenoxide formed. Like alcohols — H₂ evolves.","With NaOH(aq): C₆H₅OH + NaOH → C₆H₅O⁻Na⁺ + H₂O. Phenol IS acidic enough to react with bases. ALCOHOLS DO NOT REACT WITH NaOH. Key distinguishing test.","With Na₂CO₃: NO reaction. Phenol is too weak to react with carbonate. Carboxylic acids DO react with Na₂CO₃ — distinguishes phenol from carboxylic acids."]},{"type":"h","text":"Reactions on the ring (electrophilic substitution)"},{"type":"ul","items":["With Br₂(aq): 3 H atoms on the ring replaced. C₆H₅OH + 3Br₂ → C₆H₂Br₃OH + 3HBr. Yields 2,4,6-tribromophenol — WHITE PRECIPITATE. NO catalyst needed (unlike benzene which needs FeBr₃). Bromine water decolourised.","With dilute HNO₃: 2-nitrophenol and 4-nitrophenol. Much faster than nitration of benzene (no need for conc. acids).","These reactions MUCH FASTER than for benzene because OH ACTIVATES the ring (donates electron density via O lone pair)."]},{"type":"h","text":"Why is phenol so reactive on the ring?"},{"type":"p","text":"The lone pair on the oxygen of –OH overlaps with the π electron system of the benzene ring. This donates electron density into the ring, making it more nucleophilic and so more reactive towards electrophiles. The ortho and para positions become especially electron-rich, which is why substitution occurs at the 2, 4 and 6 positions."},{"type":"h","text":"Uses of phenol"},{"type":"ul","items":["Disinfectants and antiseptics: original \\"carbolic acid\\" used by Joseph Lister.","Manufacture of plastics: phenol-formaldehyde resins (Bakelite), epoxy resins.","Pharmaceuticals: aspirin synthesis (phenol → salicylic acid → aspirin).","Explosives: 2,4,6-trinitrophenol (picric acid)."]},{"type":"takeaway","items":["Phenol + Na: H₂ evolved (like alcohol).","Phenol + NaOH: phenoxide forms (alcohols don't).","Phenol + Br₂(aq): white ppt of 2,4,6-tribromophenol, NO catalyst needed.","OH activates ring → much faster electrophilic substitution than benzene."]}]},{"id":"hy10","title":"Acidity: Water vs Phenol vs Ethanol","blocks":[{"type":"p","text":"Comparing acidity of these three OH-containing molecules is one of the most asked exam questions. Key: compare the STABILITY of conjugate bases."},{"type":"d","caption":"Acidity ranking by pKa"},{"type":"h","text":"The data"},{"type":"ul","items":["Ethanol (CH₃CH₂OH): pKa ≈ 16. Very weak acid.","Water (H₂O): pKa ≈ 14.","Phenol (C₆H₅OH): pKa ≈ 10. Weak acid (about 1 million times stronger than ethanol).","Lower pKa = stronger acid. Order: phenol > water > ethanol."]},{"type":"h","text":"Why phenol is more acidic than water"},{"type":"d","caption":"Phenoxide ion stabilised by delocalisation"},{"type":"ul","items":["When phenol loses H⁺, the phenoxide ion (C₆H₅O⁻) forms.","The negative charge on oxygen can be DELOCALISED into the benzene ring through overlap of the O lone pair with the π system.","Negative charge spreads over O AND ortho/para positions of the ring → much more stable than localised charge.","More stable conjugate base → equilibrium of dissociation lies further right → more acidic."]},{"type":"h","text":"Why ethanol is less acidic than water"},{"type":"ul","items":["In ethoxide (CH₃CH₂O⁻), negative charge localised on O.","CH₃CH₂ group is ELECTRON-DONATING (positive inductive effect, +I).","Alkyl group pushes electron density TOWARDS the negative O → makes negative charge LESS stable.","Less stable conjugate base → less acidic alcohol → ethanol does NOT release H⁺ as readily as water."]},{"type":"h","text":"Distinguishing test"},{"type":"ul","items":["Phenol reacts with NaOH(aq) → soluble (forms phenoxide).","Ethanol does NOT react with NaOH(aq) at all.","Both react with Na metal (release H₂) — more vigorously for phenol.","Phenol does NOT react with Na₂CO₃ (carboxylic acids do — they are stronger acids)."]},{"type":"callout","title":"The exam template","body":"For acidity comparisons, ALWAYS argue from CONJUGATE BASE stability. (1) Phenoxide stabilised by delocalisation into the ring. (2) Ethoxide destabilised by electron-donating ethyl group. Hydroxide (from water) sits in between. State this clearly."},{"type":"takeaway","items":["Acidity: phenol > water > ethanol (pKa: 10 > 14 > 16).","Phenol acidic because phenoxide stabilised by delocalisation.","Ethanol weak because ethoxide destabilised by alkyl +I effect.","NaOH test: phenol dissolves; ethanol does not."]}]},{"id":"hy11","title":"Synthesis Pathways with Alcohols","blocks":[{"type":"p","text":"Alcohols are central to organic synthesis — many functional groups can be made from them, and they can be made from many other compounds."},{"type":"h","text":"Making alcohols"},{"type":"ul","items":["From halogenoalkane: R-X + NaOH(aq), reflux → R-OH (nucleophilic substitution).","From alkene: hydration with H₂O/H₂SO₄ or H₂O/H₃PO₄ catalyst → alcohol (Markovnikov).","From aldehyde: reduction with NaBH₄ or LiAlH₄ → 1° alcohol.","From ketone: reduction with NaBH₄ → 2° alcohol.","From ester: hydrolysis with H₂O/H⁺ or NaOH → alcohol + carboxylic acid.","From sugars: fermentation → ethanol."]},{"type":"h","text":"From an alcohol you can make:"},{"type":"ul","items":["Halogenoalkane: PCl₅, SOCl₂, HBr, or red P + I₂.","Aldehyde (1°): K₂Cr₂O₇/H₂SO₄, distil out.","Carboxylic acid (1°): K₂Cr₂O₇/H₂SO₄, reflux.","Ketone (2°): K₂Cr₂O₇/H₂SO₄, reflux.","Alkene: dehydration with conc. H₂SO₄ at 170 °C.","Ester: with carboxylic acid + conc. H₂SO₄, reflux.","Alkoxide: with Na metal."]},{"type":"callout","title":"Multi-step synthesis","body":"Many exam questions involve linking alcohols with other functional groups in 2 or 3 steps. Common: halogenoalkane → alcohol → aldehyde → carboxylic acid. Or: alkene → alcohol → ester. Practice forward (synthesis) and backward (retrosynthesis)."},{"type":"takeaway","items":["Alcohols are the central hub of organic synthesis.","From: halogenoalkanes, alkenes, carbonyls, esters, sugars.","To: halogenoalkanes, aldehydes, ketones, acids, alkenes, esters."]}]},{"id":"hy12","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Hydroxy compound questions test classification, oxidation, mechanism and acidity. Here are the patterns."},{"type":"h","text":"Classification questions"},{"type":"ul","items":["Always count the carbons attached to the C–OH carbon. 0–1 = primary; 2 = secondary; 3 = tertiary.","Watch out for branched structures — number from end nearest OH for IUPAC.","For oxidation predictions, state the class FIRST, then predict the products."]},{"type":"h","text":"Oxidation must-haves"},{"type":"ul","items":["State colour change: ORANGE → GREEN.","For 1° → aldehyde: state DISTILLATION (collect aldehyde as it forms).","For 1° → carboxylic acid: state REFLUX with EXCESS oxidising agent.","For 2° → ketone: REFLUX.","For 3°: state NO REACTION, NO COLOUR CHANGE."]},{"type":"h","text":"Acidity comparisons"},{"type":"ul","items":["Always argue from CONJUGATE BASE stability — never from \\"the alcohol's O-H bond is weaker\\".","Phenoxide: state \\"negative charge delocalised into ring\\" or \\"lone pair overlap with π system\\".","Ethoxide: state \\"alkyl group is electron-donating (+I effect)\\" → destabilises negative O.","Use Na, NaOH, Na₂CO₃ as a ladder: Na = OH/COOH; NaOH adds phenols; Na₂CO₃ = COOH only."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Saying ethanol reacts with NaOH — IT DOES NOT. Only Na metal.","Confusing iodoform scope: detects CH₃-CH(OH)- (and CH₃-C=O), so methanol does NOT give a positive test, but ethanol does.","Forgetting 3° alcohols are NOT oxidised — colour stays orange.","Wrong dehydration product when more than one alkene possible — Saytzeff: more substituted alkene major."]},{"type":"callout","title":"Distinguishing tests summary","body":"(1) Na: alcohol/phenol/COOH all release H₂. (2) NaOH: phenol and COOH dissolve; alcohol does not. (3) Na₂CO₃: COOH gives CO₂; phenol does not. (4) K₂Cr₂O₇: 1°/2° → green; 3° → no change. (5) Iodoform: detects CH₃CH(OH)- and CH₃C=O specifically."},{"type":"takeaway","items":["Argue acidity from conjugate base stability.","Three colour changes: orange → green (oxidation); brown → colourless (Br₂/phenol); yellow ppt (iodoform).","Distinguishing tests: Na, NaOH, Na₂CO₃, K₂Cr₂O₇, iodoform."]}]}]}`),carbonyl:JSON.parse(`{"objectives":["Name and draw aldehydes and ketones; describe isomerism (chain, position, functional group, optical)","Describe the preparation of aldehydes and ketones from primary and secondary alcohols","Outline the mechanism of nucleophilic addition with HCN to give cyanohydrins","Describe the reduction of carbonyl compounds with NaBH₄ to give alcohols","Describe how to distinguish aldehydes and ketones using Tollens', Fehling's, 2,4-DNPH and iodoform tests","Suggest a suitable test for a given carbonyl compound and predict the observations","Explain why aldehydes are oxidised by mild reagents but ketones are not","Use carbonyls in multi-step synthesis (HCN addition for chain extension; reduction; oxidation to acids)"],"chapters":[{"id":"cb1","title":"The Carbonyl Group: C=O","blocks":[{"type":"p","text":"Carbonyl compounds contain the C=O double bond. There are two main classes at A-level: ALDEHYDES (R-CHO, the C=O is at the end of a chain with at least one H attached) and KETONES (R-CO-R', the C=O is in the middle of a chain with two R groups attached). The C=O group is highly polar and is the centre of nearly all carbonyl chemistry."},{"type":"d","caption":"Aldehydes and ketones differ in what is attached to the C=O"},{"type":"h","text":"Why is C=O so reactive?"},{"type":"ul","items":["Oxygen is much more electronegative than carbon, so the C=O bond is highly POLAR — δ+ on C, δ− on O.","The δ+ carbon is a target for NUCLEOPHILES (electron-rich species like CN⁻, H⁻, NH₃).","The C=O π bond is a \\"locked\\" target — it can break easily on attack, providing a place for nucleophile addition.","Most carbonyl reactions are NUCLEOPHILIC ADDITION — a nucleophile adds across the C=O, breaking the π bond."]},{"type":"h","text":"Aldehyde vs ketone — what's the difference?"},{"type":"ul","items":["Aldehyde: at least one H attached directly to the carbonyl carbon. R-CHO. The H makes aldehydes EASIER TO OXIDISE (this distinguishes them from ketones).","Ketone: two R groups (carbon chains) attached to the carbonyl carbon, no H. R-CO-R'. Cannot be easily oxidised because there is no H on the carbonyl C to remove.","Both have the same C=O reactivity towards nucleophiles, but aldehydes are slightly more reactive because the smaller H lets the nucleophile approach more easily and the H is also less electron-donating than alkyl groups."]},{"type":"callout","title":"The defining test","body":"Aldehydes and ketones look similar — both contain C=O — and give the same response to 2,4-DNPH. To distinguish them, use a mild oxidising agent: Tollens' reagent (silver mirror) or Fehling's solution (red precipitate). Aldehydes oxidise; ketones do not. This is the most asked carbonyl distinction at A-level."},{"type":"takeaway","items":["Carbonyl group: C=O, highly polar (δ+ C, δ− O).","Aldehyde: R-CHO (H on C=O); ketone: R-CO-R' (no H).","Most reactions: nucleophilic addition across the C=O.","Aldehydes oxidise easily (Tollens'/Fehling's positive); ketones do not."]}]},{"id":"cb2","title":"Naming Aldehydes & Ketones","blocks":[{"type":"p","text":"IUPAC names of aldehydes end in \\"-al\\"; ketones end in \\"-one\\". The carbonyl carbon is included in the longest chain count."},{"type":"h","text":"Naming aldehydes"},{"type":"ul","items":["Find the longest chain that includes the C=O carbon (always at C1 — at the end).","Replace the \\"-e\\" of the parent alkane with \\"-al\\". The carbonyl is automatically position 1, no locant needed.","Examples: HCHO = methanal (formaldehyde); CH₃CHO = ethanal (acetaldehyde); CH₃CH₂CHO = propanal; CH₃CH(CH₃)CHO = 2-methylpropanal."]},{"type":"h","text":"Naming ketones"},{"type":"ul","items":["Find the longest chain including the C=O carbon. Number from the end giving the C=O the LOWEST locant.","Replace the \\"-e\\" of the alkane with \\"-one\\", with the position of C=O before it.","Examples: CH₃COCH₃ = propan-2-one (commonly: acetone); CH₃COCH₂CH₃ = butan-2-one; CH₃CH₂COCH₂CH₃ = pentan-3-one.","For ketones with more than 5 carbons, the locant matters because the C=O can be at different positions."]},{"type":"h","text":"Common names worth knowing"},{"type":"ul","items":["Methanal (HCHO) — also called formaldehyde. Used as preservative (formalin solution).","Ethanal (CH₃CHO) — also called acetaldehyde.","Propan-2-one (CH₃COCH₃) — also called acetone. Common solvent (nail polish remover).","Benzaldehyde (C₆H₅CHO) — almond smell, used in flavourings.","Phenylethanone (C₆H₅COCH₃) — also called acetophenone."]},{"type":"takeaway","items":["Aldehyde names end in \\"-al\\"; ketones end in \\"-one\\".","Aldehyde C=O is always at C1; ketone C=O needs a locant.","Common names you should recognise: formaldehyde, acetaldehyde, acetone, benzaldehyde."]}]},{"id":"cb3","title":"Isomerism","blocks":[{"type":"p","text":"Carbonyl compounds show several types of isomerism: chain, position, functional group (between aldehydes and ketones), and optical isomerism."},{"type":"h","text":"Functional group isomerism: aldehyde vs ketone"},{"type":"ul","items":["Aldehydes and ketones with the same molecular formula are functional group isomers.","C₃H₆O has two such isomers: propanal (CH₃CH₂CHO, aldehyde) and propanone (CH₃COCH₃, ketone).","They have similar chemistries (both react with 2,4-DNPH to give an orange precipitate) but DIFFERENT response to mild oxidisers (only the aldehyde reacts)."]},{"type":"h","text":"Position isomerism in ketones"},{"type":"p","text":"For larger ketones, the C=O can be at different positions. C₅H₁₀O has pentan-2-one (CH₃COCH₂CH₂CH₃) and pentan-3-one (CH₃CH₂COCH₂CH₃) as position isomers."},{"type":"h","text":"Chain isomerism"},{"type":"p","text":"Same molecular formula, different carbon skeleton. C₅H₁₀O ketones include pentan-2-one (straight chain) and 3-methylbutan-2-one (branched, CH₃COCH(CH₃)CH₃)."},{"type":"h","text":"Optical isomerism"},{"type":"ul","items":["Possible when a carbon other than the carbonyl C has 4 different groups attached.","Example: 2-methylbutanal — CH₃CH₂CH(CH₃)CHO — the C2 has H, CH₃, CH₂CH₃ and CHO attached → chiral.","The carbonyl carbon itself is sp² (planar) so cannot be a chiral centre."]},{"type":"callout","title":"Test for distinguishing aldehyde from ketone (functional group isomers)","body":"Use Tollens' reagent or Fehling's solution. A silver mirror (Tollens') or brick-red precipitate (Fehling's) confirms an aldehyde. No reaction means a ketone."},{"type":"takeaway","items":["Aldehydes and ketones are functional group isomers if same molecular formula.","Position and chain isomerism for larger ketones.","Optical isomerism if a chiral centre exists OUTSIDE the C=O.","Tollens'/Fehling's distinguishes aldehyde from ketone."]}]},{"id":"cb4","title":"Preparation: Oxidation of Alcohols","blocks":[{"type":"p","text":"The standard preparation of aldehydes and ketones is by oxidation of alcohols. Primary alcohols give aldehydes (which can be further oxidised to acids); secondary alcohols give ketones (no further oxidation)."},{"type":"d","caption":"Aldehydes from 1° alcohols; ketones from 2° alcohols"},{"type":"h","text":"Aldehyde from a primary alcohol"},{"type":"ul","items":["R-CH₂-OH + [O] → R-CHO + H₂O.","Reagents: acidified potassium dichromate(VI), K₂Cr₂O₇/H₂SO₄ (or sodium dichromate, Na₂Cr₂O₇).","Conditions: warm gently, DISTIL the aldehyde out as it forms.","Why distil? The aldehyde has a LOWER boiling point than the alcohol (no H-bonding in aldehydes — only weak dipole-dipole). It evaporates and condenses in the receiver before being further oxidised to a carboxylic acid.","Colour change: orange Cr₂O₇²⁻ → green Cr³⁺."]},{"type":"h","text":"Ketone from a secondary alcohol"},{"type":"ul","items":["R₂CH-OH + [O] → R₂C=O + H₂O.","Reagents: same — acidified K₂Cr₂O₇/H₂SO₄.","Conditions: REFLUX. No need to distil — ketones are not further oxidised by these mild oxidisers.","Colour change: orange → green."]},{"type":"h","text":"Why ketones don't oxidise further"},{"type":"p","text":"Further oxidation would require breaking a C-C bond (since the carbonyl C in a ketone has no H to remove). Mild oxidisers like K₂Cr₂O₇ cannot do this. Only very harsh conditions (concentrated KMnO₄, hot) can break C-C bonds, and that gives a mixture of products."},{"type":"h","text":"Other preparation methods"},{"type":"ul","items":["Aldehyde from acyl chloride + LiAlH(OtBu)₃ (very mild reducer that stops at aldehyde) — beyond the syllabus but useful to know.","Aldehyde from ozonolysis of alkene: R-CH=CH-R' + O₃ then Zn/H₂O → 2 R-CHO. Cleaves the C=C and gives two aldehydes.","Methyl ketones from hydration of terminal alkynes (Markovnikov, with Hg²⁺ catalyst)."]},{"type":"takeaway","items":["1° alcohol + K₂Cr₂O₇/H₂SO₄ → aldehyde (DISTIL).","2° alcohol + K₂Cr₂O₇/H₂SO₄ → ketone (REFLUX).","Orange → green colour change. Ketones don't oxidise further (no H on C=O)."]}]},{"id":"cb5","title":"Nucleophilic Addition: HCN Mechanism","blocks":[{"type":"p","text":"The most important reaction of carbonyl compounds is NUCLEOPHILIC ADDITION across the C=O double bond. The classic example uses HCN to give a 2-hydroxynitrile (cyanohydrin). This adds a carbon to the chain — useful for synthesis."},{"type":"d","caption":"Two-step nucleophilic addition mechanism"},{"type":"h","text":"The two steps"},{"type":"ul","items":["STEP 1: CN⁻ attacks the δ+ carbon of C=O. Two curly arrows: one from CN⁻ lone pair to C, one from C=O π bond to O. This breaks the π bond and forms a tetrahedral intermediate with O carrying a negative charge: R₂C(O⁻)(CN).","STEP 2: The negatively charged O picks up a proton to give the neutral product. R₂C(O⁻)(CN) + H⁺ → R₂C(OH)(CN). The H⁺ can come from undissociated HCN, from water, or from a small amount of dilute acid added."]},{"type":"h","text":"Reagents and conditions"},{"type":"ul","items":["In practice, gaseous HCN is too dangerous to handle, so KCN with a small amount of dilute H₂SO₄ is used. KCN provides the CN⁻ nucleophile; the small amount of acid keeps a low concentration of free HCN around to provide H⁺ for step 2.","Without any acid: pure KCN solution would not work because the equilibrium of step 1 lies far to the left (CN⁻ is the dominant species, but no H⁺ to complete step 2).","Without any base: pure HCN gives slow reaction because CN⁻ concentration is very low.","Typical conditions: KCN(aq) + dilute H₂SO₄, at ~10-20 °C, mixed with the carbonyl compound."]},{"type":"h","text":"Why is this useful?"},{"type":"ul","items":["The product (cyanohydrin / 2-hydroxynitrile) has TWO functional groups: -OH and -CN.","Adding HCN to a carbonyl gives a chain ONE CARBON longer than the starting material.","The nitrile (CN) can then be HYDROLYSED to a carboxylic acid (R₂C(OH)COOH = a 2-hydroxy carboxylic acid, like lactic acid).","Or the nitrile can be REDUCED to a primary amine (R₂C(OH)CH₂NH₂).","This is a key chain-extension method in synthesis."]},{"type":"callout","title":"Stereochemistry: a racemate forms","body":"When HCN adds to an unsymmetrical aldehyde or ketone (like ethanal CH₃CHO), the product is a chiral molecule. CN⁻ can attack from either face of the planar C=O equally, so a 50:50 RACEMIC MIXTURE of the two enantiomers is produced. This is a frequent exam point."},{"type":"takeaway","items":["Nucleophilic addition: CN⁻ attacks δ+ C → tetrahedral intermediate → protonation gives cyanohydrin.","Reagents: KCN + dilute H₂SO₄ (safer than HCN gas).","Adds one carbon; product can be hydrolysed to a 2-hydroxy acid.","Unsymmetrical carbonyls give a racemic mixture (planar C=O attacked equally from both faces)."]}]},{"id":"cb6","title":"Reduction with NaBH₄","blocks":[{"type":"p","text":"Aldehydes and ketones can be reduced back to alcohols using NaBH₄ (sodium tetrahydridoborate, also called sodium borohydride). This is the reverse of the oxidation reaction."},{"type":"d","caption":"Reduction gives the parent alcohol back"},{"type":"h","text":"The reactions"},{"type":"ul","items":["Aldehyde + 2[H] → 1° alcohol. Example: CH₃CHO + 2[H] → CH₃CH₂OH (ethanal → ethanol).","Ketone + 2[H] → 2° alcohol. Example: CH₃COCH₃ + 2[H] → (CH₃)₂CHOH (propanone → propan-2-ol).","[H] represents a hydrogen atom from the reducing agent. NaBH₄ is the source."]},{"type":"h","text":"Reagents and conditions"},{"type":"ul","items":["NaBH₄ is the standard A-level reducer for carbonyls. Solvent: methanol or ethanol or water (NaBH₄ does not react violently with these — it is mild).","Conditions: room temperature or gentle warming.","NaBH₄ is selective: it reduces aldehydes and ketones but does NOT reduce carboxylic acids or esters under normal conditions.","LiAlH₄ (lithium tetrahydridoaluminate) is more powerful — it reduces aldehydes, ketones, AND carboxylic acids and esters. But it must be used in DRY ETHER (it reacts violently with water)."]},{"type":"h","text":"Mechanism (overview)"},{"type":"ul","items":["NaBH₄ delivers hydride (H⁻) — a hydrogen ion with a lone pair, acting as a nucleophile.","H⁻ attacks the δ+ carbon of C=O; the π bond breaks with electrons going to O.","Tetrahedral intermediate: R₂C(H)(O⁻).","Protonation of O⁻ (from solvent water/methanol) gives the alcohol: R₂CH-OH.","Mechanism is similar to HCN addition but with H⁻ as the nucleophile."]},{"type":"callout","title":"Hydrogen as a nucleophile","body":"In reduction, hydride (H⁻) acts as a nucleophile. This is unusual — usually we think of H⁺ (a proton, electrophile). NaBH₄ provides H⁻ because the boron-hydrogen bond is polarised the opposite way (H is more electronegative than B). State this clearly in mechanism questions."},{"type":"takeaway","items":["Aldehyde → 1° alcohol; ketone → 2° alcohol.","NaBH₄ in methanol/water — mild and selective.","LiAlH₄ stronger but requires dry ether.","H⁻ acts as nucleophile (hydride)."]}]},{"id":"cb7","title":"2,4-DNPH (Brady's Reagent)","blocks":[{"type":"p","text":"2,4-DNPH (2,4-dinitrophenylhydrazine, also called Brady's reagent) is the standard test for the C=O group. It reacts with both aldehydes AND ketones to give an orange/yellow precipitate, but does NOT react with esters or carboxylic acids."},{"type":"d","caption":"Brady's test confirms carbonyl group presence"},{"type":"h","text":"The reaction"},{"type":"ul","items":["R₂C=O + H₂N-NH-Ar → R₂C=N-NH-Ar + H₂O. (Ar = 2,4-dinitrophenyl group.)","Type: condensation reaction (forms a new C=N bond, eliminates water).","Product: 2,4-dinitrophenylhydrazone — an ORANGE or YELLOW solid that precipitates from solution.","Conditions: mix the carbonyl with 2,4-DNPH solution (in methanol/H₂SO₄). The precipitate appears at room temperature."]},{"type":"h","text":"Why it works"},{"type":"p","text":"The hydrazine NH₂ group acts as a nucleophile, attacking the δ+ carbonyl carbon. After addition, water is eliminated to form a stable C=N bond. The aromatic dinitrophenyl group makes the product a highly coloured, insoluble solid that precipitates out — making it a clear visual test."},{"type":"h","text":"Identifying specific carbonyls"},{"type":"ul","items":["Each carbonyl gives a 2,4-DNP derivative with a SPECIFIC, REPRODUCIBLE melting point.","Filter, wash, recrystallise the orange/yellow precipitate, then measure its melting point.","Compare the m.p. with database values to identify the specific carbonyl.","This was a primary identification method before modern spectroscopy."]},{"type":"callout","title":"What 2,4-DNPH tells you and doesn't tell you","body":"A positive Brady's test (orange ppt) confirms the presence of a C=O group (aldehyde OR ketone). It does NOT distinguish between them. To distinguish, follow up with Tollens' or Fehling's. A negative Brady's test means the substance does NOT contain a free C=O (esters and carboxylic acids give NO precipitate)."},{"type":"takeaway","items":["2,4-DNPH = Brady's reagent. Tests for C=O.","Orange/yellow precipitate of 2,4-dinitrophenylhydrazone.","Both aldehydes and ketones give positive — does not distinguish them.","M.p. of derivative identifies the specific carbonyl."]}]},{"id":"cb8","title":"Tollens' & Fehling's Tests","blocks":[{"type":"p","text":"Tollens' and Fehling's are MILD OXIDISING agents that distinguish aldehydes from ketones. Aldehydes are oxidised (giving distinctive observations); ketones are not."},{"type":"d","caption":"The two tests for aldehyde vs ketone"},{"type":"h","text":"Tollens' reagent"},{"type":"ul","items":["Made fresh: AgNO₃(aq) + NaOH(aq) gives a brown precipitate of Ag₂O. Add NH₃(aq) until the precipitate just dissolves — this gives the Tollens' reagent: [Ag(NH₃)₂]⁺ in solution.","Reaction: aldehyde + 2[Ag(NH₃)₂]⁺ + 3OH⁻ → RCOO⁻ + 2Ag↓ + 4NH₃ + 2H₂O.","Observation: a SILVER MIRROR forms on the inside of the warm test tube. This is metallic silver (Ag) deposited from reduction of Ag⁺.","Aldehyde is oxidised to carboxylic acid (carboxylate ion in alkaline conditions).","Ketones do not react: no silver mirror."]},{"type":"h","text":"Fehling's solution"},{"type":"ul","items":["Two solutions: Fehling's A (CuSO₄(aq), blue) + Fehling's B (Na/K tartrate in NaOH). Mixed together, gives a deep blue solution containing Cu²⁺ complexed with tartrate (which keeps Cu²⁺ in solution under alkaline conditions).","Reaction: aldehyde + 2Cu²⁺ + 5OH⁻ → RCOO⁻ + Cu₂O↓ + 3H₂O.","Observation: BRICK-RED PRECIPITATE of copper(I) oxide forms. The blue colour fades.","Aldehyde is oxidised; Cu²⁺ is reduced to Cu⁺ (in Cu₂O).","Ketones do not react: no precipitate."]},{"type":"h","text":"Why aldehydes oxidise and ketones don't"},{"type":"p","text":"In an aldehyde (R-CHO), the carbonyl carbon has an H attached. Oxidation removes this H and replaces it with OH, giving R-COOH (carboxylic acid). In a ketone (R-CO-R'), there is no H on the carbonyl carbon — to oxidise, you would have to break a C-C bond, which mild oxidisers cannot do."},{"type":"h","text":"Aromatic vs aliphatic aldehydes"},{"type":"ul","items":["Aliphatic aldehydes (CH₃CHO, CH₃CH₂CHO) give positive Tollens' AND Fehling's.","Aromatic aldehydes (C₆H₅CHO benzaldehyde) give POSITIVE Tollens' but NEGATIVE Fehling's — Fehling's is too weak to oxidise the more stable aromatic aldehyde.","This is a useful distinction in practice: only Tollens' is reliable for aromatic aldehydes."]},{"type":"takeaway","items":["Tollens' [Ag(NH₃)₂]⁺ — silver mirror with aldehydes.","Fehling's (Cu²⁺/tartrate) — brick-red Cu₂O ppt with aliphatic aldehydes only.","Ketones: no reaction with either.","Aldehyde oxidised to carboxylic acid (or carboxylate in alkali)."]}]},{"id":"cb9","title":"The Iodoform Test for Methyl Carbonyls","blocks":[{"type":"p","text":"The iodoform test (already met for alcohols) also identifies certain carbonyl compounds. Specifically, it gives a positive result with METHYL KETONES (CH₃-CO-R) and ETHANAL (CH₃-CHO)."},{"type":"h","text":"Reagent and conditions"},{"type":"ul","items":["Reagent: alkaline iodine — I₂ in NaOH(aq), or I₂ + KI in NaOH.","Conditions: warm gently. The iodine colour fades; a yellow precipitate of CHI₃ (triiodomethane / \\"iodoform\\") forms.","Distinctive antiseptic smell."]},{"type":"h","text":"Which carbonyls give positive?"},{"type":"ul","items":["POSITIVE: any compound containing CH₃-CO- (methyl ketone). Examples: propanone (CH₃COCH₃), butanone (CH₃COCH₂CH₃), phenylethanone (C₆H₅COCH₃).","POSITIVE: ethanal (CH₃CHO) — the only aldehyde that gives a positive iodoform.","NEGATIVE: methanal (HCHO) — no methyl group attached to the C=O. NEGATIVE: propanal (CH₃CH₂CHO) — the methyl is not adjacent to C=O.","NEGATIVE: most other ketones like pentan-3-one (CH₃CH₂COCH₂CH₃) — no CH₃ on the carbonyl."]},{"type":"h","text":"Mechanism overview"},{"type":"ul","items":["Step 1: under alkaline conditions, the alpha hydrogens of the CH₃ are removed sequentially and replaced by I, giving CI₃-CO-R.","Step 2: alkaline hydrolysis cleaves the bond between CI₃ and C=O, giving CHI₃ (yellow ppt) and a carboxylate ion R-COO⁻.","Overall: CH₃COR + 3I₂ + 4OH⁻ → CHI₃↓ + RCOO⁻ + 3I⁻ + 3H₂O."]},{"type":"callout","title":"Cross-link with hydroxy compounds","body":"The iodoform test also detects CH₃-CH(OH)- groups (methyl 2° alcohols including ethanol). This is because alkaline iodine FIRST oxidises the alcohol to a methyl ketone, then proceeds with the iodoform sequence. So the test detects BOTH carbonyls (CH₃CO–) AND certain alcohols (CH₃CHOH–). See OC-16 hydroxy compounds for full coverage."},{"type":"takeaway","items":["Iodoform: I₂ in NaOH(aq), warm. Yellow ppt of CHI₃ = positive.","Positive for: methyl ketones (CH₃CO-R) and ethanal (CH₃CHO).","Plus: ethanol and methyl 2° alcohols (oxidised first to methyl ketones)."]}]},{"id":"cb10","title":"Distinguishing Aldehydes & Ketones","blocks":[{"type":"p","text":"A common exam task: given an unknown that contains a C=O, distinguish aldehyde from ketone. Here is the systematic approach."},{"type":"d","caption":"Summary of carbonyl tests"},{"type":"h","text":"The decision tree"},{"type":"ul","items":["Step 1: Add 2,4-DNPH. Orange/yellow ppt? → C=O present (aldehyde or ketone). No ppt? → not a carbonyl (could be ester, acid, alcohol, etc.).","Step 2 (if Step 1 positive): Add Tollens' reagent and warm. Silver mirror? → ALDEHYDE. No mirror? → KETONE.","Step 3 (if needed): Use Fehling's solution. Brick-red ppt? → ALIPHATIC ALDEHYDE specifically. (Aromatic aldehydes give negative Fehling's but positive Tollens'.)","Step 4 (optional): Iodoform (I₂/NaOH) test. Yellow ppt? → methyl carbonyl (CH₃-CO-R or CH₃-CHO)."]},{"type":"h","text":"Worked decision example"},{"type":"ul","items":["Compound A: gives orange ppt with 2,4-DNPH; gives silver mirror with Tollens'; gives yellow CHI₃ with I₂/NaOH.","Step 1: 2,4-DNPH +ve → it is a carbonyl.","Step 2: Tollens' +ve → it is an ALDEHYDE.","Step 3: Iodoform +ve → must contain CH₃-CHO group.","Conclusion: A is ETHANAL (CH₃CHO) — the only aldehyde that gives a positive iodoform test."]},{"type":"h","text":"Acidified K₂Cr₂O₇ as a confirmatory test"},{"type":"p","text":"You can also use acidified K₂Cr₂O₇ as a follow-up. Aldehydes are oxidised to carboxylic acids: orange → green colour change. Ketones do NOT oxidise: orange remains orange. Less mild than Tollens' or Fehling's but useful confirmation."},{"type":"takeaway","items":["Test 1: 2,4-DNPH → confirms C=O (aldehyde or ketone).","Test 2: Tollens' → silver mirror = aldehyde.","Test 3: Fehling's → brick-red ppt = aliphatic aldehyde.","Test 4: Iodoform → CHI₃ ppt = methyl carbonyl (CH₃CO- or CH₃CHO)."]}]},{"id":"cb11","title":"Carbonyls in Synthesis","blocks":[{"type":"p","text":"Aldehydes and ketones are versatile intermediates in organic synthesis — they can be converted to many different functional groups."},{"type":"d","caption":"Synthetic options from carbonyls"},{"type":"h","text":"From a carbonyl, you can make:"},{"type":"ul","items":["Alcohol: NaBH₄ in methanol → 1° alcohol (from aldehyde) or 2° alcohol (from ketone).","Cyanohydrin (2-hydroxynitrile): KCN/dilute H₂SO₄ → R₂C(OH)CN. Adds one carbon.","2-hydroxy carboxylic acid: hydrolyse the cyanohydrin with HCl(aq), reflux → R₂C(OH)COOH (e.g. lactic acid from acetaldehyde).","Carboxylic acid (from aldehyde only): K₂Cr₂O₇/H₂SO₄ reflux, or Tollens' (in alkali, gives carboxylate).","Imine (Schiff base): aldehyde/ketone + primary amine → R₂C=N-R' + H₂O. Beyond core syllabus.","2,4-DNP derivative: 2,4-DNPH → orange ppt for identification."]},{"type":"h","text":"Multi-step example: ethanal → lactic acid"},{"type":"ul","items":["Step 1: CH₃CHO + HCN → CH₃CH(OH)CN (2-hydroxypropanenitrile). Reagents: KCN/dilute H₂SO₄, ~10 °C.","Step 2: hydrolyse the nitrile. CH₃CH(OH)CN + 2H₂O + HCl → CH₃CH(OH)COOH + NH₄Cl. Reagents: dilute HCl, reflux.","Final product: 2-hydroxypropanoic acid (lactic acid). Note this is a chiral molecule produced as a racemate."]},{"type":"h","text":"Multi-step example: propanone → propan-2-ol → propene"},{"type":"ul","items":["Step 1: CH₃COCH₃ + 2[H] → (CH₃)₂CHOH. NaBH₄ in methanol.","Step 2: (CH₃)₂CHOH → CH₃CH=CH₂ + H₂O. Conc. H₂SO₄, 170 °C (dehydration)."]},{"type":"takeaway","items":["Carbonyls → alcohols (NaBH₄), cyanohydrins (KCN), acids (oxidation).","Cyanohydrin route extends carbon chain by 1.","Multi-step synthesis: ethanal → lactic acid (HCN then hydrolyse)."]}]},{"id":"cb12","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Carbonyl questions test mechanism, identification tests, and synthesis. Here are the patterns."},{"type":"h","text":"Identifying carbonyls"},{"type":"ul","items":["Aldehyde general formula R-CHO. Ketone R-CO-R'. Both contain C=O.","For mechanism questions, ALWAYS show curly arrows correctly. Two arrows in step 1: from nucleophile lone pair to C, AND from C=O π bond to O. One arrow in step 2: from H⁺ to O⁻.","Show partial charges (δ+ on C, δ− on O) on the C=O bond.","Show lone pairs on the nucleophile (CN⁻ has lone pairs on C; H⁻ has its pair)."]},{"type":"h","text":"Test selection"},{"type":"ul","items":["To distinguish aldehyde from ketone: Tollens' (silver mirror) or Fehling's (red ppt).","To confirm any C=O: 2,4-DNPH (orange ppt).","To find a methyl carbonyl: iodoform (yellow ppt).","For aromatic aldehydes (e.g. benzaldehyde): use Tollens' — Fehling's is too weak.","For oxidation of aldehyde to acid in synthesis: K₂Cr₂O₇/H₂SO₄ reflux, or Tollens' under alkaline conditions."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Saying ketones give a positive Tollens' or Fehling's — they DO NOT (no H on C=O carbon to remove).","Forgetting that benzaldehyde gives positive Tollens' but NEGATIVE Fehling's.","In HCN mechanism: writing the nucleophile as HCN — it is CN⁻ (the conjugate base) that attacks. Use KCN as the source.","Forgetting that HCN addition gives a RACEMATE when the carbonyl is unsymmetrical.","Confusing the iodoform test conditions: it is alkaline I₂ (I₂ + NaOH), not acidic."]},{"type":"h","text":"Key equations to know"},{"type":"ul","items":["Preparation: R-CH₂-OH → R-CHO (distil); R₂CH-OH → R₂C=O (reflux).","Reduction: R₂C=O + 2[H] → R₂CH-OH (NaBH₄).","HCN addition: R₂C=O + HCN → R₂C(OH)(CN).","Tollens': RCHO + 2[Ag(NH₃)₂]⁺ + 3OH⁻ → RCOO⁻ + 2Ag↓ + 4NH₃ + 2H₂O.","Fehling's: RCHO + 2Cu²⁺ + 5OH⁻ → RCOO⁻ + Cu₂O↓ + 3H₂O.","Iodoform (CH₃CO-R): CH₃COR + 3I₂ + 4OH⁻ → CHI₃ + RCOO⁻ + 3I⁻ + 3H₂O."]},{"type":"callout","title":"The carbonyl distinction toolbox","body":"A \\"given an unknown carbonyl, distinguish it\\" question always uses some combination of: 2,4-DNPH (any C=O); Tollens'/Fehling's (aldehyde only); iodoform (CH₃-CO- or CH₃-CHO); K₂Cr₂O₇ (aldehyde to acid). Practice running through this decision tree on dozens of unknowns."},{"type":"takeaway","items":["Tests: 2,4-DNPH (any C=O), Tollens'/Fehling's (aldehyde), iodoform (methyl).","Mechanism: nucleophile attacks δ+ C, π bond breaks, O⁻ protonated.","NaBH₄ reduces back to alcohol; HCN extends chain by 1 carbon.","Ketones don't oxidise; aldehydes do."]}]}]}`),carboxylic:JSON.parse(`{"objectives":["Name and draw carboxylic acids and their derivatives (acyl chlorides, esters, amides)","Describe the formation of carboxylic acids from alcohols, aldehydes and nitriles","Recall reactions of carboxylic acids: salt formation, esterification, conversion to acyl chlorides, reduction","Explain the relative acidity of carboxylic acids and chlorinated derivatives using the inductive effect","Describe reactions of acyl chlorides with water, alcohols, phenols, primary amines and ammonia","Explain why acyl chlorides hydrolyse much faster than alkyl chlorides or aryl chlorides","Compare the two routes to esters: acid + alcohol (reversible) vs acyl chloride + alcohol (irreversible)","Describe acid and base hydrolysis of esters and the saponification of fats to make soap","State the uses of carboxylic acids and esters"],"chapters":[{"id":"ca1","title":"The Carboxylic Acid Group","blocks":[{"type":"p","text":"Carboxylic acids contain the –COOH (carboxyl) functional group: a carbonyl C=O AND a hydroxyl –OH on the same carbon. Together these create a uniquely acidic group that defines the chemistry. The general formula is R-COOH; the simplest is methanoic acid (HCOOH, formic acid) and the next is ethanoic acid (CH₃COOH, vinegar)."},{"type":"d","caption":"The carboxyl group has both C=O and O-H"},{"type":"h","text":"IUPAC nomenclature"},{"type":"ul","items":["Find the longest chain containing the –COOH group. The COOH carbon is always C1.","Replace the \\"-e\\" of the parent alkane with \\"-oic acid\\".","No locant needed for –COOH — it is automatically C1.","Examples: HCOOH = methanoic acid (formic acid); CH₃COOH = ethanoic acid (acetic acid); CH₃CH₂COOH = propanoic acid; (CH₃)₂CHCOOH = 2-methylpropanoic acid.","Dicarboxylic acids: HOOC-COOH = ethanedioic acid (oxalic acid); HOOC-CH₂-COOH = propanedioic acid."]},{"type":"h","text":"Common names worth knowing"},{"type":"ul","items":["Methanoic acid (HCOOH) = formic acid (in ant venom).","Ethanoic acid (CH₃COOH) = acetic acid (in vinegar, ~5%).","Propanoic acid (CH₃CH₂COOH) = propionic acid.","Butanoic acid (CH₃CH₂CH₂COOH) = butyric acid (rancid butter smell).","Hexadecanoic acid (CH₃(CH₂)₁₄COOH) = palmitic acid (in palm oil, fats).","Octadecanoic acid = stearic acid (in soaps, fats).","Benzoic acid (C₆H₅COOH) — preservative E210."]},{"type":"h","text":"Physical properties"},{"type":"ul","items":["Hydrogen bonding: carboxylic acids form especially strong H-bonds — they exist as DIMERS (pairs joined by two H-bonds in a ring) in pure form and in non-polar solvents.","Boiling points are even higher than alcohols of similar Mr because of dimer formation.","Small acids (HCOOH, CH₃COOH, CH₃CH₂COOH, butanoic) are miscible with water — H-bond strongly with water.","Solubility decreases as the alkyl chain lengthens (>5 carbons).","Smell: short-chain acids have sharp, vinegar-like or rancid smells."]},{"type":"callout","title":"The combination defines the chemistry","body":"The C=O makes the –COOH group electrophilic at C; the O–H provides acidity. Together, they enable: (1) loss of H⁺ to give a stabilised carboxylate ion R-COO⁻, (2) nucleophilic substitution at the C=O carbon. Both modes are heavily examined."},{"type":"takeaway","items":["–COOH = C=O + O-H on the same carbon.","IUPAC: replace \\"-e\\" with \\"-oic acid\\", COOH = C1.","Strong H-bonding (often dimers) → high b.p., good water solubility for short chains.","Two reactive features: O-H (acidic) and C=O (electrophilic)."]}]},{"id":"ca2","title":"Preparation of Carboxylic Acids","blocks":[{"type":"p","text":"Three main routes to carboxylic acids at A-level: oxidation of primary alcohols, oxidation of aldehydes, and hydrolysis of nitriles."},{"type":"d","caption":"Three routes to carboxylic acids"},{"type":"h","text":"From primary alcohols"},{"type":"ul","items":["R-CH₂-OH + 2[O] → R-COOH + H₂O.","Reagents: acidified K₂Cr₂O₇/H₂SO₄ (or KMnO₄ for harsher oxidation).","Conditions: REFLUX with EXCESS oxidising agent. The aldehyde intermediate is fully oxidised to the acid.","Colour change: orange Cr₂O₇²⁻ → green Cr³⁺.","Example: ethanol → ethanal → ethanoic acid. CH₃CH₂OH + 2[O] → CH₃COOH + H₂O."]},{"type":"h","text":"From aldehydes"},{"type":"ul","items":["R-CHO + [O] → R-COOH.","Same reagents and conditions as above (acidified K₂Cr₂O₇, reflux).","Aldehydes can also be oxidised to carboxylic acids by Tollens' reagent (giving silver mirror) or in air over time."]},{"type":"h","text":"From nitriles (hydrolysis)"},{"type":"ul","items":["R-CN + 2H₂O + HCl → R-COOH + NH₄Cl. Acid hydrolysis is the most common.","Or alkaline: R-CN + H₂O + NaOH → R-COO⁻Na⁺ + NH₃. Then acidify to get R-COOH.","Conditions: reflux with dilute aqueous acid (or alkali) for several hours.","This route extends the carbon chain by ONE atom — the CN carbon becomes part of the COOH.","Example: CH₃CH₂Br + KCN(alc) → CH₃CH₂CN → CH₃CH₂COOH (propanoic acid). Started with 2 C, ended with 3 C."]},{"type":"callout","title":"Choosing the route","body":"If you have an alcohol → oxidise. If you have an aldehyde → oxidise (or use Tollens' for synthesis). If you need a CHAIN-EXTENDED acid → use the nitrile route from a halogenoalkane. The nitrile route is the standard way to add one carbon."},{"type":"takeaway","items":["1° alcohol + K₂Cr₂O₇/H₂SO₄, reflux → carboxylic acid.","Aldehyde + K₂Cr₂O₇/H₂SO₄ → carboxylic acid.","Nitrile + H₂O/HCl, reflux → carboxylic acid (chain extends by 1 C)."]}]},{"id":"ca3","title":"Reactions of Carboxylic Acids","blocks":[{"type":"p","text":"Carboxylic acids react in two main modes: (1) as ACIDS, losing the O-H proton to bases or active metals, and (2) at the C=O group, forming esters or acyl chlorides. The acidic mode dominates with most reagents."},{"type":"d","caption":"Common reactions of carboxylic acids"},{"type":"h","text":"Salt formation"},{"type":"ul","items":["With NaOH(aq): R-COOH + NaOH → R-COO⁻Na⁺ + H₂O. Forms a sodium carboxylate (soluble, ionic).","With Na₂CO₃(aq): 2R-COOH + Na₂CO₃ → 2R-COO⁻Na⁺ + CO₂↑ + H₂O. CO₂ effervescence is observed — diagnostic test for –COOH.","With NaHCO₃(aq): R-COOH + NaHCO₃ → R-COO⁻Na⁺ + CO₂↑ + H₂O. Same effervescence; gentler base.","With Na metal: 2R-COOH + 2Na → 2R-COO⁻Na⁺ + H₂↑. Slower than with water.","These reactions show carboxylic acids are STRONGER acids than carbonic acid (H₂CO₃) — they release CO₂ from carbonates. Phenol does NOT — distinguishing test."]},{"type":"h","text":"Ester formation (with alcohols)"},{"type":"ul","items":["R-COOH + R'-OH ⇌ R-COOR' + H₂O.","Conditions: concentrated H₂SO₄ catalyst, REFLUX.","Reversible (equilibrium) — slow, modest yield.","To improve yield: use excess alcohol or acid; remove water using anhydrous drying or by distillation; or use an acyl chloride instead (next chapter).","Example: CH₃COOH + CH₃CH₂OH ⇌ CH₃COOCH₂CH₃ + H₂O (ethyl ethanoate, fruity smell)."]},{"type":"h","text":"Conversion to acyl chlorides"},{"type":"ul","items":["With PCl₅: R-COOH + PCl₅ → R-COCl + HCl + POCl₃. Vigorous; produces fumes of HCl.","With SOCl₂ (thionyl chloride): R-COOH + SOCl₂ → R-COCl + HCl + SO₂. CLEANEST method — by-products are gases that escape.","With PCl₃: 3R-COOH + PCl₃ → 3R-COCl + H₃PO₃.","The product (R-COCl, an acyl chloride) is far more reactive than the parent acid — useful intermediate."]},{"type":"h","text":"Reduction to alcohol"},{"type":"p","text":"Carboxylic acids can be reduced all the way to primary alcohols using LiAlH₄ in dry ether: R-COOH + 4[H] → R-CH₂OH + H₂O. NaBH₄ is NOT strong enough to reduce carboxylic acids (only carbonyls)."},{"type":"takeaway","items":["NaOH/Na₂CO₃/NaHCO₃: salt formation. Na₂CO₃/NaHCO₃ → CO₂ effervescence (test).","Alcohol + conc. H₂SO₄: ester (reversible).","PCl₅/SOCl₂/PCl₃: acyl chloride.","LiAlH₄: reduces to 1° alcohol (not NaBH₄)."]}]},{"id":"ca4","title":"Acidity & The Inductive Effect","blocks":[{"type":"p","text":"Carboxylic acids are weak acids (pKa ≈ 4-5) but much stronger than phenols (pKa ≈ 10) or alcohols (pKa ≈ 16). The strength depends on the stability of the carboxylate ion (the conjugate base). Substituents can dramatically increase acid strength via the inductive effect."},{"type":"d","caption":"Carboxylic acids are stronger than phenols or alcohols"},{"type":"h","text":"Why are carboxylic acids stronger than phenols?"},{"type":"ul","items":["The conjugate base of a carboxylic acid is the carboxylate ion: R-COO⁻.","The negative charge is DELOCALISED equally over BOTH oxygen atoms by resonance — the C-O bonds become equivalent (each is 1.5 bond order).","This is much more effective stabilisation than in phenoxide (where charge is spread over 1 O + 3 ring carbons but unevenly).","More stable conjugate base → stronger acid.","pKa values: carboxylic acid ≈ 4-5; phenol ≈ 10; alcohol ≈ 16. Acid is ~10⁵ times stronger than phenol."]},{"type":"h","text":"Effect of chlorine substituents (–I effect)"},{"type":"d","caption":"Chloro substitution increases acidity"},{"type":"ul","items":["Chlorine atoms are highly electronegative — they WITHDRAW electron density from neighbouring atoms (negative inductive effect, –I).","In a chlorinated acid, the Cl atoms pull electron density AWAY from the carboxylate ion, helping to spread out the negative charge.","A more stabilised carboxylate ion → easier to form → stronger acid.","pKa values: ethanoic acid 4.76; chloroethanoic acid 2.86; dichloroethanoic acid 1.30; trichloroethanoic acid 0.66. Each Cl makes it about 100× more acidic.","Trichloroethanoic acid is almost a strong acid! Comparable to inorganic acids."]},{"type":"h","text":"Distance matters"},{"type":"ul","items":["The inductive effect of Cl FALLS OFF rapidly with distance.","Compare: 2-chlorobutanoic acid (Cl on C2, next to COOH) is much more acidic than 4-chlorobutanoic acid (Cl on C4, far away).","Cl directly bonded to the C-COOH is most effective.","A CH₃ group has the OPPOSITE effect: it DONATES electron density (+I effect), DESTABILISING the carboxylate. So methanoic acid (HCOOH, pKa 3.75) is slightly stronger than ethanoic acid (CH₃COOH, pKa 4.76) — the H is \\"neutral\\", but the CH₃ pushes electrons in."]},{"type":"callout","title":"Exam template for acidity","body":"For \\"explain why X is more acidic than Y\\" questions: (1) compare conjugate bases. (2) Identify what stabilises the negative charge. (3) Carboxylates: resonance over 2 equivalent O atoms. Phenoxide: less effective resonance into ring. Alcohol's conjugate base: localised on O, destabilised by alkyl +I. (4) Chlorinated acids: -I effect of Cl removes electron density, stabilises carboxylate."},{"type":"takeaway","items":["Acid > phenol > alcohol in acidity (carboxylate stabilised by symmetric resonance).","-I substituents (Cl, F) increase acidity; +I substituents (CH₃) decrease.","Multiple Cl atoms give very strong acids.","Distance matters: closer Cl is more effective."]}]},{"id":"ca5","title":"Acyl Chlorides: Reactions","blocks":[{"type":"p","text":"Acyl chlorides (R-COCl, also called acid chlorides) are far more reactive than carboxylic acids. They contain both an electron-withdrawing Cl (excellent leaving group) and the polar C=O. They are used in synthesis when you need fast, clean reactions to make esters, amides, or related derivatives."},{"type":"d","caption":"Acyl chlorides react with many nucleophiles"},{"type":"h","text":"With water: vigorous hydrolysis"},{"type":"ul","items":["R-COCl + H₂O → R-COOH + HCl.","Reaction is RAPID and VIGOROUS at room temperature.","Steamy fumes of HCl are produced (visible).","Acyl chlorides must be kept dry — they react with moisture in the air.","Mechanism: water attacks δ+ C; tetrahedral intermediate forms; Cl⁻ leaves; H⁺ is then lost to give the acid."]},{"type":"h","text":"With alcohols: ester formation"},{"type":"ul","items":["R-COCl + R'-OH → R-COOR' + HCl.","FAST and IRREVERSIBLE — much better than esterification with the carboxylic acid.","No catalyst needed, room temperature.","High yield because no equilibrium to drive.","Example: CH₃COCl + CH₃CH₂OH → CH₃COOCH₂CH₃ + HCl (ethyl ethanoate)."]},{"type":"h","text":"With phenols: ester formation"},{"type":"ul","items":["R-COCl + ArOH → R-COOAr + HCl. Same general pattern.","Phenols are LESS nucleophilic than alcohols (the OH lone pair is delocalised into the ring), so the reaction is slower.","Usually carried out with NaOH or pyridine present to neutralise HCl and to make phenoxide ion (more nucleophilic than phenol).","Example: CH₃COCl + C₆H₅OH → CH₃COOC₆H₅ + HCl (phenyl ethanoate)."]},{"type":"h","text":"With ammonia and primary amines: amide formation"},{"type":"ul","items":["With NH₃: R-COCl + 2NH₃ → R-CONH₂ + NH₄Cl. Forms a primary AMIDE. Vigorous reaction; usually forms a white precipitate of the amide.","With primary amine R'-NH₂: R-COCl + 2R'-NH₂ → R-CONH-R' + R'-NH₃Cl. Forms an N-substituted amide. The 2nd equivalent of amine acts as a base to neutralise HCl.","Example: CH₃COCl + 2NH₃ → CH₃CONH₂ + NH₄Cl (ethanamide)."]},{"type":"callout","title":"Why are acyl chlorides so reactive?","body":"The C is doubly activated: (1) C=O makes it δ+; (2) Cl is highly electronegative, increasing the δ+. Cl is also an excellent LEAVING GROUP (Cl⁻ is stable). All four common nucleophiles (H₂O, R-OH, ArOH, NH₃/RNH₂) can attack and displace Cl⁻. The reactions are typically much faster than the analogous reactions of carboxylic acids — making acyl chlorides preferred for synthesis."},{"type":"takeaway","items":["Water → carboxylic acid + HCl (vigorous).","Alcohol → ester + HCl (preferred to acid + alcohol route).","Phenol → phenyl ester (with base to help).","NH₃ or RNH₂ → primary or N-substituted amide."]}]},{"id":"ca6","title":"Comparing Hydrolysis: Acyl vs Alkyl vs Aryl Chlorides","blocks":[{"type":"p","text":"Three classes of organic chlorides have very different hydrolysis behaviour: acyl chlorides (R-COCl) hydrolyse violently; alkyl chlorides (R-Cl) hydrolyse slowly with NaOH; aryl chlorides (Ar-Cl, e.g. chlorobenzene) require extreme conditions."},{"type":"h","text":"Order of reactivity towards water/OH⁻"},{"type":"ul","items":["ACYL chloride (R-COCl): VIGOROUS at room temperature. Hydrolyses on contact with water/moisture.","ALKYL chloride (R-CH₂Cl): SLOW at room temperature. Hydrolyses with NaOH(aq) on REFLUX.","ARYL chloride (C₆H₅-Cl): EXTREME. Requires 300 °C, 200 atm, conc. NaOH (Dow process for phenol). Effectively unreactive under normal conditions."]},{"type":"h","text":"Why acyl chlorides are most reactive"},{"type":"ul","items":["Two electron-withdrawing groups (C=O AND Cl) on the same carbon → very large δ+ on C → highly susceptible to nucleophilic attack.","C=O π bond can break to accommodate nucleophile attack (mechanism resembles addition-elimination).","Cl is an excellent leaving group from this position."]},{"type":"h","text":"Why alkyl chlorides are intermediate"},{"type":"ul","items":["The C-Cl bond is polar (δ+ on C) but only one electron-withdrawing group.","No π bond available to assist mechanism.","Mechanism is SN1 or SN2 (depending on class) — slower because it requires breaking the C-Cl bond before/during nucleophile attack."]},{"type":"h","text":"Why aryl chlorides are essentially unreactive"},{"type":"ul","items":["In chlorobenzene, the Cl lone pair OVERLAPS with the benzene π system — partial double-bond character in C-Cl bond.","C-Cl bond is shorter and stronger than in alkyl chlorides.","The electron-rich aromatic ring REPELS approaching nucleophiles.","Bond strengths: C-Cl (alkyl) ~338 kJ/mol; C-Cl (aryl) ~399 kJ/mol; the difference reflects the partial double-bond character."]},{"type":"callout","title":"The exam answer","body":"For \\"compare the ease of hydrolysis\\": state the order (acyl > alkyl >> aryl), then explain each: (1) Acyl: two electron-withdrawing groups + C=O π bond → addition-elimination at δ+ C. (2) Alkyl: standard SN1/SN2 at δ+ C. (3) Aryl: Cl lone pair delocalised into ring → C-Cl bond stronger and ring repels nucleophile. Cite typical conditions for each."},{"type":"takeaway","items":["Acyl > alkyl >> aryl in hydrolysis reactivity.","Acyl: vigorous at RT. Alkyl: reflux NaOH. Aryl: 300 °C, 200 atm.","Acyl: addition-elimination mechanism. Aryl: π-overlap stabilises C-Cl."]}]},{"id":"ca7","title":"Esters: Properties, Formation & Hydrolysis","blocks":[{"type":"p","text":"Esters (R-COOR') are common in nature — found in fruits (giving them their smell), fats and oils (triglycerides), and many synthetic flavourings and fragrances. They are made by combining a carboxylic acid (or acyl chloride) with an alcohol."},{"type":"d","caption":"Two routes to esters"},{"type":"h","text":"Naming esters"},{"type":"ul","items":["Two parts: alkyl (from the alcohol) + alkanoate (from the acid).","CH₃COOCH₂CH₃: from ethanoic acid + ethanol → ETHYL ETHANOATE.","HCOOCH₃: from methanoic acid + methanol → METHYL METHANOATE.","CH₃CH₂COOCH(CH₃)₂: from propanoic acid + propan-2-ol → PROPAN-2-YL PROPANOATE."]},{"type":"h","text":"Formation"},{"type":"ul","items":["Route 1: from carboxylic acid + alcohol with conc. H₂SO₄ catalyst, reflux. Reversible (equilibrium); modest yield. Slow.","Route 2 (preferred): from acyl chloride + alcohol. Fast, irreversible, no catalyst needed, high yield.","For high-value esters (perfumes, pharmaceuticals), Route 2 is preferred. For bulk industrial esters, Route 1 may be used with excess of one reagent and water removal."]},{"type":"h","text":"Hydrolysis of esters"},{"type":"d","caption":"Acid vs base hydrolysis of esters"},{"type":"ul","items":["ACID hydrolysis: R-COOR' + H₂O ⇌ R-COOH + R'-OH. Reagents: dilute H₂SO₄ or HCl, REFLUX. Reversible — partial conversion.","BASE hydrolysis (saponification): R-COOR' + NaOH → R-COO⁻Na⁺ + R'-OH. Reagents: NaOH(aq), REFLUX. IRREVERSIBLE because the carboxylic acid is immediately converted to its salt by the base. Goes to completion.","Base hydrolysis is preferred when complete conversion is wanted."]},{"type":"h","text":"Uses of esters"},{"type":"ul","items":["Flavourings: ethyl ethanoate (pear), pentyl ethanoate (banana), octyl ethanoate (orange), methyl butanoate (apple). Used in confectionery, drinks, perfumes.","Solvents: ethyl ethanoate is a common solvent for nail polish remover, glues, paints.","Polyesters: condensation polymers of diols + dicarboxylic acids (e.g. PET = poly(ethylene terephthalate), used in bottles and fibres). See OC-20.","Fats and oils: triglycerides — esters of glycerol with three fatty acids.","Plasticisers: phthalate esters used to make PVC flexible."]},{"type":"takeaway","items":["Naming: alkyl + alkanoate (e.g. ethyl ethanoate).","Best route to esters: acyl chloride + alcohol (irreversible, fast).","Acid hydrolysis: reversible. Base hydrolysis (saponification): irreversible.","Uses: flavours, solvents, polyesters, fats."]}]},{"id":"ca8","title":"Soap Manufacture & Saponification","blocks":[{"type":"p","text":"Soap is made by the BASE HYDROLYSIS of fats and oils (triglyceride esters). This process is called SAPONIFICATION (\\"soap-making\\"). It is one of the oldest chemical industries — the basic reaction has been used for thousands of years."},{"type":"h","text":"What are fats and oils?"},{"type":"ul","items":["Fats (solids at room T) and oils (liquids at room T) are TRIGLYCERIDES — esters of glycerol (propane-1,2,3-triol) with three FATTY ACIDS.","Structure: glycerol's three –OH groups each form an ester linkage with a long-chain carboxylic acid (typically 12–22 carbons).","Saturated fats (e.g. animal fat, butter): fatty acids have no C=C bonds → straight chains pack tightly → solid at RT.","Unsaturated fats/oils (e.g. olive oil, sunflower oil): one or more C=C bonds → kinked chains, can't pack tightly → liquid at RT."]},{"type":"h","text":"The saponification process"},{"type":"ul","items":["Triglyceride + 3NaOH → glycerol + 3 R-COO⁻Na⁺ (sodium salt of the fatty acid = SOAP).","Conditions: heat fat or oil with concentrated NaOH(aq), reflux for several hours.","Mechanism: NaOH hydrolyses each of the three ester linkages.","Sodium soaps: hard, used for bar soap. Potassium soaps (with KOH): softer, used for liquid soap, shaving cream."]},{"type":"h","text":"How soap cleans"},{"type":"ul","items":["Soap molecules are AMPHIPHILIC: a long hydrophobic hydrocarbon \\"tail\\" (CH₃(CH₂)ₙ–) and a hydrophilic ionic \\"head\\" (–COO⁻Na⁺).","Hydrophobic tails embed in oil/grease; hydrophilic heads point out into water.","This forms MICELLES — droplets of grease surrounded by soap molecules with their heads facing water.","The micelles are dispersed and washed away by water — grease is removed."]},{"type":"h","text":"The \\"salting out\\" step"},{"type":"p","text":"After the saponification reaction, salt (NaCl) is added to the mixture. Soap is less soluble in salt solution than in pure water — it precipitates out as a solid lump, separating from the glycerol-water layer below. This is \\"salting out\\" the soap."},{"type":"callout","title":"Why does this matter?","body":"Saponification is the prototype example of base hydrolysis of esters. Triglycerides are the natural feedstock; the principle applies to all esters. The glycerol by-product is itself useful (in pharmaceuticals, cosmetics, explosives nitroglycerine)."},{"type":"takeaway","items":["Soap = sodium (or potassium) salt of long-chain fatty acid.","Made by base hydrolysis (saponification) of fats/oils with NaOH or KOH.","Cleans by forming micelles — hydrophobic tail in grease, ionic head in water.","Salting out separates the soap as a solid."]}]},{"id":"ca9","title":"Amides & Their Hydrolysis","blocks":[{"type":"p","text":"Amides (R-CONH₂) are formed when an acyl chloride reacts with ammonia. They contain the amide functional group –C(=O)–NH–, which is also found in proteins (where it is called the peptide bond). Amides can be hydrolysed back to carboxylic acids and amines."},{"type":"h","text":"Formation of amides"},{"type":"ul","items":["From acyl chloride + ammonia: R-COCl + 2NH₃ → R-CONH₂ + NH₄Cl. Forms a primary amide.","From acyl chloride + primary amine: R-COCl + 2R'-NH₂ → R-CONHR' + R'NH₃Cl. Forms an N-substituted amide. The 2nd equivalent of amine acts as a base to absorb HCl.","From acid + amine direct: difficult — usually goes via the acyl chloride.","Examples: CH₃COCl + NH₃ → CH₃CONH₂ (ethanamide); CH₃COCl + CH₃NH₂ → CH₃CONHCH₃ (N-methylethanamide)."]},{"type":"h","text":"Naming amides"},{"type":"ul","items":["Replace \\"-oic acid\\" or \\"-oyl chloride\\" with \\"-amide\\". Example: ethanoic acid → ethanamide.","For N-substituted amides: prefix \\"N-\\" with the substituent name. CH₃CONHCH₃ = N-methylethanamide.","CH₃CON(CH₃)₂ = N,N-dimethylethanamide (both H replaced)."]},{"type":"h","text":"Hydrolysis of amides"},{"type":"ul","items":["ACID hydrolysis: R-CONH₂ + H₂O + HCl → R-COOH + NH₄Cl. Reagents: dilute HCl, reflux several hours.","BASE hydrolysis: R-CONH₂ + NaOH → R-COO⁻Na⁺ + NH₃. Reagents: dilute NaOH, reflux. Releases ammonia as gas.","Both routes work but require harsher conditions than ester hydrolysis (amides are less reactive than esters because the lone pair on N delocalises into the C=O).","Hydrolysis of N-substituted amides gives the carboxylic acid (or salt) + the amine: R-CONHR' + H₂O + HCl → R-COOH + R'NH₃Cl."]},{"type":"h","text":"The peptide bond"},{"type":"ul","items":["In proteins, amino acids are linked by peptide bonds: –NH–C(=O)– (an amide bond).","Hydrolysis of proteins (e.g. by digestion or laboratory acid/base) breaks these peptide bonds, releasing individual amino acids.","This is the same chemistry as amide hydrolysis — proteins are essentially long chains of amides.","See OC-19 Nitrogen Compounds for the full discussion of amino acids and proteins."]},{"type":"callout","title":"Reactivity hierarchy of acid derivatives","body":"Acyl chlorides > esters > amides in reactivity (towards nucleophiles). This is because: (1) Cl is the best leaving group, NH₂ is the worst. (2) The lone pair on N donates into C=O strongly (good resonance), making amides less electrophilic; OR on O is weaker resonance. So amides are the LEAST reactive — which is why proteins (containing peptide bonds) are stable to mild conditions."},{"type":"takeaway","items":["Amide formation: acyl chloride + NH₃/RNH₂.","Naming: \\"-amide\\" suffix. N-substituted amides have prefix \\"N-\\".","Acid or base hydrolysis: amide → acid (or salt) + amine.","Peptide bond = amide bond in proteins. Hydrolysis breaks them."]}]},{"id":"ca10","title":"Distinguishing Tests & Functional Group ID","blocks":[{"type":"p","text":"Carboxylic acids and their derivatives can be distinguished from each other and from other classes (alcohols, phenols, esters) using a combination of simple tests."},{"type":"h","text":"Test 1: Sodium carbonate (Na₂CO₃)"},{"type":"ul","items":["Add Na₂CO₃(aq) and observe.","Carboxylic acids: EFFERVESCENCE — CO₂ released. 2R-COOH + Na₂CO₃ → 2R-COO⁻Na⁺ + CO₂ + H₂O.","Phenols: NO reaction (too weak as acids).","Alcohols: NO reaction.","This test is the PRIMARY way to identify a carboxylic acid."]},{"type":"h","text":"Test 2: Sodium hydroxide (NaOH)"},{"type":"ul","items":["All three (acid, phenol, alcohol have OH groups), but only acids and phenols react with NaOH(aq).","Acid: dissolves to form sodium carboxylate.","Phenol: dissolves to form sodium phenoxide.","Alcohol: NO reaction.","Combined with Na₂CO₃ test, this gives a clear distinction."]},{"type":"h","text":"Test 3: Smell"},{"type":"ul","items":["Short-chain acids: pungent (vinegar-like); butanoic acid has a particularly rancid smell.","Esters: PLEASANT, fruity smells (banana, pineapple, etc.).","Useful as a quick check but never the only test."]},{"type":"h","text":"Test 4: Acyl chlorides — fume test"},{"type":"ul","items":["Add a drop of water (or expose to moist air): VIGOROUS reaction, white fumes of HCl visible.","No other class of organic compound behaves like this."]},{"type":"h","text":"Test 5: Amides — release of NH₃"},{"type":"ul","items":["Boil with NaOH(aq). Ammonia gas is released — turns damp red litmus paper blue.","Distinguishes amides from other functional groups."]},{"type":"callout","title":"Quick decision tree for OH-containing organics","body":"Add Na: alcohol/phenol/acid all release H₂. Add NaOH: phenol and acid dissolve; alcohol does not. Add Na₂CO₃: acid effervesces with CO₂; phenol does not react. So: Na ✓ + NaOH ✓ + Na₂CO₃ ✓ = ACID. Na ✓ + NaOH ✓ + Na₂CO₃ ✗ = PHENOL. Na ✓ + NaOH ✗ + Na₂CO₃ ✗ = ALCOHOL."},{"type":"takeaway","items":["Na₂CO₃: CO₂ effervescence = carboxylic acid (specific test).","NaOH: dissolves phenol and acid; not alcohol.","Acyl chloride: vigorous fumes with water = HCl.","Amide: NaOH/heat → NH₃ released."]}]},{"id":"ca11","title":"Synthesis: Multi-Step Examples","blocks":[{"type":"p","text":"Carboxylic acids and their derivatives are central to many synthetic sequences. Here are common multi-step patterns."},{"type":"h","text":"Pattern 1: Alcohol → ester (via acyl chloride)"},{"type":"ul","items":["Alcohol → carboxylic acid → acyl chloride → ester.","Step 1: oxidation. R-CH₂OH + 2[O] → R-COOH (K₂Cr₂O₇/H₂SO₄, reflux).","Step 2: acyl chloride. R-COOH + SOCl₂ → R-COCl (SOCl₂, reflux briefly).","Step 3: esterification. R-COCl + R'-OH → R-COOR' + HCl (room temperature, fast).","Why use Route 2 (acyl chloride)? Fast, irreversible, no equilibrium to manage."]},{"type":"h","text":"Pattern 2: Halogenoalkane → carboxylic acid (chain extension)"},{"type":"ul","items":["R-X (n carbons) → R-CN (n+1 carbons) → R-COOH (n+1 carbons).","Step 1: nucleophilic substitution. R-Br + KCN(alc) → R-CN + KBr. Reflux in ethanol.","Step 2: acid hydrolysis of nitrile. R-CN + 2H₂O + HCl → R-COOH + NH₄Cl. Dilute HCl, reflux.","Net result: chain extended by 1 carbon, halogen replaced by COOH group.","Example: 1-bromopropane → butanoic acid (C3 → C4)."]},{"type":"h","text":"Pattern 3: Aldehyde → 2-hydroxy carboxylic acid (chain extension)"},{"type":"ul","items":["R-CHO → R-CH(OH)CN → R-CH(OH)COOH.","Step 1: HCN addition. R-CHO + HCN → R-CH(OH)CN (KCN/dilute H₂SO₄, ~10 °C).","Step 2: hydrolysis. R-CH(OH)CN + 2H₂O + HCl → R-CH(OH)COOH + NH₄Cl. Dilute HCl, reflux.","Example: ethanal → 2-hydroxypropanoic acid (lactic acid)."]},{"type":"h","text":"Pattern 4: Acid → amide → primary amine"},{"type":"ul","items":["R-COOH → R-COCl → R-CONH₂ → R-CH₂-NH₂.","Step 1: acid → acyl chloride (SOCl₂).","Step 2: acyl chloride + NH₃ → primary amide.","Step 3: amide reduction with LiAlH₄ in dry ether → primary amine.","Useful for converting an acid to an amine with the same number of carbons."]},{"type":"callout","title":"Plan your synthesis","body":"When given a multi-step problem, work BACKWARDS from the product. Identify which functional group transformation is needed at each step. Carboxylic acids and acyl chlorides are common intermediates because so many things connect through them."},{"type":"takeaway","items":["Alcohol → acid → acyl chloride → ester (preferred ester route).","Halogenoalkane → nitrile → acid (chain extension by 1 C).","Aldehyde → cyanohydrin → 2-hydroxy acid.","Acid → acyl chloride → amide → primary amine."]}]},{"id":"ca12","title":"Exam Technique & Common Pitfalls","blocks":[{"type":"p","text":"Carboxylic acid questions test acidity, derivative interconversions, and multi-step synthesis. Here are the patterns."},{"type":"h","text":"Acidity comparisons — the must-have argument"},{"type":"ul","items":["ALWAYS argue from CONJUGATE BASE STABILITY.","Carboxylate: charge spread over 2 equivalent O atoms (resonance) — very stable.","Phenoxide: charge in ring + on O, less effective resonance — less stable.","Alkoxide (alcohol's base): charge localised on one O, +I from alkyl destabilises.","Chlorinated acids: more Cl = more stabilisation of carboxylate via –I → stronger acid.","Distance matters: Cl on the C adjacent to COOH is most effective."]},{"type":"h","text":"Choosing the right ester route"},{"type":"ul","items":["For HIGH YIELD ester: use acyl chloride + alcohol (irreversible, fast).","For BULK/cheap esters: acid + alcohol with conc. H₂SO₄ (reversible — use excess).","For PHENYL esters: use acyl chloride (acid + phenol is too slow because phenol is a weaker nucleophile)."]},{"type":"h","text":"Common mistakes"},{"type":"ul","items":["Saying \\"acyl chlorides + water gives an ester\\" — they give the ACID, not an ester. Esters need an alcohol.","Forgetting that base hydrolysis of esters is IRREVERSIBLE (because the carboxylate ion forms — base sucks up the acid product).","Saying \\"NaBH₄ reduces carboxylic acids\\" — it does NOT. Use LiAlH₄.","Using PCl₅ to make an acid → ester directly. PCl₅ converts acid to ACYL CHLORIDE, not to ester.","Forgetting that the iodoform test for CH₃-CO- substructure works for methyl ketones, NOT for carboxylic acids."]},{"type":"h","text":"Equations to memorise"},{"type":"ul","items":["Acid + Na₂CO₃: 2R-COOH + Na₂CO₃ → 2R-COO⁻Na⁺ + CO₂↑ + H₂O. (Diagnostic test.)","Acid + alcohol ⇌ ester + water. (Conc. H₂SO₄, reflux.)","Acyl chloride + alcohol → ester + HCl. (Fast, irreversible.)","Acyl chloride + NH₃ → primary amide + NH₄Cl.","Ester + NaOH → carboxylate + alcohol. (Saponification, irreversible.)","Nitrile + H₂O + HCl → carboxylic acid + NH₄Cl. (Reflux, chain +1 C.)"]},{"type":"callout","title":"The acidity ladder","body":"pKa: trichloroethanoic acid 0.66 < dichloro 1.30 < chloro 2.86 < methanoic 3.75 < ethanoic 4.76 < propanoic 4.87 < phenol 10 < water 14 < ethanol 16. Memorise the order: carboxylic acids >> phenols > water > alcohols. Within carboxylic acids: more –I substituents (Cl, F) = stronger acid."},{"type":"takeaway","items":["Argue acidity from conjugate base stability.","Best ester route: acyl chloride + alcohol.","Distinguishing tests: Na₂CO₃ for acid (CO₂); NaOH for phenol/acid; Na for any OH.","Acyl chlorides > esters > amides in reactivity (Cl > OR > NH₂ as leaving groups)."]}]}]}`),norganic:JSON.parse(`{"objectives":["Classify amines as primary, secondary, tertiary, or quaternary; name them by IUPAC and common conventions","Prepare ethylamine by reduction of nitriles and phenylamine by reduction of nitrobenzene","Account for the relative basicity of ammonia, alkylamines, and phenylamines using inductive and resonance effects","Describe and explain the reactions of phenylamine with aqueous bromine and with nitrous acid","Synthesise azo dyes by diazonium coupling and explain the colour in terms of conjugated π systems","Form amides from acyl chlorides + amines/ammonia and predict products of acid- and base-hydrolysis","Describe amino acid structure and explain zwitterion behaviour, isoelectric point, and titration curves","Form peptide bonds by condensation; predict the products of acid, base, and enzymatic hydrolysis of proteins","Identify nitrogen compounds from a sequence of standard chemical tests"],"chapters":[{"id":"nc1","title":"Amines: Structure & Classification","blocks":[{"type":"p","text":"An amine is an organic compound derived from ammonia (NH₃) by replacing one or more H atoms with hydrocarbon groups (alkyl or aryl). The N still keeps a lone pair, which is the source of every reaction we will meet — basicity, nucleophilic attack, diazotisation, and dye coupling all flow from that single non-bonding pair on N."},{"type":"d","caption":"1°/2°/3° refers to N — count the C atoms attached to nitrogen"},{"type":"h","text":"Classification"},{"type":"ul","items":["Primary (1°) amine: N has TWO H + one R. General formula R–NH₂. Example: ethylamine, CH₃CH₂NH₂.","Secondary (2°): N has ONE H + two R groups. General formula R–NH–R'. Example: dimethylamine, (CH₃)₂NH.","Tertiary (3°): N has NO H + three R groups. General formula R₃N. Example: trimethylamine, (CH₃)₃N.","Quaternary (4°) ammonium salt: N has FOUR R groups + positive charge. General formula [R₄N]⁺X⁻. Example: tetramethylammonium chloride, (CH₃)₄N⁺Cl⁻."]},{"type":"callout","title":"Don't confuse 1°/2°/3° at N with 1°/2°/3° at C","body":"For alcohols and halogenoalkanes, \\"primary/secondary/tertiary\\" describes the carbon. For amines, it describes the nitrogen — count groups attached to N, not C. They are different conventions; be careful when describing a compound like 2-aminobutane (it is a 2° alcohol... but a 1° amine, because the N still has two H)."},{"type":"h","text":"Naming"},{"type":"ul","items":["Suffix style: replace the alkane \\"-e\\" with \\"-amine\\": methanamine, ethanamine, propan-1-amine. (IUPAC 2013 preferred.)","Older \\"-ylamine\\" style is still acceptable: methylamine, ethylamine, propylamine.","Aromatic 1° amines: phenylamine (C₆H₅NH₂), often called aniline. The systematic name is benzenamine but is rarely used in exams.","For 2°/3°: list groups alphabetically before \\"-amine\\". e.g. N-methylethanamine (CH₃CH₂NHCH₃) — the \\"N-\\" specifies that methyl is on the nitrogen, not on a carbon."]},{"type":"h","text":"Why the lone pair matters"},{"type":"ul","items":["Basicity: the lone pair accepts H⁺. R₃N: + H⁺ → R₃NH⁺.","Nucleophilicity: the lone pair attacks electrophilic C (e.g. C=O of acyl chlorides) → amides.","In phenylamine, the lone pair partially delocalises INTO the ring — this single fact explains why the amine is a weak base AND why the ring is highly activated to electrophiles. We will return to this in chapter 3."]},{"type":"takeaway","items":["Amine = derivative of NH₃; classify by number of groups on N.","Names: -amine suffix or -ylamine; phenylamine = C₆H₅NH₂.","The N lone pair drives every reaction we will study.","1°/2°/3° at N is NOT the same convention as at C — careful."]}]},{"id":"nc2","title":"Preparation of Amines","blocks":[{"type":"p","text":"There are two preparations the syllabus expects you to recall in detail: (a) reduction of a nitrile to a primary aliphatic amine, and (b) reduction of nitrobenzene to phenylamine. A third route — substitution of a halogenoalkane by ammonia — is mentioned for completeness but is rarely the preferred method because it produces mixtures."},{"type":"d","caption":"Three routes — A and B are the syllabus-essential ones"},{"type":"h","text":"Route A — reduction of a nitrile (chain extension by 1 C)"},{"type":"ul","items":["Equation: R–C≡N + 4[H] → R–CH₂–NH₂.","Reagent option 1: LiAlH₄ in dry ether (very strong reducer, anhydrous conditions because LiAlH₄ reacts violently with water).","Reagent option 2: H₂(g) with a Ni catalyst at high temperature and pressure (industrial; cheaper than LiAlH₄ for scale).","Why this matters synthetically: nitriles are easily made from halogenoalkanes (R–X + KCN/ethanol → R–CN). So R–X → R–CN → R–CH₂–NH₂ extends the carbon chain by one. e.g. CH₃CH₂Br → CH₃CH₂CN → CH₃CH₂CH₂NH₂ (3-carbon amine from 2-carbon halide)."]},{"type":"h","text":"Route B — reduction of nitrobenzene to phenylamine"},{"type":"ul","items":["Equation: C₆H₅–NO₂ + 6[H] → C₆H₅–NH₂ + 2H₂O.","Reagents: tin (Sn) or iron (Fe) with concentrated HCl, reflux. The acid is essential — it converts the metal to active reducing species. The reduction proceeds through nitrosobenzene (Ar-N=O) and phenylhydroxylamine (Ar-NHOH) intermediates, but you do not need to know these for ZIMSEC.","Workup: the initial product is the soluble salt C₆H₅NH₃⁺Cl⁻ (phenylammonium chloride); add NaOH(aq) afterwards to liberate the free amine, which is then steam-distilled out.","Industrial method: H₂/Ni catalyst, again at high T,P — cleaner and safer at scale.","Significance: nitrobenzene is itself made by nitrating benzene (HNO₃/H₂SO₄). So benzene → nitrobenzene → phenylamine puts an –NH₂ group on a benzene ring — a hugely useful first step in dye and pharmaceutical synthesis."]},{"type":"h","text":"Route C — halogenoalkane + ammonia (mentioned, not preferred)"},{"type":"ul","items":["Equation: R–X + 2NH₃ → R–NH₂ + NH₄X.","Conditions: excess NH₃ in ethanol, sealed tube, heat.","Problem: the product 1° amine is itself nucleophilic and competes with NH₃ for the next halogenoalkane molecule, giving 2° amine, then 3°, then quaternary salt. The result is a mixture.","Excess NH₃ pushes towards the 1° amine but the route is rarely clean. Routes A and B are preferred for that reason."]},{"type":"callout","title":"Synthesis lever — chain extension","body":"Of all the routes, the nitrile route is most useful in multi-step synthesis because it adds a carbon. Whenever a question gives you an alcohol or halogenoalkane and asks for an amine with one more carbon, plan: alcohol → halogenoalkane → nitrile → amine."},{"type":"takeaway","items":["A: R–CN + 4[H] → R–CH₂–NH₂. Use LiAlH₄/dry ether or H₂/Ni. Adds one C.","B: C₆H₅NO₂ + 6[H] → C₆H₅NH₂. Use Sn/conc.HCl, then NaOH (or H₂/Ni).","C: R-X + NH₃ — gives mixtures, not preferred.","Both A and B work because the N–O or N≡C bond is reducible; the C–H bonds in the rest of the molecule are unaffected by mild reducing agents."]}]},{"id":"nc3","title":"Basicity of Amines","blocks":[{"type":"p","text":"All amines are bases — they accept H⁺ via the N lone pair. But not all amines are equally basic. The trend alkylamine > NH₃ > phenylamine spans about six orders of magnitude in pKb, and the entire reasoning for the syllabus rests on one idea: the AVAILABILITY of the lone pair on N."},{"type":"d","caption":"pKb data: smaller pKb = stronger base"},{"type":"h","text":"How an amine acts as a base"},{"type":"ul","items":["In water: R–NH₂ + H₂O ⇌ R–NH₃⁺ + OH⁻ (the lone pair grabs H⁺, leaving OH⁻ behind).","With acid: R–NH₂ + HCl → R–NH₃⁺Cl⁻ (an alkylammonium salt, ionic, water-soluble, often a white solid).","Strength is measured by Kb = [R-NH₃⁺][OH⁻] / [R-NH₂], and pKb = −log₁₀ Kb. Smaller pKb = stronger base."]},{"type":"h","text":"Why alkylamines are stronger than ammonia"},{"type":"d","caption":"Alkyl groups push electrons onto N; the aryl ring pulls them away"},{"type":"ul","items":["Alkyl groups are weakly electron-donating (positive inductive effect, +I). They push electron density TOWARDS the N atom.","More electron density on N = more available lone pair = better at accepting H⁺ = stronger base.","Methylamine (pKb 3.36) and ethylamine (pKb 3.27) are both about 30× more basic than ammonia (pKb 4.75).","In the gas phase the trend continues: 3° > 2° > 1° amine. In aqueous solution, hydrogen-bonding stabilisation of the protonated amine partly cancels the trend, so pKb values for 1°/2°/3° in water are similar — exam answers focus on the simple +I argument."]},{"type":"h","text":"Why phenylamine is weaker than ammonia"},{"type":"ul","items":["Phenylamine: pKb ≈ 9.42 — about 10⁵ times WEAKER than methylamine and ~10⁴ weaker than NH₃.","Mechanism: the N lone pair is in a p-type orbital that overlaps with the π system of the benzene ring. This delocalises the lone pair INTO the ring, lowering its energy.","A delocalised lone pair is much less available to bond H⁺ — it is \\"tied up\\" in the aromatic system. So phenylamine is a poor base.","Consequence (ring side): the same delocalisation injects electron density INTO the ring. The ring is now strongly activated towards electrophilic substitution — chapter 4 picks this up."]},{"type":"callout","title":"One cause, two consequences","body":"Memorise this pattern. Delocalisation of the N lone pair into the benzene ring (1) weakens phenylamine as a base AND (2) activates the ring for halogenation/nitration. The same explanation answers both halves of an exam question."},{"type":"h","text":"Salt formation — useful chemistry, useful solubility"},{"type":"ul","items":["Phenylamine is barely soluble in water but dissolves in dilute HCl as the ammonium salt: C₆H₅NH₂ + HCl → C₆H₅NH₃⁺Cl⁻.","Ethylamine, in contrast, is fully water-miscible because of strong N–H···O–H hydrogen bonding to water.","Ammonium salts can be turned back into the free amine with NaOH(aq): C₆H₅NH₃⁺Cl⁻ + NaOH → C₆H₅NH₂ + NaCl + H₂O.","This pH-dependent solubility is exploited industrially to separate amines from non-basic organics: \\"shake with HCl, run off the aqueous, basify with NaOH, recover the amine\\"."]},{"type":"takeaway","items":["alkylamine > NH₃ > phenylamine. Always.","Alkyl: +I donates e⁻ → lone pair more available → stronger base.","Aryl: lone pair delocalised into ring → less available → weaker base.","The same delocalisation activates the ring (relevant in chapter 4).","Amines + acid → salts (water-soluble). NaOH liberates the free amine."]}]},{"id":"nc4","title":"Reactions of Phenylamine","blocks":[{"type":"p","text":"Phenylamine has two faces: a weak base at N, and a highly activated benzene ring. Two named reactions in the ZIMSEC syllabus probe each face. Bromination probes the activated ring; reaction with nitrous acid probes the N–H bond and gives access to the rich diazonium chemistry of chapter 5."},{"type":"d","caption":"Two named reactions: bromine (ring) and HNO₂ (N–H)"},{"type":"h","text":"Reaction 1 — with aqueous bromine"},{"type":"ul","items":["Equation: C₆H₅NH₂ + 3Br₂ → 2,4,6-tribromophenylamine + 3HBr.","Conditions: simply add Br₂(aq) at room temperature. NO halogen carrier (no FeBr₃ or AlBr₃) is required — the ring is so activated that bromine attacks unaided.","Observation: the orange Br₂(aq) is decolourised; a white precipitate of 2,4,6-tribromophenylamine forms.","Why three substitutions? The –NH₂ group activates 2,4,6 positions. Each bromination still leaves the ring activated enough for the next. Stopping at mono- or di-substitution is impractical without protecting the N first (e.g. as the amide).","Compare with benzene itself: benzene + Br₂ requires FeBr₃ catalyst and gives mainly mono-substituted product. The contrast is the activating effect of –NH₂.","Diagnostic value: a white ppt with Br₂(aq) at RT is good evidence for an aromatic 1° amine (or for phenol — distinguish using HNO₂)."]},{"type":"h","text":"Reaction 2 — with nitrous acid (HNO₂) below 10 °C"},{"type":"ul","items":["Nitrous acid is unstable and is generated in situ: NaNO₂(aq) + HCl(aq) → HNO₂ + NaCl. The mixture must be ICE-COLD throughout (typically 0–5 °C).","Equation: C₆H₅NH₂ + HNO₂ + HCl → C₆H₅N₂⁺Cl⁻ + 2H₂O.","Product: benzenediazonium chloride (sometimes written PhN₂⁺Cl⁻). It is a pale yellow soluble salt — but only stable below 10 °C. Above this it decomposes.","Decomposition above 10 °C: C₆H₅N₂⁺Cl⁻ + H₂O → C₆H₅OH + N₂↑ + HCl. So warm the salt and you get phenol plus a stream of nitrogen bubbles. This is a useful synthesis of phenol from phenylamine.","Mechanism summary: HNO₂ in acidic conditions provides the nitrosating agent NO⁺ (or H₂NO₂⁺). It attacks the N of the amine, and a sequence of proton-transfers and dehydration yields the diazonium ion Ar–N⁺≡N."]},{"type":"h","text":"Comparing 1° aliphatic vs 1° aromatic amines with HNO₂"},{"type":"ul","items":["1° aliphatic amine (e.g. ethylamine) + HNO₂: gives an unstable aliphatic diazonium that decomposes immediately at any temperature, releasing N₂ as a steady stream of gas. Other products are messy: alkene, alcohol, halide.","1° aromatic amine (e.g. phenylamine): aromatic diazonium is STABLE in cold solution because the +N≡N group is stabilised by overlap with the ring π system. This stability is what makes coupling chemistry possible.","In short: cold HNO₂ + amine, watch for nitrogen gas. Steady gas → 1° aliphatic. No gas (cold), but a clear pale-yellow solution that effervesces only on warming → 1° aromatic."]},{"type":"callout","title":"Diazotisation","body":"The conversion of a 1° aromatic amine to a diazonium salt using HNO₂ at <10 °C. This is the gateway to azo dyes (chapter 5)."},{"type":"takeaway","items":["Aqueous bromine: 3 substitutions to give 2,4,6-tribromo-, room T, no catalyst, white ppt.","HNO₂ < 10 °C: forms benzenediazonium chloride C₆H₅N₂⁺Cl⁻.","Same reagent > 10 °C: decomposes to phenol + N₂.","Aromatic diazonium is stable cold (ring-stabilised); aliphatic is not."]}]},{"id":"nc5","title":"Diazonium Coupling & Dyes","blocks":[{"type":"p","text":"The benzenediazonium ion is a strongly electrophilic cation, but it is a comparatively gentle one — only electron-RICH aromatic rings (phenoxide ions, dialkylanilines, naphthols) react with it. The product is a coloured azo (–N=N–) compound and this is the chemistry behind a large fraction of synthetic dyes."},{"type":"d","caption":"Diazotise cold, then couple — two steps to a dye"},{"type":"h","text":"Step 1: diazotise (chapter 4 recap)"},{"type":"ul","items":["Phenylamine + NaNO₂ + HCl, in an ice bath (< 10 °C) → C₆H₅N₂⁺Cl⁻.","Keep this solution COLD throughout — warming destroys the diazonium and you lose the synthesis."]},{"type":"h","text":"Step 2: couple with phenol in alkali"},{"type":"ul","items":["Mix the cold diazonium solution with phenol that has been DISSOLVED IN NaOH(aq) (so phenol is present as the more reactive phenoxide, C₆H₅O⁻).","Equation: C₆H₅N₂⁺ + C₆H₅O⁻ → 4-hydroxyazobenzene  (HO–C₆H₄–N=N–C₆H₅).","Observation: an immediate orange precipitate forms.","Why phenoxide and not phenol? –O⁻ is a stronger ring activator than –OH. The diazonium is a weak electrophile and needs all the help it can get.","Why position 4 (para)? Phenoxide directs ortho/para; the bulky diazonium prefers para to avoid steric clash with –O⁻."]},{"type":"h","text":"Why is it coloured? — a quick chromophore picture"},{"type":"ul","items":["The –N=N– bond joins two aromatic rings into one extended π system. The system has many close-spaced π and π* energy levels.","Some of the π → π* transitions now correspond to wavelengths in the VISIBLE range (rather than UV, as for benzene alone).","The molecule absorbs visible light at one wavelength and we see the COMPLEMENTARY colour. e.g. absorbs blue → looks orange.","Adding electron-donating or electron-withdrawing substituents to either ring shifts the absorption — that is how the same coupling reaction generates dozens of distinct dye colours."]},{"type":"h","text":"Important industrial azo dyes"},{"type":"ul","items":["Methyl orange: a sulfonate-bearing azo dye, used as a pH indicator (red below pH 3.1, yellow above pH 4.4).","Sunset yellow FCF (E110): food colouring.","Para red: textile dye, the first synthetic azo dye, made on factory scale from 1875.","Many azo dyes have been replaced or banned because of toxicology concerns (some metabolise to carcinogenic aromatic amines) — but the chemistry is still the foundation of the dye industry."]},{"type":"callout","title":"Coupling — when does it work?","body":"Diazonium ion is a WEAK electrophile. It only attacks rings activated by strong donors (–O⁻, –NR₂, –OH). Plain benzene does not react. The coupling reaction will fail unless the partner ring is electron-rich."},{"type":"h","text":"Other diazonium reactions (overview)"},{"type":"ul","items":["Hydrolysis (warming in water): → phenol + N₂↑ + HCl. (covered in chapter 4)","These together make diazonium salts the most versatile aromatic intermediate in organic synthesis: from one 1° aromatic amine you can reach phenols, halides, nitriles, and dyes."]},{"type":"takeaway","items":["Cold diazonium + alkaline phenol → orange azo dye.","Coupling needs an activated ring (phenoxide, dialkylaniline).","Colour comes from extended π system across –N=N–.","Diazonium chemistry connects amines to phenols, dyes, and many other aromatics."]}]},{"id":"nc6","title":"Amides — Structure & Formation","blocks":[{"type":"p","text":"An amide has the general formula R–CO–NHR'. The nitrogen is directly attached to the carbonyl carbon. This single structural feature has dramatic consequences: amides are NOT basic (unlike amines), they have very high boiling points (because of strong N–H hydrogen bonding), and they form the linkage that runs through every protein in every living organism."},{"type":"d","caption":"Amide structure, formation, and key properties"},{"type":"h","text":"Classification by N substitution"},{"type":"ul","items":["1° amide: R–CO–NH₂ (two H on N).","2° amide: R–CO–NH–R' (one H on N, one C). N-substituted.","3° amide: R–CO–NR'R'' (no H on N).","Naming for 1°: replace –oic acid with –amide. Ethanoic → ethanamide (CH₃CONH₂).","For 2°/3°: prefix groups attached to N with \\"N-\\". e.g. CH₃CONHCH₃ = N-methylethanamide."]},{"type":"h","text":"Formation — the acyl chloride route"},{"type":"ul","items":["The standard preparation in the syllabus: react an acyl chloride with ammonia or a primary amine.","With NH₃: R–COCl + 2NH₃ → R–CONH₂ + NH₄Cl. The first NH₃ is the nucleophile; the second mops up HCl as NH₄Cl. White solid product (1° amide).","With R'NH₂: R–COCl + 2R'NH₂ → R–CONHR' + R'NH₃⁺Cl⁻. Forms an N-substituted (2°) amide. The second equivalent of amine acts as a base.","Conditions: room temperature, often in dry ether or DCM. The reactions are vigorous because acyl chlorides are highly reactive (revisit OC-18, chapter 8).","Less commonly: heating an ammonium salt — CH₃COO⁻NH₄⁺ → CH₃CONH₂ + H₂O. Industrial but slow and impractical at lab scale."]},{"type":"h","text":"Why amides are NOT basic"},{"type":"ul","items":["In an amine, the N lone pair is freely available to bond H⁺ → basic.","In an amide, the N is bonded to the carbonyl C. The N lone pair delocalises INTO the C=O. The effective electron density on N is reduced.","Pictorially: the N–C bond is partially double; the C=O is partially single. The lone pair is shared with C and not free for H⁺.","Consequence: amides have pKb around 15–17 (essentially neutral), not 3–9 like amines. They will not turn red litmus blue. They will not protonate with dilute HCl in a useful way.","A common exam check: \\"Why is propan-1-amine basic but propanamide is not?\\" — answer: amide N lone pair is delocalised into the C=O."]},{"type":"h","text":"Physical properties"},{"type":"ul","items":["Most amides are solids at RT (even small ones — methanamide is a liquid, but ethanamide melts at 81 °C and boils at 222 °C).","High m.p./b.p. compared to alcohols of similar Mr: each amide has TWO N-H bonds AND a strong C=O acceptor — extensive 3D hydrogen bonding network.","Soluble in water for small amides (H-bond donors and acceptors); solubility falls off with chain length.","Cyclic amides (lactams) and the polyamides we will meet in OC-20 are essentially long chains of amide groups joined together."]},{"type":"callout","title":"Peptide bond","body":"A peptide bond is just an amide bond, but the term is used when it joins two amino acid residues. Same chemistry, same restricted N rotation, same delocalisation. We will pick this up in chapter 10."},{"type":"takeaway","items":["Amide = R–CO–N. Best made from R-COCl + amine/NH₃.","NOT basic — N lone pair delocalised into C=O.","High m.p./b.p. — strong intermolecular H-bonding.","Same chemistry as the peptide bond in proteins."]}]},{"id":"nc7","title":"Hydrolysis of Amides","blocks":[{"type":"p","text":"Amides are surprisingly stable — they need vigorous acid OR base + heat to hydrolyse. This stability is exactly what proteins require: a peptide chain must not fall apart in your bloodstream. But under harsh conditions the C–N bond does break, and the products tell you what was on either side of the original bond."},{"type":"d","caption":"Acid (left) and base (right) hydrolysis — different products"},{"type":"h","text":"Acid hydrolysis"},{"type":"ul","items":["Equation: R–CONH₂ + H₂O + HCl → R–COOH + NH₄Cl.","Conditions: dilute HCl (or dilute H₂SO₄), reflux for 30–60 min.","Products: a carboxylic acid + an ammonium salt. Note the HCl ends up in the NH₄⁺Cl⁻ salt.","For an N-substituted amide: R–CONHR' + H₂O + HCl → R–COOH + R'NH₃⁺Cl⁻ (the amine is recovered as its ammonium salt)."]},{"type":"h","text":"Base hydrolysis"},{"type":"ul","items":["Equation: R–CONH₂ + NaOH → R–COO⁻Na⁺ + NH₃↑.","Conditions: NaOH(aq), reflux for 30–60 min.","Products: a carboxylate SALT (not the free acid — NaOH consumes any acid that forms) + ammonia gas, which can be detected by its smell or by turning damp red litmus paper blue.","For N-substituted: R–CONHR' + NaOH → R–COO⁻Na⁺ + R'NH₂ (the free amine, not the salt — NaOH ensures the basic form)."]},{"type":"h","text":"Diagnostic value"},{"type":"ul","items":["NH₃ evolution on heating with NaOH(aq) is a strong test for an AMIDE. Compare: amides give NH₃ on heating with alkali, but amines do not — amines simply remain as R-NH₂ (already a free amine, it is not \\"released\\" by NaOH).","However, ammonium salts of organic acids (e.g. CH₃COO⁻NH₄⁺) will also give off NH₃ with NaOH. To distinguish: a true amide is neutral (no smell of vinegar / no acid character on its own)."]},{"type":"h","text":"Why amide hydrolysis is slow"},{"type":"ul","items":["The C of the amide is much less electrophilic than the C of an ester or acyl chloride — because the N pushes electron density onto C via the same delocalisation that explains non-basicity.","Also, the leaving group from the tetrahedral intermediate is RNH⁻ or NH₂⁻ — very poor leaving groups, requiring acid (to protonate to RNH₂ or NH₃, which leave better) or vigorous base + heat to drive the reaction.","Practical consequence in the body: peptide bonds in proteins survive blood pH and 37 °C unaided — but specific protease enzymes accelerate hydrolysis at the right places, by ~10⁹ fold."]},{"type":"callout","title":"Acid vs base hydrolysis — predict the products","body":"Acid: amine emerges as the salt R-NH₃⁺. Base: amine emerges as the free amine R-NH₂. The acid traps the basic product; the base traps the acidic product. This pattern repeats for esters too."},{"type":"takeaway","items":["Acid: R-CONH₂ + HCl → R-COOH + NH₄Cl.","Base: R-CONH₂ + NaOH → R-COO⁻Na⁺ + NH₃↑.","Both need REFLUX — amide is the most stable acyl derivative.","NH₃ evolution with NaOH = amide test."]}]},{"id":"nc8","title":"Amino Acids","blocks":[{"type":"p","text":"An α-amino acid has both an amino group (–NH₂) and a carboxylic acid group (–COOH) attached to the same carbon, called the α-carbon. The general formula is H₂N–CHR–COOH, where R is the side chain. There are 20 standard α-amino acids; their side chains R differ in size, polarity, charge, and reactivity, and these differences determine the structure and function of every protein."},{"type":"d","caption":"The α-amino acid skeleton with R = side chain"},{"type":"h","text":"The α-carbon is chiral (with one exception)"},{"type":"ul","items":["For 19 of the 20 standard amino acids, the α-C has FOUR different groups attached: H, NH₂, COOH, R. So it is a chiral centre, and the molecule has two enantiomers (mirror images) called L and D.","Glycine (R = H) is the exception: now the α-C has TWO H atoms, so it is not chiral.","Biology uses ONLY L-amino acids in proteins. The reasons go back to the chemistry of the genetic code and to early biochemistry; the consequence for us is that proteins have a definite handedness.","Optical rotation: L-amino acids rotate plane-polarised light. Some happen to be levorotatory (–), some dextrorotatory (+); \\"L\\" refers to a stereochemical label, not the sign."]},{"type":"h","text":"Side chains R define the amino acid"},{"type":"ul","items":["Non-polar (hydrophobic): glycine (R=H), alanine (CH₃), valine ((CH₃)₂CH-), leucine, isoleucine, methionine, phenylalanine. These cluster in protein interiors away from water.","Polar uncharged: serine (CH₂OH), threonine, asparagine, glutamine, cysteine (CH₂SH). They form hydrogen bonds.","Acidic side chains: aspartate (CH₂COOH), glutamate (CH₂CH₂COOH). At physiological pH these are deprotonated, –COO⁻.","Basic side chains: lysine, arginine, histidine. These are protonated at physiological pH, –NH₃⁺ etc.","Aromatic: phenylalanine, tyrosine, tryptophan.","Special: proline (cyclic, the N is in a ring), cysteine (forms disulfide bridges, S–S, between residues)."]},{"type":"h","text":"Naming and abbreviations"},{"type":"ul","items":["Each amino acid has a common name (glycine, alanine), a 3-letter abbreviation (Gly, Ala), and a single-letter code (G, A).","IUPAC names exist (glycine = aminoethanoic acid; alanine = 2-aminopropanoic acid) but are rarely used in practice.","The 3-letter and 1-letter codes are how protein sequences are written. e.g. \\"Met-Lys-Val...\\" or \\"MKV...\\" for the start of a protein."]},{"type":"h","text":"Why amino acids are unusual physically"},{"type":"ul","items":["Amino acids in pure form melt at very high temperatures (often > 200 °C, with decomposition).","They are crystalline solids, water-soluble, but barely soluble in non-polar solvents.","They have very low vapour pressure — they do not behave like volatile organic molecules.","These properties resemble those of ionic salts, NOT typical organics. The reason is that in the solid and in water they exist as ZWITTERIONS — chapter 9."]},{"type":"callout","title":"α-amino acid","body":"An organic compound containing both a carboxylic acid (–COOH) and an amino group (–NH₂) on adjacent carbons. The α-position is the carbon next to the –COOH group."},{"type":"takeaway","items":["General formula: H₂N–CHR–COOH. The R defines which amino acid.","α-C is chiral except in glycine; biology uses L only.","20 standard amino acids; classified by side chain.","Solid m.p. > 200 °C, water-soluble, low volatility — ionic-like behaviour."]}]},{"id":"nc9","title":"Zwitterions & Acid-Base Behaviour","blocks":[{"type":"p","text":"A zwitterion is a single molecule that carries a positive charge AND a negative charge in different places — net zero charge but full ionic separation. Amino acids are the textbook example. Their acid (–COOH) and base (–NH₂) groups are on the same molecule, and the acid protonates the base internally. This explains the high melting points and water solubility we noted in chapter 8 and gives amino acids a pH-dependent behaviour you must master."},{"type":"d","caption":"Three forms of an amino acid as pH changes"},{"type":"h","text":"Why a zwitterion forms"},{"type":"ul","items":["In a typical amino acid, –COOH has pKa ≈ 2.3 and the –NH₃⁺ on the α-N has pKa ≈ 9.6. (For glycine specifically: pKa₁ = 2.34, pKa₂ = 9.60.)","At neutral pH (7), the –COOH is well above its pKa — fully deprotonated to –COO⁻.","At pH 7, the –NH₃⁺ form is well below its pKa — protonated to –NH₃⁺.","The MOST stable form at neutral pH is therefore both ionised: H₃N⁺–CHR–COO⁻. This is the zwitterion.","There is no covalent change — just intramolecular proton transfer from –COOH to –NH₂."]},{"type":"h","text":"pH-dependent behaviour"},{"type":"ul","items":["At LOW pH (strongly acidic, pH ≪ pKa₁): both groups protonated. Form: H₃N⁺–CHR–COOH. Net charge +1 (cation).","At INTERMEDIATE pH around pI: zwitterion. H₃N⁺–CHR–COO⁻. Net charge 0.","At HIGH pH (strongly basic, pH ≫ pKa₂): both groups deprotonated. Form: H₂N–CHR–COO⁻. Net charge −1 (anion).","In an electric field, the cation (low pH) migrates to the cathode; the anion (high pH) migrates to the anode; the zwitterion at pI does not migrate. This is the principle behind electrophoresis."]},{"type":"h","text":"Isoelectric point (pI)"},{"type":"ul","items":["Definition: the pH at which the amino acid carries NO net charge (the zwitterion form predominates).","For amino acids with neutral side chains: pI = (pKa₁ + pKa₂) / 2. e.g. glycine pI = (2.34 + 9.60)/2 = 5.97.","For acidic side chains (Asp, Glu): pI is LOWER (around 3) because there are two acidic groups.","For basic side chains (Lys, Arg, His): pI is HIGHER (around 9–11) because there are two basic groups.","Practical use: at its pI, an amino acid is least soluble in water (no net charge to attract water) — separation by isoelectric precipitation."]},{"type":"h","text":"Titration curve"},{"type":"d","caption":"Two pKa values give two buffer plateaus"},{"type":"ul","items":["Start at low pH with the cation. Add NaOH gradually.","First buffer plateau around pH = pKa₁: removing the proton from –COOH.","Sharp jump through pI: the zwitterion dominates.","Second buffer plateau around pH = pKa₂: removing the proton from –NH₃⁺.","Continue: end with the anion form.","For amino acids with ionisable side chains, expect a third buffer plateau at the side-chain pKa."]},{"type":"h","text":"Why crystals are high-melting"},{"type":"ul","items":["In the solid, amino acids pack as zwitterions. The crystal is held together by strong electrostatic attractions between –NH₃⁺ and –COO⁻ on neighbouring molecules.","These ionic interactions are much stronger than the dipole-dipole or H-bond interactions in non-zwitterionic organic solids.","Consequence: m.p. > 200 °C (often with decomposition before melting), low volatility, low solubility in non-polar solvents but high solubility in water."]},{"type":"callout","title":"Predict the form: compare pH to pI","body":"pH ≪ pI → cation (positive). pH = pI → zwitterion (neutral). pH ≫ pI → anion (negative). This rule is enough to answer \\"What is the predominant form of glycine at pH 4?\\" — answer: pH 4 < pI 5.97, so the cation H₃N⁺–CH₂–COOH dominates (more precisely, a mix of cation and zwitterion)."},{"type":"takeaway","items":["Zwitterion: H₃N⁺–CHR–COO⁻, full ⁺/⁻ separation, net zero.","Forms because pKa₁ (COOH) ≈ 2 and pKa₂ (NH₃⁺) ≈ 10.","pI = (pKa₁ + pKa₂)/2 for neutral side chains.","pH < pI → cation; pH > pI → anion. Useful in electrophoresis."]}]},{"id":"nc10","title":"Peptides & Proteins","blocks":[{"type":"p","text":"When the –COOH of one amino acid joins the –NH₂ of another, with loss of water, the product is a dipeptide. Repeat the process and you build a polypeptide — an unbranched chain of amino acids joined head-to-tail by amide (peptide) bonds. Proteins are simply long polypeptides folded into specific 3D shapes."},{"type":"d","caption":"Two amino acids → dipeptide + H₂O"},{"type":"h","text":"Forming the peptide bond"},{"type":"ul","items":["General reaction: H₂N–CHR–COOH + H₂N–CHR'–COOH → H₂N–CHR–CO–NH–CHR'–COOH + H₂O.","The –COOH of one residue and the –NH₂ of the next condense; one H₂O is released per bond formed.","This is just amide formation. In the lab it requires activation (e.g. via acyl chloride) — direct condensation is too slow at room temperature. In cells, ribosomes catalyse it with enzymes and ATP.","A dipeptide has ONE peptide bond. A tripeptide has two peptide bonds. A polypeptide of n residues has (n − 1) peptide bonds.","Convention: the chain has an N-terminus (free –NH₂) on the LEFT and a C-terminus (free –COOH) on the RIGHT. The order matters — Gly-Ala is different from Ala-Gly."]},{"type":"h","text":"Levels of protein structure (overview)"},{"type":"ul","items":["Primary structure: the sequence of amino acid residues, written from N-terminus to C-terminus. Encoded by DNA via the genetic code.","Secondary structure: regular folding patterns formed by H-bonds between –C=O and N–H of the backbone. The two main motifs are the α-helix (right-handed coil) and the β-pleated sheet (extended strands H-bonded side-by-side).","Tertiary structure: the overall 3D fold of one polypeptide, stabilised by side-chain interactions — H-bonds, ionic bridges (–COO⁻···⁺H₃N–), van der Waals, hydrophobic clustering, and –S–S– disulfide links between cysteines.","Quaternary structure: assembly of two or more separate polypeptide subunits into one functional protein (haemoglobin has 4 subunits, for instance)."]},{"type":"h","text":"Why peptide bonds are special"},{"type":"ul","items":["The peptide bond is partially double in character — the N lone pair delocalises into the C=O. So the bond is shorter than a typical C–N single bond and rotation around it is restricted.","Six atoms — Cα, C=O, N, H, Cα' (and the H on N, the O on C) — lie in approximately one plane.","This planarity constrains protein folding: only the backbone bonds either side of the peptide unit can rotate (the φ and ψ angles).","It also makes peptide bonds resistant to hydrolysis under physiological conditions — exactly what is needed to keep proteins intact in the body."]},{"type":"callout","title":"Peptide vs protein","body":"\\"Peptide\\" is a general term for a chain of amino acids joined by peptide bonds. \\"Polypeptide\\" usually means a longer chain (often >20 residues). \\"Protein\\" usually means a polypeptide that has folded into its functional 3D shape, often with non-amino-acid co-factors (haem, metal ions, glycans) attached. There is no strict cut-off in length — usage is conventional."},{"type":"h","text":"Drawing dipeptides — exam tip"},{"type":"ul","items":["Question may ask: \\"Draw the structure of the dipeptide Gly-Ala.\\" Always read N-terminus first.","Step 1: write glycine on the left with its –NH₂ free. H₂N–CH₂–CO–.","Step 2: write alanine on the right with its –COOH free. –NH–CH(CH₃)–COOH.","Step 3: join them at the peptide bond shown by –CO–NH–.","Final: H₂N–CH₂–CO–NH–CH(CH₃)–COOH.","For \\"Ala-Gly\\" the order is reversed: H₂N–CH(CH₃)–CO–NH–CH₂–COOH."]},{"type":"takeaway","items":["Peptide bond = amide bond between α-amino acids; loses H₂O.","Direction: N-terminus → C-terminus; the order matters.","Primary structure = sequence; higher orders are folding patterns.","Restricted rotation at the peptide bond shapes the whole protein."]}]},{"id":"nc11","title":"Hydrolysis & Analysis of Proteins","blocks":[{"type":"p","text":"To find out which amino acids make up a protein, we hydrolyse it back to the free residues and identify them by chromatography or electrophoresis. The hydrolysis is the reverse of peptide-bond formation — the conditions are exactly those for amide hydrolysis from chapter 7, scaled up to a polymer. The analysis ties this topic to phase equilibria (AC-22)."},{"type":"d","caption":"Three ways to hydrolyse a protein, then visualise spots"},{"type":"h","text":"Acid hydrolysis"},{"type":"ul","items":["Conditions: ~6 M HCl, sealed tube, 110 °C, 24 hours. (Or microwave-assisted, faster.)","Result: every peptide bond is broken; the protein is reduced to a mixture of free amino acids in their cation form (low pH).","After hydrolysis, neutralise to pI for analysis.","Drawback: tryptophan is destroyed. Asparagine and glutamine lose their side-chain –NH₂ to become aspartate and glutamate. So acid hydrolysis miscounts these four — they need separate determination."]},{"type":"h","text":"Base hydrolysis"},{"type":"ul","items":["Conditions: concentrated NaOH or KOH, reflux.","Drawback: causes RACEMISATION (L → D/L mix) at the α-carbon and destroys some side chains (Ser, Thr, Cys, Arg).","Used mainly when tryptophan content is needed — Trp survives base hydrolysis."]},{"type":"h","text":"Enzymatic hydrolysis"},{"type":"ul","items":["Specific protease enzymes cut at specific peptide bonds.","Trypsin: cleaves on the C-terminal side of lysine (K) and arginine (R).","Chymotrypsin: cleaves on the C-terminal side of large hydrophobic residues (F, W, Y).","Mild conditions (37 °C, neutral pH) — used to map sequences."]},{"type":"h","text":"Separation and detection"},{"type":"ul","items":["Paper chromatography or thin-layer chromatography (TLC): different amino acids have different Rf values in a chosen solvent. (Recall AC-22.)","Electrophoresis: at a chosen pH, amino acids with different pI values acquire different charges and migrate at different rates in an electric field.","Visualisation with NINHYDRIN: spray the chromatogram or gel with ninhydrin solution and warm. Most amino acids give a violet/purple spot. Proline gives a YELLOW spot (a known exception — proline's α-N is in a ring and reacts differently).","Modern variants include HPLC with UV/fluorescence detection and mass spectrometry — touched on in AC-22."]},{"type":"h","text":"Worked sequencing example"},{"type":"ul","items":["Suppose a tetrapeptide P gives, after total acid hydrolysis, equal amounts of Gly, Ala, Lys, Phe.","Trypsin cleaves P after Lys, giving fragments: F1 = (3 residues, contains Lys at C-end) and F2 = (1 residue).","Chymotrypsin cleaves P after Phe, giving fragments: G1 = (2 residues, contains Phe at C-end) and G2 = (2 residues).","Combining the two patterns: only one sequence — Ala-Phe-Gly-Lys — fits both partial digests. (Detail: trypsin gives Ala-Phe-Gly-Lys / nothing... actually trypsin would cut after Lys but Lys is C-terminal so would leave it intact in this case; chymotrypsin would cut after Phe to give Ala-Phe / Gly-Lys.)","This kind of partial-digest jigsaw is the principle behind early protein sequencing methods (Sanger, Edman). Modern methods use mass spec."]},{"type":"callout","title":"Hydrolysis = the reverse of formation","body":"Synthesising peptides loses H₂O at each bond. Hydrolysis ADDS H₂O at each bond. The number of moles of water released or consumed equals the number of peptide bonds, which is (n − 1) for an n-residue peptide."},{"type":"takeaway","items":["Acid hydrolysis: 6 M HCl, reflux 24 h — destroys Trp.","Base hydrolysis: NaOH, reflux — racemises α-C; spares Trp.","Enzymatic: specific cuts, used for sequencing.","Detect free amino acids with ninhydrin (purple; proline yellow).","Separation by chromatography or electrophoresis (AC-22)."]}]},{"id":"nc12","title":"Identification & Synthesis Strategy","blocks":[{"type":"p","text":"This closing chapter consolidates the chemistry of OC-19. Two skills to lock in: (1) given an unknown nitrogen compound, deduce what it is from a sequence of test results; (2) given a starting material, plan a multi-step synthesis to a target nitrogen compound. Both are routine exam tasks and reward rehearsed pattern recognition."},{"type":"d","caption":"Test sequence and decision tree for unknowns"},{"type":"h","text":"Identification — the test sequence to memorise"},{"type":"ul","items":["Step 1: Is it an AMINE? Add HCl. An amine dissolves and forms an ionic salt. (Amides, nitriles, amino acids do not behave as simple bases here.)","Step 2: Is it a 1°/2°/3° amine? Add HNO₂ at < 10 °C. (a) Steady N₂ gas at all temperatures → 1° aliphatic amine. (b) Stable cold solution; warming gives N₂ + phenol-like product → 1° aromatic amine (phenylamine). (c) Yellow oily layer (N-nitroso compound) → 2° amine. (d) No obvious reaction → 3° amine (or amide).","Step 3: Aromatic 1° amine? Confirm with Br₂(aq) at RT — instant white precipitate (2,4,6-tribromophenylamine).","Step 4: Is it an AMIDE? Heat with NaOH(aq). Damp red litmus paper goes blue at the mouth of the tube → NH₃ → amide.","Step 5: Is it an AMINO ACID? Spray with NINHYDRIN, warm. Purple/violet spot → amino acid (yellow → proline, exception)."]},{"type":"h","text":"Synthesis strategy — common chains"},{"type":"ul","items":["Halogenoalkane → 1° amine (chain extension): R–X → R–CN (KCN/EtOH, reflux) → R–CH₂–NH₂ (LiAlH₄/dry ether or H₂/Ni).","Benzene → phenylamine: C₆H₆ → C₆H₅NO₂ (HNO₃/H₂SO₄, 50 °C) → C₆H₅NH₂ (Sn/conc. HCl, then NaOH).","Phenylamine → phenol: C₆H₅NH₂ → C₆H₅N₂⁺Cl⁻ (NaNO₂/HCl, < 10 °C) → C₆H₅OH (warm in water).","Phenylamine → azo dye: diazotise (cold) → couple with phenoxide.","Carboxylic acid → 1° amide: R–COOH → R–COCl (SOCl₂) → R–CONH₂ (NH₃).","1° amide → carboxylic acid (or amine): R–CONH₂ + NaOH/heat → R–COO⁻Na⁺ + NH₃. Acidify to recover R–COOH.","Polypeptide → free amino acids: 6 M HCl, reflux 24 h."]},{"type":"h","text":"Common exam errors to avoid"},{"type":"ul","items":["Saying \\"amides are basic\\". They are NOT — N lone pair delocalised into C=O.","Forgetting the temperature requirement for diazotisation (< 10 °C). Above this you get phenol, not the salt.","Reporting \\"phenylamine + HNO₂ gives N₂\\". No — at low T it gives the diazonium salt; only on warming does N₂ evolve.","Confusing the order of reagents in coupling. Phenol + NaOH FIRST (to make phenoxide), THEN add cold diazonium.","Drawing the zwitterion at pH 1 or pH 13 — at those extremes the cation/anion forms dominate, not the zwitterion.","Quoting \\"alkylamines stronger because they are bigger\\" — molecular size is not the reason; the +I effect is."]},{"type":"callout","title":"Three ideas tie this whole topic together","body":"(1) The N lone pair drives basicity, nucleophilic attack, and dye coupling. (2) Delocalisation of the N lone pair (into a C=O or into a benzene ring) reduces basicity but adds new chemistry. (3) Acid/base behaviour at the same molecule (zwitterion) explains the unusual physical properties of amino acids and gives proteins their charge."},{"type":"takeaway","items":["Test sequence: HCl → HNO₂ → Br₂ → NaOH/heat → ninhydrin.","Chain extension via nitrile is the most common synthesis manoeuvre.","The N lone pair is the key — its availability determines reactivity.","Practice multi-step plans on past papers; the same chains repeat."]}]}]}`),polymer:JSON.parse(`{"objectives":["Distinguish addition from condensation polymerisation in terms of mechanism and atom economy","Describe the free-radical mechanism of addition polymerisation: initiation, propagation, termination","Recognise common addition polymers (polythene, PVC, PP, polystyrene, PTFE) and their uses","Predict the products of condensation polymerisation between diols, diacids and diamines","Describe polyesters (Terylene/PET, PLA) and polyamides (Nylon-6,6, Nylon-6, Kevlar)","Deduce the repeat unit from a given monomer and vice versa","Identify the monomer(s) that gave a particular section of polymer chain","Discuss the environmental implications of plastic use, disposal and recycling"],"chapters":[{"id":"pl1","title":"What is a Polymer?","blocks":[{"type":"p","text":"A polymer is a very large molecule made by joining together many small molecules called monomers. The structure repeats over and over, often hundreds or thousands of times. Polymers are responsible for an enormous range of materials in our daily lives — from plastic bags and clothing fibres to proteins, DNA, and rubber. In this topic we focus on the two main classes of synthetic polymer chemistry: addition polymerisation and condensation polymerisation."},{"type":"d","caption":"Three terms to internalise: polymer, monomer, repeat unit"},{"type":"h","text":"Three definitions to keep straight"},{"type":"ul","items":["Polymer: a large macromolecule (Mr ≈ 10⁴ to 10⁶) built from many small repeat units. e.g. polythene, PVC, nylon.","Monomer: the small molecule that joins together in many copies to form the polymer. e.g. ethene is the monomer for polythene.","Repeat unit: the smallest section of the polymer that, when repeated, generates the whole chain. Always written in square brackets with subscript n: –[A]ₙ–.","Degree of polymerisation, n: the number of repeat units in the chain. Typically 10² to 10⁵."]},{"type":"h","text":"Two ways monomers can join"},{"type":"ul","items":["Addition polymerisation: monomers contain a C=C double bond, which opens to form new C–C single bonds. NO atoms are lost. The polymer has the same empirical formula as the monomer.","Condensation polymerisation: monomers have TWO functional groups each. Each new bond loses a small molecule (H₂O or HCl). The polymer's empirical formula DIFFERS from the monomer's.","Examples we will meet: polythene (addition, from ethene), PVC (addition, from chloroethene), Terylene/PET (condensation polyester), nylon (condensation polyamide), Kevlar (aromatic condensation polyamide)."]},{"type":"h","text":"A note on biological polymers"},{"type":"ul","items":["Proteins are condensation polymers of amino acids — peptide bonds release H₂O at each linkage. Encountered in OC-19.","Polysaccharides (starch, cellulose) are condensation polymers of sugars — glycosidic bonds release H₂O at each linkage.","DNA and RNA are condensation polymers of nucleotides — phosphodiester bonds release H₂O at each linkage.","The same chemistry rules in nature and in factories."]},{"type":"callout","title":"Repeat unit","body":"The smallest section that, repeated n times, gives the polymer chain. Always written in square brackets and subscripted n: –[CH₂CH₂]–ₙ for polythene. Distinct from the monomer (CH₂=CH₂) — the repeat unit has the C=C opened."},{"type":"takeaway","items":["Polymer = macromolecule of repeated small units.","Two main mechanisms: addition (C=C → C–C, no loss) vs condensation (loss of H₂O or HCl per linkage).","Monomer → repeat unit → polymer.","Biological polymers (proteins, polysaccharides, DNA) all use the same condensation logic."]}]},{"id":"pl2","title":"Addition Polymerisation","blocks":[{"type":"p","text":"Addition polymerisation joins alkene monomers head-to-tail to form a long, saturated carbon chain. The C=C double bond opens up; one π-bond breaks, and the electrons end up forming new C–C single bonds to neighbouring monomers. No atoms are lost. Free-radical, cationic, anionic and coordination mechanisms are used industrially; Ziegler–Natta catalysts use coordination polymerisation."},{"type":"d","caption":"Three stages: initiation, propagation, termination"},{"type":"h","text":"Free radical mechanism"},{"type":"ul","items":["Initiation: a peroxide initiator R–O–O–R is heated and breaks homolytically to give two oxy-radicals: R–O–O–R → 2 R–O•.","Propagation step 1: the radical adds to a C=C, forming a new C–O bond and leaving the unpaired electron on the terminal C: R–O• + CH₂=CH₂ → R–O–CH₂–CH₂•.","Propagation step 2: this new radical attacks ANOTHER monomer the same way: R–O–CH₂–CH₂• + CH₂=CH₂ → R–O–CH₂–CH₂–CH₂–CH₂•. The radical chain marches along, adding one monomer at a time.","Termination: two growing chains meet and the unpaired electrons combine: R'–CH₂• + •CH₂–R'' → R'–CH₂–CH₂–R''. Or the chain abstracts a H from elsewhere (chain-transfer).","Each propagation step adds 2 carbon atoms to the chain. The repeat unit has 2 C atoms."]},{"type":"h","text":"Conditions and tuning"},{"type":"ul","items":["Temperature: typically 100–300 °C (high T favours initiation but also termination — there is an optimum).","Pressure: from a few atmospheres to several thousand atmospheres, depending on the polymer. Polythene: low-density (LDPE) made at very high P with branched chains; high-density (HDPE) made at moderate P with Ziegler–Natta catalyst, giving linear chains.","Initiator: organic peroxides for free-radical; transition-metal catalysts (Ti, Al) for Ziegler–Natta.","Chain length depends on the ratio of propagation rate to termination rate. Higher monomer concentration → longer chains."]},{"type":"h","text":"General equation"},{"type":"ul","items":["For a generic substituted alkene CH₂=CHR: n CH₂=CHR → –[CH₂–CHR]–ₙ.","For ethene specifically: n CH₂=CH₂ → –[CH₂–CH₂]–ₙ (polythene).","For propene: n CH₂=CH(CH₃) → –[CH₂–CH(CH₃)]–ₙ (polypropene).","For chloroethene: n CH₂=CHCl → –[CH₂–CHCl]–ₙ (PVC).","For tetrafluoroethene: n CF₂=CF₂ → –[CF₂–CF₂]–ₙ (PTFE/Teflon)."]},{"type":"callout","title":"No atoms lost","body":"In addition polymerisation, the empirical formula of the repeat unit equals the molecular formula of the monomer. Mr of the polymer = n × (Mr of monomer). This is the chemical signature of addition polymerisation. Use it to recognise it in exam questions."},{"type":"takeaway","items":["Addition polymerisation: alkene C=C opens; no atoms lost.","Free radical mechanism: initiation (peroxide), propagation (radical adds to C=C), termination (radicals combine).","Repeat unit has 2 C atoms (the two C of the C=C).","Pressure, temperature, and catalyst control chain length and branching."]}]},{"id":"pl3","title":"Common Addition Polymers","blocks":[{"type":"p","text":"A handful of addition polymers dominate plastic production worldwide. Their properties differ because of one feature only — the substituent on the alkene monomer. Different substituents change packing, intermolecular forces, and crystallinity, giving anything from soft, transparent film to hard, rigid pipe."},{"type":"d","caption":"Five major addition polymers and their uses"},{"type":"h","text":"Polythene (polyethene)"},{"type":"ul","items":["Monomer: ethene CH₂=CH₂. Repeat: –[CH₂CH₂]–ₙ.","Two main grades: low-density polythene (LDPE) and high-density polythene (HDPE).","LDPE: made at very high pressure (1000–3000 atm) with peroxide initiator. The chain has many short branches → cannot pack tightly → low density, flexible, low m.p. (~110 °C). Used in: plastic bags, cling film, squeezy bottles.","HDPE: made at moderate P with Ziegler–Natta catalyst. Chains are linear → pack tightly → higher density, stronger, higher m.p. (~135 °C). Used in: milk bottles, gas pipes, ropes.","Both are chemically inert (saturated C-C and C-H bonds, no functional groups). Both float on water. Both are very poor electrical conductors."]},{"type":"h","text":"PVC (poly(chloroethene))"},{"type":"ul","items":["Monomer: chloroethene CH₂=CHCl. Repeat: –[CH₂CHCl]–ₙ.","Polar C-Cl bonds give relatively strong dipole-dipole interactions between chains → harder, stiffer than polythene.","Pure (rigid) PVC: brittle. Used in pipes, gutters, window frames, vinyl flooring.","Plasticised PVC: phthalate plasticisers added to make the polymer flexible. Used in cable insulation, \\"leatherette\\" upholstery, blood-bag tubing, garden hoses.","Issue: burning PVC releases HCl(g) and small amounts of dioxins. Recycling difficult because of plasticiser contamination."]},{"type":"h","text":"Polypropene (polypropylene, PP)"},{"type":"ul","items":["Monomer: propene CH₂=CH(CH₃). Repeat: –[CH₂CH(CH₃)]–ₙ.","Methyl group gives stereochemistry: isotactic (all CH₃ on the same side, regular packing, high crystallinity, strong) vs atactic (random CH₃ orientation, soft, useless commercially) vs syndiotactic (alternating).","Industrial PP is mostly isotactic, made with Ziegler–Natta catalysts.","Uses: ropes, fibres (carpets), containers, packaging crates, surgical instruments.","Higher m.p. than HDPE (~165 °C); good chemical resistance."]},{"type":"h","text":"Polystyrene"},{"type":"ul","items":["Monomer: phenylethene (styrene) CH₂=CH(C₆H₅). Repeat: –[CH₂CH(C₆H₅)]–ₙ.","Bulky phenyl groups disrupt packing → glassy, transparent material.","Solid (atactic) polystyrene: disposable cutlery, plastic models, CD cases.","Expanded polystyrene (foam): blowing agent injected during polymerisation creates closed-cell foam — light, insulating. Used in packaging, takeaway containers, building insulation.","Brittle and burns very easily — banned in many countries for food packaging."]},{"type":"h","text":"PTFE (Teflon)"},{"type":"ul","items":["Monomer: tetrafluoroethene CF₂=CF₂. Repeat: –[CF₂CF₂]–ₙ.","C-F bonds are very strong (484 kJ/mol). The fluorine atoms also coat the chain, making it extremely non-polar and unreactive.","Properties: chemically inert (resists acids, alkalis, organic solvents), low coefficient of friction (slippery surface), high m.p. (327 °C), good electrical insulator.","Uses: non-stick pans, plumbers' tape, gaskets in chemical plants, insulation for high-frequency cables.","Manufacture: high pressure radical polymerisation in water emulsion."]},{"type":"h","text":"Perspex (PMMA)"},{"type":"ul","items":["Monomer: methyl 2-methylpropenoate CH₂=C(CH₃)CO₂CH₃. Repeat: –[CH₂C(CH₃)(CO₂CH₃)]–ₙ.","Hard, transparent, weather-resistant — often called \\"acrylic glass\\" or \\"Plexiglas\\".","Uses: aircraft canopies, signs, dental fillings, contact lenses, optical fibres.","Note that the substituent is a -CO₂CH₃ ester group, but the polymer is still ADDITION (the C=C of the monomer is what polymerises)."]},{"type":"callout","title":"Pattern","body":"For any monomer of the form CH₂=CHX (or CH₂=CXY), the repeat unit is –[CH₂CHX]– (or –[CH₂CXY]–). The C=C opens; the substituents stay where they were. Memorise the pattern, not the individual examples — you can derive any polymer from its monomer this way."},{"type":"takeaway","items":["All addition polymers come from C=C monomers; backbone is saturated.","Side group → properties: polythene (none, soft) → PP (CH₃, stronger) → PVC (Cl, stiff) → polystyrene (C₆H₅, glassy) → PTFE (F, inert).","LDPE vs HDPE: branching changes density, strength, m.p.","Common uses are exam-staples — learn at least three."]}]},{"id":"pl4","title":"Condensation Polymerisation","blocks":[{"type":"p","text":"Condensation polymerisation joins monomers by forming a new bond AND releasing a small molecule (H₂O or HCl) at each step. Each monomer must have TWO functional groups — one at each end — so that it can react on both sides and become part of a long chain. The two main classes are polyesters (the new bond is an ester, –CO–O–) and polyamides (the new bond is an amide, –CO–NH–)."},{"type":"d","caption":"Polyesters and polyamides — same logic, different linkage"},{"type":"h","text":"The key requirement: bifunctional monomers"},{"type":"ul","items":["Each monomer must have TWO reactive groups, one at each end. e.g. HOOC–R–COOH (dicarboxylic acid), HO–R–OH (diol), H₂N–R–NH₂ (diamine), HOOC–R–NH₂ (a single bifunctional monomer with both groups).","If one of the monomers had only ONE functional group, it could only react once, terminating the chain — so the polymer would never grow.","Two-monomer schemes (the most common): (a) diol + diacid → polyester; (b) diamine + diacid → polyamide.","One-monomer schemes: a single molecule with one acid and one amine (or acid and alcohol) — e.g. an amino acid → polypeptide; lactic acid → PLA."]},{"type":"h","text":"Why H₂O is lost"},{"type":"ul","items":["When –COOH reacts with –OH, the –OH of the acid combines with the H of the alcohol to leave as H₂O. The new bond is –CO–O– (an ester linkage). Same as ester formation in OC-18.","When –COOH reacts with –NH₂, the –OH of the acid combines with one of the H atoms on the amine to leave as H₂O. The new bond is –CO–NH– (an amide linkage). Same chemistry as amide formation in OC-19.","Each new linkage = one H₂O released. For a polymer of n monomers: (n−1) bonds = (n−1) H₂O released.","Industrially the H₂O has to be removed continuously (high temperature, vacuum) — by Le Chatelier, removing the by-product drives the equilibrium forwards."]},{"type":"h","text":"Acid chloride alternative"},{"type":"ul","items":["In place of a dicarboxylic acid, an industrial process can use the di-acyl chloride (e.g. ClOC–R–COCl). The leaving group is then HCl(g), not H₂O.","Advantage: the reaction is much faster, irreversible, and works at lower temperatures. Used for high-melting polymers like Kevlar.","Disadvantage: acyl chlorides are expensive and corrosive (HCl by-product needs scrubbing)."]},{"type":"h","text":"Comparison with addition polymerisation"},{"type":"ul","items":["Addition: monomer has C=C; no atoms lost; backbone is saturated C–C; mechanism is chain-growth via radicals/ions.","Condensation: monomer has –COOH/–OH/–NH₂; H₂O (or HCl) lost per linkage; backbone contains heteroatoms (O or N) at every linkage; mechanism is step-growth.","Step-growth has a useful consequence: the polymer chain length grows slowly, and average Mr only becomes high near the end of the reaction (~99% conversion needed for Mr ~10 000)."]},{"type":"callout","title":"Condensation polymerisation","body":"A polymerisation in which a small molecule (most commonly H₂O) is eliminated each time two monomers join. Always involves bifunctional monomers carrying –COOH, –OH, –NH₂ or related groups."},{"type":"takeaway","items":["Condensation: bifunctional monomers + small-molecule loss per linkage.","Polyester: diol + diacid (or diacyl chloride) → –CO–O– linkages.","Polyamide: diamine + diacid (or diacyl chloride) → –CO–NH– linkages.","Lose 1 H₂O (or 1 HCl) per linkage formed."]}]},{"id":"pl5","title":"Polyesters","blocks":[{"type":"p","text":"A polyester is a polymer joined by repeated ester linkages (–CO–O–). The most important polyester by volume is polyethylene terephthalate, PET — the same plastic that bottles soft drinks, Terylene clothing fibres, and Mylar film. Both monomers are made on a vast industrial scale from oil refining intermediates."},{"type":"d","caption":"Terylene/PET — the textbook polyester"},{"type":"h","text":"Terylene / PET — structure"},{"type":"ul","items":["Monomer 1: ethane-1,2-diol HOCH₂CH₂OH (also called ethylene glycol). A diol — two –OH groups.","Monomer 2: benzene-1,4-dicarboxylic acid HOOC–C₆H₄–COOH (also called terephthalic acid). A diacid — two –COOH groups, one at each para position of a benzene ring.","Equation: n HOCH₂CH₂OH + n HOOC–C₆H₄–COOH → –[O–CH₂CH₂–O–CO–C₆H₄–CO]–ₙ + 2n H₂O.","Repeat unit: –[O–CH₂CH₂–O–CO–C₆H₄–CO]–ₙ. Two ester linkages per repeat (one on each side of the benzene ring), made by losing two H₂O molecules per repeat.","Conditions: ~280 °C with a catalyst (e.g. antimony(III) oxide); water removed continuously by vacuum to drive equilibrium forwards."]},{"type":"h","text":"Forms and uses of PET"},{"type":"ul","items":["As a fibre: Terylene. Mixed with cotton (e.g. polycotton) — strong, wrinkle-resistant, easy to wash. Major textile fibre.","As film: Mylar. Used for magnetic tape, food packaging, balloons, archival document protection.","As bottles: PET. Stretch-blow moulded; transparent, lightweight, low O₂ permeability — ideal for fizzy drinks. Recyclable: marked with the \\"1\\" recycling symbol.","As engineering plastic: glass-reinforced PET for car parts, electrical components."]},{"type":"h","text":"Hydrolysis: recycling and biodegradation"},{"type":"ul","items":["Acid-catalysed hydrolysis cleaves the ester linkages to give the diol and diacid. Alkaline hydrolysis gives the diol and the dicarboxylate salt; acidify the salt to recover the diacid. These recovered monomers can be used again in chemical recycling. Ignoring end groups, acid hydrolysis is represented by: –[O–CH₂CH₂–O–CO–C₆H₄–CO]–ₙ + 2n H₂O → n HOCH₂CH₂OH + n HOOC–C₆H₄–COOH.","In practice, mechanical recycling (melt and reform) is more common because it is cheaper. Chemical recycling is reserved for contaminated streams.","Slow biodegradation: the ester linkages CAN be hydrolysed by some bacterial enzymes (PETase, discovered 2016), but the rate is slow at ambient temperatures."]},{"type":"h","text":"Polylactic acid (PLA) — a single-monomer polyester"},{"type":"ul","items":["Lactic acid CH₃CH(OH)COOH has BOTH –OH and –COOH on the same molecule. Two molecules can condense head-to-tail.","Equation: n CH₃CH(OH)COOH → –[O–CH(CH₃)–CO]–ₙ + n H₂O.","PLA is biodegradable: enzymes in compost facilities hydrolyse the ester linkages back to lactic acid (which is metabolised by microbes).","Made from renewable corn starch, fermented to lactic acid. Uses: bioplastics, 3D printing filament, surgical sutures, food packaging."]},{"type":"callout","title":"Spotting a polyester","body":"In a polymer chain, count the linkages. If they are –CO–O–C– (carbonyl carbon then oxygen then carbon), it is a polyester. The polymer can be hydrolysed back to a diol + diacid (or one bifunctional monomer with both groups)."},{"type":"takeaway","items":["PET = ethane-1,2-diol + benzene-1,4-dicarboxylic acid; ester linkage; loses H₂O.","Brand names: Terylene (fibre), Dacron, Mylar (film), PET (bottles).","Recyclable by chemical hydrolysis or by melt-reform.","PLA: a one-monomer biodegradable polyester from lactic acid."]}]},{"id":"pl6","title":"Polyamides","blocks":[{"type":"p","text":"A polyamide is a polymer joined by repeated amide linkages (–CO–NH–). The amide bond is exactly the same chemistry as the peptide bond in proteins — only the monomers differ. Synthetic polyamides include the nylons (used for fabrics, ropes, gears) and Kevlar (aromatic polyamide, used for body armour). All are valuable for high tensile strength and good wear resistance."},{"type":"d","caption":"Three industrially important polyamides"},{"type":"h","text":"Nylon-6,6"},{"type":"ul","items":["Monomer 1: hexane-1,6-diamine H₂N–(CH₂)₆–NH₂ (a diamine).","Monomer 2: hexanedioic acid HOOC–(CH₂)₄–COOH (a diacid; also called adipic acid). Note: 4 carbons in the chain + 2 from the COOH groups = 6 total.","Equation: n H₂N–(CH₂)₆–NH₂ + n HOOC–(CH₂)₄–COOH → –[NH–(CH₂)₆–NH–CO–(CH₂)₄–CO]–ₙ + 2n H₂O.","Why \\"6,6\\"? Each monomer has 6 carbon atoms. Numbers count C atoms in each starting material.","Industrial process: melt-mix at ~270 °C, water removed continuously. Often the diacid chloride is used instead of the acid for faster reaction.","Properties: strong tensile fibres, abrasion-resistant, m.p. ~265 °C.","Uses: textiles (stockings, parachutes, ropes, carpets), engineering parts (gears, bearings — strong yet self-lubricating), surgical sutures."]},{"type":"h","text":"Nylon-6 — one monomer"},{"type":"ul","items":["Made from a single monomer: caprolactam, a 7-membered cyclic amide. The ring has six carbon atoms and one nitrogen atom; the carbonyl carbon is one of the six carbons.","In ring-opening polymerisation, the cyclic amide ring opens and monomer units join into a continuous chain: ...CO–NH–(CH₂)₅–CO–NH–(CH₂)₅–CO–... . No small molecule is eliminated when caprolactam undergoes ring-opening polymerisation. Nylon-6 can also be made by condensation of 6-aminohexanoic acid, which does eliminate water.","Repeat unit: –[NH–(CH₂)₅–CO]–ₙ. Six carbon atoms in the repeat (5 in the chain + 1 from C=O). Hence \\"Nylon-6\\".","Properties similar to Nylon-6,6 but slightly lower m.p. and softer feel — preferred for delicate textiles."]},{"type":"h","text":"Kevlar — aromatic polyamide"},{"type":"ul","items":["Monomers: benzene-1,4-diamine H₂N–C₆H₄–NH₂ and benzene-1,4-dicarbonyl chloride ClOC–C₆H₄–COCl.","Repeat unit: –[NH–C₆H₄–NH–CO–C₆H₄–CO]–ₙ.","Both rings are para-substituted, so the chain is RIGID and almost straight. The chains pack into sheets, with extensive H-bonding between –C=O···H–N– on neighbouring chains.","Properties: very high tensile strength (5× steel by weight), high m.p. (~500 °C), low extensibility — extreme rigidity and toughness.","Uses: bulletproof vests, helmets, fire-resistant clothing, motorcycle brake-cable cores, optical fibre cables."]},{"type":"h","text":"Hydrolysis of polyamides"},{"type":"ul","items":["Like proteins (which are polyamides), nylons can be hydrolysed back to monomers.","Acid hydrolysis: 6 M HCl, reflux for many hours → diamine (as ammonium salt) + diacid. Same conditions as for protein hydrolysis (OC-19, chapter 11).","Base hydrolysis: NaOH, reflux → diamine + carboxylate salt of the diacid.","Resistance to hydrolysis: amide bonds are hard to break (stronger than ester bonds because N is a worse leaving group than O). Nylons last in clothing and ropes for years; Kevlar resists chemical attack from most acids/bases under normal conditions."]},{"type":"callout","title":"Spotting a polyamide","body":"Look for –CO–NH– linkages along the chain. Count carbons in each monomer to deduce the nylon name (Nylon-6,6 = two C₆ monomers; Nylon-6 = one C₆ ring monomer)."},{"type":"takeaway","items":["Polyamide linkage: –CO–NH–. Same as the peptide bond.","Nylon-6,6: hexane-1,6-diamine + hexanedioic acid. Strong, high m.p.","Nylon-6: from caprolactam (single monomer, ring-opening).","Kevlar: aromatic polyamide, rigid, bulletproof.","Hydrolysed by acid or base (slow); nylons can be recycled chemically."]}]},{"id":"pl7","title":"Identifying Monomers & Repeat Units","blocks":[{"type":"p","text":"Two skills the exam tests routinely: (1) given the monomer(s), draw the repeat unit and write the equation; (2) given a section of polymer, deduce the monomer(s). The rules for each are simple and worth practising. The trick to (2) is recognising the linkage and \\"putting back\\" what was lost — a C=C for addition polymers, an H₂O for condensation."},{"type":"d","caption":"Reverse the polymerisation: cut linkages, restore lost atoms"},{"type":"h","text":"Forward direction — monomer → repeat unit"},{"type":"ul","items":["For an addition (alkene) monomer: identify the C=C, change it to C–C, wrap in [ ]ₙ. The substituents do not move. Example: CH₂=CHCN → –[CH₂–CH(CN)]–ₙ (poly(propenenitrile), used in fibres).","For a condensation pair (e.g. diol + diacid): pair them up, drop H₂O at each new bond. Ignoring end groups: n HOCH₂CH₂OH + n HOOC–CH₂–COOH → –[O–CH₂CH₂–O–CO–CH₂–CO]–ₙ + 2n H₂O.","For a single bifunctional condensation monomer (e.g. an amino acid or hydroxyacid): join –NH₂ of one to –COOH of next, drop H₂O. Ignoring end groups, for glycine: n H₂N–CH₂–COOH → –[NH–CH₂–CO]–ₙ + n H₂O."]},{"type":"callout","title":"Counting water: include the chain ends","body":"Repeat-unit equations omit end groups, so a diol/diacid pair corresponds to two ester linkages and 2 H₂O. For an exact finite open chain made from n diol molecules and n diacid molecules, 2n starting molecules form 2n − 1 new linkages: 2n − 1 H₂O molecules are released. Likewise, n amino-acid molecules form n − 1 links in one open chain. State which convention you are using."},{"type":"h","text":"Reverse direction — polymer → monomer(s)"},{"type":"ul","items":["Step 1: identify the repeat unit. Look for the smallest pattern that repeats along the chain. The repeat unit will contain ALL the atoms of one (or two) original monomer(s).","Step 2: identify the linkage type. (a) Saturated –C–C–C– backbone with side groups → addition polymer. (b) –CO–O–C– link → polyester. (c) –CO–NH–C– link → polyamide.","Step 3: cut the linkages and restore lost atoms. (a) For addition: re-introduce a C=C between the same two carbons. (b) For polyester: cut the –CO–O– bond, add H back to the –O– end (making –OH) and add –OH back to the –CO– end (making –COOH). (c) For polyamide: same idea — cut –CO–NH– and add –OH to –CO– (giving –COOH) and add H to –NH (giving –NH₂).","Step 4: check by writing the polymerisation equation in the forward direction with your proposed monomer(s)."]},{"type":"h","text":"Worked example A — addition"},{"type":"ul","items":["Polymer fragment: –CH₂–CH(CH₃)–CH₂–CH(CH₃)–CH₂–CH(CH₃)–...","Repeat unit: –[CH₂–CH(CH₃)]–ₙ (the smallest section that repeats).","Linkage type: saturated C–C; no heteroatoms in backbone → addition polymer.","Monomer: re-insert a C=C between the two C atoms of the repeat unit: CH₂=CH(CH₃) (propene).","This is polypropene."]},{"type":"h","text":"Worked example B — polyester"},{"type":"ul","items":["Polymer fragment: –O–CH₂CH₂CH₂–O–CO–CH₂CH₂–CO–O–CH₂CH₂CH₂–O–CO–CH₂CH₂–CO–...","Repeat unit: –[O–CH₂CH₂CH₂–O–CO–CH₂CH₂–CO]–.","Linkage type: –CO–O–C– → polyester.","Cut the two ester linkages in the repeat unit and restore H₂O at each cut.","Monomer A: HO–CH₂CH₂CH₂–OH = propane-1,3-diol.","Monomer B: HOOC–CH₂CH₂–COOH = butanedioic acid (succinic acid)."]},{"type":"h","text":"Worked example C — polyamide"},{"type":"ul","items":["Polymer fragment: –NH–CH₂CH₂–NH–CO–CH₂CH₂CH₂CH₂CH₂CH₂–CO–NH–CH₂CH₂–NH–CO...","Repeat unit: –[NH–CH₂CH₂–NH–CO–(CH₂)₆–CO]–.","Linkage type: –CO–NH– → polyamide.","Cut the two amide linkages and restore H₂O at each cut.","Monomer A: H₂N–CH₂CH₂–NH₂ = ethane-1,2-diamine.","Monomer B: HOOC–(CH₂)₆–COOH = octanedioic acid."]},{"type":"callout","title":"Restoring atoms","body":"When you cut a polyester or polyamide linkage to find monomers, ALWAYS add a –H to the heteroatom side (giving –OH or –NH₂) and –OH to the carbonyl carbon side (giving –COOH). For an acyl-chloride-derived polymer the question may ask you to write –Cl on the C=O side instead."},{"type":"takeaway","items":["Forward: open C=C (addition) or drop H₂O (condensation) at each linkage.","Reverse: re-form C=C (addition) or restore H₂O at each linkage.","Ester linkage –CO–O–C–: hydrolysis gives a –COOH and an –OH.","Amide linkage –CO–NH–C–: hydrolysis gives a –COOH and an –NH₂."]}]},{"id":"pl8","title":"Uses and Environmental Issues","blocks":[{"type":"p","text":"Synthetic polymers transformed the 20th century: light, cheap, durable, mouldable. The same properties that make plastics so useful — chemical inertness, high melting point, low density — also make them an environmental burden. The chemistry of disposal and recycling closes our look at this topic."},{"type":"d","caption":"Three main environmental problems and the alternatives"},{"type":"h","text":"Why most plastics are non-biodegradable"},{"type":"ul","items":["Addition polymers (polythene, PVC, polystyrene, PTFE) have a saturated C–C backbone. There are no functional groups for enzymes to attack. Bacteria and fungi have no metabolic pathway evolved for these synthetic materials.","Decomposition by sunlight (photodegradation) breaks chains slowly into smaller fragments — but the underlying C–C bonds remain. The small fragments are MICROPLASTICS (< 5 mm), now found in oceans, soils, and the human bloodstream.","Some condensation polymers ARE more easily degraded — PLA (polylactic acid) is biodegradable in industrial composters because the ester linkages are hydrolysed by microbes back to lactic acid. But common condensation polymers (PET, nylon) hydrolyse only slowly at ambient temperature."]},{"type":"h","text":"Disposal options and their drawbacks"},{"type":"ul","items":["Landfill: cheap, but plastics persist for centuries; toxic plasticisers (e.g. phthalates from PVC) leach into groundwater; increasingly land-limited.","Incineration: reduces volume, generates electricity; but BURNING PVC releases HCl(g) and dioxins (highly toxic at trace levels); polyurethane releases HCN(g). Modern incinerators have flue-gas treatment but the cost is high.","Mechanical recycling: melt and reform. Works well for thermoplastic addition polymers (LDPE, HDPE, PP, PET). Quality drops with each recycle (chains shorten, contamination accumulates) — typically only 1–3 recycle cycles before the plastic is \\"downcycled\\" to lower-grade products.","Chemical recycling: hydrolyse condensation polymers back to monomers, then re-polymerise. Works in principle for PET and nylons but is energy-intensive and only commercial for high-purity feedstocks.","Open dumping: the world's commonest practice. Wind-blown plastic ends up in rivers and the ocean (the Great Pacific Garbage Patch contains an estimated 80 000 tonnes of floating plastic)."]},{"type":"h","text":"Greener alternatives"},{"type":"ul","items":["PLA (polylactic acid): made from corn or sugarcane, biodegradable in industrial composts, Mr 50–100 kDa. Used in food packaging, single-use cutlery, 3D printing filament.","PHA (polyhydroxyalkanoates): bacterial polyesters that are fully biodegradable (even in seawater). Currently expensive but production is scaling up.","Designed-for-recycling polymers: ester or imine linkages built in deliberately so that the polymer can be cleanly hydrolysed at end of life.","Bio-based PET: same chemistry as PET but with monomers derived from plant sugars rather than oil. Reduces fossil-carbon footprint but does not solve the persistence problem.","Reusable systems: deposit-return for glass and PET bottles dramatically reduces waste; refillable consumer packaging is gaining ground."]},{"type":"h","text":"Major use categories — a quick reference"},{"type":"ul","items":["Packaging (~40% of plastic use): LDPE film, HDPE bottles, PET bottles, polystyrene foam, PP containers. Most is single-use.","Construction (~20%): PVC pipes, window frames, flooring; polythene damp-proof course.","Textiles (~15%): polyester (PET), nylon, polypropene fibres, acrylic.","Consumer goods, electronics, transport (~25% combined): polystyrene, ABS, PMMA (Perspex), PTFE (Teflon)."]},{"type":"callout","title":"The environmental dilemma","body":"Polymers improve resource use in transport (lighter cars), packaging (less food waste), insulation (lower heating energy) — they often save more carbon than they emit. The problem is end-of-life: persistent waste accumulating in the environment. The solutions are policy (deposit returns, single-use bans) and chemistry (biodegradable polymers, designed-for-recycling)."},{"type":"takeaway","items":["Addition polymers are non-biodegradable; saturated C-C backbone resists microbes.","Disposal: landfill (slow), incineration (toxic gases for some), recycling (limited).","Burning PVC → HCl + dioxins; burning polyurethane → HCN.","Greener: PLA (compostable polyester from corn), PHA, bio-based PET.","Plastics often save carbon in use; the challenge is end-of-life waste."]}]}]}`),phase:JSON.parse(`{"objectives":["Explain the principle of steam distillation and identify suitable substrates","Define partition coefficient and use it in calculations","Explain why multiple smaller extractions are more efficient than a single large one","Describe the unifying principle of chromatography (mobile + stationary phase)","Distinguish adsorption from partition mechanisms","Use Rf values from paper and TLC to identify compounds","Compare column, ion-exchange, HPLC and GLC chromatography","Explain electrophoresis and the role of buffer pH","Outline the steps in genetic fingerprinting"],"chapters":[{"id":"pe1","title":"Phases & Phase Equilibria — Why This Topic Exists","blocks":[{"type":"p","text":"Modern chemistry depends on separation. Whenever we make a compound, isolate a natural product, test for a contaminant, or sequence a protein, we have to separate one substance from a mixture. Every separation method exploits the same idea — that different compounds distribute themselves differently between two phases. This topic gives you the principles behind steam distillation, solvent extraction, all the chromatographies, and electrophoresis. Once you see the common framework, you can predict what each technique will do."},{"type":"d","caption":"A phase is a uniform region with definite composition and properties"},{"type":"h","text":"What is a phase?"},{"type":"ul","items":["A phase is a region of matter that is physically distinct, uniform throughout, and separated from other phases by a boundary.","The familiar three: solid, liquid, gas. Within \\"liquid\\" you can have several mutually immiscible phases — oil and water, for example.","A solution of NaCl in water is ONE phase (uniform composition); add some hexane and shake — now you have TWO liquid phases (water-rich and hexane-rich), with the salt almost entirely in the water phase.","A glass of fizzy water has TWO phases: aqueous solution + gaseous CO₂ (the bubbles)."]},{"type":"h","text":"Phase equilibrium"},{"type":"ul","items":["When two phases are in contact and a substance can exist in both, the system reaches a dynamic equilibrium: molecules cross the boundary in both directions at equal rates.","At equilibrium the concentration ratio is fixed (at given T) — this is the principle behind partition coefficients.","Disturbing the equilibrium drives net transfer until balance is restored — this is why solvent extraction works (remove the loaded solvent, partition shifts to refill it)."]},{"type":"h","text":"How this topic ties to other syllabus areas"},{"type":"ul","items":["OC-19: peptide bonds; protein hydrolysis; ninhydrin staining of amino acids — those amino acids are separated by chromatography or electrophoresis methods we develop here.","PC-07: equilibrium constants. The partition coefficient is a special equilibrium constant for a phase-distribution equilibrium.","AC-23: chromatography is used to detect environmental pollutants; ion-exchange columns are used in industrial water treatment."]},{"type":"callout","title":"Phase","body":"A physically distinct, homogeneous region of matter, separated from other phases by a recognisable boundary. Phases need not be macroscopic — fog droplets are a separate (liquid) phase suspended in air."},{"type":"takeaway","items":["A phase = uniform region with a definite boundary.","Many separation methods rely on different distributions of compounds between two phases.","Equilibrium between phases is dynamic; disturbing it drives transfer.","This topic is the unifying theory behind distillation, extraction, chromatography, and electrophoresis."]}]},{"id":"pe2","title":"Steam Distillation","blocks":[{"type":"p","text":"Many organic compounds — phenylamine, nitrobenzene, plant-derived essential oils — decompose if heated to their normal boiling points. Steam distillation lets us distil them at a temperature below 100 °C by exploiting a quirk of the vapour pressures of two immiscible liquids in contact."},{"type":"d","caption":"Two immiscible liquids share boiling — neither boils alone"},{"type":"h","text":"The principle"},{"type":"ul","items":["For a single pure liquid, boiling occurs when its vapour pressure equals the external pressure (1 atm at sea level).","For TWO immiscible liquids in contact (e.g. water + an organic), each exerts its OWN saturated vapour pressure, independent of the other. The total vapour pressure above the mixture is P_total = P°_water + P°_organic.","Boiling occurs when P_total = atmospheric. Because we are summing two contributions, this is reached at a temperature LOWER than the b.p. of either pure component.","Example: phenylamine (b.p. 184 °C, would decompose if heated alone in air) + water — the mixture boils at about 98 °C, well below 100 °C and far below 184 °C."]},{"type":"h","text":"Composition of the distillate"},{"type":"ul","items":["The mole ratio in the vapour is given by the ratio of partial pressures: n_org / n_water = P°_org / P°_water at the boiling temperature.","Converting to mass: m_org / m_water = (P°_org × Mr_org) / (P°_water × Mr_water).","Despite the organic having LOWER P° than water, if its Mr is much larger, the mass ratio of organic in the distillate can be substantial (often 30–60% organic by mass).","Each fraction of distillate has a fixed composition determined by these ratios — no fractionating column needed for this part."]},{"type":"h","text":"Procedure"},{"type":"ul","items":["Steam is passed (or generated in situ) through the impure organic.","The two-phase mixture boils as soon as its sum of vapour pressures = atmospheric.","Vapour goes up through a condenser; the condensate is two layers (water + organic, immiscible).","Separate the layers in a separating funnel; dry the organic over anhydrous Na₂SO₄ (or MgSO₄); decant."]},{"type":"h","text":"Ideal substrates"},{"type":"ul","items":["Volatile (significant P° at 100 °C — say > 5 kPa).","Immiscible with water (negligible mutual solubility).","Thermally unstable above ~100 °C — that is why we want to AVOID the high temperature of conventional distillation.","Examples of compounds purified industrially this way: phenylamine, nitrobenzene, essential oils (lavender, lemon, peppermint), nicotine, naphthalene."]},{"type":"callout","title":"Why steam, not just heat?","body":"For a single pure organic, the only way to lower its boiling point is reduced pressure (vacuum distillation). Steam distillation lowers it by ADDING water rather than reducing pressure — simpler equipment, no vacuum pump. Use vacuum distillation when the organic IS miscible with water; use steam distillation when it is NOT."},{"type":"takeaway","items":["Steam distillation: P_total = P°_water + P°_org → boils below 100 °C.","Used for heat-sensitive, water-immiscible, volatile organics.","Mass ratio in distillate = (P°_org × Mr_org) / (P°_water × Mr_water).","Industrial: essential oils, phenylamine, nitrobenzene purification."]}]},{"id":"pe3","title":"Partition Coefficient","blocks":[{"type":"p","text":"When a solute is shaken with two immiscible solvents, it distributes between the two phases until equilibrium. The ratio of its concentrations in the two phases at equilibrium is a constant — the partition coefficient. This is the most important quantitative idea in this topic, and the basis of solvent extraction."},{"type":"d","caption":"Partition coefficient = ratio of concentrations at equilibrium"},{"type":"h","text":"Definition"},{"type":"ul","items":["For a solute X distributing between two immiscible solvents, e.g. an organic solvent and water, at equilibrium: K_pc = [X]_organic / [X]_aqueous.","K_pc is a function of solute, solvents, and temperature only. Independent of total amount of X (within limits — at very high concentration, the simple law breaks down).","Convention: by tradition K_pc is written with the LESS POLAR solvent on top. For a non-polar organic + water, K_pc = [X]_org / [X]_aq.","A large K_pc (≫ 1) means X greatly prefers the organic phase; small K_pc (≪ 1) means it prefers the aqueous phase."]},{"type":"h","text":"Conditions for the simple law"},{"type":"ul","items":["Solute must be in the SAME molecular state in both solvents. e.g. it does not dissociate to ions in one but stay as molecule in the other.","It must not associate (dimerise) in one phase and not the other.","Concentrations must be reasonably dilute — at high concentrations, deviations occur (analogous to non-ideal gas behaviour).","If the solute IS in different states in the two phases, write K_pc using the MOLECULAR (not total) concentration in each phase."]},{"type":"h","text":"Worked example — calculating K_pc"},{"type":"ul","items":["A mixture of 25 cm³ of organic solvent and 75 cm³ of water is shaken with 5.0 g of solute X. After equilibrium, 1.0 g of X is in the aqueous layer.","Mass in organic = 5.0 − 1.0 = 4.0 g.","[X]_org = 4.0 g / 25 cm³ = 0.16 g cm⁻³. [X]_aq = 1.0 g / 75 cm³ = 0.0133 g cm⁻³.","K_pc = 0.16 / 0.0133 = 12.0. (Units cancel — they were the same on both sides.)","X has a strong preference for the organic phase: it would be efficiently extracted from water with this solvent."]},{"type":"h","text":"When the simple law fails — examples"},{"type":"ul","items":["Carboxylic acids in water + benzene: in water, R-COOH partly dissociates to R-COO⁻ + H⁺ (so total [acid] in water exceeds [molecular acid]). In benzene, no dissociation. Use the MOLECULAR concentration in water (not total) to get the true K_pc.","Ethanoic acid in water + non-polar solvent: in the non-polar solvent, two molecules dimerise via H-bonding, (CH₃COOH)₂. Use the MONOMER concentration in the non-polar phase.","Both of these are exam-classic complications — you can calculate the simple K_pc only after first calculating the concentration of the molecular form."]},{"type":"callout","title":"Partition coefficient K_pc","body":"The ratio of equilibrium concentrations of a solute in two immiscible solvents at constant temperature, with the solute existing in the same molecular state in both solvents."},{"type":"takeaway","items":["K_pc = [X]_top / [X]_bottom (or [X]_organic / [X]_aqueous).","Constant at given T; depends on solute, solvents, T.","Solute must be in the SAME molecular state in both phases.","Large K_pc = solute prefers organic; small K_pc = prefers water."]}]},{"id":"pe4","title":"Solvent Extraction","blocks":[{"type":"p","text":"Solvent extraction uses partition between two immiscible solvents to remove a substance from one phase to another. It is one of the commonest unit operations in any organic chemistry lab — almost every preparation of a non-volatile organic finishes with extraction into a non-polar solvent, then drying, then evaporation."},{"type":"d","caption":"Procedure: shake, separate, repeat with fresh solvent"},{"type":"h","text":"Procedure (separating funnel)"},{"type":"ul","items":["Pour the aqueous mixture into a separating funnel.","Add a portion of the chosen extracting solvent (typically diethyl ether, ethyl acetate, or DCM).","Stopper, invert, shake (vent regularly to release pressure from CO₂ or vapour).","Stand vertically; allow the two layers to separate.","Drain the lower layer into one beaker, the upper into another.","Re-extract the AQUEOUS layer with FRESH solvent. Repeat 2-3 times for efficiency.","Combine the organic extracts; dry over anhydrous Na₂SO₄; filter; evaporate."]},{"type":"h","text":"Why multiple small extractions beat one big one"},{"type":"ul","items":["For a fixed volume V_org of organic solvent and V_aq of water, with K_pc = [X]_org / [X]_aq, the FRACTION of X remaining in the aqueous after one extraction is V_aq / (V_aq + K_pc × V_org).","Each extraction multiplies the remaining fraction by this same factor. So n extractions leave [V_aq / (V_aq + K_pc × V_org)]ⁿ of the original X.","Splitting the same total volume into n smaller portions reduces the remaining fraction more aggressively because the (n-th) power amplifies the effect.","Example calculation: V_aq = 100 cm³, K_pc = 4. Total organic = 100 cm³. (1) one extraction with 100 cm³: remaining = 100/(100 + 4×100) = 20%. (2) Two extractions of 50 cm³ each: remaining = (100/(100+200))² = (1/3)² = 11.1%. (3) Four extractions of 25 cm³ each: remaining = (100/(100+100))⁴ = (1/2)⁴ = 6.25%.","Diminishing returns: doubling the number of extractions does not double the recovery. After about 4–5 extractions the remaining is small enough that further effort is wasted."]},{"type":"h","text":"Choosing the extracting solvent"},{"type":"ul","items":["Must be IMMISCIBLE with water. Common choices: diethyl ether, DCM (dichloromethane), ethyl acetate, hexane, chloroform.","Must dissolve the target SOLUTE well (large K_pc favours extraction).","Should NOT dissolve impurities (or should leave them in water).","Should be VOLATILE for easy evaporation at the end.","Should be SAFE — diethyl ether is highly flammable; chloroform is suspected carcinogen; modern preference is ethyl acetate for most extractions."]},{"type":"h","text":"Industrial applications"},{"type":"ul","items":["Extraction of caffeine from coffee beans (using supercritical CO₂ — modern decaffeination).","Extraction of essential oils from plant material (lavender, peppermint, citrus oils).","Recovery of antibiotics from fermentation broth.","Purification of organic acids — exploit pH-dependent solubility (acid form in non-polar; carboxylate form in water).","Hydrometallurgy: extracting copper, uranium, rare earths from leach liquors using selective organic complexants."]},{"type":"callout","title":"Always do multiple small extractions","body":"For a given volume of extractant, splitting it into more, smaller portions ALWAYS removes more solute than a single large portion. The maths above proves it. Standard lab practice: \\"extract with 3 × 10 cm³\\" rather than \\"extract with 1 × 30 cm³\\"."},{"type":"takeaway","items":["Solvent extraction transfers solute from water to organic via partition.","Procedure: shake, separate, repeat with fresh solvent.","Multiple small extractions > one big extraction (exponential decay).","Choose solvent: immiscible, dissolves target, easy to evaporate, safe."]}]},{"id":"pe5","title":"Chromatography — Unified Principle","blocks":[{"type":"p","text":"Chromatography is partition or adsorption equilibrium done many thousands of times in series. Every variant — paper, TLC, column, ion-exchange, HPLC, GLC — uses the same idea: two phases (one mobile, one stationary), and components of a mixture distribute between them differently as the mobile phase moves past the stationary phase. Components with stronger affinity for the stationary phase travel slowly; those with stronger affinity for the mobile phase travel quickly. Result: the mixture spreads out into bands or peaks."},{"type":"d","caption":"All chromatographies share the same logic"},{"type":"h","text":"Two phases — defining the technique"},{"type":"ul","items":["The MOBILE phase carries the components through. It can be a liquid (paper, TLC, column, HPLC, ion-exchange) or a gas (GLC).","The STATIONARY phase stays put. It can be a solid (paper cellulose, silica, alumina, ion-exchange resin) or a liquid coated on a solid support (in GLC, the stationary phase is liquid; in paper chromatography, water adsorbed onto cellulose acts as a liquid stationary phase).","The technique's name usually identifies the mobile phase: liquid chromatography, gas chromatography, ion chromatography."]},{"type":"h","text":"Two mechanisms — adsorption vs partition"},{"type":"ul","items":["Adsorption chromatography: solute STICKS to the surface of a solid stationary phase (e.g. silica, alumina) by intermolecular forces (H-bonding, dipole, dispersion). Strongly-adsorbing components move slowly. Examples: silica TLC, alumina column.","Partition chromatography: solute DISSOLVES in a liquid stationary phase (often a thin film of water on cellulose, or an organic liquid coating on a solid support). The solute partitions between the mobile and stationary liquid phases — basic K_pc behaviour. Examples: paper chromatography, GLC.","In practice the line is blurred: in TLC on silica, both adsorption AND partition (in adsorbed water) contribute. The exam mostly asks you to identify which mechanism dominates for a given technique."]},{"type":"h","text":"Retention factor and retention time"},{"type":"ul","items":["For paper or TLC: Rf = (distance to spot) / (distance to solvent front). 0 ≤ Rf ≤ 1. Rf is characteristic of compound, mobile phase, and stationary phase.","For column-based methods: retention time t_R = time from injection to peak emergence at detector. Identifies the compound (compared with a known standard) under fixed conditions.","In all cases: separation is achieved if components have DIFFERENT Rf (or t_R). If two components have the same Rf, they cannot be separated by that method — change the solvent or the stationary phase."]},{"type":"h","text":"Common to every variant"},{"type":"ul","items":["Apply the sample to the stationary phase as a small spot or injection.","Allow the mobile phase to flow past for a defined distance or time.","Detect the resolved components — visually (coloured), with a stain, or with an instrument detector.","Identify by comparing Rf or t_R with known standards.","Quantify by measuring spot size or peak area — proportional to amount, with calibration."]},{"type":"callout","title":"Chromatography","body":"A separation method based on the differential distribution of components between a mobile and a stationary phase. The single principle that links paper, TLC, column, GLC, HPLC, and ion exchange."},{"type":"takeaway","items":["All chromatographies: mobile phase + stationary phase + differential distribution.","Adsorption (sticking to solid surface) vs partition (dissolving in liquid layer).","Rf or t_R is characteristic — identifies compounds.","Variants distinguished by what the phases are — gas/liquid/solid combinations."]}]},{"id":"pe6","title":"Paper & Thin-Layer Chromatography","blocks":[{"type":"p","text":"Paper chromatography and TLC are the two simplest and most-used variants — found in every school and in the early stages of any analytical workflow. They differ mainly in the stationary phase. Both give Rf values that are diagnostic for a compound under specified conditions."},{"type":"d","caption":"Spot, run, measure — Rf is the result"},{"type":"h","text":"Paper chromatography"},{"type":"ul","items":["Stationary phase: water adsorbed on cellulose fibres in paper — effectively a liquid-on-solid stationary phase. Mechanism: PARTITION between the water and the moving solvent.","Mobile phase: a chosen solvent that moves up the paper by capillarity.","Procedure: spot the sample on a baseline drawn in pencil; dip the paper just below the baseline into solvent; let the solvent rise; remove and mark the solvent front; let dry; locate spots.","Locating agents: visible spots are easy. Invisible compounds need a stain — ninhydrin (purple) for amino acids, iodine vapour (brown) for many organics, UV light for aromatics.","Calculating Rf: Rf = distance from baseline to spot centre / distance from baseline to solvent front.","Limitations: paper has limited capacity; Rf reproducibility ~5%; not used for large or non-polar compounds."]},{"type":"h","text":"Thin-layer chromatography (TLC)"},{"type":"ul","items":["Stationary phase: a thin layer of silica gel or alumina spread on a glass, plastic, or aluminium sheet. Mechanism: mainly ADSORPTION (with some partition contribution from any adsorbed water).","Mobile phase: chosen organic solvent, moves up by capillarity (same as paper).","Procedure: identical to paper, but on a TLC plate.","Speed: faster than paper (silica is more porous), better resolution.","Visualisation: UV lamp is the most common (silica plates contain a fluorescent indicator that glows green; spots show up dark). Other staining methods: ninhydrin, iodine, KMnO₄ dip.","Routine uses: monitoring reaction progress (run a TLC of starting material vs reaction mixture every 30 min); checking purity; comparing unknowns with reference standards."]},{"type":"h","text":"Choosing a solvent"},{"type":"ul","items":["Polar stationary phase (silica, paper): need polar mobile phase to move polar compounds; non-polar mobile phase to move non-polar compounds.","Common TLC solvents: hexane (non-polar), ethyl acetate (medium), ethanol or methanol (polar), water-containing systems for amino acids.","Solvent strength affects all spots. If everything moves to the front, solvent is too strong — use a weaker solvent. If nothing moves from the baseline, solvent is too weak.","Mixed solvents: e.g. 50:50 hexane/ethyl acetate — adjust ratio to \\"tune\\" Rf into the 0.2–0.7 range, where separation is best."]},{"type":"h","text":"Two-dimensional (2D) chromatography"},{"type":"ul","items":["For complex mixtures (e.g. all 20 amino acids in a protein hydrolysate), one solvent often cannot resolve everything.","Solution: run the chromatogram in one direction with solvent A; rotate the plate 90°; run it again with solvent B.","Compounds that had the same Rf in solvent A may now separate, because they have different Rf in solvent B.","Result: a 2D pattern of spots, much more discriminating than 1D."]},{"type":"callout","title":"Rf is conditional","body":"An Rf value is meaningful only with the same solvent system, the same stationary phase, and the same temperature. Always run a known standard ALONGSIDE the unknown — comparing Rf values side-by-side is reliable; comparing across runs or across labs is not."},{"type":"takeaway","items":["Paper chromatography: partition; cellulose stationary; cheap and simple.","TLC: adsorption (mainly); silica/alumina stationary; faster, better resolution.","Rf = spot distance / solvent-front distance (between 0 and 1).","2D chromatography for complex mixtures (e.g. amino acids)."]}]},{"id":"pe7","title":"Column, Ion-Exchange & HPLC","blocks":[{"type":"p","text":"Move from a thin layer to a long packed tube and you have column chromatography — the same principles applied at a larger scale, with the option of collecting fractions for further use. Ion-exchange and HPLC are specialised variants that have transformed analytical chemistry."},{"type":"d","caption":"Three column-based variants for different jobs"},{"type":"h","text":"Column chromatography"},{"type":"ul","items":["Vertical glass tube packed with adsorbent (silica or alumina).","Sample loaded at the top in a small volume of solvent.","Solvent flows down by gravity (or pumped pressure).","Different components elute at different times — collect fractions, monitor by TLC.","Use: PREPARATIVE — separate gram quantities for further use. Standard final purification step in synthetic organic labs."]},{"type":"h","text":"Ion-exchange chromatography"},{"type":"ul","items":["Stationary phase: a polymer resin bead carrying many charged sites. Cation-exchange resin: anionic groups (–SO₃⁻ or –COO⁻) bonded to the resin, with H⁺ counterions; binds cations (Ca²⁺, Na⁺, etc.). Anion-exchange resin: cationic groups (–NR₃⁺) with OH⁻ or Cl⁻ counterions; binds anions.","Solute ions exchange with the resin counterions: 2 R-SO₃⁻H⁺ + Ca²⁺(aq) ⇌ (R-SO₃⁻)₂Ca²⁺ + 2 H⁺(aq).","Solutes with different charges or different binding affinities elute at different times when the column is washed (e.g. with increasing salt or pH).","Industrial use: WATER SOFTENING (Ca²⁺ swapped for Na⁺ on a cation resin); DEMINERALISATION (cation resin in H⁺ form + anion resin in OH⁻ form removes all ions; outflow is pure water — used for boiler feed water and battery electrolytes).","Analytical use: separating amino acids (charged at any pH except their pI), separating nucleotides, ions chromatography for environmental samples."]},{"type":"h","text":"High-Performance Liquid Chromatography (HPLC)"},{"type":"ul","items":["Like column chromatography, but with much finer particles (typically 5 µm) and high pressure to push solvent through.","Steel column 5–25 cm long, packed under pressure.","Mobile phase: pumped at hundreds of bars by a high-pressure pump.","Detector at the column outlet (UV-Vis, fluorescence, refractive index, mass spec).","Output: a chromatogram = plot of detector signal vs time. Each compound emerges as a peak at its retention time t_R.","Sensitivity: sub-µg detection limits.","Speed: a typical HPLC run takes 5–30 minutes (vs hours for gravity-flow column).","Modes: REVERSED-PHASE (non-polar stationary, polar mobile — most common, for organic analytes) vs NORMAL-PHASE (polar stationary, non-polar mobile — for very non-polar analytes)."]},{"type":"h","text":"Industrial and medical applications"},{"type":"ul","items":["Pharmaceutical: assaying drug purity and concentration; quality control of every batch.","Forensic: identifying drugs in body fluids; doping tests in athletic competition.","Environmental: pesticide residues in water and food; herbicide concentrations in soil leachates.","Food safety: vitamin content, residual antibiotics in milk, heavy metals via ion chromatography.","Clinical: blood tests for hormones, drug therapy monitoring, neonatal screening."]},{"type":"h","text":"Comparison with TLC"},{"type":"ul","items":["TLC is fast, cheap, and good for QUALITATIVE analysis (is the compound present? is the reaction done?).","HPLC is more expensive and slower per run, but provides QUANTITATIVE analysis with sub-percent precision and excellent reproducibility.","Workflow: monitor reaction progress with TLC; quantify final purity with HPLC."]},{"type":"callout","title":"Ion-exchange in everyday water","body":"Hard water (high in Ca²⁺ and Mg²⁺) is softened by passing through a column of cation-exchange resin in the Na⁺ form. The Ca²⁺/Mg²⁺ binds and Na⁺ is released. Eventually the resin is exhausted and is regenerated by flushing with concentrated brine (Na⁺ excess pushes the equilibrium back)."},{"type":"takeaway","items":["Column chromatography: gravity-flow, preparative, gram scale.","Ion-exchange: charged resin swaps ions; water softening, demineralisation.","HPLC: high pressure + fine particles → fast, sensitive, quantitative.","Used everywhere in pharmaceutical, forensic, environmental, clinical labs."]}]},{"id":"pe8","title":"Gas-Liquid Chromatography (GLC)","blocks":[{"type":"p","text":"GLC takes the chromatography idea and uses a GAS as the mobile phase. The stationary phase is a high-boiling liquid coated on a solid support (or directly on the column wall). Volatile organic samples are vaporised, swept through the column by the carrier gas, and emerge at characteristic retention times. Coupled with a mass spectrometer (GC-MS), GLC is the gold standard for analysis of volatile mixtures."},{"type":"d","caption":"Gas mobile + liquid stationary = partition for volatile compounds"},{"type":"h","text":"How it works"},{"type":"ul","items":["Carrier gas: an inert gas (helium, nitrogen, hydrogen) flows continuously through the column.","Stationary phase: a liquid with high b.p. (e.g. silicone oil, polyethylene glycol) coated on a solid support inside the column. In modern capillary columns, the liquid is bonded directly to the inside wall of a fused silica tube.","Sample: small volume (typically µL) injected through a heated septum into the carrier gas stream. Sample vaporises immediately.","Separation: each compound partitions between gas (mobile) and liquid (stationary). High-affinity compounds spend more time dissolved in the liquid → they travel slowly. Low-affinity compounds stay mostly in the gas → they travel fast.","Detection: at the outlet, a detector responds to compounds emerging. Common detectors: flame ionisation (FID — universal for organics), thermal conductivity, mass spectrometer (GC-MS — also identifies).","Output: a chromatogram of detector signal vs time, with peaks for each component."]},{"type":"h","text":"Quantitation: peak area"},{"type":"ul","items":["The AREA under each peak is proportional to the AMOUNT of that compound (with calibration).","If you inject a known amount of standard, you can calibrate the response factor and quantify unknowns by ratio.","For pure standards of two different compounds, the relative areas tell you the molar ratio in a mixture.","Modern instruments calculate areas automatically; old GCs used a chart recorder and you literally cut out and weighed the peaks!"]},{"type":"h","text":"When to use GLC"},{"type":"ul","items":["Sample is VOLATILE and stable to vaporisation (typically b.p. < 250 °C).","Components are organic (most common) but inorganic gases also work.","For NON-volatile or thermally labile samples, use HPLC instead.","Common applications: forensic analysis (drugs, alcohol), pesticide residues, perfume composition, breath alcohol, exhaust gas analysis, petroleum analysis (hydrocarbon profiling), flavour chemistry."]},{"type":"h","text":"GC-MS — the powerhouse"},{"type":"ul","items":["Modern instruments connect a GC column directly to a mass spectrometer. Each compound emerges from the GC, enters the MS, and is fragmented and analysed.","Result: every peak in the GC trace has a full mass spectrum attached, identifying it from libraries of known spectra.","GC-MS is used in: drug testing (Olympics anti-doping), environmental forensics (oil spill source identification), arson investigation (residual accelerants in burnt debris), space exploration (Mars rover instruments).","Sensitivity: detects parts-per-billion (ng/g) routinely."]},{"type":"callout","title":"Retention time t_R","body":"The time taken for a compound to travel from the injection port to the detector under specified GC conditions. Characteristic of the compound; used for identification."},{"type":"takeaway","items":["GLC: gas mobile, liquid stationary; partition mechanism.","Sample must be volatile and stable.","Peaks at characteristic retention times t_R; area ∝ amount.","GC-MS combines separation + identification — the analytical workhorse."]}]},{"id":"pe9","title":"Electrophoresis","blocks":[{"type":"p","text":"Electrophoresis is separation by movement in an electric field. Charged species drift towards the electrode of opposite charge; the rate depends on the size of the charge, the friction (which depends on size and shape), and the strength of the field. With a buffer that fixes the pH, you can separate amino acids, proteins, or DNA fragments — the same gel format used for genetic fingerprinting."},{"type":"d","caption":"Charged species migrate towards the opposite electrode"},{"type":"h","text":"Setup"},{"type":"ul","items":["Support medium: a strip of paper or (more often now) a slab of agarose or polyacrylamide gel. The medium is soaked in buffer.","Buffer: holds the pH constant. Typical: pH 8.5 (for proteins), pH 7.4 (for amino acids when needed), pH 8.0 (for DNA). The choice of pH determines what charges the species carry.","Electrodes: at each end of the medium, with a potential difference (typically 100–300 V).","Sample: applied as a spot or thin band at one end of the medium.","Run: charged species migrate towards the opposite electrode; uncharged species do not move.","Stop, dry, stain: detect the bands or spots."]},{"type":"h","text":"pH controls migration — amino acid example"},{"type":"ul","items":["Recall from OC-19 chapter 9: an amino acid has different charges at different pH.","pH < pI: cation (H₃N⁺-CHR-COOH); migrates to the CATHODE (negative electrode).","pH = pI: zwitterion, net charge 0; does NOT migrate.","pH > pI: anion (H₂N-CHR-COO⁻); migrates to the ANODE (positive electrode).","Different amino acids have different pI values. Choose buffer pH to maximise the difference in their net charges, hence their migration distances."]},{"type":"h","text":"Worked separation of amino acids"},{"type":"ul","items":["Mixture: aspartate (acidic, pI ≈ 3), alanine (neutral, pI ≈ 6), lysine (basic, pI ≈ 10). Buffer at pH 6.","Aspartate at pH 6: pH > pI 3, so net charge is NEGATIVE → migrates to + (anode).","Alanine at pH 6: pH ≈ pI, net charge 0 → does not migrate.","Lysine at pH 6: pH < pI 10, so net charge is POSITIVE → migrates to − (cathode).","After running: three distinct bands, separated cleanly. Stain with ninhydrin to visualise."]},{"type":"h","text":"Detection of separated amino acids and proteins"},{"type":"ul","items":["For amino acids and small peptides: NINHYDRIN spray and warming → purple/violet spots (proline gives yellow, an exception).","For proteins: COOMASSIE BLUE stain (binds to peptide bonds, gives blue bands) or SILVER STAIN (more sensitive, gives black bands).","For DNA: ethidium bromide soaks into DNA and fluoresces under UV light; modern alternative is SYBR Green (less toxic)."]},{"type":"h","text":"Protein hydrolysis followed by electrophoresis (link to OC-19)"},{"type":"ul","items":["Hydrolyse the protein with 6 M HCl, reflux 24 h → mixture of free amino acids.","Neutralise; spot onto electrophoresis paper or 2D chromatography paper.","Apply electric field at chosen pH → amino acids separate by net charge.","Stain with ninhydrin → identify which amino acids are present in the protein, and (with a quantitative scanner) in what proportions.","This was the standard amino acid analysis method from the 1950s to the 1990s. Modern methods use HPLC or mass spec."]},{"type":"callout","title":"Choosing the buffer pH","body":"For maximum separation of two species, choose a buffer pH that puts as much difference between their net charges as possible. A pH halfway between two pI values often works well."},{"type":"takeaway","items":["Electrophoresis: charged species migrate in an electric field.","Direction set by sign of charge; speed set by charge magnitude and friction.","pH (set by buffer) controls the charge on each species.","Used for amino acids, proteins, and DNA — same principle, scale-up."]}]},{"id":"pe10","title":"Genetic Fingerprinting","blocks":[{"type":"p","text":"Every person's DNA carries unique sequence patterns. Genetic fingerprinting (also called DNA profiling) uses gel electrophoresis to display these patterns as bands of DNA fragments, generating a \\"fingerprint\\" pattern that is essentially unique. The chemistry is electrophoresis applied to DNA fragments produced by restriction enzymes."},{"type":"d","caption":"Five-step workflow from sample to band pattern"},{"type":"h","text":"The five-step workflow"},{"type":"ul","items":["Step 1: Collect a DNA-containing sample. Blood, saliva, hair root, semen, skin cells from a crime scene; cheek swab from a suspect; embryo cells in paternity testing.","Step 2: Extract DNA. Lyse the cells; remove proteins and lipids; precipitate the DNA with ethanol; redissolve in buffer.","Step 3: Cut DNA into fragments using RESTRICTION ENZYMES. These bacterial enzymes recognise specific 4–8 base pair sequences and cut at those sites. Different individuals carry different lengths of repeated DNA between cut sites — these length differences are the fingerprint.","Step 4: AMPLIFY using PCR (polymerase chain reaction) if the sample is small. PCR doubles the DNA in each cycle; 30 cycles → 10⁹-fold amplification. Now we have enough DNA to see.","Step 5: Run on agarose gel ELECTROPHORESIS. DNA is uniformly negatively charged (phosphate backbone); ALL fragments migrate towards the anode. SMALLER fragments move faster (less friction in gel pores); LARGER fragments move slower. Stain with ethidium bromide; view under UV → bands of DNA at different positions."]},{"type":"h","text":"Why is the pattern unique?"},{"type":"ul","items":["The human genome contains regions with VARIABLE NUMBERS OF TANDEM REPEATS (VNTRs) and SHORT TANDEM REPEATS (STRs) — short sequences (e.g. 4 base pairs) repeated different numbers of times in different individuals.","Each person inherits one set of repeats from each parent.","Combining the VNTR/STR lengths at 13–20 different locations gives a pattern with combined probability of ~ 1 in 10⁹ to 10¹³ of appearing in another (unrelated) individual.","Identical twins SHARE the pattern — they have the same DNA. Everyone else differs."]},{"type":"h","text":"Applications"},{"type":"ul","items":["Forensic science: identify criminals from blood/saliva/semen/hair at crime scenes; exonerate the wrongly convicted.","Paternity testing: a child shares half of their DNA with each biological parent; bands in the child's pattern can be matched to either parent.","Identifying remains: bodies in mass graves, after natural disasters, or victims of war.","Pedigree of plants and animals: tracking lineages in conservation, agriculture, racehorse breeding.","Conservation: identifying poached animal products; tracking endangered species.","Personal genomics: ancestry tests, predisposition to inherited diseases."]},{"type":"h","text":"Limitations and ethical issues"},{"type":"ul","items":["Contamination: a single skin flake from someone else can spoil a sample. Strict lab procedures prevent this.","Degraded samples (old, weathered) may not amplify cleanly — partial profiles only.","Statistical interpretation: a \\"1 in 10⁹ match\\" still has a small probability of occurring by chance, especially in small populations or related individuals.","Privacy: large national DNA databases (kept by police forces) raise concerns about who has access and for what purposes.","Discrimination: fear that insurers or employers might use genetic data — addressed in some countries by genetic anti-discrimination legislation."]},{"type":"callout","title":"Genetic fingerprinting","body":"A DNA-profiling technique that uses restriction enzymes and gel electrophoresis to produce a band pattern characteristic of an individual. Same chemistry as protein electrophoresis; different macromolecule."},{"type":"takeaway","items":["DNA fragments from one individual give a unique band pattern on electrophoresis.","Steps: extract → cut with restriction enzymes → amplify (PCR) → electrophorese → stain.","DNA is uniformly negatively charged; smaller fragments travel faster.","Forensics, paternity, identification of remains — high discriminating power."]}]}]}`),environment:JSON.parse(`{"objectives":["Explain the formation of acid rain from SO₂ and NOx","Describe industrial methods of SO₂ control: FGD, alkaline scrubbing, fluidised-bed combustion","Explain how NOx is formed in vehicles and how catalytic converters and SCR control it","Compare environmental impacts of different power sources","Discuss hazards from natural radioactivity and nuclear waste","Outline the waste management hierarchy and the chemistry of landfill and incineration","Identify common heavy-metal pollutants and their treatment by reduction and ion exchange","Describe acid mine drainage and its remediation"],"chapters":[{"id":"ev1","title":"Pollution and Environmental Chemistry — Setting the Scene","blocks":[{"type":"p","text":"Environmental chemistry studies the sources, behaviour, and removal of substances introduced into the natural environment by human activity. Most pollution comes down to a few well-understood chemical pathways: combustion (CO, CO₂, SO₂, NOx), industrial waste streams (heavy metals, organic solvents), agricultural run-off (nitrates, phosphates, pesticides), and end-of-life products (plastics, electronics). Each of these has both a chemistry of HOW the pollutant enters the environment and a chemistry of WHAT can be done to reduce or remove it."},{"type":"d","caption":"Major pollutant categories in the syllabus"},{"type":"h","text":"Some recurring chemistry ideas"},{"type":"ul","items":["Acid-base: SO₂ and NOx form acids in moist air → acid rain. Reverse the chemistry with alkaline scrubbers (chapter 3).","Redox: NOx and CO are reduced to N₂ and oxidised to CO₂ in catalytic converters (chapter 5). Heavy metals exist in different oxidation states with different toxicities (e.g. Cr(III) vs Cr(VI)).","Equilibrium: many pollution-control processes work by shifting an equilibrium — flue gas desulphurisation pulls SO₂ out of the gas phase by reacting it with solid CaCO₃, removing it from the atmospheric cycle.","Catalysis: catalytic converters (chapter 5) and selective catalytic reduction (SCR) of NOx in power-station chimneys.","Phase equilibria: ion-exchange resins (link to AC-22) take heavy metal ions out of waste water by exchanging them for harmless Na⁺ or H⁺."]},{"type":"h","text":"Why this topic matters"},{"type":"ul","items":["The chemistry of pollution control is both academically interesting and economically vital — global pollution-control industry is worth ~ $1 trillion/year and growing.","Many syllabus topics tie together here: catalysis, equilibria, redox, acid-base, organic toxicology, chromatography for monitoring.","Engineers and policy-makers depend on the chemistry to set emissions standards, design equipment, and verify compliance.","Public health: respiratory disease, cardiovascular disease, cancer, neurological damage are all linked statistically to specific chemical pollutants."]},{"type":"h","text":"How the topic is structured"},{"type":"ul","items":["Chapters 2–3: sulphur dioxide pollution and control.","Chapter 4: nitrogen oxides and acid rain.","Chapter 5: catalytic converters and lean-burn engines.","Chapters 6–7: power generation — fossil fuels and nuclear.","Chapter 8: waste management hierarchy.","Chapter 9: landfill and incineration in detail.","Chapter 10: heavy metals and water-borne pollutants."]},{"type":"callout","title":"Pollutant","body":"A substance present in the environment in higher concentrations than would naturally occur, with measurable detrimental effects on health, ecosystems, or built infrastructure. The same substance (e.g. nitrate) may be a nutrient at low concentration and a pollutant at high concentration."},{"type":"takeaway","items":["Environmental chemistry covers both the formation and the abatement of pollutants.","Acid-base, redox, equilibrium, and catalysis recur as the underlying chemistry.","Topic ties together to most other syllabus areas — kinetics, equilibria, organic, transition metals.","Pollution control is a major global industry with measurable public-health benefits."]}]},{"id":"ev2","title":"Sulphur Dioxide & Acid Rain","blocks":[{"type":"p","text":"Sulphur dioxide (SO₂) is the most important acidic gas pollutant from coal combustion. Coal contains 0.5 – 4% sulphur (as iron pyrite, FeS₂, or as organic sulphur). When the coal burns, the sulphur oxidises to SO₂, which is released into the flue gas. Acid rain — first identified in the 1970s as the cause of forest decline in Scandinavia — is the chief environmental consequence."},{"type":"d","caption":"SO₂ → H₂SO₄ in two oxidation steps"},{"type":"h","text":"How SO₂ becomes acid rain"},{"type":"ul","items":["Step 1: combustion. S(in coal) + O₂ → SO₂(g). Roughly 5–20 kg of SO₂ per tonne of coal burnt.","Step 2: oxidation in the atmosphere. 2SO₂ + O₂ → 2SO₃. Slow without catalysts; fast in the presence of NOx (acts as a catalytic carrier of O atoms) or transition-metal aerosols.","Step 3: dissolution in water droplets. SO₃ + H₂O → H₂SO₄. Sulphuric acid is a strong acid, fully ionised in water.","Step 4: deposition. Acidic rain (pH 4 typical, sometimes pH 3 in heavily polluted areas) falls back onto land and water.","Note that SO₂ itself dissolves directly: SO₂ + H₂O ⇌ H₂SO₃ (sulphurous acid, weak). Both H₂SO₃ and H₂SO₄ contribute, but H₂SO₄ dominates the acidity over time."]},{"type":"h","text":"Damage caused by acid rain"},{"type":"ul","items":["Lakes and rivers: pH drops below 5.5 — toxic to fish (e.g. trout); lakes in Sweden and Canada lost most of their aquatic life by the 1980s.","Forests: leaches Mg²⁺ and Ca²⁺ from soil (essential nutrients); mobilises Al³⁺ which is toxic to roots; weakens trees against disease and drought.","Buildings: limestone/marble (CaCO₃) reacts: CaCO₃ + H₂SO₄ → CaSO₄ + CO₂ + H₂O. Surfaces lose detail; many famous monuments (Acropolis, Taj Mahal, Cologne Cathedral) have suffered visible damage. The CaSO₄ formed is more soluble than the original CaCO₃, so erodes away.","Iron/steel structures: H₂SO₄ accelerates rusting. Cathedrals' iron reinforcements; rail bridges; iron statues all corrode faster.","Human health: fine sulphate aerosols penetrate deep into lungs; correlated with increased asthma and cardiovascular disease."]},{"type":"h","text":"Sulphurous gases — a comparison"},{"type":"ul","items":["SO₂: from coal/oil combustion, ore smelting (Cu, Ni). Major historical pollutant.","H₂S: from petroleum refining, sewage, volcanic. Smaller scale. Highly toxic but oxidises quickly to SO₂ in air.","COS, CS₂: trace sulphur compounds from natural and industrial sources. Mostly local issues."]},{"type":"h","text":"Trends in atmospheric SO₂"},{"type":"ul","items":["Peak SO₂ emissions in industrialised countries: roughly 1970s. EU acid-rain legislation, US Clean Air Act amendments (1990) → emissions cut by 70–90% in subsequent decades.","Lakes recovering — but soils are slower to heal because aluminium contamination persists.","Developing economies (China, India) had rising emissions through 2000s but China has now begun aggressive control measures and emissions are falling.","Continued threat from sulphur-rich coal in some regions; from shipping fuel (heavy fuel oil with up to 4.5% S — mostly capped by IMO sulphur rule from 2020)."]},{"type":"callout","title":"Sulphur in coal — global impact","body":"A 1 GW coal power station burning 4% sulphur coal at 30% efficiency emits roughly 80 000 tonnes of SO₂ per year if uncontrolled. The same plant with FGD (chapter 3) emits less than 5000 tonnes. The technology exists to cut SO₂ emissions to near-zero — the question is policy and cost."},{"type":"takeaway","items":["SO₂ from coal combustion → atmospheric oxidation → H₂SO₄ → acid rain.","Damage: lakes (fish die), forests (nutrient loss), buildings (CaCO₃ erosion).","Acid rain pH typically 4, sometimes 3 in heavily polluted areas.","Industrialised countries have cut emissions ~80% since the 1970s; trend now global."]}]},{"id":"ev3","title":"Controlling SO₂ Emissions","blocks":[{"type":"p","text":"There are three main industrial strategies for cutting SO₂ emissions, each rooted in acid-base chemistry: flue gas desulphurisation (FGD) with a calcium or alkali sorbent; alkaline scrubbing with NaOH or Mg(OH)₂; and fluidised-bed combustion that captures SO₂ at source. The choice depends on plant size, cost, and the form in which the spent sorbent is disposed."},{"type":"d","caption":"Three industrial methods for SO₂ capture"},{"type":"h","text":"Flue Gas Desulphurisation (FGD) — wet limestone"},{"type":"ul","items":["Most widely used technology — fitted to most modern coal-fired power stations.","Process: flue gas is sprayed with a slurry of finely-ground limestone CaCO₃ in water. SO₂ dissolves in the water and reacts with CaCO₃.","Net reaction (with oxidation): 2CaCO₃ + 2SO₂ + O₂ → 2CaSO₄ + 2CO₂. The CaSO₄ (gypsum) precipitates out as a solid.","Removal efficiency: 90–98% of SO₂ removed.","Product: gypsum-grade calcium sulphate is sold for plasterboard manufacture — turns a waste stream into a saleable product.","Drawbacks: high water consumption; large installation; CO₂ emitted as a by-product (adding to greenhouse gas emissions).","Variant: spray-dry FGD uses a slaked-lime slurry Ca(OH)₂ instead of CaCO₃; the product is a dry powder, easier to handle but lower-value."]},{"type":"h","text":"Alkaline scrubbing"},{"type":"ul","items":["Use a strong alkali solution — typically NaOH(aq) or Mg(OH)₂(aq) — to react with SO₂.","Reactions: 2NaOH + SO₂ → Na₂SO₃ + H₂O (then partial oxidation: 2Na₂SO₃ + O₂ → 2Na₂SO₄). Or with Mg: Mg(OH)₂ + SO₂ → MgSO₃ + H₂O.","Removal efficiency: 95–99% (very high — alkali drives the equilibrium far towards product).","Drawback: NaOH is expensive; spent solution is liquid waste containing dissolved salts; suitable for smaller plants where cost per tonne of SO₂ removed is less critical.","Used in smelting plants (copper, nickel) where SO₂ concentrations are very high and alkali consumption per kg of fuel is small."]},{"type":"h","text":"Fluidised-bed combustion (FBC)"},{"type":"ul","items":["Burn the coal in a bed of crushed limestone particles, suspended (\\"fluidised\\") by an upward stream of air.","CaCO₃ first decomposes thermally: CaCO₃ → CaO + CO₂.","Then captures SO₂ in situ as it forms: CaO + SO₂ + ½O₂ → CaSO₄.","Operating temperature is lower than a conventional pulverised-coal boiler (~850 °C vs ~1500 °C). Lower T also REDUCES NOx formation (chapter 4 explains why) — combined air-quality benefit.","Removal: 70–90% of SO₂ in situ. Easier to retrofit on smaller boilers than a wet FGD.","Used: power station boilers, industrial steam generators, district heating."]},{"type":"h","text":"Comparing the three methods"},{"type":"ul","items":["Removal efficiency: alkaline scrubbing > FGD wet > FBC.","Capital cost: FGD wet > alkaline scrubbing > FBC.","Operating cost: alkaline scrubbing > FGD wet > FBC (NaOH is expensive).","Saleable by-product: FGD wet (gypsum) > alkaline scrubbing (Na sulphate) > FBC (CaSO₄ + ash mixed).","Co-benefit on NOx: FBC > FGD wet ≈ alkaline scrubbing (FGD reduces NOx slightly via the spray; FBC reduces it via low T)."]},{"type":"h","text":"Other approaches mentioned in passing"},{"type":"ul","items":["Switch to lower-sulphur coal (varies by mine; Eastern US coal is high-S, Western US low-S).","Switch to cleaner fuel: natural gas has essentially no S; oil has moderate S; renewables have zero.","Pre-combustion desulphurisation: e.g. coal washing reduces inorganic FeS₂ content but does little for organic S.","Selective catalytic reduction (SCR): more often used for NOx but some catalysts also remove SO₂ co-pollutants."]},{"type":"callout","title":"The unifying chemistry","body":"Every SO₂ control strategy uses the acid-base reaction of acidic SO₂ with a base — CaCO₃, CaO, NaOH, or Mg(OH)₂. The chemistry is identical to neutralisation in a beaker; only the engineering differs."},{"type":"takeaway","items":["FGD (wet limestone): standard for power stations; gypsum by-product.","Alkaline scrubbing: highest removal; expensive; for smelting and small plants.","Fluidised-bed combustion: in-situ capture; lower T → also less NOx.","All three exploit acid-base reaction of SO₂ with a base."]}]},{"id":"ev4","title":"Nitrogen Oxides & Acid Rain","blocks":[{"type":"p","text":"NOx — a collective term for NO and NO₂ — is the second major contributor to acid rain (after SO₂). Unlike SO₂, NOx is not present in the fuel; it forms by oxidation of atmospheric N₂ at the high temperatures inside engines and combustion chambers. Reducing NOx requires either lowering the combustion temperature (lean-burn engines, low-NOx burners), reducing it back to N₂ after formation (catalytic converters, SCR), or switching to a fuel that burns cooler."},{"type":"h","text":"How NOx forms"},{"type":"ul","items":["Three pathways: thermal NOx (the main one), prompt NOx (small fraction), and fuel NOx (only relevant for nitrogen-rich fuels like coal).","Thermal NOx: at temperatures above 1500 °C, atmospheric N₂ and O₂ react: N₂ + O₂ → 2NO. The reaction is endothermic by 90.4 kJ/mol — only fast at high T.","Inside a car engine cylinder during combustion, T can reach 2500 °C; NOx formation is significant during the few milliseconds of peak combustion.","Once formed, NO partially oxidises in the exhaust: 2NO + O₂ → 2NO₂.","Atmospheric chemistry: NO + O₃ → NO₂ + O₂; NO₂ photolysis gives back NO + O. Cycle continues until NOx is washed out as nitric acid."]},{"type":"h","text":"NOx → nitric acid → acid rain"},{"type":"ul","items":["Slow gas-phase oxidation: 2NO + O₂ → 2NO₂; NO₂ + OH• → HNO₃ (slow, but persistent in atmosphere).","Aqueous-phase reaction in cloud droplets: 3NO₂ + H₂O → 2HNO₃ + NO. Net: dissolves out NO₂ as nitric acid, releasing some NO back to the atmosphere.","Combined oxidation: 4NO + 3O₂ + 2H₂O → 4HNO₃ (slow but cumulative).","Result: rainwater pH drops further. In the polluted northeast US in the 1980s, ~60% of acidity from H₂SO₄ and ~40% from HNO₃; nitric acid contribution rising as SO₂ controls bite."]},{"type":"h","text":"Other harmful effects of NOx"},{"type":"ul","items":["PHOTOCHEMICAL SMOG: NOx + sunlight + volatile organic compounds (from vehicle exhaust and industrial solvents) → ground-level ozone (O₃) + peroxyacetyl nitrates (PAN).","Ground-level O₃ is a respiratory irritant and a powerful greenhouse gas. PAN is a powerful eye irritant.","Smog episodes in Los Angeles (1950s onwards), Mexico City, Beijing, New Delhi, Athens.","Health: NOx damages respiratory tissue directly; aggravates asthma; correlated with cardiovascular events.","Eutrophication: NOx deposition on land and water adds nitrogen — too much can fertilise algae bloom, killing fish.","Greenhouse contribution: N₂O (a related but distinct nitrogen oxide, formed in agriculture and combustion) has 300× the warming effect of CO₂, kg-for-kg. About 6% of total greenhouse gas warming."]},{"type":"h","text":"Sources of NOx"},{"type":"ul","items":["Vehicle engines: 50–80% of urban NOx in industrialised countries. Diesel engines are particularly bad (run hotter and leaner than petrol).","Power stations and industrial boilers: 20–30%.","Aviation: small but rising; high-altitude NOx affects ozone differently than ground-level.","Natural sources: biomass burning, soil microbes, lightning. Together ~30% of global NOx but distributed widely."]},{"type":"callout","title":"NOx","body":"Collective term for the gases NO (nitric oxide, colourless) and NO₂ (nitrogen dioxide, brown). N₂O (nitrous oxide) is a related but separate compound, important as a greenhouse gas but not normally counted as \\"NOx\\" because it comes from different sources and has different effects."},{"type":"takeaway","items":["NOx forms from atmospheric N₂ at high combustion T (>1500 °C).","Atmospheric oxidation → HNO₃ → acid rain (now ~40% of total acidity).","Photochemical smog: NOx + sunlight + VOCs → ground-level ozone.","Sources: vehicles (urban dominant), power stations, industrial boilers."]}]},{"id":"ev5","title":"Catalytic Converters & Lean-Burn Engines","blocks":[{"type":"p","text":"The two main approaches to reducing vehicle NOx and other exhaust pollutants are: (1) the three-way catalytic converter (chemistry on the exhaust pipe — convert pollutants to harmless gases); and (2) the lean-burn engine (combustion design — produce less pollutant in the first place). The two are complementary; modern petrol engines combine both, and diesels add SCR (selective catalytic reduction with urea injection)."},{"type":"d","caption":"Three-way catalytic converter — handles CO, hydrocarbons, and NOx"},{"type":"h","text":"The three-way catalytic converter — function"},{"type":"ul","items":["Catalysts: platinum (Pt) and palladium (Pd) for oxidation; rhodium (Rh) for reduction. All three are precious-metal transition elements with active d-orbitals (link to AC-21 transition metal catalysis).","Support: ceramic honeycomb (cordierite, 2MgO·2Al₂O₃·5SiO₂) coated with washcoat (γ-Al₂O₃) on which the precious metals are dispersed as nano-particles. The honeycomb maximises surface area while minimising back-pressure.","Working temperature: > 350 °C. Below this the catalyst is inactive (the cold-start problem; modern cars use additional electrically-heated catalysts to handle the first 20-30 seconds).","Three reactions handled simultaneously: (a) oxidation of CO; (b) oxidation of unburnt hydrocarbons; (c) reduction of NOx."]},{"type":"h","text":"The three reactions"},{"type":"ul","items":["Oxidation of CO: 2CO + O₂ → 2CO₂ (over Pt or Pd surface).","Oxidation of hydrocarbons: e.g. C₈H₁₈ + 12½O₂ → 8CO₂ + 9H₂O (over Pt or Pd).","Reduction of NOx: 2NO + 2CO → N₂ + 2CO₂ (over Rh). The CO is being oxidised AND the NO is being reduced simultaneously — both pollutants destroyed in one elegant step.","Optimal performance requires the air/fuel ratio to be near stoichiometric (~14.7:1 by mass, λ ≈ 1.0). Lambda sensors in the exhaust monitor O₂ and the engine ECU adjusts fuel injection in real time to keep the catalyst within its window.","Removal efficiency: 90–98% for each pollutant in normal driving conditions."]},{"type":"h","text":"Why catalysts work — recap of AC-21 ideas"},{"type":"ul","items":["Heterogeneous catalysis: gas-phase reactants adsorb on the metal surface, weakening their bonds and bringing them close together for reaction.","Pt, Pd, Rh have partially-filled d-orbitals that interact effectively with both CO (via the carbon lone pair and π* orbital) and NO (via the N lone pair).","Catalysts are not consumed — they cycle through adsorbed states and regenerate as products desorb.","Catalyst poisons: lead destroys the catalyst (forms stable Pt-Pb compounds, blocking active sites). Hence the global switch to UNLEADED PETROL from the 1970s onwards."]},{"type":"h","text":"The lean-burn engine"},{"type":"ul","items":["Standard (\\"stoichiometric\\") petrol engine: air/fuel ratio λ ≈ 1.0. Produces some unburnt hydrocarbons (rich pockets) and some NOx (hot zones) — handled by 3-way cat.","Lean-burn engine: λ > 1 (excess air). Lower combustion temperature → much less thermal NOx formed. More complete combustion → less unburnt hydrocarbon and CO.","Fuel economy benefit: leaner combustion = more oxygen-rich = more efficient extraction of energy from the fuel; up to 20% better fuel economy.","Drawback: with so much excess O₂ in the exhaust, the 3-way reduction of NOx no longer works (O₂ takes the catalyst sites and prevents NO reduction). Lean-burn engines need a DIFFERENT NOx control system: lean NOx trap (LNT) or selective catalytic reduction (SCR)."]},{"type":"h","text":"SCR — selective catalytic reduction (modern diesels)"},{"type":"ul","items":["Diesel engines run very lean (λ ≈ 1.5–2.5). Three-way catalysts cannot handle the NOx.","SCR: inject a urea solution (AdBlue / DEF — 32.5% urea in deionised water) into the hot exhaust. Urea decomposes to ammonia: (NH₂)₂CO + H₂O → 2NH₃ + CO₂.","Ammonia reduces NOx selectively over a copper-zeolite or vanadium-based catalyst: 4NH₃ + 4NO + O₂ → 4N₂ + 6H₂O. (The \\"selectivity\\" — SCR — is that NH₃ reduces NOx but does not waste reductant on the abundant O₂.)","Removal: 80–95% of NOx.","Drawback: requires AdBlue refilling (typical car: every 15 000–20 000 km). Modern diesels essentially all use SCR."]},{"type":"callout","title":"Why catalytic converters changed everything","body":"Without catalytic converters, every car would emit ~10× the pollution it does today. The technology was mandated in the US (1975) and EU (1993), and is responsible for the dramatic improvement in urban air quality in industrialised countries despite the rise in vehicle numbers."},{"type":"takeaway","items":["3-way catalytic converter: Pt, Pd, Rh on ceramic honeycomb; oxidises CO + HC, reduces NOx.","Critical reaction: 2NO + 2CO → N₂ + 2CO₂ (Rh catalyst).","Lean-burn engine: better fuel economy + lower NOx but needs SCR (urea injection) for NOx control.","Lead poisons Pt — universal switch to unleaded fuel."]}]},{"id":"ev6","title":"Power Generation & Climate","blocks":[{"type":"p","text":"Electricity generation accounts for about a quarter of all greenhouse gas emissions. The choice of fuel — coal, gas, nuclear, hydroelectric, or renewable — determines the chemistry of the emissions and therefore the environmental cost. Each source has trade-offs that the chemistry and the policy must address."},{"type":"d","caption":"Comparison of major power sources"},{"type":"h","text":"Fossil fuels — combustion chemistry recap"},{"type":"ul","items":["Coal: a complex, high-carbon, sulphur-containing solid. Composition varies but typically 70-90% C, 4-6% H, 1-4% S, 1-5% N, 5-15% O, plus mineral matter (the ash).","Combustion: C + O₂ → CO₂ (the dominant reaction). Roughly 3.7 kg of CO₂ per kg of carbon burnt. A 1 GW coal station emits ~6 million tonnes CO₂/year.","Side reactions: S + O₂ → SO₂ (chapter 2); 2N₂ + O₂ → 2NO (chapter 4); incomplete combustion → CO and unburnt carbon (soot).","Natural gas: mostly methane CH₄. CH₄ + 2O₂ → CO₂ + 2H₂O. About 0.55 kg CO₂ per kWh — half of coal's 1.0 kg CO₂/kWh because (i) more H per C (so more H₂O than CO₂) and (ii) higher conversion efficiency.","Oil: liquid hydrocarbons, intermediate. Mainly used for transport, not power generation (transport accounts for most oil use)."]},{"type":"h","text":"Climate change — the chemistry"},{"type":"ul","items":["Greenhouse gases (CO₂, CH₄, N₂O, water vapour, fluorinated gases) absorb infrared radiation emitted by Earth's surface, trapping heat in the lower atmosphere.","CO₂ is the dominant anthropogenic greenhouse gas — long-lived (centuries-millennia in the atmosphere) and rising rapidly with fossil fuel use.","Pre-industrial atmospheric CO₂: 280 ppm. Today: ~420 ppm. The fastest known rise in geological history.","Effects: global mean temperature has risen ~1.2 °C since 1900. Heatwaves, sea level rise, more intense storms, ocean acidification, biodiversity loss.","Important to distinguish: traditional air pollutants (SO₂, NOx, CO) cause LOCAL/REGIONAL damage and are removed from the atmosphere on timescales of days. CO₂ causes GLOBAL damage and persists for centuries."]},{"type":"h","text":"Decarbonising power — alternatives"},{"type":"ul","items":["Nuclear: no CO₂ in operation; fuel (uranium) abundant; capacity factor ~90% (very reliable). Drawbacks: long-lived waste, accident risk, capital cost, public perception. (Chapter 7 covers the chemistry in detail.)","Hydroelectric: dam a river; turn turbines with falling water. Effectively zero CO₂ in operation, very long lifetime. Drawback: methane from rotting vegetation in the reservoir; ecological impact on river systems.","Wind: Pelton-type or modern horizontal-axis turbines. Zero CO₂ in operation. Intermittent (~25-40% capacity factor); needs storage or backup.","Solar PV: photons excite electrons in silicon (or thin-film) cells; current flows directly. Zero CO₂ in operation. Capital intensive; falling rapidly in cost.","Geothermal: hot water from underground rock; very limited geographic availability.","Biomass: in principle CO₂-neutral (plants absorb same CO₂ they release on combustion), but real life is messier (transport, processing, land use)."]},{"type":"h","text":"Energy storage — the key chemistry challenge"},{"type":"ul","items":["Renewables are intermittent — wind doesn't blow at night, sun doesn't shine at night. Need to store energy from peak production for when it's needed.","Lithium-ion batteries: now the dominant grid-scale storage. Chemistry covered in PC-06 electrochemistry and AC-21 transition metals.","Pumped hydro: pump water uphill when energy is cheap; let it flow down through turbines when needed. Mature, large-scale.","Hydrogen: produce by electrolysis of water (2H₂O → 2H₂ + O₂); store; burn or use in fuel cell to recover energy. Potential for \\"green\\" hydrogen if powered by renewables.","Compressed air, flywheels, thermal storage: niche but growing."]},{"type":"h","text":"Why this is a hard problem"},{"type":"ul","items":["Coal and gas are CHEAP — fossil fuel prices remain competitive without carbon pricing.","Existing infrastructure (power lines, plants, networks) was built for steady fossil generation.","Renewables need new infrastructure (transmission lines, storage, demand-response).","Different countries have different resources (much wind in UK; much sun in southern Europe; much hydro in Scandinavia; coal in China and India).","Pace of transition is constrained by replacement rate of large infrastructure (typical lifespan 30-50 years)."]},{"type":"callout","title":"CO₂ vs traditional pollutants","body":"The chemistry of pollution control treats SO₂, NOx, particulates, and heavy metals — local-to-regional pollutants. Climate change is a different problem: CO₂ is not \\"captured\\" by an end-of-pipe control. The only real solutions are to burn less fossil fuel, capture CO₂ at source (CCS), or remove it from the atmosphere (not yet at scale)."},{"type":"takeaway","items":["Coal: high CO₂, high SO₂, high NOx. Worst conventional fuel.","Gas: half the CO₂ of coal; very low SO₂; moderate NOx.","Nuclear: no CO₂ in operation; waste and accident concerns.","Wind/solar: zero CO₂ in operation; intermittent; needs storage.","Decarbonisation = the central environmental chemistry challenge of our time."]}]},{"id":"ev7","title":"Nuclear Power & Hazards","blocks":[{"type":"p","text":"Nuclear power generates electricity from the heat released by controlled fission of heavy nuclei (mostly ²³⁵U or ²³⁹Pu). It produces zero CO₂ in operation and supplies about 10% of global electricity. The hazards are entirely different from those of fossil fuel: instead of air pollutants, the issue is radioactive waste, accident risk, and naturally occurring radioactivity from uranium-bearing rocks."},{"type":"d","caption":"Three categories of nuclear hazard"},{"type":"h","text":"How nuclear power works (briefly)"},{"type":"ul","items":["Fuel: uranium, mined as the oxide U₃O₈ (\\"yellowcake\\"); enriched in the fissile isotope ²³⁵U from 0.7% (natural) to about 4–5% (reactor-grade); fabricated into ceramic UO₂ pellets stacked in zirconium-alloy fuel rods.","Fission: ²³⁵U + n → ²³⁶U* → fission fragments (e.g. ¹⁴⁰Ba + ⁹³Kr or many other combinations) + 2-3 n + ~200 MeV energy.","Each fission releases neutrons that can cause more fissions — chain reaction. Controlled by neutron-absorbing rods (B, Cd, Hf) inserted into the core.","Heat → boils water → steam turbine → electricity (just like a coal plant, but the heat source is fission, not combustion).","A 1 GW reactor consumes about 30 tonnes of fuel/year (vs ~3 million tonnes of coal — 100 000 times less mass)."]},{"type":"h","text":"Naturally occurring radioactivity"},{"type":"ul","items":["Uranium and thorium are present at trace levels in most rocks, especially granite. They decay through long chains, releasing α-particles, β-particles, and γ-rays.","RADON (²²²Rn) is the most important hazard: a noble gas released from decay of U in rocks, diffuses through soil into buildings, accumulates indoors. α-emitter; if breathed in, lung cancer risk is significant.","Mitigation: ventilate basements; build with radon-impermeable membranes in high-Rn areas (e.g. Cornwall in the UK; parts of Pennsylvania in US).","Mining workers face higher exposure: U mining historically had very poor radiation protection; high lung cancer rates among uranium miners in the 1950s-70s prompted modern regulations.","Building stone: granite countertops emit some Rn but at safe levels for normal use."]},{"type":"h","text":"Operational waste"},{"type":"ul","items":["Low-level waste: contaminated tools, clothing, water; short half-lives (years); can be stored in shallow burial after a few decades.","Intermediate-level waste: reactor components, sludges; longer-lived; usually solidified in cement and stored in lined vaults.","High-level waste (the spent fuel): hot, intensely radioactive; contains fission products and trans-uranic elements.","Most worrying isotopes: ¹³⁷Cs (t½ 30 yr), ⁹⁰Sr (t½ 29 yr), ¹³¹I (t½ 8 days), and very long-lived actinides ²³⁹Pu (t½ 24 000 yr), ⁹⁹Tc (t½ 211 000 yr).","Volume is small — total global high-level waste from 60 years of nuclear power fits in a sports stadium. But it must be isolated from the biosphere for ~10⁵ years."]},{"type":"h","text":"Disposal strategies"},{"type":"ul","items":["Vitrification: incorporate waste into glass blocks (silicate-based) that resist leaching for 10⁵ years.","Deep geological repository: bury vitrified waste 500-1000 m underground in stable rock formations. Finland's Onkalo (operating from 2025) is the first; others in development in Sweden, France, Switzerland.","Reprocessing: chemically separate unburnt U and Pu from the waste, recycle as fresh fuel (closes the fuel cycle, reduces waste volume). Done in France, UK, Russia, Japan; not in US for proliferation concerns.","Transmutation: in principle, neutron irradiation could turn long-lived actinides into shorter-lived ones. Research-stage only."]},{"type":"h","text":"Accidents"},{"type":"ul","items":["Three Mile Island (1979, USA): partial core melt, but containment held. No measurable health effects on public.","Chernobyl (1986, USSR): graphite-moderated reactor went prompt-supercritical during a poorly-conducted test, exploded, fire spread fission products across Europe. Estimated 4 000 - 60 000 cancer deaths over decades.","Fukushima (2011, Japan): tsunami knocked out backup cooling at three reactors; cores melted; controlled venting and seawater quenching limited release. Estimated long-term cancer deaths ~ hundred or fewer.","Lessons: containment is critical; passive (failure-tolerant) cooling systems; siting away from major hazards."]},{"type":"callout","title":"The nuclear paradox","body":"Nuclear power is among the LEAST carbon-emitting and SAFEST per unit of energy produced (deaths per TWh) of any electricity source — including wind. Yet public perception emphasises rare accidents over the steady, long-term mortality from coal pollution. The chemistry is well understood; the politics is not."},{"type":"takeaway","items":["Nuclear: zero CO₂ operation; fission of ²³⁵U/²³⁹Pu → heat → electricity.","Hazards: radon from U-bearing rocks; spent fuel; rare accidents.","Waste: ~10⁵ yr isolation needed; vitrification + deep geological repository.","Accidents: Three Mile Island (contained), Chernobyl (worst), Fukushima (moderate)."]}]},{"id":"ev8","title":"Waste Management Hierarchy","blocks":[{"type":"p","text":"Modern waste management follows a five-step hierarchy, in order of preference: REDUCE, REUSE, RECYCLE, INCINERATE (with energy recovery), LANDFILL. The first three have lowest environmental impact; the last two are end-of-pipe options. Chemistry plays a role at every level — designing materials to be recyclable, optimising recycling processes, controlling combustion to minimise toxic emissions."},{"type":"d","caption":"Five-tier waste hierarchy — top is best"},{"type":"h","text":"Reduce"},{"type":"ul","items":["Use less material in the first place. e.g. lighter packaging, dematerialised products, repairable rather than disposable.","Best for the environment but hardest to legislate or measure.","Examples: thinner aluminium drink cans (reduced by 40% over 30 years); EU bans on single-use plastic items; redesign of products for durability and repair."]},{"type":"h","text":"Reuse"},{"type":"ul","items":["Same physical item used multiple times. Glass milk bottles before disposable plastics; refillable water bottles; refurbished computers.","Energy savings vs new: typically 70-90% (depending on product).","Example: deposit-return schemes for glass and PET bottles. Currently ~95% return rate in countries that have them (Norway, Germany)."]},{"type":"h","text":"Recycle"},{"type":"ul","items":["Collect waste material; reprocess it into raw material; manufacture new products from it.","Chemistry-intensive: paper de-inked; aluminium re-melted (saves 95% of energy vs primary smelt); steel re-melted; PET hydrolysed or re-melted; glass melted; lead-acid batteries decomposed and rebuilt.","Recycling rates: aluminium > 70%, paper > 60%, glass > 70% in EU. PET ~40%; mixed plastics much lower.","Single-stream \\"comingled\\" recycling improves consumer participation but increases contamination — sorting becomes harder.","Some materials cannot be recycled cost-effectively (low value, contamination, mixed materials) — these end up incinerated or landfilled."]},{"type":"h","text":"Recovery (incineration with energy)"},{"type":"ul","items":["Burn at controlled temperature (typically > 850 °C to destroy organic toxins like dioxins).","Generate steam → electricity + district heating.","Reduces volume by ~90% (dense ash residue).","Issues: COMBUSTION PRODUCTS — CO₂, NOx, particulates, possibly dioxins (esp. from chlorinated plastics like PVC), SO₂ if S-containing waste, heavy metals from battery and other contamination.","Modern incinerators have advanced flue gas treatment: particulate filters (electrostatic precipitators, baghouses), SCR for NOx, scrubbers for SO₂ and HCl, activated carbon injection for dioxins and Hg.","Bottom ash often used as construction aggregate; fly ash hazardous, sent to special landfill."]},{"type":"h","text":"Disposal (landfill)"},{"type":"ul","items":["Last resort. Put the waste in the ground, cover, monitor.","Modern engineered landfill: lined with HDPE membrane + clay to prevent leachate escape; collection pipes for leachate (which is treated); methane capture (anaerobic decomposition produces CH₄, a strong greenhouse gas if vented; usually flared to CO₂ or used for power).","Decomposition timescales: organic waste decomposes over decades; plastics over centuries; some materials effectively indefinite.","Issues: land use; leachate even with liners eventually fails; methane escapes; potential for groundwater contamination.","Old, uncontrolled landfills are environmental disasters — many require remediation decades after closure."]},{"type":"callout","title":"Material design matters","body":"A product designed for easy recycling — separable components, single-material packaging, no glued mixed-material parts — recycles efficiently. A product not designed for recycling often cannot be recycled economically. Chemistry and engineering choices made at design time determine end-of-life options."},{"type":"takeaway","items":["Hierarchy: reduce > reuse > recycle > recover (incinerate) > dispose (landfill).","Reduce: less material used. Reuse: same item, multiple lives. Recycle: reprocess to raw material.","Energy savings of recycling: aluminium saves 95% vs primary; steel ~70%; glass ~30%.","Modern landfills and incinerators have strong environmental controls but are not zero-impact."]}]},{"id":"ev9","title":"Landfill, Incineration & Dumping","blocks":[{"type":"p","text":"When reduce, reuse and recycle have done their work, the residual waste needs disposal. Two engineering approaches dominate: landfill (controlled burial) and incineration (controlled combustion). A third, much less acceptable, is dumping at sea or in rivers. Each has specific chemistry that determines its environmental impact."},{"type":"d","caption":"Pros and cons of landfill vs incineration"},{"type":"h","text":"Modern engineered landfill — chemistry"},{"type":"ul","items":["Liner: HDPE membrane + compacted clay layer at the base, to prevent leachate escape.","Cover: daily soil layer to control odours and pests; final cap when site is full (impermeable layer + soil + vegetation).","Leachate: water that percolates through the waste, dissolving soluble contaminants. Composition: high in BOD/COD, ammonia, heavy metals, organic chemicals. Collected by drainage pipes; treated like sewage before discharge.","Gas: anaerobic decomposition of organic waste produces CH₄ + CO₂ (50:50 mixture). Methane is captured via vertical wells, then either flared to CO₂ (less harmful greenhouse gas) or used as fuel for power generation.","Decomposition stages: aerobic (initial weeks) → anaerobic (years to decades). After 30-50 years a landfill is biologically \\"stable\\" but plastic and metals remain unchanged."]},{"type":"h","text":"Modern incineration — chemistry"},{"type":"ul","items":["Combustion conditions: > 850 °C, residence time 2 seconds, excess oxygen — to destroy organic toxins.","Primary combustion: organic waste + O₂ → CO₂ + H₂O + heat. Inorganic (metals, ash) does not burn — it falls through as bottom ash.","Side products: NOx (from N in protein-rich waste; controlled by SCR or low-NOx burners); SO₂ (from S in waste; controlled by scrubbing); HCl (from PVC; scrubbing with NaOH); particulate matter (controlled by ESP/baghouse).","DIOXINS: a major historical issue. Dioxins (polychlorinated dibenzo-p-dioxins, PCDDs) form at incinerator temperatures of 200-400 °C from chlorine-containing organics. At > 850 °C they are destroyed. Modern incinerators prevent dioxin re-formation by RAPID quench from > 850 °C through the danger zone.","Activated carbon: injected before the final filter to adsorb residual dioxins, mercury, and trace organics.","Ash: bottom ash (~25% of input mass) often used as construction aggregate; fly ash (5%, from filters) is more hazardous and sent to special landfill."]},{"type":"h","text":"Dumping in waterways and oceans"},{"type":"ul","items":["Direct discharge of untreated sewage into rivers and seas: still common in many parts of the world.","Sewage chemistry: high in nutrients (NH₄⁺, NO₃⁻, PO₄³⁻), pathogens, organics. Effects: oxygen depletion (eutrophication), algal blooms, fish kills, disease.","Modern sewage treatment: 3-stage process — primary (settling), secondary (biological breakdown by bacteria), tertiary (nitrate/phosphate removal, UV/Cl disinfection).","Oil spills: major chemical impact on marine ecosystems. Crude oil floats and forms slicks; aromatic compounds dissolve into water; PAHs accumulate in shellfish; tar adheres to feathers/fur.","Cleanup: booms (containment), skimmers (recovery), dispersants (chemical break-up), bioremediation (oil-eating bacteria added). Each has trade-offs.","International law: MARPOL Convention regulates ship discharges; Ocean Dumping Convention bans dumping at sea of certain wastes (radioactive, chlorinated organic, mercury)."]},{"type":"h","text":"The \\"polluter pays\\" principle"},{"type":"ul","items":["Modern environmental legislation in most countries: the producer of pollution bears the cost of cleanup or prevention.","Implementation: emission permits, pollution taxes, deposit-return schemes, \\"extended producer responsibility\\" (e.g. for packaging, electronics).","Effectiveness: variable. Where enforced (EU, US), pollution levels have fallen. Where weakly enforced, dumping persists."]},{"type":"callout","title":"The right disposal for the right waste","body":"Organic-rich biodegradable waste → composting > landfill. Recyclable materials → recycle, never landfill. Hazardous chemicals → specialist hazardous-waste landfill. Toxic combustibles → high-T incineration. Inert non-recyclable → engineered landfill. Sewage → biological treatment, never untreated discharge. Mixing categories increases all of the problems."},{"type":"takeaway","items":["Modern landfill: lined, covered, leachate collected, methane captured.","Modern incineration: > 850 °C destroys dioxins; flue gas treatment controls NOx, SO₂, HCl, particulates.","Untreated sewage discharge: eutrophication, fish kills, disease.","Polluter-pays principle: producer bears cost of cleanup."]}]},{"id":"ev10","title":"Heavy Metals & Industrial Effluent","blocks":[{"type":"p","text":"Heavy metals — lead, mercury, cadmium, chromium, arsenic — are persistent toxic pollutants with no biological function in humans. Once released to the environment, they cycle indefinitely, biomagnify up food chains, and cause neurological, kidney, and other organ damage. Their chemistry of pollution control connects directly to the ion-exchange and chromatography of AC-22, and to the redox of AC-21."},{"type":"d","caption":"Five major heavy-metal pollutants"},{"type":"h","text":"Lead — the historical legend"},{"type":"ul","items":["Source: leaded petrol (banned in most countries by 2000), lead-based paint (banned in most rich countries by 1970s but still in older buildings), lead solder in plumbing, electronic waste, lead-acid batteries.","Toxicity: neurotoxin — IQ loss in children (3-5 IQ points per 10 µg/dL blood lead); cardiovascular disease in adults; reproductive effects.","Chemistry of removal: precipitation as PbS or PbCO₃ in lake sediments; sorption onto soil organic matter; ion-exchange resins for water treatment.","Notable success: leaded petrol phase-out cut atmospheric lead by ~95% in 30 years. Children's blood lead levels in industrialised countries fell similarly."]},{"type":"h","text":"Mercury — methylmercury and bioaccumulation"},{"type":"ul","items":["Sources: coal combustion (releases trace Hg from coal); artisanal gold mining (Hg used to amalgamate gold, then evaporated, releasing Hg vapour); industrial cell-room (chlor-alkali); past use in dental amalgam; mercury thermometers and switches.","Inorganic Hg(0) and Hg²⁺ are toxic but partly excreted. The dangerous form is METHYLMERCURY CH₃Hg⁺ — formed by anaerobic bacteria in lake sediments from inorganic Hg.","Methylmercury bioaccumulates: small fish ingest it, large fish eat many small fish, etc. Apex predators (tuna, swordfish, sharks) carry the highest concentrations.","Toxicity: methylmercury crosses the blood-brain barrier; severe neurological damage (Minamata disease, Japan, 1950s — fishing village poisoned by industrial Hg discharge into Minamata Bay).","Chemistry of removal: stack-gas treatment with activated carbon (adsorbs Hg) or selenium (forms HgSe, insoluble); avoid coal combustion; ban Hg in industrial processes."]},{"type":"h","text":"Chromium — Cr(III) vs Cr(VI)"},{"type":"ul","items":["Different oxidation states have very different toxicities (link to AC-21 transition elements).","Cr(III) (e.g. Cr₂O₃): essentially non-toxic; even an essential trace element for glucose metabolism.","Cr(VI) (e.g. CrO₄²⁻, Cr₂O₇²⁻): highly toxic, carcinogenic, mutagenic. Penetrates cell membranes; reduces inside the cell to Cr(III) which damages DNA.","Sources of Cr(VI) pollution: leather tanning, electroplating, stainless-steel production, wood preservatives.","Treatment: REDUCE Cr(VI) to Cr(III) using SO₂ or FeSO₄, then precipitate Cr(III) as Cr(OH)₃ insoluble solid.","The Erin Brockovich case (California, 1990s) involved Cr(VI) contamination of groundwater."]},{"type":"h","text":"Cadmium — batteries and ore"},{"type":"ul","items":["Source: NiCd batteries (now mostly replaced by NiMH and Li-ion); zinc-ore smelting (Cd is a co-product of Zn).","Toxicity: kidney damage (the Itai-Itai disease in Japan, 1910s-1960s, was Cd poisoning from contaminated rice); bone weakness; carcinogen (lung).","Treatment: precipitation as Cd(OH)₂ or CdS; recovery from battery waste streams."]},{"type":"h","text":"Arsenic — natural and anthropogenic"},{"type":"ul","items":["Largely a NATURAL contaminant: dissolves from arsenic-bearing rocks into groundwater. Worst affected: Bangladesh (10s of millions exposed), West Bengal, parts of Argentina, Vietnam.","Anthropogenic: tin and copper smelting; pesticides (now banned); wood preservatives.","Toxicity: chronic — skin lesions (arsenicosis); cancer (lung, bladder, skin); cardiovascular.","Treatment: oxidise As(III) to As(V); precipitate with iron(III) salts (forms FeAsO₄ insoluble); also activated alumina sorption."]},{"type":"h","text":"Industrial waste-water treatment using ion-exchange"},{"type":"ul","items":["Waste water from electroplating, mining, textile dyeing contains mixed heavy-metal cations.","Ion-exchange resin (chelating type, with iminodiacetate or aminophosphonate groups) selectively binds Cu²⁺, Pb²⁺, Cd²⁺, Hg²⁺ in preference to Na⁺ and Ca²⁺.","Flow waste through the column. Metals are retained on the resin. Effluent is metal-free.","Regenerate the resin with concentrated acid: acid releases the metals as soluble salts (concentrated waste stream, much smaller volume — easier to handle).","Metal recovery: precipitate from the regeneration acid as metal hydroxides; sometimes electroplate back to recover pure metal.","Same chemistry as water softening (chapter 7 of AC-22) but with chelating resins for heavy metals."]},{"type":"h","text":"Mine waste"},{"type":"ul","items":["Tailings: ground rock left after the metal has been extracted; often contains residual metal and toxic chemicals from extraction.","Acid mine drainage: pyrite (FeS₂) in tailings oxidises in air to give H₂SO₄ + Fe³⁺. The acidic water (often pH 2-4) leaches more heavy metals from the rock.","4FeS₂ + 15O₂ + 14H₂O → 4Fe(OH)₃ + 8H₂SO₄.","Treatment: limestone neutralises acid (CaCO₃ + H₂SO₄ → CaSO₄ + CO₂ + H₂O); precipitates Fe(OH)₃; constructed wetlands use sulphate-reducing bacteria to immobilise residual metals as sulphides.","Many old, abandoned mines continue to discharge for centuries."]},{"type":"callout","title":"Heavy metals never go away","body":"Unlike organic pollutants (which can be broken down by microbes or sunlight), heavy metals are ELEMENTS — they cannot be destroyed. They can only be moved or immobilised. Pollution prevention is therefore far more cost-effective than cleanup."},{"type":"takeaway","items":["Heavy metals (Pb, Hg, Cd, Cr, As) are persistent, toxic, bioaccumulate.","Lead: phase-out of leaded petrol cut atmospheric Pb by 95%.","Mercury: methylmercury bioaccumulates up food chain; coal main source.","Chromium: Cr(VI) toxic; reduce to Cr(III) and precipitate as hydroxide.","Industrial waste-water: ion-exchange recovers metals selectively.","Acid mine drainage: pyrite oxidation; treated with limestone neutralisation."]}]}]}`),nano:JSON.parse(`{"objectives":["Define the nanoscale and identify nanomaterials","Explain why surface-to-volume ratio drives much of nanoscale behaviour","Describe quantum confinement and its consequences (tunable optical properties)","Classify nanomaterials by dimensionality (0D, 1D, 2D, 3D) and recognise key examples","Explain applications in medicine: targeted drug delivery, imaging, antimicrobials","Explain applications in water and environmental remediation","Discuss risks of nanomaterials and the regulatory response"],"chapters":[{"id":"nn1","title":"What is the Nanoscale?","blocks":[{"type":"p","text":"The nanoscale spans 1 to 100 nanometres — about a billionth of a metre, ten to a thousand atoms across. At this size, materials behave differently from bulk: they catalyse more efficiently, absorb light at unusual wavelengths, melt at lower temperatures, and exhibit quantum effects. Nanotechnology is the deliberate manipulation of materials at this scale."},{"type":"d","caption":"1–100 nm: between atoms and bacteria"},{"type":"h","text":"Size context"},{"type":"ul","items":["A typical atom is about 0.1 nm; a small molecule (water) about 0.3 nm.","Proteins range from ~3 nm (small enzyme) to ~50 nm (virus capsid).","A DNA double helix is 2 nm in diameter.","A red blood cell is about 7 µm = 7000 nm.","A human hair is ~80 µm wide — 800 times the upper nanoscale limit."]},{"type":"h","text":"Why this range matters"},{"type":"ul","items":["Biological matter is largely built at this scale: proteins, DNA, viruses, organelles.","Quantum effects (electron confinement, tunnelling) become significant below ~10 nm.","Surface-to-volume ratio is enormous (next chapter).","Optical properties become size-dependent: gold nanoparticles look red at 30 nm and purple at 80 nm — bulk gold is yellow.","Catalytic activity often peaks for very small clusters."]},{"type":"h","text":"Nanoscience vs nanotechnology"},{"type":"ul","items":["Nanoscience: study of phenomena at the nanoscale — fundamental research.","Nanotechnology: design and manipulation of nanoscale structures for useful applications.","Top-down fabrication: carve from bulk material (lithography, milling).","Bottom-up fabrication: assemble from atoms/molecules (chemical synthesis, self-assembly)."]},{"type":"callout","title":"Nanoparticle","body":"A particle with at least one dimension in the range 1–100 nm. May be 0D (sphere), 1D (rod, tube), 2D (sheet), or 3D depending on which dimensions are nano-sized."},{"type":"takeaway","items":["Nanoscale = 1–100 nm; between atoms and bacteria.","This range coincides with biological structures and where quantum effects matter.","Top-down (carve) and bottom-up (assemble) are the two fabrication routes."]}]},{"id":"nn2","title":"Why Nano Properties Differ from Bulk","blocks":[{"type":"p","text":"Reduce a material from a coin to a nanoparticle and three things change: surface-to-volume ratio explodes, electron confinement starts to matter, and the fraction of surface atoms grows from negligible to dominant. Together these make nano-sized versions of familiar materials behave like entirely different substances."},{"type":"d","caption":"SA/V scales as 1/size — orders of magnitude bigger at nm"},{"type":"h","text":"Surface area-to-volume ratio (SA/V)"},{"type":"ul","items":["For a cube of side L: SA = 6L²; V = L³; SA/V = 6/L. As L decreases, SA/V increases.","A 1 cm cube has SA/V = 6 cm⁻¹. A 1 nm cube has SA/V = 6 × 10⁷ cm⁻¹ — ten million times bigger.","For a fixed mass, breaking it into nanoparticles dramatically increases the total exposed surface.","Consequences: faster reaction with environment, more efficient catalysis, lower melting point, faster dissolution."]},{"type":"h","text":"High SA/V matters in catalysis"},{"type":"ul","items":["Heterogeneous catalysts work at the surface — only surface atoms can adsorb reactants.","In bulk Pt, only the outermost atoms are active — a tiny fraction of total Pt mass.","Pt nanoparticles 2 nm across: ~50% of atoms are at the surface. Almost every Pt atom does useful chemistry.","Cost saving: same activity for less precious metal.","This is exactly why catalytic converters use nano-dispersed Pt/Pd/Rh on alumina (AC-23 chapter 5)."]},{"type":"h","text":"High SA/V drives reactivity and dissolution"},{"type":"ul","items":["A solid dissolves at its surface — rate is proportional to surface area.","Nano-sized drug particles dissolve faster than micro-sized → faster onset of action.","Nano iron particles in contaminated groundwater react quickly with pollutants — bulk iron in the same site would corrode much more slowly.","Nano-aluminium powder ignites in air spontaneously; bulk aluminium is stable thanks to its protective oxide layer."]},{"type":"h","text":"Quantum confinement"},{"type":"ul","items":["Below about 10 nm, electrons in semiconductor nanoparticles (\\"quantum dots\\") are confined to a small region. Energy levels become discrete (like atoms) rather than continuous bands.","Energy gap ∝ 1/L². So smaller dot → larger gap → higher-energy emitted light.","CdSe quantum dots: 2 nm dot → blue fluorescence; 7 nm dot → red. Just by changing size, the colour tunes.","Used in: high-quality TVs (QLED), fluorescent tags for biological imaging, single-photon sources."]},{"type":"h","text":"Melting point depression"},{"type":"ul","items":["Bulk gold melts at 1064 °C. Gold nanoparticles 2 nm across melt at ~330 °C — a 700 °C reduction.","Reason: surface atoms have fewer neighbours, so they vibrate more freely. At nanoscale, they are a large fraction of total — average bond strength is reduced.","Practical implication: sinter nano-metal powders at much lower temperatures than bulk.","Used in printed electronics: silver nanoparticle inks dried at 200 °C give continuous Ag traces — impossible with bulk Ag (m.p. 962 °C)."]},{"type":"h","text":"Optical properties"},{"type":"ul","items":["Gold nanoparticles in solution show \\"surface plasmon resonance\\" — collective oscillation of conduction electrons. Resonance wavelength depends on size and shape.","Spheres ~30 nm: red colour; spheres ~80 nm: blue/purple.","Stained glass in medieval cathedrals: colours are gold (red) and silver (yellow) nanoparticles trapped in glass — known empirically for centuries; explained scientifically only in the 19th century."]},{"type":"callout","title":"Same material, different properties","body":"Bulk Au is a noble metal — yellow, melts at 1064 °C, almost chemically inert. Nano-Au is red or purple, melts at 330 °C, and is an excellent catalyst for CO oxidation at low T. Two different \\"materials\\" by any practical measure, even though both are pure gold."},{"type":"takeaway","items":["SA/V scales as 1/size → nanoparticles have huge surface area per gram.","Quantum confinement → discrete electronic levels → tunable optical/electronic properties.","Melting point depression → easier processing.","Same chemical composition shows different colours, reactivity, m.p. at the nanoscale."]}]},{"id":"nn3","title":"Types of Nanomaterials","blocks":[{"type":"p","text":"Nanomaterials are conventionally classified by how many dimensions are confined to the nanoscale. Spheres are 0D; nanowires/tubes are 1D; sheets are 2D; bulk nanostructured solids are 3D. Each class has its own characteristic chemistry and applications."},{"type":"d","caption":"Four classes by dimensionality"},{"type":"h","text":"0D — nanoparticles and quantum dots"},{"type":"ul","items":["Spheres or nearly spherical, all three dimensions in 1-100 nm.","Metal nanoparticles: gold, silver, platinum, palladium. Catalysis, antimicrobial surfaces, drug delivery, sensors.","Metal oxide nanoparticles: TiO₂ (sunscreens, photocatalysis), Fe₃O₄ (magnetic — MRI contrast), ZnO (sunscreen, antibacterial).","Quantum dots: CdSe, CdTe, InP, PbS. Tunable fluorescence by size. Displays, biological imaging.","Carbon dots and silicon dots: less toxic alternatives to heavy-metal quantum dots."]},{"type":"h","text":"1D — nanotubes, nanowires, nanorods"},{"type":"ul","items":["Long in one dimension (microns), nano in the other two.","CARBON NANOTUBES (CNTs): graphene rolled into a cylinder. Single-walled or multi-walled. Diameter 1–50 nm; length up to mm.","CNT properties: tensile strength 50–100 GPa (~100× steel by mass); current 1000× copper by area; thermal conductivity higher than diamond.","CNT applications: structural composites (Boeing 787, sports gear), electronics (transistors), batteries, water filters.","Other 1D: silver nanowires (transparent conducting films for touch screens), boron nitride nanotubes, silicon nanowires (battery anodes)."]},{"type":"h","text":"2D — sheets and films"},{"type":"ul","items":["GRAPHENE: a single layer of carbon atoms in a hexagonal lattice. One atom thick. Discovered/isolated 2004 — Nobel Prize 2010.","Graphene properties: highest known thermal conductivity, ~2.5× copper electrical conductivity, transparent, very strong.","Applications: high-frequency electronics, transparent conductive electrodes (touch screens), composites, water purification membranes.","Other 2D: hexagonal boron nitride (h-BN, \\"white graphene\\"); MoS₂ (tunable bandgap); MXenes (titanium carbides for batteries)."]},{"type":"h","text":"3D — bulk nanostructured solids"},{"type":"ul","items":["Macroscopic objects with grain size, pore size, or filler size in the nanoscale range.","Nanostructured metals: very fine grain size makes the metal much stronger than coarse-grained (Hall-Petch strengthening).","Nanoporous materials: aerogels, zeolites, MOFs (metal-organic frameworks).","Nanocomposites: bulk matrix (polymer, metal, ceramic) reinforced with nanoparticles or nanotubes.","Natural examples: bone (collagen + apatite), nacre (CaCO₃ + protein), wood (cellulose + lignin). Nature has been using nanocomposites for hundreds of millions of years."]},{"type":"h","text":"How nanomaterials are made"},{"type":"ul","items":["Top-down: ball milling, lithography, mechanical attrition.","Bottom-up: chemical synthesis (reduction of metal salts), sol-gel, CVD, self-assembly, biological templating.","CVD (chemical vapour deposition): heat substrate + reactive gases; product nucleates on substrate. Used for graphene, carbon nanotubes, semiconductor films.","Each method gives different control over size, shape, dispersity, surface chemistry."]},{"type":"callout","title":"Carbon nanotube","body":"A long cylindrical structure of carbon atoms, formed by rolling up a sheet of graphene. SWCNT diameters 1-2 nm; MWCNT 5-50 nm. Combine high tensile strength, electrical and thermal conductivity in one material."},{"type":"takeaway","items":["0D: nanoparticles, quantum dots — catalysis, imaging, drug delivery.","1D: nanotubes, nanowires — electronics, structural composites.","2D: graphene, h-BN — transparent conductors, membranes, electronics.","3D: bulk nanostructured — stronger metals, lightweight composites."]}]},{"id":"nn4","title":"Applications in Medicine","blocks":[{"type":"p","text":"Medicine is the most active commercial application of nanotechnology. Nanoparticles operate at the size scale of biological structures, so they can interact with cells, target tissues, and pass through biological barriers in ways bulk materials cannot. Three areas dominate: drug delivery, diagnostic imaging, and antimicrobial surfaces."},{"type":"d","caption":"Three pillars of nanomedicine"},{"type":"h","text":"Targeted drug delivery"},{"type":"ul","items":["Conventional drugs distribute throughout the body — they reach the target tissue but also healthy tissue, causing side effects.","Nanoparticles can deliver drugs SELECTIVELY: load drug into a nanoparticle, attach a targeting ligand (antibody, peptide), inject. The nanoparticle finds the target and releases the drug there.","EXAMPLE: Doxil (FDA-approved 1995) — doxorubicin in PEGylated liposomes (~100 nm). Reduces cardiac toxicity by ~50% vs free doxorubicin.","EXAMPLE: COVID-19 mRNA vaccines (Pfizer, Moderna). The mRNA is encapsulated in lipid nanoparticles (~100 nm). LNPs protect the mRNA, enable cellular uptake, and release inside the cell.","Future: targeted gene therapy, glucose-responsive insulin nanoparticles, magnetic NPs steered to target sites."]},{"type":"h","text":"Diagnostic imaging"},{"type":"ul","items":["Iron oxide nanoparticles (~10 nm): superparamagnetic. Used as MRI contrast agents to highlight tumours and inflammation.","Gold nanoparticles: high atomic number → strong X-ray attenuation. CT contrast and photo-acoustic imaging.","Quantum dots: bright, photostable fluorescence at tunable wavelengths. Microscopy, single-molecule tracking in living cells.","Theranostics: a single nanoparticle that both images disease and delivers treatment."]},{"type":"h","text":"Antimicrobial surfaces"},{"type":"ul","items":["Silver nanoparticles (5-50 nm) release Ag⁺ slowly. Ag⁺ binds proteins, disrupts membranes, generates reactive oxygen species — kills bacteria with multiple mechanisms; resistance is hard to develop.","Used in wound dressings (Acticoat, Aquacel Ag): high-burn hospitals routinely use silver-impregnated dressings.","Hospital surfaces: silver-coated door handles, light switches, bed rails reduce surface bacterial loads by 70-90%.","Fabrics: silver-impregnated socks (anti-odour), surgical gowns, food packaging.","Other: ZnO and CuO have weaker activity but cheaper; TiO₂ in sunlight produces ROS (photocatalytic kill)."]},{"type":"h","text":"Sunscreens — nano-TiO₂ and nano-ZnO"},{"type":"ul","items":["Conventional sunscreens use organic UV absorbers; some have allergenic or hormonal-disruption concerns.","TiO₂ and ZnO are inorganic UV blockers that physically scatter and absorb UV. The bulk powders are white and chalky.","Nano-TiO₂ and nano-ZnO (~50-100 nm) scatter UV but transmit visible light — appear transparent on skin while blocking UV.","Excellent cosmetic acceptance + photostability — leading mineral sunscreens use nano-TiO₂.","Concern: skin penetration and free-radical generation; current evidence: negligible penetration through intact skin."]},{"type":"callout","title":"Why nano works in medicine","body":"Nanoparticles match the size scale of cells, viruses, and protein machinery. Small enough to circulate in the bloodstream (< 100 nm to avoid kidney filtration; > 10 nm to avoid rapid uptake), large enough to carry useful drug payloads, surface-engineered to find specific tissues. No bulk material can do all three."},{"type":"takeaway","items":["Targeted drug delivery: NPs + ligands → drug to diseased cells; reduces side effects.","Imaging: iron oxides for MRI, quantum dots for fluorescence, gold for CT.","Antimicrobials: silver NPs in dressings, surfaces, fabrics.","Sunscreens: nano-TiO₂ and nano-ZnO transparent UV blockers.","Vaccines: lipid nanoparticles deliver mRNA."]}]},{"id":"nn5","title":"Applications in Water and Environment","blocks":[{"type":"p","text":"After medicine, the second-most active application of nanotechnology is environmental — water purification and pollution remediation. High surface area, tunable surface chemistry, and (sometimes) magnetic recoverability make nanomaterials ideal sorbents and catalysts for cleaning up contamination."},{"type":"d","caption":"Three areas: water, soil, air"},{"type":"h","text":"Water purification"},{"type":"ul","items":["Nano-iron (zerovalent iron, nZVI): tiny iron particles injected into contaminated groundwater. Iron is a strong reducing agent. Reduces Cr(VI) → Cr(III), reduces As(V) → insoluble As(0)/As(III), dechlorinates PCE/TCE to ethene + Cl⁻.","TiO₂ photocatalysis: nano-TiO₂ + UV generates hydroxyl radicals that oxidise organic pollutants (dyes, pesticides, drugs) all the way to CO₂ + H₂O.","Carbon nanotube membranes: channels can be smaller than salt ions but allow water through — proposed for energy-efficient desalination.","Iron oxide nanoparticles: bind heavy metal ions strongly; can be removed by a magnet after treatment.","Graphene oxide membranes: very thin barriers that allow water but exclude salt — work in progress on commercial desalination."]},{"type":"h","text":"Soil and groundwater remediation"},{"type":"ul","items":["Contaminated industrial sites: chlorinated solvent plumes, heavy metals, acid mine drainage. Conventional pump-and-treat takes decades.","In-situ nano-iron treatment: inject nZVI slurry into the contaminated zone. Iron particles disperse in the aquifer and react with contaminants over months to years.","Reactions: 4Fe⁰ + Cr(VI) → 4Fe(III) + Cr(III); Fe⁰ + Cl-CH=CCl-Cl + H⁺ → CH₂=CH₂ + Fe²⁺ + 3HCl.","Advantage: no excavation; treatment underground; fraction of pump-and-treat cost.","Limitations: nanoparticle aggregation reduces reactivity; uneven distribution in heterogeneous aquifers."]},{"type":"h","text":"Air purification"},{"type":"ul","items":["Photocatalytic tiles and pavements: TiO₂ coating on building surfaces. In sunlight, TiO₂ generates radicals that destroy NOx and VOCs on contact.","Used on motorway sound barriers in the Netherlands; on roof tiles in Italy and Japan; on tunnel walls.","Efficacy: well-designed coatings reduce local NOx by 30-50%.","Self-cleaning property: organic dirt is decomposed by the same radicals; surfaces stay clean longer.","Indoor air: TiO₂ photocatalytic filters destroy VOCs and odours."]},{"type":"h","text":"Sensors and other applications"},{"type":"ul","items":["CNT-based sensors detect specific gases (NOx, NH₃, ethene from fruit ripening) at ppb levels.","Quantum dot biosensors bind specific proteins or viruses; fluorescence change → rapid disease detection.","Nano-fertilisers: slow-release nutrient delivery; less wash-off, less run-off pollution.","Food packaging: nano-Ag for antimicrobial packaging; nano-clay for improved barrier; nano-sensors for spoilage."]},{"type":"callout","title":"Why nano works in environmental cleanup","body":"High surface area means more contaminant binding per gram of sorbent. High reactivity means contaminants are destroyed (not just sequestered). Tiny size lets particles infiltrate porous soils. Magnetic NPs allow recovery after cleanup."},{"type":"takeaway","items":["Nano-iron: in-situ groundwater cleanup of Cr(VI), As, chlorinated solvents.","TiO₂ photocatalysis: destroys organics in water and air.","Nano-membranes: efficient desalination and contaminant filtering.","Nano-sensors: ppb-level real-time detection."]}]},{"id":"nn6","title":"Risks and Regulation","blocks":[{"type":"p","text":"The same properties that make nanomaterials useful — small size, high surface area, ability to cross biological barriers — also raise safety concerns. Bulk gold is one of the safest materials known; nano-gold may be very different. Toxicology and environmental fate research has been racing to keep up with product release."},{"type":"d","caption":"Three categories of nanomaterial concern"},{"type":"h","text":"Routes of human exposure"},{"type":"ul","items":["Inhalation: airborne nanoparticles from manufacturing, abrasion of nano-products, accidental release. Particles < 100 nm reach the alveoli (deepest part of the lung), where they are not effectively cleared.","Ingestion: nanoparticles in food (intentional, e.g. nano-TiO₂ as whitener; or unintentional, e.g. wear from food processing equipment), in water from industrial discharges.","Dermal: cosmetics, sunscreens — though intact skin generally blocks penetration of well-formulated NPs.","Injection: medical applications — direct introduction into bloodstream."]},{"type":"h","text":"Health concerns"},{"type":"ul","items":["Carbon nanotubes: long, fibre-like CNTs resemble asbestos. Animal studies show that long, straight CNTs cause inflammation and tumours in lung lining (mesothelioma) — the same disease asbestos causes. Short, tangled CNTs appear less hazardous.","Metal nanoparticles: silver, gold, copper NPs taken up by cells, concentrate in liver, spleen, brain. Long-term effects in humans not fully studied.","TiO₂: classified by IARC as \\"possibly carcinogenic\\" (group 2B) when inhaled in particulate form. France banned nano-TiO₂ as a food additive in 2020.","Quantum dots: many contain heavy metals (Cd, Pb) toxic if released; design effort focuses on coating to prevent leaching.","Crossing the blood-brain barrier: nanoparticles small enough can reach the brain — toxic effects there are particularly serious."]},{"type":"h","text":"Environmental concerns"},{"type":"ul","items":["Sunscreens shed nano-TiO₂ and nano-ZnO into rivers and oceans during swimming; effects on coral and fish are emerging research areas.","Silver NPs in fabric/clothing wash into wastewater; can damage beneficial bacteria in sewage treatment plants.","CNTs released from composite materials at end-of-life (incineration, weathering) — long-term fate uncertain.","Aggregation: many NPs aggregate over time into less reactive lumps. Toxicity of aggregated nano-material is generally less than freshly dispersed form.","Bioaccumulation: some NPs accumulate up the food chain — concern especially for persistent metal NPs."]},{"type":"h","text":"Regulation and the precautionary principle"},{"type":"ul","items":["EU REACH (2007): chemical regulation framework requires safety data. Specific nanomaterial requirements added 2018 — registrants must consider nanoform-specific properties.","EU Cosmetics Regulation: nanomaterial ingredients must be labelled with \\"[nano]\\" suffix.","US FDA: regulates nanomaterials in food, drugs, cosmetics — but the threshold for what counts as \\"nano\\" is debated.","Difficulty: a single material can have many nanoforms with different properties — toxicology must consider EACH form.","Precautionary principle: if a product cannot be proven safe, restrict its use until evidence is in.","Ongoing research: large EU and US programmes investigating nanomaterial fate and toxicity."]},{"type":"h","text":"How risk is managed in practice"},{"type":"ul","items":["Workplace: protective masks (N95 or better), enclosed handling, ventilation. Treat nano-powders like asbestos.","Consumer products: nanomaterials typically incorporated into solid matrices (plastics, ceramics, coatings). Wear and weathering still emit some — research continues.","End-of-life: incineration and recycling release NPs. Modern incinerators with advanced filtration capture most; landfill is a long-term unknown.","Informed consent: drug delivery and medical imaging applications must establish risk/benefit before approval."]},{"type":"callout","title":"The science is racing the products","body":"Nanotechnology has produced thousands of commercial products since the early 2000s. Toxicological understanding lags behind. The chemistry and engineering are well understood; long-term ecological and health impacts are not. Continuing research and adaptive regulation are essential."},{"type":"takeaway","items":["Exposure routes: inhalation (worst), ingestion, dermal, injection.","Health: long CNTs may resemble asbestos; metal NPs accumulate in organs.","Environment: sunscreens, fabrics, products release NPs into water.","Regulation: EU REACH, cosmetics labelling, FDA — adaptive but lagging.","Precautionary principle: assume risk until proven safe."]}]}]}`)},o=(e=``)=>String(e).toLowerCase().replace(/[–—−]/g,`-`).replace(/\s+/g,` `).trim(),s=(e={})=>e.type===`p`||e.type===`h`?e.text||``:e.type===`ul`||e.type===`takeaway`?(e.items||[]).join(` `):e.type===`callout`?[e.title,e.body].filter(Boolean).join(` `):e.type===`d`&&e.caption||``,c=(e={},t=`Lesson content`)=>{if(e.type===`h`)return e.text||t;if(e.type===`callout`)return e.title||t;if(e.type===`takeaway`)return`Key takeaways`;if(e.type===`ul`)return(e.items||[t])[0]||t;if(e.type===`d`)return e.caption||`Diagram`;if(e.type===`p`){let n=e.text||t;return n.length>72?`${n.slice(0,69)}…`:n}return t},l=(e=``,t=180)=>{let n=String(e).replace(/\s+/g,` `).trim();return n.length<=t?n:`${n.slice(0,t-1).trimEnd()}…`};function u(t){let n=[];return e.forEach(e=>{let r=t[e.id],i=[e.title,e.code,e.tagline,...e.keywords||[],...r?.objectives||[]].join(` `);n.push({id:`topic:${e.id}`,kind:`topic`,topicId:e.id,title:e.title,path:`${e.code} · ${e.title}`,snippet:e.tagline||`Open topic overview`,haystack:o(i),searchTitle:o(`${e.title} ${e.code}`)}),(r?.chapters||[]).forEach(t=>{let r=(t.blocks||[]).map(s).join(` `);n.push({id:`chapter:${e.id}:${t.id}`,kind:`chapter`,topicId:e.id,chapterId:t.id,title:t.title,path:`${e.title} › ${t.title}`,snippet:l(r||`Open chapter`),haystack:o(`${e.title} ${e.code} ${t.title} ${r}`),searchTitle:o(`${t.title} ${e.title}`)}),(t.blocks||[]).forEach((r,i)=>{let a=s(r);if(!String(a).trim())return;let u=r.type===`h`||r.type===`callout`||r.type===`takeaway`?`section`:r.type===`d`?`diagram`:`paragraph`;n.push({id:`block:${e.id}:${t.id}:${i}`,kind:u,topicId:e.id,chapterId:t.id,blockIndex:i,title:c(r,t.title),path:`${e.title} › ${t.title}`,snippet:l(a),haystack:o(`${e.title} ${e.code} ${t.title} ${a}`),searchTitle:o(`${c(r,t.title)} ${t.title}`)})})})}),n}var d=(e=``)=>String(e).toLowerCase().replace(/[–—−]/g,`-`).replace(/\s+/g,` `).trim(),f=(e=``,t=180)=>{let n=String(e).replace(/\s+/g,` `).trim();return n.length<=t?n:`${n.slice(0,t-1).trimEnd()}…`};function p(e=[]){return e.map(e=>[e.reagent,e.obs,e.eq,e.confirm,e.absent,e.note].filter(Boolean).join(` `)).join(` `)}function m(){let e=[{id:`tool:periodic`,kind:`tool`,toolKey:`periodic`,title:`Periodic Table`,path:`Tools › Periodic Table`,snippet:`Elements, symbols, atomic numbers and electron configurations.`,haystack:d(`periodic table elements symbols atomic number electron configuration`),searchTitle:`periodic table`},{id:`tool:balancer`,kind:`tool`,toolKey:`balancer`,title:`Equation Balancer`,path:`Tools › Equation Balancer`,snippet:`Balance chemical equations with the exact solver.`,haystack:d(`equation balancer balance chemical equations stoichiometric coefficients`),searchTitle:`equation balancer`},{id:`tool:mole`,kind:`tool`,toolKey:`mole`,title:`Mole Calculator`,path:`Tools › Mole Calculator`,snippet:`Moles, mass, molar mass, gas equation, concentration and dilution.`,haystack:d(`mole calculator moles mass molar mass pv nrt concentration dilution`),searchTitle:`mole calculator`},{id:`tool:qa`,kind:`tool`,toolKey:`qa`,qaTab:`functional`,title:`Qualitative Analysis Table`,path:`Tools › QA Table`,snippet:`Cation, anion, gas and organic functional-group tests.`,haystack:d(`qualitative analysis qa cation anion gas functional group organic tests reagents observations`),searchTitle:`qualitative analysis qa table`}],a=(t,n,r,i,a)=>{t.forEach((t,o)=>{let s=r(t),c=i(t),l=p(a(t));e.push({id:`qa:${n}:${o}`,kind:`tool`,toolKey:`qa`,qaTab:n,qaOpen:`${n}-${o}`,title:s,path:`Tools › QA Table › ${c}`,snippet:f(l),haystack:d(`${s} ${c} ${l}`),searchTitle:d(`${s} ${c}`)})})};return a(n,`cations`,e=>`${e.ion} — ${e.name}`,e=>e.name,e=>e.tests||[]),a(i,`anions`,e=>`${e.ion} — ${e.name}`,e=>e.name,e=>e.tests||[]),a(t,`gases`,e=>`${e.gas} gas test`,e=>e.gas,e=>[{reagent:e.test,obs:e.result}]),a(r,`functional`,e=>`${e.group} — ${e.name}`,e=>e.name,e=>e.tests||[]),e}var h=[...u(a),...m()];function g(e,t=36){let n=d(e);if(!n)return[];let r=n.split(` `).filter(Boolean);return h.map(e=>{if(!r.every(t=>e.haystack.includes(t)))return null;let t=10;return e.searchTitle===n&&(t+=180),e.searchTitle.startsWith(n)&&(t+=110),e.searchTitle.includes(n)&&(t+=80),e.haystack.includes(n)&&(t+=45),e.kind===`section`&&(t+=18),e.kind===`chapter`&&(t+=14),e.kind===`topic`&&(t+=12),e.kind===`tool`&&(t+=10),t-=Math.min(e.snippet.length/100,4),{...e,score:t}}).filter(Boolean).sort((e,t)=>t.score-e.score||e.title.localeCompare(t.title)).slice(0,t)}export{g as searchChemWiz};